INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diverge','v.分歧','/daɪˈvɜːdʒ/','/daɪˈvɜːdʒ/','verb',["Both stories start out the same way, but they diverge halfway through.","The sidewalk runs next to the street for a few miles, then diverges from it and turns north.","The software is pretty good, except for a few cases where its behavior diverges from user expectations."]);
