INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grope','v./n摸索','/ɡɹəʊp/','/ɡɹəʊp/','noun',["the old man tried to get a quick grope of the young lady on the train.","We''ve been together two weeks, and have just been kissing and groping, but no sex yet.","That old man groped that girl on the train!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hesitate','v.犹豫,踌躇','/ˈhɛzɪteɪt/','/ˈhɛzɪteɪt/','verb',["He hesitated whether to accept the offer or not; men often hesitate in forming a judgment."]);
