INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jolt','v&n.(使)颠簸；震动','/dʒɒlt/','/dʒoʊlt/','noun',["The bus jolted its passengers at every turn.","I jolted her out of complacency.","Her untimely death jolted us all."]);
