INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breech','n.臀部,后膛vt.给…穿上裤子','/bɹiːtʃ/','/bɹiːtʃ/','noun',["to breech a gun"]);
