INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comical','adj.好笑的,滑稽的','/ˈkɒmɪkəl/','/ˈkɑmɪkəl/','adjective',["It was a comical performance.","The tutor excelled in comical scoldings.","He''s just put salt in his tea instead of sugar. What a comical error!"]);
