INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sequester','v.使隐退,扣押,没收','/səˈkwɛs.tə/','/səˈkwɛs.tɚ/','noun',["The jury was sequestered from the press by the judge''s order.","The Budget Control Act of 2011 sequestered 1.2 trillion dollars over 10 years on January 2, 2013."]);
