INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('selfless','adj.无私的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obligation','n.义务,职责,债务','/ɑb.ləˈɡeɪ.ʃən/','/ɑb.ləˈɡeɪ.ʃən/','noun',["X shall be entitled to subcontract its obligation to provide the Support Services. <>"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fanatical','adj.狂热的,入迷的','/fəˈnætɪkəl/','/fəˈnætɪkəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coax','v.巧妙地（耐心地）处理,哄','/kəʊks/','/kəʊks/','noun',["He coaxed the horse gently into the trailer.","They coaxed the rope through the pipe."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flue','n.烟道,暖气管','/fluː/','/fluː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pivot','n.枢轴v.在枢轴上转动','/ˈpɪvət/','/ˈpɪvət/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coordination','n.协调','/koʊˌɔɹdɪˈneɪʃən/','/koʊˌɔɹdɪˈneɪʃən/','noun',["I''m terrible at sports; I have no coordination."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cancel','v.取消，废除；删去，删除；抵消','/ˈkænsl̩/','/ˈkænsl̩/','noun',["He cancelled his order on their website.","This machine cancels the letters that have a valid zip code.","The corrective feedback mechanism cancels out the noise."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recline','v.向后倚靠，斜倚','/ɹəˈklaɪn/','/ɹəˈklaɪn/','noun',["She reclined her arms on the table and sighed.","to recline against a wall","to recline on a couch"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explosive','adj.爆炸的，爆发的；使人冲动的n.炸药','','','noun',["an explosive device","an explosive fire","an explosive accusation"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crusade','v.加入十字军，投身正义运动n.十字军；斗争，运动','/kɹuːˈseɪd/','/kɹuːˈseɪd/','noun',["During the crusades, many Muslims and Christians and Jews were slaughtered.","a crusade against drug abuse","He crusaded against similar injustices for the rest of his life."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supplant','vt.取代，代替','/səˈplænt/','/səˈplænt/','verb',["Will online dictionaries ever supplant paper dictionaries?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surgeon','n.外科医师','/ˈsɜːdʒən/','/ˈsɜːdʒən/','noun',["The surgeon refused to operate because the patient was her son."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abrupt','adj.突然的，意外的；唐突的，鲁莽的','/aˈbɹʌpt/','/aˈbɹʌpt/','noun',["The party came to an abrupt end when the parents of our host arrived."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('predispose','v.事先影响某人；易受感染','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convection','n.对流；传送','/kənˈvɛkʃən/','/kənˈvɛkʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wreck','vt.使失事；破坏n.沉船；失事','/ˈɹɛk/','/ˈɹɛk/','noun',["He was an emotional wreck after the death of his wife.","He wrecked the car in a collision."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('twinkling','adj.闪光的n.瞬间，一眨眼','/ˈtwɪŋklɪŋ/','/ˈtwɪŋklɪŋ/','verb',["We could see the lights of the village twinkling in the distance.","His shrewd little eyes twinkled roguishly."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gloomy','adj.忧郁的，令人沮丧的；昏暗的，阴暗的，阴沉的','/ˈɡlumi/','/ˈɡlumi/','adjective',["The cavern was gloomy.","a gloomy temper or countenance"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reproach','v&n.指责，斥责，批评','/ɹɪˈpɹəʊtʃ/','/ɹɪˈpɹoʊtʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('customs','n.关税，进口税；海关','/ˈkʌstəmz/','/ˈkʌstəmz/','noun',["Customs of £200 were due on all the wine we took back from France.","Customs has pulled us over on our way for an inspection."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('warrant','n.授权，批准；许可证；委任状，执行令vt.保证，担保；使正当','/ˈwɒɹənt/','/ˈwɑɹənt/','noun',["a warrant of authenticity; a warrant for success","an arrest warrant issued by the court","That tree is going to fall, I’ll warrant."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sake','n.缘故，理由；好处','/seɪk/','/seɪk/','noun',["For the sake of argument","For old times'' sake"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coincide','vi.同时发生；一致，相符；重合','/ˌkoʊɪnˈsaɪd/','/ˌkoʊɪnˈsaɪd/','verb',["The two squares coincide nicely.","The conference will coincide with his vacation.","Our ideas coincide, except in certain areas."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circular','adj.圆形的，环形的；循环的；绕行的','/ˈsɜːk.jə.lə(ɹ)/','/ˈsɝk.jə.lɚ/','noun',["Your dictionary defines \"brave\" as \"courageous\", and \"courageous\" as \"brave\". That''s a circular definition."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scratch','vt.刮擦，划；抓，搔n.划痕；挠痒','/skɹætʃ/','/skɹætʃ/','noun',["Her skin was covered with tiny scratches.","The dog sat up and had a good scratch.","There were two scratches in race 8, which reduced the field from 9 horses to 7."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('require','vt.需要；要求，命令','/ɹɪˈkwaɪə/','/ɹɪˈkwaɪɹ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cooperative','adj.合作的，协作的；配合的n.合作企业','','','noun',["The patient was rarely cooperative, and tended to refuse treatment.","a cooperative business enterprise"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('willow','n.柳，柳树；柳木制品','/ˈwɪl.əʊ/','/ˈwɪloʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corporeal','adj.肉体的，身体的；物质的；实体的','/kɔːˈpɔːɹiəl/','/kɔːˈpɔːɹiəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('irritable','adj.急躁的，易怒的；易受刺激的；过敏的','/ˈɪɹɪtəbl/','/ˈɪɹɪtəbl/','adjective',["an irritable old man"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('triple','v.增至三倍adj.三部分的；三方的；三倍的','/ˈtɹɪpl/','','noun',["I''ve had a hard day; make that a triple.","I''d like a triple with cheese.","The shortstop hit a triple to lead off the ninth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('temper','n.脾气，性情vt.缓和，调节','/ˈtɛmpə/','/ˈtɛmpɚ/','noun',["to have a good, bad, or calm temper","He has quite a temper when dealing with salespeople.","an outburst of temper"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('legible','adj.清楚的；易读的','/ˈlɛd͡ʒəbl/','/ˈlɛd͡ʒəbl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tickle','v.发痒；使高兴，逗乐n.痒','/ˈtɪkl̩/','/ˈtɪkl̩/','noun',["I have a persistent tickle in my throat.","He tickled Nancy''s tummy, and she started to giggle.","A stranger tickled Nancy''s tummy, causing her to scream in fear."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cardiac','adj.心脏的；心脏病的','/ˈkɑːdɪæk/','/ˈkɑɹdiˌæk/','noun',["the cardiac arteries"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accessible','adj.易接近的；可得到的；可进入的','','/əkˈsɛs.ə.bəl/','adjective',["an accessible town or mountain","accessible public transport"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ageism','n.年龄歧视','/ˈeɪdʒ.ɪz.əm̩/','/ˈeɪdʒ.ɪz.əm̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notable','adj.值得注意的，明显的；显著的；著名的；重要的n.名人，要人','/ˈnəʊtəbl̩/','/ˈnoʊdəbəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concede','v.承认；让步；允许','/kənˈsiːd/','/kənˈsiːd/','verb',["He conceded the race once it was clear he could not win."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unparalleled','adj.空前的，无比的','','','adjective',["The candidate experienced unparalleled support in the last election."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('luminosity','n.亮度，发光度；光明','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resume','v.重新开始，继续','/ɹɪˈzjuːm/','/ɹɪˈz(j)um/','verb',["We will resume this discussion tomorrow at nine."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('provocative','adj.挑衅的，煽动性的；惹人讨厌的；挑逗的','/pɹəˈvɒk.ə.tɪv/','/pɹəˈvɒk.ə.tɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ramble','vi.漫游；漫谈，闲聊n.漫步','/ˈɹæmbəl/','/ˈɹæmbəl/','noun',["Francine has a tendency to ramble when it gets to be late in the evening."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vocation','n.职业；使命感；圣召','/vəʊˈkeɪʃən/','/voʊˈkeɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('halt','v.停住，停下n.停止，阻止；暂停','/hɔːlt/','/hɔːlt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sunset','n.日落，傍晚','/ˈsʌnˌsɛt/','/ˈsʌnˌsɛt/','noun',["one''s sunset years","The tax increase legislation included a sunset clause requiring renewal to prevent the tax increase from expiring.","We''ll be sunsetting version 1.9 of the software shortly after releasing version 2.0 next quarter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stature','n.身材，身高；地位，声望，名望','/ˈstætʃ.ə/','/ˈstætʃ.ɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dogged','adj.顽强的，坚持不懈的；顽固的，固执的','/dɒɡd/','/dɒɡd/','verb',["The woman cursed him so that trouble would dog his every step.","It is very important to dog down these hatches...","I admit that I like to dog at my local country park."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plasma','n.血浆；等离子体','/ˈplazmə/','/ˈplazmə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exorbitant','adj.过高的，不合理的','/ɛɡˈzɔːbɪtənt/','','adjective',["It''s a nice car, but they are charging an exorbitant price for it."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surgery','n.外科手术；外科学；手术室，诊疗室','/ˈsɜːdʒəɹi/','/ˈsɝdʒəɹi/','noun',["Many times surgery is necessary to prevent cancer from spreading.","I dropped in on the surgery as I was passing to show the doctor my hemorrhoids.","Our MP will be holding a surgery in the village hall on Tuesday."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inaccessible','adj.难达到的，不可及的；不能得到的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resolve','v.解决；决定，决心；分解；显现n.决心，决议','/ɹiːˈzɒlv/','/ɹɪˈzɑlv/','noun',["It took all my resolve to go through with the surgery.","to resolve a riddle","I resolve to finish this work before I go home."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choreograph','v.设计舞蹈动作，编舞','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confront','vt.使面临，使遭遇；对抗','/kɒnˈfɹɒnt/','/kɒnˈfɹɒnt/','verb',["We should confront him about the missing money."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nonverbal','adj.非语言的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deploy','vt.部署，调度；利用','/dɪˈplɔɪ/','/dɪˈplɔɪ/','noun',["\"Deploy two units of infantry along the enemy''s flank,\" the general ordered.","He waited tensely for his parachute to deploy.","The process for the deployment scenario includes: building a master installation of the operating system, creating its image and deploying the image onto a destination computer."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('huddle','vi.聚集在一起，挤作一团；蜷缩，缩成一团，蜷缩n.挤在一起的人','/ˈhʌdəl/','/ˈhʌdəl/','noun',["The sheep huddled together seeking warmth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('syntactic','adj.句法的；按照句法的','/sɪnˈtæktɪk/','/sɪnˈtæktɪk/','adjective',["The sentence “I saw he” contains a syntactic mistake."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rendition','n.表演，演唱；提供，给予；翻译','/ɹɛnˈdɪʃ(ə)n/','/ɹɛnˈdɪʃ(ə)n/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intersection','n.交点；十字路口，道路交叉口','/ˈɪntəɹˌsɛkʃən/','/ˈɪntəɹˌsɛkʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scholarship','n.奖学金；学问，学识','/ˈskɒləʃɪp/','/ˈskɒləʃɪp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('myriad','adj.无数的；大量的n.无数；大量','/ˈmɪɹi.æd/','/ˈmɪɹi.æd/','noun',["Earth hosts a myriad of animals.","Earth hosts myriad animals."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('besides','adv.而且，还有prep.除…之外','/biˈsaɪdz/','/biˈsaɪdz/','adverb',["I don''t feel like going out tonight. Besides, I have to work tomorrow morning anyway.","I have been to Spain but nowhere besides.","I don''t want to go anywhere besides India."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('erratic','adj.古怪的，反复无常的；不规则的；不稳定的','/ɪˈɹætɪk/','/ɪˈɹætɪk/','noun',["Henry has been getting erratic scores on his tests: 40% last week, but 98% this week.","erratic conduct"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incinerate','vt.焚化，焚毁','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('capillary','adj.毛状的；毛细血管的n.毛细血管','/kəˈpɪ.lə.ɹi/','/ˈkæpɪˌlɛɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('informative','adj.提供消息的，给予知识的；见闻广博的','/ɪnˈfɔɹmətɪv/','/ɪnˈfɔɹmətɪv/','adjective',["I read a very informative newspaper article on that subject last week."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('check','n.支票；账单；','/t͡ʃɛk/','/t͡ʃɛk/','noun',["I don''t know if she will be there, but it''s worth a check.","The castle moat should hold the enemy in check.","Place a check by the things you have done."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frustrate','vt.使感到灰心，挫败；阻止','/fɹəˈstɹeɪt/','/fɹəˈstɹeɪt/','verb',["It frustrates me to do all this work and then lose it all.","My clumsy fingers frustrate my typing efforts.","This test frustrates me because if I fail, it''ll destroy my grade."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sparse','adj.稀疏的，稀少的；贫乏的','/spɑːs/','/spɑːs/','verb',["a sparse array, index, or matrix"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gorgeous','adj.漂亮的；令人愉快的；华丽的，灿烂的','/ˈɡɔːdʒəs/','/ˈɡɔɹdʒəs/','adjective',["All the contest judges agreed that Brigitt was absolutely gorgeous.","Hummus is absolutely gorgeous."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pragmatic','adj.务实的，注重实效的，实用的','/pɹæɡˈmætɪk/','/pɹæɡˈmætɪk/','noun',["The sturdy furniture in the student lounge was pragmatic, but unattractive."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('methane','n.甲烷，沼气','/ˈmiːθeɪn/','/ˈmɛθeɪn/','noun',["Cattle emit a large amount of methane."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superstitious','adj.迷信的，受迷信思想支配的','/ˌs(j)uː.pəˈstɪ.ʃəs/','/ˌs(j)u.pɚˈstɪ.ʃəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ascend','v.上升，升高；攀登','/əˈsɛnd/','/əˈsɛnd/','verb',["He ascended to heaven upon a cloud.","You ascend the stairs and take a right.","She ascended the throne when her mother abdicated."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elasticity','n.弹力；弹性','/ɪ.læsˈtɪs.ɪ.ti/','/ɪ.læsˈtɪs.ɪ.ti/','noun',["If the sales of an item drop by 5% when the price increases by 10%, its price elasticity is -0.5.","Her elasticity allowed her to recover quickly."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proactive','adj.积极主动的；先发制人的','','','adjective',["We can deal with each problem as it pops up, or we can take a proactive stance and try to prevent future problems."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indispensable','adj.必不可少的','/ɪndɪˈspɛnsəbəl/','/ɪndɪˈspɛnsəbəl/','noun',["The law was moral and indispensable. -Bp. Burnet","An indispensable component of a heart-healthy diet."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embody','vt.表达，体现；含有','/ɪmˈbɒdi/','/ɪmˈbɒdi/','verb',["As the car salesman approached, wearing a plaid suit and slicked-back hair, he seemed to embody sleaze.","The US Constitution aimed to embody the ideals of diverse groups of people, from Puritans to Deists."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('verifiable','adj.可证实的，可核实的','/vɛɹ.ɪˈfaɪ.ə.bəl/','/vɛɹ.ɪˈfaɪ.ə.bəl/','noun',["Do you have verifiable evidence to support that claim?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comprehensible','adj.可理解的，能懂的，能充分理解的','/kɒmpɹəˈhɛnsɪbəl/','/kɒmpɹəˈhɛnsɪbəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emancipate','vt.解放，解除','/ɪˈmænsɪpeɪt/','/ɪˈmænsɪpeɪt/','verb',["emancipate someone from prejudices or error"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('romantic','adj.爱情的；浪漫的，富有情调的；多情的；不切实际的，幻想的；[R-]浪漫主义的','/ɹə-/','/ɹoʊˈmæn(t)ɪk/','adjective',["Oh, flowers! You''re such a romantic.","Mary sighed, knowing her ideals were far too romantic to work in reality.","Their kiss started casually, but it slowly turned romantic."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('motivate','vt.激励；激发','/ˈməʊtɪveɪt/','/ˈməʊtɪveɪt/','verb',["The weekly staff meeting was meant to motivate employees.","He was motivated purely by self-interest."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spoil','v.破坏；宠坏，溺爱；变质','/spɔɪl/','/spɔɪl/','noun',["Make sure you put the milk back in the fridge, otherwise it will spoil."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pasture','n.牧场，草原；','/ˈpɑːstjə/','/ˈpæstʃɚ/','noun',["The farmer pastures fifty oxen; the land will pasture forty cows."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conducive','adj.有助于…的，有益于…的','/kənˈdjuːsɪv/','/kənˈdjuːsɪv/','adjective',["A small, dark kitchen is not conducive to elaborate cooking."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pilot','adj.试验性的n.飞行员，领航员；领导人vt.驾驶，领航；试行，试用；使通过，引导','/ˈpaɪlət/','','noun',["We would like to run a pilot in your facility before rolling out the program citywide.","The pilot plant showed the need for major process changes.","a pilot light"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curative','adj.有助于治疗的，有疗效的n.药物','/ˈkjʊɹ.ə.tɪv/','/ˈkjʊɹ.ə.tɪv/','noun',["The curative power of the antibiotics introduced in the 1950s was amazing at the time."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cartilage','n.软骨','/ˈkɑːtɪlɪd͡ʒ/','/ˈkɑɹtəlɪd͡ʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snide','adj.伪造的；不诚实的；讽刺的，挖苦的，含沙射影的','/snaɪd/','/snaɪd/','noun',["Don''t make snide remarks to me.","He was a snide lawyer."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('magnet','n.磁铁，磁体；有吸引力的人','/ˈmæɡnət/','/ˈmæɡnət/','noun',["He always had a girl on his arm – he''s a bit of a babe magnet."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('versatile','adj.多才多艺的；多用途的','/ˈvɜːsətaɪl/','/ˈvɝsətl̩/','adjective',["2004, \"queenchaser1158\", Horny Versatile TV/TS Wanted in Phoenix (on newsgroup alt.personals.gay)"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('versus','prep.对，对抗；与…相对，与…相比','/ˈvɜːsəs/','/ˈvɜːsəs/','preposition',["It is the Packers versus the Steelers in the Super Bowl.","Brown v. Board of Education of Topeka, Kans."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('penmanship','n.书法','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tundra','n.苔原，冻原，冻土地带','/ˈtʌndɹə/','/ˈtʌndɹə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tinker','vi.做焊锅匠；做拙劣修补n.补锅匠','/ˈtɪŋkə(ɹ)/','/ˈtɪŋkə(ɹ)/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('puncture','v.刺穿；泄气，挫伤n.小孔；刺伤','/ˈpʌŋktʃə/','/ˈpʌŋktʃɚ/','noun',["There were two small punctures in his arm where the snake''s fangs had pierced the skin.","On the way back we got a puncture, and we were stuck at the roadside for three hours until help arrived.","The needle punctured the balloon instantly."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('translation','n.翻译；译文，译本','/tɹæns-/','/tɹæn(t)sˈleɪʃ(ə)n/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('personnel','n.全体人员，员工','/-el/','/pɝ.səˈnɛl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('splash','v.溅，泼n.重点文章；溅上的液体；斑点','/splæʃ/','/splæʃ/','noun',["I heard a splash when the rock landed in the pond.","I felt a splash of rain, so I put up my hood.","The painter put a splash of blue on the wall to make it more colorful"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fountain','n.喷泉；丰富来源，源泉','[ˈfaʊn.ʔn̩]','[ˈfaʊn.ʔn̩]','noun',["Lava fountained from the volcano."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('part-time','adj.兼职的；部分时间的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chilly','adj.寒冷的；冷淡的，不友好的','/ˈtʃɪli/','/ˈtʃɪli/','adjective',["I’m getting rather chilly over here – could you shut the window please?","She gave me a chilly look when I made the suggestion."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flagellum','n.[昆]鞭毛；鞭子；鞭状匍匐枝','/fləˈdʒɛləm/','/fləˈdʒɛləm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rhinoceros','n.犀牛','/ɹaɪˈnɒsəɹəs/','/ɹaɪˈnɑsəɹəs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fierce','adj.凶猛的，残忍的；狂热的，强烈的；激烈的，猛烈的','/fɪəs/','/fɪɹs/','adjective',["A fierce storm battered the coast.","We made a fierce attempt to escape.","The lion gave a fierce roar."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reservation','n.预约，预订；保留意见，疑惑；居留地','/ˌɹɛzəˈveɪʃən/','/ˌɹɛzəˈveɪʃən/','noun',["The committee authorised the reservation of funds.","I have reservations about your intentions.","I have a hotel reservation in the name of Mr Smith."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cordial','adj.亲切的，热诚的','/ˈkɔː.dɪ.əl/','/ˈkɔɹ.djəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('odorous','adj.有气味的，难闻的；香的，芬芳的','','','adjective',["The table was piled with odorous lilies."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conceit','n.自负，自大','/kənˈsiːt/','/kənˈsiːt/','noun',["a man of quick conceit"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modulate','v.调整，调节；调制','/ˈmɑː.dʒə.ˌleɪt/','/ˈmɑː.dʒə.ˌleɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mottled','adj.有杂色的，斑驳的','/ˈmɑt əld/','/ˈmɑt əld/','verb',["The mottled skin of the snake was a camouflage that helped it blend in with the shadows."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('morphology','n.形态学，形态论','/mɔɹˈfɑlədʒi/','/mɔɹˈfɑlədʒi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resonance','n.共振，共鸣；回声，反响','/ˈɹɛzənəns/','/ˈɹɛzənəns/','noun',["2004, When experiments with the first ‘atom-smashers’ took place in the 1950s to 1960s, many short-lived heavier siblings of the proton and neutron, known as ‘resonances’, were discovered. — Frank Close, Particle Physics: A Very Short Introduction (Oxford 2004, p. 35)"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spearhead','n.先锋，前锋，先头部队vt.为…作先锋；带头做','/ˈspɪə.hɛd/','/ˈspiɹ.hɛd/','noun',["He spearheaded the entire project from day one."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seismograph','n.地震仪，测震仪','/ˈsaɪz.mə.ɡɹæf/','/ˈsaɪz.mə.ɡɹæf/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('angular','adj.有角的，尖角的；消瘦的，瘦骨嶙峋的','/-lɑɹ/','/-lɑɹ/','noun',["an angular figure","angular distance","He''s remarkably angular in his habits and appearance."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('daylight','n.日光；白昼','/ˈdeɪlaɪt/','/ˈdeɪlaɪt/','noun',["We should get home while it''s still daylight.","We had only two hours to work before daylight.","Budgeting a spy organization can''t very well be done in daylight."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('podium','n.讲坛，讲台；指挥台','/ˈpəʊ.dɪi.ʌm/','/ˈpəʊ.dɪi.ʌm/','noun',["The swimmer podiumed three times at the Olympics."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('binary','adj.二进制的；二元的；由两部分组成的','/ˈbaɪ.nə.ɹɪ/','/ˈbaɪ.nə.ɹi/','noun',["Binary states are often represented as 1 and 0 in computer science.","A binary statistical distribution has only two categories.","Division of reals is a binary operation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ensue','vi.继而发生，接着发生','/ɛnˈsjuː/','/ɛnˈsjʉː/','verb',["Give three freshmen six bottles of wine, and hilarity will ensue."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crazy','adj.疯狂的，不理智的；狂热的，热衷的；精神失常的','/ˈkɹeɪzi/','/ˈkɹeɪzi/','noun',["His ideas were both frightening and crazy.","When she gets on the motorcycle she goes crazy.","He went crazy when he won."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('homage','n.尊敬，敬意','/ˈhɒmɪdʒ/','/oʊˈmɑʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('penicillin','n.青霉素，盘尼西林','/ˌpɛnɪˈsɪlɪn/','/ˌpɛnɪˈsɪlɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pine','vi.憔悴；难过，悲伤n.松树','/paɪn/','/paɪn/','noun',["The northern slopes were covered mainly in pine."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enlightenment','n.启发，教化，启迪；[theE-]启蒙运动','/-laɪtmənt/','/-laɪtmənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('irony','n.反话，讽刺，嘲弄；具有讽刺意味的事','/ˈaɪə.ɹən.i/','/ˈaɪ.ɚ.ni/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mandatory','n.强制的，法定的，义务的；受托人；代理人','/ˈmæn.də.t(ə)ɹi/','/ˈmæn.dəˌtɔ.ɹi/','noun',["Attendance at a school is usually mandatory for children.","Mandatory Palestine"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hypertext','n.超文本','/ˈhaɪpəɹˌtɛkst/','/ˈhaɪpəɹˌtɛkst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bedrock','n.基础，根基；基岩','','','noun',["If culture is the bedrock of a society, then language is the cornerstone of culture."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('syndrome','n.综合征；典型表现','/ˈsɪndɹəʊm/','/ˈsɪndɹəʊm/','noun',["Down syndrome; acquired immune deficiency syndrome; restless-leg syndrome; battered-wife syndrome","not-in-my-backyard syndrome; tip-of-the-tongue syndrome"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('newsprint','n.新闻纸','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tow','vt&n.拖，牵引','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harmonic','n.泛音；','/hɑː(ɹ)ˈmɒnɪk/','/hɑː(ɹ)ˈmɒnɪk/','noun',["The harmonic polar line of an inflection point of a cubic curve is the component of the polar conic other than the tangent line."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('haul','v.拖，拖运n.拖，拉，拖运；一次获得的数量；旅行的距离','/hɔːl/','/hɔːl/','noun',["Getting to his place was a real haul.","The robber’s haul was over thirty items.","to haul logs to a sawmill"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('energetic','adj.精力充沛的，积极的','/ˌɛnəˈdʒɛtɪk/','/ˌɛnɚˈdʒɛtɪk/','adjective',["Cosmic rays are energetic particles from outer space.","Those kids are so energetic: they want to run around playing all day."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quilt','v.缝被；缝制n.被褥','/kwɪlt/','/kwɪlt/','noun',["My grandmother is going to sew a quilt."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('premier','adj.第一的，首要的；最著名的n.首相，总理','/ˈpɹemjə/','/ˈpɹemjə/','noun',["The composer invited all his friends when they premiered the movie he orchestrated, we got to see it before anyone but the crew."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allergic','adj.过敏的，变态反应的；对…讨厌的','[ə.ˈlɜː.dʒɪk]','[ə.ˈlɜː.dʒɪk]','noun',["I am allergic to cats."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oceanographer','n.海洋学者','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anecdote','n.秘闻；轶事，趣闻','/ˈæ.nɪk.doʊt/','/ˈæ.nɪk.doʊt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('officious','adj.爱发号施令的，爱指手画脚的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('infiltrate','v.渗入，渗透；悄悄进入，潜入','/ˈɪnfɪltɹeɪt/','/ɪnˈfɪltɹeɪt/','noun',["High-grade tumors often infiltrate surrounding structures."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hostile','adj.不友好的，敌意的；敌方的','/ˈhɒstaɪl/','/ˈhɑstaɪl/','noun',["a hostile country","Microsoft may go hostile in its bid for Yahoo as soon as Friday, according to a published report."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flora','n.植物群','/ˈflɔː.ɹə/','/ˈflɔː.ɹə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('celestial','adj.天空的，天上的','/səˈlɛstiəl/','/səˈlɛstiəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decode','vt.译，解，破译','/diːˈkəʊd/','/diːˈkəʊd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bruise','v.出现伤痕；挫伤n.伤痕，擦痕，青肿','/bɹuːz/','/bɹuːz/','noun',["Bananas bruise easily.","I bruise easily."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crawl','v.缓慢行进；爬行n.缓慢的速度','/kɹɔl/','/kɹɔl/','noun',["My computer has slowed down to a crawl since I installed that software package.","Clutching my wounded side, I crawled back to the trench.","The rush-hour traffic crawled around the bypass."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unaided','adj.未受协助的，独立的','','','adjective',["Fleas are difficult to see with the unaided eye."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambitious','adj.有雄心的，有野心的','/æmˈbɪʃ.əs/','/æmˈbɪʃ.əs/','adjective',["an ambitious person","an ambitious attempt to take power"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('academic','adj.学术的；学校的，学院的；纯理论的n.大学教师','/ˌækəˈdɛmɪk/','/ˌækəˈdɛmɪk/','noun',["the academic sect or philosophy","I have always had an academic interest in hacking.","I''m more academic than athletic — I get lower marks in phys. ed. than in anything else."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coral','adj.珊瑚色的，红色的n.珊瑚','/ˈkɒɹəl/','/ˈkɒɹəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delinquency','n.行为不良；过失，失职','/dɪˈlɪŋkwənsi/','/dɪˈlɪŋkwənsi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pipe','vt.用管道输送；用线路系统传输n.管子，管道；烟斗','/paɪp/','/paɪp/','noun',["to pipe flowers on to a cupcake"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pliant','adj.柔软的；温顺的；易受影响的','/ˈplaɪənt/','/ˈplaɪənt/','adjective',["a pliant thread  pliant wax"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revere','vt.尊敬，敬畏','/ɹə.viːɹ/','/ɹə.viːɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sneaky','adj.偷偷摸摸的，鬼鬼祟祟的','/ˈsniːki/','/ˈsniːki/','noun',["Catching those thieves will be hard: they''re so sneaky!","They played a sneaky trick on us."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('longitude','n.经度，经线','/-tʃuːd/','/ˈlɑndʒəˌtud/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lax','adj.懒散的；不严格的，马虎的','/læks/','/læks/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patriot','n.爱国者','/ˈpeɪ.tɹi.ət/','/ˈpeɪ.tɹi.ət/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pernicious','adj.有害的，恶性的','/pəˈnɪʃəs/','/pəˈnɪʃəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revert','v.恢复；归还，归属','/ɹɨˈvɜːt/','/ɹɨˈvɜːt/','noun',["We''ve found that git reverts are at least an order of magnitude faster than SVN reverse merges.","If they attack, we will revert to the bunker.","When a book goes out of print, rights revert from the publisher to the author."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cohabitation','n.同居，同住','/koʊhæbɪˈteɪʃən/','/koʊhæbɪˈteɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adventure','n.奇遇；冒险活动','/ædˈvɛnt͡ʃɚ/','/ædˈvɛnt͡ʃɚ/','noun',["A life full of adventures.","his sense of adventure"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('idyllic','adj.田园诗般的，田园风光的，牧歌的','/ɪˈdɪlɪk/','/aɪˈdɪlɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hawk','n.鹰，隼；主战分子vt.叫卖，兜售','/hɔːk/','/hɔk/','noun',["It is illegal to hunt hawks or other raptors in many parts of the world.","to hawk at flies"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('speckle','v.弄上斑点；点缀n.斑点；色斑','/ˈspɛkəl/','/ˈspɛkəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emanate','v.散发；表现，显示','/ˈɛm.ə.ˌneɪt/','/ˈɛm.ə.ˌneɪt/','verb',["Fragrance emanates from flowers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exterior','adj.外部的，外表的n.外部，外表','/ɛkˈstɪəɹɪə/','/ɛkˈstɪəɹɪə/','noun',["The sticker was attached to the exterior of the package","She is our new minister of the exterior","the exterior part of a sphere"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('captivity','n.囚禁，拘留','/kæpˈtɪvɪti/','/kæpˈtɪvɪti/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('levy','vt.征收n.征收额；税款；征兵','/ˈlɛ.vi/','/ˈlɛ.vi/','noun',["to levy a tax","to levy a mill, dike, ditch, a nuisance, etc."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('effective','adj.有效的，生效的；显著的；实际的，事实上的','/əˈfɛktɪv/','/əˈfɛktɪv/','noun',["The pill is an effective method of birth control.","The president delivered an effective speech!","How long does it take to make a bunch of civilians an effective military force?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generous','adj.慷慨的，大方的；大量的，丰富的；宽厚的，宽宏大量的','/ˈdʒɛn(ə)ɹəs/','/ˈdʒɛn(ə)ɹəs/','adjective',["Thank you for your generous words.","She''s been extremely generous with her winnings.","Add a generous helping of mayonnaise."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flux','n.变迁，不断的变动','/flʌks/','/flʌks/','noun',["Languages, like our bodies, are in a continual flux.","It is important to use flux when soldering or oxides on the metal will prevent a good bond.","That high a neutron flux would be lethal in seconds."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jelly','n.果冻，胶状物','/ˈd͡ʒɛl.i/','/ˈd͡ʒɛl.i/','noun',["calf''s-foot jelly"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('probe','v.探查，探测；盘问，追问n.探针；探测器；探索，调查','/pɹəʊb/','/pɹəʊb/','noun',["They launched a probe into the cause of the accident.","Insert the probe into the soil and read the temperature.","If you probe further, you may discover different reasons."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crescent','adj.新月形的；逐渐增强的n.新月；新月形，月牙形','/ˈkɹɛ.sənt/','/ˈkɹɛ.sənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inflate','v.充气，膨胀；鼓吹，吹捧；涨价','/ɪnˈfleɪt/','/ɪnˈfleɪt/','verb',["You inflate a balloon by blowing air into it.","The balloon will inflate if you blow into it.","to inflate somebody with pride or vanity"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quantitative','adj.数量的，定量的','/ˈkwɒntətɪv/','/ˈkwɒntətɪv/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clamor','n.吵闹，喧哗','/ˈklæm.ə/','/ˈklæm.ɚ/','noun',["Anyone who tastes our food seems to clamor for more.","Thousands of demonstrators clamoring the government''s resignation were literally deafening, yet their cries fell in deaf ears","After a confused murmur the audience soon clamored"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harness','vt.利用…产生动力；给上挽具n.马具','/ˈhɑː(ɹ).nəs/','','noun',["They harnessed the horse to the post.","Imagine what might happen if it were possible to harness solar energy fully."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foment','vt.煽动，挑起，激起','/fəʊˈmɛnt/','/foʊˈmɛnt/','noun',["Foreign governments have tried to foment unrest."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incident','n.事情，事件；摩擦，冲突','/ˈɪn.sɪ.dənt/','/ˈɪn.sɪ.dənt/','noun',["It was an incident that he hoped to forget.","The incident light illuminated the surface."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attire','n.穿着，服饰vt.给…穿衣，打扮','/əˈtaɪə(ɹ)/','/əˈtaɪə(ɹ)/','noun',["He stood there, attired in his best clothes, waiting for applause."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tug','v.拖，','/tʌɡ/','/tʌɡ/','noun',["He had a quick tug to calm himself down before his date.","The police officers tugged the drunkard out of the pub.","He lost his patience trying to undo his shoe-lace, but tugging it made the knot even tighter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neuron','n.神经元，神经细胞','/ˈnjəɹɑn/','/ˈnjəɹɑn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concert','n.音乐会，演奏会；一致','','/ˈkɒnsət/','noun',["I''m going to the rock concert on Friday."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supply','n.供应；储备；补给vt.供给，供应；满足，弥补','/səˈplaɪ/','/səˈplaɪ/','noun',["supply and demand","A supply of good drinking water is essential.","to vote supplies"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circulate','v.循环；流通；传播，流传','/ˈsɚˌkju.leɪt/','/ˈsɚˌkju.leɪt/','verb',["to circulate money or gossip"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incubate','v.孵化；培育；潜伏','/ˈɪŋkjʊbeɪt/','/ˈɪŋkjʊbeɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rectify','vt.矫正，纠正；整顿','/ˈɹɛktəˌfaɪ/','/ˈɹɛktəˌfaɪ/','verb',["to rectify the crisis"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('antonym','n.反义词','/ˈæntəˌnɪm/','/ˈæntəˌnɪm/','noun',["“rich” is an antonym of “poor”; “full” is an antonym of “empty”"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('integrity','n.正直；完整','/ɪnˈtɛɡɹəti/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refrain','v.抑制；戒除n.反复句，副歌','/ɹɪˈfɹeɪn/','/ɹɪˈfɹeɪn/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pact','n.协议，条约，公约','/pækt/','/pækt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notation','n.符号，记号','/noʊˈteɪʃən/','/noʊˈteɪʃən/','noun',["The notations used in the two books differed. (Using notation would be incorrect).","She made a notation in the margin of the book."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liable','adj.有责任的，有义务的；易于…的','/ˈlaɪ̯əbəl/','/ˈlaɪ̯əbəl/','adjective',["1748. David Hume. Enquiries concerning the human understanding and concerning the principles of moral. London: Oxford University Press, 1973. § 34.","A man liable to heart disease.","Someone is liable to slip on your icy sidewalk."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('homing','adj.有返回原地本能的','/ˈhəʊmɪŋ/','/ˈhəʊmɪŋ/','verb',["The dog homed.","The missile was able to home in on the target."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('state','v.陈述，说明，声明；规定n.情况，状况；国家；州','/steɪt/','/steɪt/','noun',["He stated that he was willing to help.","State your intentions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cargo','n.货物','/ˈkɑːɡəʊ/','/ˈkɑɹɡoʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jumble','vt.混杂，掺杂n.杂乱的一堆，混乱的一团','','','noun',["I tried to study, but in my half-awake state, all of the concepts seemed to jumble together."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('element','n.元素，要素，组成部分；','/ˈɛlɪmənt/','/ˈɛlɪmənt/','noun',["Letters are the elements of written language.","an element of doubt;  an element of the picture","exposed to the elements"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('environmental','adj.有关环境的，自然环境的，生态环境的；环境的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('picky','adj.挑剔的，难以取悦的','/ˈpɪki/','/ˈpɪki/','noun',["I am very picky about the way my kitchen is laid out."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crustacean','adj.甲壳类的n.甲壳类动物','/kɹʌsˈteɪʃən/','/kɹʌsˈteɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exclaim','v.惊叫，呼喊','/ɛkˈskleɪm/','/ɛkˈskleɪm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('restraint','n.抑制，克制；限制；约束力；管制措施','/ɹɪˈstɹeɪnt/','/ɹɪˈstɹeɪnt/','noun',["Make sure all the restraints are tight.","Try to exercise restraint when talking to your boss."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aftermath','n.后果，余波','/ˈæf.təˌmæθ/','/ˈæf.tɚˌmæθ/','noun',["In contrast to most projections of the aftermath of nuclear war, in this there is no rioting or looting."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('untapped','adj.未开发的，未使用的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('effluent','n.流出物，废水，污水','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('untamed','adj.未驯服的，难驾驭的','/ʌnˈteɪmd/','/ʌnˈteɪmd/','adjective',["The mustang is an untamed horse that roams where it wants, with little interest in humans."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stereotype','n.陈规；固定形式，老套；刻板印象vt.对…形成固定看法','/ˈstɛ.ɹi.əˌtaɪp/','/ˈstɛ.ɹi.əˌtaɪp/','noun',["to stereotype the Bible"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enroll','v.登记，注册；招收','/ɪnˈɹəʊl/','/ɪnˈɹəʊl/','verb',["They were eager to enroll new recruits.","Have you enrolled in classes yet for this term?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sweeping','adj.彻底的，广泛的；〈贬〉笼统的，一概而论的n.清扫，扫除；垃圾','/ˈswiːpɪŋ/','/ˈswiːpɪŋ/','verb',["to sweep a floor, the street, or a chimney","The offended countess swept out of the ballroom.","She swept the peelings off the table onto the floor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ardent','adj.热心的，热情洋溢的','/ˈɑːdənt/','/ˈɑɹdənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cohesive','adj.黏着的；使凝结的，使内聚的','/ˈkəʊ.hiː.sɪv/','/koʊˈhiː.sɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('battery','n.电池；排炮；一系列，一批','/ˈbætəɹi/','/ˈbætəɹi/','noun',["Schoolchildren take a battery of standard tests to measure their progress."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('irreverent','adj.不敬的','','','adjective',["an irreverent examination of reviewing"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('façade','n.正面；表面','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('divorce','v.与…离婚；使分离，使脱离n.离婚；分离，脱离','/dɪˈvɔːs/','/dɪˈvɔːs/','noun',["Richard obtained a divorce from his wife some years ago, but hasn''t returned to the dating scene.","The Civil War split between Virginia and West Virginia was a divorce based along cultural and economic as well as geographic lines.","A ship captain can marry couples, but cannot divorce them."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cornerstone','n.墙角石，奠基石；基础','','','noun',["The cornerstone on the Flatiron Building is set on the Fifth Avenue facade.","Exceptional service is the cornerstone of the hospitality industry."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quiz','n.小测验；智力竞赛vt.测验；盘问，查问，询问','/kwɪz/','/kwɪz/','noun',["We came second in the pub quiz."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consolidate','v.巩固；合并','/kənˈsɒlɪdeɪt/','','verb',["He consolidated his luggage into a single large bag."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('biochemical','adj.生物化学的，生化的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('librarian','n.图书馆馆长；图书管理员','/laɪˈbɹɛɹ.i.ən/','/laɪˈbɹɛɹ.i.ən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contour','n.等高线；轮廓','/-tɔː(ɹ)/','/-tɔː(ɹ)/','noun',["the low drag contour of a modern automobile"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lyric','adj.抒情的n.抒情诗；','/ˈlɪɹ.ɪk/','/ˈlɪɹ.ɪk/','noun',["The lyric in line 3 doesn''t rhyme."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suborn','vt.收买，买通，唆使','/səˈbɔːn/','/səˈbɔːn/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clan','n.家族，宗族，氏族；帮派','/klæn/','/klæn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('purple','adj.紫色的n.紫色','/ˈpɜː(ɹ).pəl/','/ˈpɝpəl/','noun',["to put on the imperial purple","the banded purple"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quit','v.停止；放弃；离开；辞','/kwɪt/','/kwɪt/','verb',["After having to work overtime without being paid, I quit my job.","John is planning to quit smoking."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clam','n.蛤，蛤肉；〈口〉守口如瓶的人，寡言的人','/klæm/','/klæm/','noun',["Those sneakers cost me fifty clams!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('economical','adj.经济的，实惠的；节俭的，节约的；精打细算的','/ˌɛkəˈnɒmɪkəl/','/ˌɛkəˈnɑmɪkəl/','adjective',["He was an economical person by nature.","The new, eco-friendly bicycle was an economical purchase."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('polish','v.磨光，擦亮；修改，润色n.上光剂','/ˈpɒlɪʃ/','/ˈpɑlɪʃ/','noun',["A good silver polish will remove tarnish easily.","The floor was waxed to a high polish.","The lecturer showed a lot of polish at his last talk."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cabinet','n.内阁；储藏柜，陈列柜','/ˈkæ.bɪ.nɪt/','/ˈkæ.bɪ.nɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ordinal','adj.序数的；顺序的n.序数词','/ˈɔː(ɹ).dɪ.nəl/','/ˈɔː(ɹ).dɪ.nəl/','noun',["The most common numerals in Latin, as in English, are the \"cardinals\"...and the \"ordinals\"... — F. M. Wheelock, Wheelock’s Latin, 6th ed. revised (2005), p97"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insurance','n.保险；保险费；保险业','/ɪn.ˈʃɔː.ɹəns/','/ɪn.ˈʃɝ.əns/','noun',["The car was totalled, but fortunately I had insurance.","After five years in banking, I switched to insurance.","The sky was clear, but I took my umbrella for insurance."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tedious','adj.单调乏味的，令人厌烦的','/ˈtiː.dɪəs/','/ˈti.di.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('source','n.源，源泉；来源，出处；信息来源','/sɔːs/','/sɔɹs/','noun',["The accused refused to reveal the source of the illegal drugs she was selling.","The main sources of the Euphrates River are the Karasu and Murat Rivers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('telecommunication','n.电信','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('detergent','adj.净化的，清洁的n.清洁剂','/dɪˈtɜːdʒənt/','/dɪˈtɜːdʒənt/','adjective',["Apply the cleansing cream to your skin."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glare','v.怒目而视；发出刺眼的光n.耀眼的光；怒视，瞪眼','/ɡlɛə/','/ɡlɛə/','noun',["a glare of ice","He walked in late, with the teacher glaring at him the whole time.","The sun glared down on the desert sand."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deception','n.骗局；诡计；欺骗，欺诈','/dɪˈsɛpʃən/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compile','vt.汇编；编辑，编纂','/kəmpʌɪl/','/kəmpʌɪl/','noun',["Samuel Johnson compiled one of the most influential dictionaries of the English language.","After I compile this program I''ll run it and see if it works.","There must be an error in my source code because it won''t compile."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bias','n.偏见，偏心vt.使有偏见，使偏心','/ˈbaɪəs/','/ˈbaɪəs/','noun',["Our prejudices bias our views.","to cut cloth bias"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fume','vi.冒烟；大为恼火','/fjuːm/','','noun',["Don''t stand around in there breathing the fumes while the adhesive cures.","Lead fume is a greyish powder, mainly comprising lead sulfate.","the fumes of passion"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('budget','v.做预算adj.价格低廉的n.预算','/ˈbʌdʒ.ɪt/','/ˈbʌdʒ.ɪt/','noun',["Budgeting is even harder in times of recession","The PM’s pet projects are budgeted rather generously","The prestigious building project is budgeted in great detail, from warf facilities to the protocollary opening."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radiate','v.辐射，发射；流露，显示；自中心向各方伸展','/ˈɹeɪdi.ət/','/ˈɹeɪdi.ət/','noun',["The stove radiates heat.","The heat radiates from a stove.","a radiate crystal"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tenuous','adj.纤细的；稀薄的；脆弱的','/ˈtɛn.ju.əs/','/ˈtɛn.ju.əs/','adjective',["Far from being amicable, the numbers seemed to turn their backs on each other, and I couldn''t find a pair with even the most tenuous connection.","His argument was not convincing in the debate, considering how tenuous it was."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('campus','n.校园','/ˈkæmpəs/','/ˈkæmpəs/','noun',["The campus is sixty hectares in size.","During the late 1960s, many an American campus was in a state of turmoil."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ultimate','adj.最后的，最终的；根本的n.最好的事物；最大的或最先进的事物','/ˈʌltɪmɪt/','/ˈʌltɪmɪt/','noun',["the ultimate disappointment","an ultimate constituent of matter"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prosecute','v.起诉，控告，检举；担任控方律师；继续从事','/ˈpɹɒsɪkjuːt/','/ˈpɹɒsɪkjuːt/','verb',["to prosecute a man for trespass, or for a riot","to prosecute a right or a claim in a court of law","to prosecute a scheme, hope, or claim"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arboreal','adj.树栖的；树木的','/ɑɹˈbɔɹi.əl/','/ɑɹˈbɔɹi.əl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pepper','n.胡椒；辣椒vt.撒胡椒粉；大量给予','/ˈpɛpə/','/ˈpɛpə/','noun',["Some ballparks have signs saying \"No pepper games\".","After the hailstorm, the beach was peppered with holes.","He liked to pepper his conversation with long words."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mellow','adj.醇香的；柔和的；成熟的v.醇香；柔和；成熟','/ˈmɛləʊ/','/ˈmɛloʊ/','noun',["The fervour of early feeling is tempered and mellowed by the ripeness of age.","a mellow apple","a mellow soil"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impersonal','adj.没有人情味的，冷淡的；客观的','','/ɪmˈpɝsənəl/','noun',["She sounded impersonal as she gave her report of the Nazi death camps.","The verb “rain” is impersonal in sentences like “It’s raining.”"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salamander','n.火蜥蜴；火蛇','/ˈsæləˌmændə/','/ˈsæləˌmændə/','noun',["The chef first put the steak under the salamander to sear the outside."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stark','adv.十足adj.赤裸的；严酷的，严峻的；明显的，鲜明的；十足的，极端的','/stɑːk/','/stɑɹk/','adjective',["I picked my way forlornly through the stark, sharp rocks.","A flower was growing, in stark contrast, out of the sidewalk.","He''s gone stark, staring mad."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hitch','v.搭便车；提起，拉起；拴住n.故障，障碍','/hɪtʃ/','/hɪtʃ/','noun',["His truck sported a heavy-duty hitch for his boat.","The banquet went off without a hitch","The deal sounds too good to be true. What''s the hitch?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('furry','adj.毛皮似的；盖着毛皮的；生苔的','/ˈfɜːɹi/','/ˈfɜːɹi/','noun',["What percentage of furries are wolves?","The furry had designed an elaborate costume.","His treatment of our furry friends was nothing short of appalling."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cranial','n.头盖骨的，颅骨的','/ˈkɹeɪni.əl/','/ˈkɹeɪni.əl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('teem','vi.充满，到处都是','/tiːm/','/tiːm/','verb',["Fish teem in this pond."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anomie','n.社会道德沦丧，失范；混乱','/ˈænəmiː/','/ˈænəmiː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chlorine','n.氯','/ˈklɔːɹiːn/','/ˈklɔɹin/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stylish','adj.漂亮的，时髦的；高雅的，有格调的','/ˈstaɪlɪʃ/','/ˈstaɪlɪʃ/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('marvel','v.对…感到惊异，大为赞叹n.令人惊异的人，奇迹；不凡的成果','/ˈmɑːvl̩/','/ˈmɑɹvl̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('silicon','n.硅','/ˈsɪləkɑn/','/ˈsɪləkɑn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('silicate','n.硅酸盐','/ˈsɪlɪkeɪt/','/ˈsɪlɪkeɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recipient','n.接受者，收受者','/ɹəˈsɪp.i.ənt/','/ɹəˈsɪp.i.ənt/','noun',["My e-mail never reached the intended recipient."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mesmerize','vt.施催眠术；使入迷，迷住','/ˈmɛzməɹaɪz/','/ˈmɛzməɹaɪz/','verb',["She mesmerized the audience with her tricks"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stash','vt.隐藏，藏匿n.贮藏物','/stæʃ/','/stæʃ/','noun',["They had quite a stash of food saved up for emergencies.","The dealers managed to store the dope in the stash just in time to avoid being caught by the police.","He stashed his liquor in the cabinet under the bar."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parking','n.机动车停放；停车场','/ˈpɑːkɪŋ/','/ˈpɑːkɪŋ/','verb',["I parked the drive heads of my hard disk before travelling with my laptop.","Let''s park that until next week''s meeting.","to park artillery, wagons, automobiles, etc."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('studio','n.工作室，画室；摄影室，演播室，录音室；练习室；电影公司','/ˈstjuːdiəʊ/','/ˈstudioʊ/','noun',["His studio was cramped when he began as an artist.","As he gained a reputation, he took larger space and took students into his studio,","The recording studio had some slight echo, but was good enough to make a demo."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incur','vt.招致，招惹，遭受','/ɪnˈkəː/','/ɪnˈkɝ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plump','adj.微胖的；丰满的','/plʌmp/','/plʌmp/','verb',["Her cheeks have plumped.","to plump oysters or scallops by placing them in fresh or brackish water","to plump a stone into water"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abreast','adv.并列地，并排地','/əˈbɹɛst/','/əˈbɹɛst/','adjective',["to keep abreast of [or with] the present state of science.","She believes it is important to keep abreast of new scientific developments.","This ship sank abreast the island."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recoil','vi.弹回；后退，退缩；产生后坐力n.后退，退缩；反冲，后坐力','/ˈɹiːkɔɪl/','/ˈɹiːkɔɪl/','noun',["the recoil of nature, or of the blood","He recoiled in disgust when he saw the mess."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interactive','adj.交互式的；合作的，互相配合的','','/ɪntɚˈæktɪv/','noun',["interactive teaching methods","interactive user interface"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('listless','adj.倦怠的，没精打采的','/ˈlɪstləs/','/ˈlɪstləs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complementary','adj.补充的；互补的','/ˌkɒmplɪ̈ˈmɛnt(ə)ɹi/','/ˌkɒmplɪ̈ˈmɛnt(ə)ɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consistency','n.浓度，密度；一致性，协调；连接，结合','/kənˈsɪst(ə)nsi/','/kənˈsɪstənsi/','noun',["They want to achieve a high degree of consistency in their process and their product.","Mix it until it has the consistency of a thick paste."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ordeal','n.折磨；严峻考验','/ɔɹˈdil/','/ɔɹˈdil/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wispy','adj.成束的；纤细的','/ˈwɪspi/','/ˈwɪspi/','adjective',["The wispy smoke rose from chimneys all around town."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('premise','n.房屋和地基，经营场址；前提，假设','/ˈpɹɛ.mɪs/','/ˈpɹɛ.mɪs/','noun',["trespass on another’s premises"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tenant','n.房客，承租人vt.居住','/ˈtɛ.nənt/','/ˈtɛ.nənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pale','vi.变得苍白，变得暗淡adj.苍白的；淡色的；暗淡的，微弱的','/peɪl/','/peɪl/','noun',["I have pale yellow wallpaper.","His face turned pale after hearing about his mother''s death.","He is but a pale shadow of his former self."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hardware','n.五金制品，金属制品；硬件','/ˈhɑːdˌwɛə/','/ˈhɑɹdˌwɛɹ/','noun',["military hardware"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('batter','v.连续猛击n.击球手；面糊','/ˈbætə(ɹ)/','/ˈbætəɹ/','verb',["The firemen battered down the door.","I prefer it when they batter the cod with breadcrumbs.","Leeds United battered Charlton 7-0."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wretch','n.不幸的人；恶棍，无赖','/ɹɛtʃ/','/ɹɛtʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('priority','n.优先权，优先；优先考虑的事，最重要的事','/pɹaɪˈɒɹɨti/','/pɹaɪˈɒɹɨti/','noun',["He set his e-mail message''s priority to high.","She needs to get her priorities straight and stop playing games.","In bankruptcy law, a business'' debt to its employees has priority over its debt to a landlord, so the employees must be paid first."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('creative','adj.有创造力的，创造性的','/kɹiˈeɪtɪv/','/kɹiˈeɪtɪv/','noun',["He is a visionary creative.","I''ve included in my portfolio all the creative I''ve completed in my five year design career.","a creative dramatist who avoids cliche"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mythology','n.神话；神话学；虚幻的想法','/mɪˈθɒlədʒi/','/mɪˈθɑlədʒi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shuttle','v.穿梭往返；短程往返运送n.航天飞机；梭子；航班','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allocate','vt.分配，分派，把…拨给','/ˈæl.ə.keɪt/','/ˈæl.ə.keɪt/','verb',["The bulk of K–12 education funds are allocated to school districts that in turn pay for the cost of operating schools."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bagel','n.硬面包圈','/bæ.ɡɫ̩/','/ˈbeɪɡəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enterprise','n.企业，公司；事业','/ˈɛntɚˌpɹaɪz/','/ˈɛntɚˌpɹaɪz/','noun',["A micro-enterprise is defined as a business having 5 or fewer employees and a low seed capital.","Biosphere 2 was a scientific enterprise aimed at the exploration of the complex web of interactions within life systems.","He has shown great enterprise throughout his early career."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ventilation','n.通风设备；空气流通','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('psychoanalysis','n.心理分析，精神分析','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bilingualism','n.双语现象','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('competence','n.能力，胜任；权限；技能','/ˈkɒmpətəns/','/ˈkɒmpətəns/','noun',["That question is out with the competence of this court and must be taken to a higher court."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fuse','v.融合；熔接；熔化；因保险丝烧断而断电；合并n.保险丝；引信；导火线','/fjuːz/','/fjuːz/','noun',["When talking about being laid off, he has a short fuse."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frivolous','adj.琐碎的，无关紧要的；愚蠢的，可笑的；无聊的，不严肃的，轻佻的','/ˈfɹɪv.əl.əs/','/ˈfɹɪv.əl.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pretext','n.借口，托词','/ˈpɹiːtɛkst/','/ˈpɹiːtɛkst/','noun',["The reporter called the company on the pretext of trying to resolve a consumer complaint.","The spy obtained his phone records using possibly-illegal pretexting methods."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emergent','adj.突现的；新兴的；紧急的','/ɪ.ˈmɜː.dʒənt/','/ɪ.ˈmɜː.dʒənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assure','vt.确保；使确信','/əˈʃɔː/','/əˈʃɝ/','verb',["He assured of his commitment to her happiness."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consult','v.请教；商议；参考，翻阅','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('funding','n.基金，资金；提供资金','/ˈfʌndɪŋ/','/ˈfʌndɪŋ/','verb',["He used his inheritance to fund his gambling addiction.","The council is providing funding to the church to repair the roof."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rudimentary','adj.未充分发展的，原始的；基本的，基础的','/ˌɹuːdɪˈmɛntəɹi/','/ˌɹuːdɪˈmɛntəɹi/','noun',["I have only a rudimentary grasp of chemistry.","His grasp of rudimentary English allowed him at least to do the shopping."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adversary','n.对手，敌手','/ædˈvɜː.sə.ɹi/','/ˈæd.vəɹ.sɛɹi/','noun',["He prepared to fight his adversary."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('infest','vt.大批滋生，大批出没于','/ɪnˈfɛst/','/ɪnˈfɛst/','noun',["Insects are infesting my basement!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('satiric','adj.讽刺的，嘲讽的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eternal','adj.永恒的，不朽的','/ɪˈtɜːnəl/','/ɪˈtɝnəl/','noun',["some eternal villain"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crumple','v.变皱，起皱；破裂；崩溃，垮台','/ˈkɹʌmpəl/','/ˈkɹʌmpəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prevalent','adj.流行的，普遍的','/ˈpɹɛvələnt/','/ˈpɹɛvələnt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cling','vi.附着，黏住；紧紧抓住；挨近','/ˈklɪŋ/','/ˈklɪŋ/','noun',["Seaweed clung to the anchor.","Wood clings."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clip','v.夹住，扣住；修剪；剪下n.夹子，回形针，别针；弹夹，弹仓；电影片段，剪报','/klɪp/','/klɪp/','noun',["Use this clip to attach the check to your tax form.","He was walking at a fair clip and I was out of breath trying to keep up.","Please clip the photos to the pages where they will go."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oasis','n.绿洲；避风港','/əʊˈeɪsəs/','/oʊˈeɪsəs/','noun',["The park was an oasis in the middle of the busy city."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outlaw','vt.宣布…为非法n.罪犯，歹徒，亡命之徒；被剥夺法律权益者','','','noun',["The main character in the play was a bit of an outlaw who refused to shake hands or say thank you.","to outlaw a debt or claim","Laws outlawed by necessity. — Fuller."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shrivel','v.枯萎','/ˈʃɹɪvəl/','/ˈʃɹɪvəl/','verb',["The plant shrivelled from lack of water.","His fingers were shriveled from being in the bath for too long.","The hot sun shrivelled the leaves."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('encrust','v.在表面形成硬壳，结壳；用…装饰外层','','','verb',["a doughnut encrusted with sugar","The jeweller encrusted the ring with gems."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('upsurge','n.高涨；激增','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bloom','v.开花n.花；开花；青春焕发','/bluːm/','/bluːm/','noun',["The cherry trees are in bloom.","the bloom of youth","the rose-red cobalt bloom"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('denote','v.表示，意指；标示，预示，象征','/dɪˈnəʊt/','/dɪˈnoʊt/','verb',["The yellow blazes denote the trail."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('audible','adj.听得见的','/ˈɔːdɪbl̩/','/ˈɔːdɪbl̩/','noun',["The audible changed the play to a run.","The quarterback audibled after seeing the defensive formation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exhort','vt.劝告，规劝，告诫','/ɛɡˈzɔːt/','/ɛɡˈzɔːt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('propagate','v.繁殖；散布，传播','/ˈpɹɒpəˌɡeɪt/','/ˈpɹɒpəˌɡeɪt/','verb',["to propagate sound or light","It takes 24 hours for password changes to propagate throughout the system.","The server propagates the password file at midnight each day."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('checked','adj.格子花纹的；棋盘状的','/tʃɛkt/','/tʃɛkt/','verb',["Check the oil in your car once a month.","Check off the items that you''ve checked (inspected).","Check your enthusiasm during a negotiation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('necessitate','vt.需要，使成为必要','/nɪˈsɛsɪteɪt/','/nɪˈsɛsɪteɪt/','verb',["The early departure of her plane necessitated her waking up at 4 a.m."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('orthodox','adj.传统的；正统的','/ˈɔːθədɒks/','/ˈɔːɹθədɑks/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depredation','n.劫掠，掠夺，破坏','/ˌdɛpɹəˈdeɪʃən/','/ˌdɛpɹəˈdeɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambush','n&vt.埋伏，伏击','/ˈæm.bʊʃ/','/ˈæm.bʊʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jewelry','n.〈总称〉首饰；珠宝','','','noun',["She had more jewellery ornamented about her than any three ladies needed."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('statesman','n.政治家','/ˈsteɪtsmən/','/ˈsteɪtsmən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quadruple','v.成四倍adj.四部分组成的；四倍的n.四倍','/ˈkwɒdɹʊpl/','/kwɑˈdɹupəl/','verb',["Quadrupling four gives sixteen.","Our profits quadrupled when we made the improvements.","He''s quite an athlete and can do quadruple jumps with ease."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adept','adj.熟练的，精通的，内行的n.行家，熟手','/əˈdɛpt/','','noun',["adepts in philosophy"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curiosity','n.好奇心，求知欲；罕见而有趣之物，珍品','/ˌkjʊəɹɪˈɒsɪti/','/ˌkjʊəɹɪˈɒsɪti/','noun',["He put the strangely shaped rock in his curiosity cabinet."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repute','v.称为，认为n.名声，名誉','/ɹɪˈpjuːt/','/ɹɪˈpjuːt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nimble','adj.敏捷的，灵活的','/ˈnɪmbl̩/','/ˈnɪmbl̩/','adjective',["nimble fingers","He was too nimble for the assailant and easily escaped his grasp.","She has a nimble mind and can improvise in any situation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amiable','adj.可爱的；友好的，和蔼的，亲切的','/ˈeɪ.mi.ə.bəl/','/ˈeɪ.mi.ə.bəl/','adjective',["amiable ideas","an amiable person"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sacrifice','v.牺牲，献出；以…做祭献n.牺牲，献身；献祭，祭品','/ˈsækɹɪfaɪs/','/ˈsækɹɪfaɪs/','noun',["the sacrifice of one''s spare time in order to volunteer","Venison has many advantages over meat from factory farms, although it still requires a hunter to sacrifice the life of a deer."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('particular','adj.特定的；独特的；详细的；挑剔的n.详情，细目','/pəˈtɪkjələ/','/pəˈtɪkjələ/','noun',["I couldn''t find the particular model you asked for, but I hope this one will do.","I don''t appreciate your particular brand of cynicism.","He brought no particular news."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corps','n.军团，兵团；特种部队；一群人，一组人','','','noun',["White House press corps"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pause','n&v.中止，暂停','/pɔːz/','/pɔz/','noun',["Teach the pupil to mind the pauses.","When telling the scary story, he paused for effect.","to pause a song, a video, or a computer game"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rainbow','n.彩虹','/ˈɹeɪnbəʊ/','/ˈɹeɪmboʊ/','noun',["a rainbow of possibilities","Many electoral promises are rainbows, vanishing soon after poll day."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instructor','n.导师，讲师；教练，指导员','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fervor','n.热情，热烈','/ˈfɝvɚ/','/ˈfɝvɚ/','noun',["The coach trains his water polo team with fervor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ample','adj.富足的，充足的，丰富的；宽敞的','/ˈæm.pəl/','/ˈæm.pəl/','adjective',["an ample house","ample material","an ample story"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cohesion','n.内聚力；凝聚力；团结，结合','','/koʊˈhiʒən/','noun',["Unit cohesion is important in the military."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entertain','v.招待，款待；使快乐，娱乐','/ˌɛntəˈteɪn/','/ˌɛntɚˈteɪn/','noun',["The motivational speaker not only instructed but also entertained the audience.","They enjoy entertaining a lot.","The committee would like to entertain the idea of reducing the budget figures."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ease','v.缓和，减轻n.不费力，容易；悠闲，自在','/iːz/','/iz/','noun',["He eased his conscience by confessing.","He loosened his shoe to ease the pain.","The provision of extra staff eased their workload."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('condiment','n.调味品','/ˈkɒn.dɪ.mənt/','/ˈkɒn.dɪ.mənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('certitude','n.确定，确信；必然性','/ˈsɜːtɪtjuːd/','/ˈsɜːtɪtjuːd/','noun',["I have absolute certitude about that.","Taxes are obviously certitudes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overrun','v.超过，溢出；泛滥；横行n.泛滥；超出的部分','/əʊvəˈɹʌn/','/əʊvəˈɹʌn/','noun',["At least this year''s overrun isn''t as unmanageable as last year!","The vine overran its trellis; the field is overrun with weeds.","One line overruns another in length."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deceptive','adj.欺骗性的，导致误解的','/dɪ.ˈsɛp.tɪv/','/dɪ.ˈsɛp.tɪv/','adjective',["Appearances can be deceptive."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mathematics','n.数学','/mæθ(ə)ˈmætɪks/','/mæθ(ə)ˈmætɪks/','noun',["My mathematics is always improving."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reactor','n.反应堆','/ɹiːˈæktə/','/ɹiːˈæktə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cookout','n.野外烧烤宴会','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('envision','vt.想象，展望，预想','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outcry','n.大声疾呼，强烈的抗议','/ˈaʊtkɹaɪ/','/ˈaʊtkɹaɪ/','noun',["His appearance was greeted with an outcry of jeering.","The proposal was met with a public outcry.","to send goods to an outcry"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paddle','v.用桨划船；涉水，戏水n.桨；桡足','/ˈpæ.dəl/','/ˈpæ.dəl/','noun',["We had a nice paddle this morning.","The paddle practically ousted the British cane for spankings in the independent US.","A sea turtle''s paddles make it swim almost as fast as land tortoises are slow."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reschedule','vt.重新计划，重订…的时间表','','','verb',["We''ll have to reschedule next Monday''s meeting because of the public holiday."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('somber','adj.昏暗的；忧郁的','/ˈsɒmbə/','/ˈsɑmbɚ/','verb',["a sombre situation"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('synonym','n.同义词','/ˈsɪnənɪm/','/ˈsɪnənɪm/','noun',["“Happy” is a synonym of “glad”."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equitable','adj.公平的，公正的','/ˈɛk.wɪ.tə.bəl/','/ˈɛk.wɪ.tə.bəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inconspicuous','adj.不引人瞩目的，不显眼的','/ˌɪn.kənˈspɪk.ju.əs/','/ˌɪn.kənˈspɪk.ju.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exotic','adj.外来的，来自异国的；奇异的','/ɪɡˈzɒtɪk/','/ɪɡˈzɒtɪk/','noun',["Glueballs, theoretical particles composed only of gluons, are exotics.","an exotic appearance"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relief','n.缓解，减轻，轻松；援救，救济；宽慰；浮雕','/ɹɪˈliːf/','/ɹɪˈliːf/','noun',["I sighed with relief when I found out that my daughter hadn''t got lost, but was waiting for me at home.","Officer Schmidt can finally go home because his relief has arrived."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boycott','vt.联合抵制，拒绝购买','/ˈbɔɪkɒt/','/ˈbɔɪkɒt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subscribe','v.订购，订阅；申请，预订；捐助，赞助','/səbˈskɹaɪb/','/səbˈskɹaɪb/','verb',["Would you like to subscribe or subscribe a friend to our new magazine, Lexicography Illustrated?","I don’t subscribe to that theory.","Each man subscribed ten dollars."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('therapy','n.治疗，疗法','/ˈθɛɹ.ə.pi/','/ˈθɛɹ.ə.pi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chromosome','n.染色体','/ˈkɹəʊ.məˌsəʊm/','/ˈkɹoʊməˌsoʊm/','noun',["Chromosomes store genetic information."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fellowship','n.友谊；奖学金；团体，协会','/ˈfɛləʃɪp/','/ˈfɛləʃɪp/','noun',["The Fellowship of the Ring","The Bishop''s family fellowshipped the new converts.","After she got married, she stopped fellowshipping with the singles in our church."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unadorned','adj.未装饰的，朴实的','/əˌnʌˈdɔːnd/','/əˌnʌˈdɔːnd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confession','n.供认，招供，坦白；供词；承认','/kənˈfɛʃən/','/kənˈfɛʃən/','noun',["Without the real murderer''s confession, an innocent person will go to jail.","He forced me to sign a confession!","I went to confession and now I feel much better about what I had done."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meridian','n.子午线，经线','/məˈɹɪdɪən/','/məˈɹɪdɪən/','noun',["meridian splendour"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stack','v.堆积，堆放n.堆','/stæk/','/stæk/','noun',["They paid him a stack of money to keep quiet.","I''ve got 107 Golden Branches, but the stack size is 20 so they''re taking up 6 spaces in my inventory.","Please stack those chairs in the corner."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resent','v.憎恶，愤恨，怨恨','/ɹiˈzɛnt/','/ɹiˈzɛnt/','verb',["The bride greatly resented being left at the church."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fiery','adj.似火的；易怒的，暴躁的','/ˈfaɪəɹi/','/ˈfaɪəɹi/','adjective',["a fiery temper"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mime','v.模拟，模仿n.喜剧；哑剧；哑剧演员；模拟表演','/maɪm/','/maɪm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambiguous','adj.不明确的，模棱两可的','/æmˈbɪɡjuəs/','/æmˈbɪɡjuəs/','adjective',["The politician was criticized for his ambiguous statements and lack of precision.","He gave an ambiguous answer."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parliament','n.国会，议会','/ˈpɑːləmənt/','/ˈpɑɹləmənt/','noun',["Following the general election, Jane Doe took her oath of office as a member of the nation''s fifth parliament."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allay','vt.减轻，减少','/əˈleɪ/','/əˈleɪ/','noun',["to allay popular excitement","to allay the severity of affliction or the bitterness of adversity"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dote','vi.溺爱','/dəʊt/','/dəʊt/','noun',["Little Bill''s parents just keep doting on him."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retrieval','n.数据检索；取回，索回','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conceivable','adj.可能的；可信的，可想象的','/kənˈsiːvəbl̩/','/kənˈsiːvəbl̩/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cube','n.立方体；立方形的东西；立方','/kjuːb/','/kjub/','noun',["a stock cube","the cube of 2 is 8","Three cubed can be written as 33, and equals twenty-seven."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('synchronize','v.同步，同时发生','/ˈsɪŋ.kɹə.naɪːz/','','verb',["We synchronized our watches and agreed to meet at four o''clock precisely."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sequoia','n.美洲杉，红杉','/səˈkwɔɪ.ə/','/səˈkwɔɪ.ə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impact','v.影响；冲击，撞击n.影响；冲击，撞击','','','noun',["The hatchet cut the wood on impact.","His spine had an impingement; L4 and L5 made impact, which caused numbness in his leg.","His friend''s opinion had an impact on his decision."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('profile','n.人物专访；概述，传略，人物简介；面部的侧影；轮廓，外形vt.扼要介绍，概述','/ˈpɹəʊfaɪl/','/ˈpɹəʊfaɪl/','noun',["His fingers traced the profile of the handle.","The brooch showed the profile of a Victorian woman.","Law enforcement assembled a profile of the suspect."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tributary','n.支流；','/ˈtɹɪbjʊtəɹi/','/ˈtɹɪbjʊtəɹi/','noun',["The Ohio has many tributary streams, and is itself tributary to the Mississippi."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clog','v.堵塞，阻塞n.障碍','/klɒɡ/','/klɒɡ/','noun',["Dutch people rarely wear clogs these days.","The plumber cleared the clog from the drain.","Hair is clogging the drainpipe."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('senior','adj.地位较高的；','/ˈsiːnjə(r)/','/ˈsinjɚ/','noun',["He was four years her senior.","senior citizen","senior member; senior counsel"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dilate','v.膨胀，扩大；详述','/daɪˈleɪt/','/daɪˈleɪt/','verb',["The eye doctor put drops in my eye to dilate the pupil so he could see the nerve better.","His heart dilates and glories in his strength."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('domain','n.领土；领域','/dəʊˈmeɪn/','/dəʊˈmeɪn/','noun',["The king ruled his domain harshly.","Dealing with complaints isn''t really my domain: get in touch with customer services."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smear','v.胡乱涂抹；弄脏；诽谤，诋毁n.污迹，污斑；诽谤，诋毁；涂片','/smɪə/','/smɪə/','noun',["This detergent cleans windows without leaving smears.","I''m going to the doctor''s this afternoon for a smear.","The artist smeared paint over the canvas in broad strokes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('willful','adj.成心的，有意的；任性的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pluralism','n.多元化，多元性；多元主义','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amenity','n.生活设施；便利设施','/əˈmiːnəti/','/əˈmiːnəti/','noun',["We especially enjoyed the amenity of the climate on our last holiday.","All the little amenities the hotel provided made our stay very enjoyable."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bequeath','vt.遗赠；流传','/bɪˈkwiːð/','/bɪˈkwiːð/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transparent','adj.透明的；明显的，显而易见的；直率的','/tɹæn(t)sˈpæɹənt/','/tɹæn(t)sˈpæɹənt/','adjective',["The waters of the lake were transparent until the factory dumped waste there.","His reasons for the decision were transparent."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mint','v.铸造n.薄荷；造币厂；大量的钱','/mɪnt/','/mɪnt/','noun',["It must have cost a mint to produce!","in mint condition."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grasp','vt&n.抓住；掌握，理解，领会','/ɡɹɑːsp/','/ɡɹæsp/','noun',["The goal is within my grasp.","I have never been able to grasp the concept of infinity."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('journal','n.期刊，杂志；日记，日志','/ˈd͡ʒɜːnəl/','/ˈd͡ʒɜːnəl/','noun',["The university''s biology department subscribes to half a dozen academic journals."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pave','v.铺；密布','/peɪv/','/peɪv/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chaotic','adj.混乱的，无秩序的','/keɪˈɒtɪk/','/keɪˈɒtɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brag','v.吹嘘，自夸，自吹自擂','/bɹæɡ/','/bɹæɡ/','noun',["to brag of one''s exploits, courage, or money","a woundy, brag young fellow"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('annoyed','adj.生气的','/əˈnɔɪd/','','verb',["Marc loved his sister, but when she annoyed him he wanted to switch her off.","to annoy an army by impeding its march, or by a cannonade"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('term','n.学期；期限，期间；条件，条款；术语vt.把…称为','/tɜːm/','/tɝm/','noun',["\"Alright, look...we can spend the holidays with your parents, but this time it will be on my terms.\"","The term of a lease agreement is the period of time during which the lease is effective, and may be fixed, periodic, or of indefinite duration.","Be sure to read the terms and conditions before signing."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquisition','n.习得，获得；收购，购置','/æ.kwɪ.ˈzɪ.ʃən/','/æ.kwɪ.ˈzɪ.ʃən/','noun',["The acquisition of sports equipment can be fun in itself.","That graphite tennis racquet is quite an acquisition."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deadline','n.最后期限，截止时间','/ˈdɛdˌlaɪn/','/ˈdɛdˌlaɪn/','noun',["I must make this deadline or my boss will kill me!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('so-called','adj.所谓的','/ˈsəʊˌkɔːld/','/ˈsəʊˌkɔːld/','adjective',["These so-called \"assistants\" are making our jobs harder, not easier!","the so-called Ising model"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('medieval','adj.中世纪的，中古的','/mɪd.ˈiː.vəl/','/mɪd.ˈiː.vəl/','noun',["Thank God for modern remedies: the medievals were often useless or even harmful."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('staff','n.全体职工；行政人员；棍棒vt.为…配备人员；任职于','/ˈstæf/','','noun',["The company employed 10 new members of staff this month.","a constable''s staff"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('involve','vt.包含；牵涉，牵连；使参加','/ɪnˈvɒlv/','/ɪnˈvɒlv/','verb',["to involve in darkness or obscurity","He''s involved in the crime.","By getting involved in her local community, Mary met lots of people and also helped make it a nicer place to live."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complicated','adj.难懂的，复杂的','/ˈkɒmplɪkeɪtɪd/','/ˈkɑmplɪkeɪtɪd/','verb',["Don''t complicate yourself in issues that are beyond the scope of your understanding.","It seems this complicated situation will not blow over soon."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('finch','n.雀类','/fɪntʃ/','/fɪntʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('syllabus','n.教学大纲，课程提纲','/ˈsɪləbəs/','/ˈsɪləbəs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fragrant','adj.芬芳的，香的','/ˈfɹeɪ.ɡɹənt/','/ˈfɹeɪ.ɡɹənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tolerant','adj.宽容的；容忍的','/ˈtɒləɹənt/','/ˈtɒləɹənt/','adjective',["He''s pretty tolerant of different political views, but don''t ask him about religion.","These plants are tolerant of drought and sunlight."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dialect','n.方言，土话','/ˈdaɪ.əˌlɛkt/','/ˈdaɪ.əˌlɛkt/','noun',["Home computers in the 1980s had many incompatible dialects of BASIC."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rigor','n.严格；严酷','/ɹɪɡɚ/','/ɹɪɡɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dim','adj.模糊的；暗淡的；朦胧的；不乐观的v.变暗淡；变冷漠','/dɪm/','/dɪm/','noun',["He dimmed the lights and put on soft music.","The lights dimmed briefly when the air conditioning was turned on.","The lighting was too dim for me to make out his facial features."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impel','vt.驱使，促使','/ɪmˈpɛl/','/ɪmˈpɛl/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paralyze','vt.使瘫痪，使麻痹；使无效','','','verb',["The transport strike paralyzed the city."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('besiege','vt.包围；使应接不暇','/bəˈsiːd͡ʒ/','/bəˈsiːd͡ʒ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exemplary','adj.模范的；典型的','/ɛɡˈzɛmpləɹi/','/ɛɡˈzɛmpləɹi/','noun',["Her behaviour was always exemplary.","exemplary justice, exemplary punishment, exemplary damages"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('faculty','n.学院；全体教职员工；能力','/ˈfæ.kəl.ti/','/ˈfæ.kəl.ti/','noun',["She transferred from the Faculty of Science to the Faculty of Medicine.","He lived until he reached the age of 90 with most of his faculties intact."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('photodissociation','n.光解','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adamant','adj.坚定不移的，坚决的；固执的','/ˈæ.də.mænt/','/ˈæ.də.mænt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hydraulic','adj.水力的，液压的；液压驱动的；与水力系统有关的','/haɪˈdɹɒlɪk/','/haɪˈdɹɔːlɪk/','verb',["A hydraulic press is operated by the differential pressure of water on pistons of different dimensions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('considerate','adj.考虑周到的，体贴的，体谅的','/kənˈsɪdəɹət/','/kənˈsɪdəɹət/','verb',["Consider that we’ve had three major events and the year has hardly begun.","I’m considering going to the beach tomorrow.","Consider yourself lucky, but consider your opponent skillful."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('molten','adj.熔化的，熔融的','/ˈmɒltən/','/ˈmɒltən/','verb',["I melted butter to make a cake.","His troubles melted away.","She melted when she saw the romantic message in the Valentine''s Day card."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radius','n.半径；周围，范围','/ˈɹeɪ.di.əs/','/ˈɹeɪ.di.əs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scruffy','adj.不整洁的，邋遢的','/ˈskɹʌ.fi/','/ˈskɹʌ.fi/','noun',["A scruffy little dog came scampering down the road."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impair','vt.削弱；损害','/ɪmˈpɛə/','/ɪmˈpɛə/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sumptuous','adj.奢华的，豪华的','/ˈsʌmpt͡ʃuəs/','/ˈsʌmpt͡ʃuəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stray','vi.迷路；分心，走神；离题adj.迷路的；','/stɹeɪ/','/stɹeɪ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('static','adj.静态的，静止的；静电的；静力的n.静电噪音；静电；[-s]静力学','/ˈstæt.ɪk/','/ˈstæt.ɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kinship','n.血缘关系，亲属关系','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exhaust','n.废气；排气管vt.用尽，耗尽；使非常疲倦；详尽讨论','/ɪɡˈzɔːst/','/ɪɡˈzɔːst/','noun',["Moisture of the earth is exhausted by evaporation.","to exhaust a treasury","I exhausted my strength walking up the hill."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soluble','adj.可溶的；可解决的','[ˈsɔɫ.jʊ.bəɫ]','[ˈsɔɫ.jʊ.bəɫ]','adjective',["Sugar is soluble in water.","That mystery should be easily soluble."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('varied','adj.各式各样的','/ˈvɛəɹid/','/ˈvæɹid/','adjective',["He varies his magic tricks so as to minimize the possibility that any given audience member will see the same trick twice.","You should vary your diet. Eating just bread will do you harm in the end.","His mood varies by the hour."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intriguing','adj.引起兴趣的，吸引人的','/ɪnˈtɹiːɡɪŋ/','/ɪnˈtɹiːɡɪŋ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strap','n.带vt.用带捆扎，束牢；用绷带包扎','/stɹæp/','/stɹæp/','noun',["to strap a razor"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diversify','v.多样化，不同','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('graph','n.图表','/ɡɹæf/','/ɡɹæf/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feast','v.尽情享用n.节日；盛宴，宴会','/fiːst/','/fiːst/','noun',["We had a feast to celebrate the harvest.","It was a feast for the eyes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imbibe','v.喝；吸收，接受','/ɪmˈbaɪb/','/ɪmˈbaɪb/','verb',["to imbibe knowledge"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impermeable','adj.不可渗透的，不透水的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precautionary','adj.预防的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pretentious','adj.自负的','/pɹɪˈtɛnʃəs/','/pɹɪˈtɛnʃəs/','adjective',["Her dress was obviously more pretentious than comfortable.","Their song titles are pretentious in the context of their basic lyrics."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tackle','v.对付，处理；阻截；抢球n.拦截；用具','/ˈtækəl/','/ˈtækəl/','noun',["The government''s measures to tackle crime were insufficient."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solvent','adj.有溶解力的；有偿付能力的n.溶剂','[ˈsɒlvənt]','[ˈsɒlvənt]','noun',["a solvent of mystery"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nude','adj.裸体的','/n(j)uːd/','/n(j)uːd/','noun',["Lexa sent me a nude last week.","she caught him in the nude","Why do you act so prudish whenever you see nude people?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distract','vt.分散注意力，使分心','/dɪsˈtɹækt/','/dɪsˈtɹækt/','verb',["The crowd was distracted by a helicopter hovering over the stadium when the only goal of the game was scored."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('palate','n.上腭；味觉，品尝力','/ˈpælət/','/ˈpælət/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('influenza','n.流行性感冒','/ˌɪn.flu.ˈɛn.zə/','/ˌɪn.flu.ˈɛn.zə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loan','n.贷款；出借，借出；暂借的东西vt.借出；贷给','/ləʊn/','/loʊn/','noun',["Because of the loan that John made to me, I was able to pay my tuition for the upcoming semester.","All loans from the library, whether books or audio material, must be returned within two weeks.","He made a payment on his loan."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('virtual','adj.模拟的，虚拟的；实际上的，事实上的','/ˈvɜːtʃuəl/','/ˈvɵːtʃuəl/','noun',["In fact a defeat on the battlefield, Tet was a virtual victory for the North, owing to its effect on public opinion.","The angry peasants were a virtual army as they attacked the castle.","The virtual world of his computer game allowed character interaction."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('endless','adj.无止境的，无穷尽的','/ˈɛndləs/','/ˈɛndləs/','adjective',["endless time; endless praise","an endless line"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('continuation','n.延长，延续，持续；延长物，扩建物；延续部分','/kəntɪnjʊˈeɪʃ(ə)n/','/kəntɪnjʊˈeɪʃ(ə)n/','noun',["The series'' continuation was commercially if not artistically successful."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('applaud','v.鼓掌，喝彩；称赞','/əˈplɔːd/','/əˈplɔd/','noun',["After the performance, the audience applauded for five minutes.","Although we don''t like your methods, we applaud your motives."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lunar','adj.月亮的','/ˈl(j)uːnə/','/ˈlunɚ/','noun',["lunar observations  a lunar eclipse"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arrogant','adj.傲慢的，自大的','/ˈæɹəɡənt/','/ˈæɹəɡənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relay','vt.转播；传达，转述n.接替人员，轮换者；接力赛；中继设备','','','noun',["Can you relay this message to John?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('permission','n.允许，同意；许可证，书面许可','/pəˈmɪʃən/','/pɚˈmɪʃən/','noun',["Sire, do I have your permission to execute this traitor?","I used the \"chmod\" command to change the file''s permission."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('permeate','v.弥漫；渗透','/ˈpɜːmiˌeɪt/','/ˈpɜːmiˌeɪt/','noun',["water permeates sand"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monogamous','adj.一夫一妻制的；单配的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apprehend','vt.逮捕；领会，理解','','/æ.pɹiˈhɛnd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crippling','adj.令人震惊的；严重损害身体的；极其有害的','','','verb',["The car bomb crippled five passers-by.","My ambitions were crippled by a lack of money.","The word processor was released in a crippled demonstration version that did not allow you to save."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inherit','v.继承，遗传而得','/ɪnˈhɛɹɪt/','/ɪnˈhɛɹɪt/','verb',["Your descendants will inherit the earth.","After Grandad died, I inherited the house.","Let''s hope the baby inherits his mother''s looks and his father''s intelligence."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arduous','adj.费力的，艰巨的','/ˈɑːdjuːəs/','/ˈɑːɹd͡ʒuəs/','adjective',["The movement towards a peaceful settlement has been a long and arduous political struggle."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('faction','n.派别，派系，小集团；派系斗争','/ˈfæk.ʃn̩/','/ˈfæk.ʃn̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blanket','n.毯子；覆盖物','/ˈblæŋkɪt/','/ˈblæŋkɪt/','noun',["The baby was cold, so his mother put a blanket over him.","The city woke under a thick blanket of fog.","A press operator must carefully wash the blanket whenever changing a plate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grant','v.给予，授予；允许，同意；承认n.拨款；津贴；授予物','/ɡɹɑːnt/','/ɡɹænt/','noun',["I got a grant from the government to study archeology in Egypt.","a grant of land or of money","He was granted permission to attend the meeting."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recoup','vt.收回，弥补','/ɹɪˈkuːp/','/ɹɪˈkuːp/','verb',["He barely managed to recoup his money. He sold out for just what he had invested.","A landlord recouped the rent of premises from damages awarded to the plaintiff for eviction."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('append','vt.附加，增补','/əˈpɛnd/','/ʌˈpɛnd/','noun',["An inscription was appended to the column.","notes appended to a book chapter"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('newsletter','n.时事通讯','/ˈnjuːzˌlɛtə/','/ˈnjuːzˌlɛtə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('copilot','n.副驾驶员','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frigid','adj.寒冷的；冷淡的','/ˈfɹɪdʒɪd/','/ˈfɹɪdʒɪd/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bellows','n.风箱','/ˈbɛl.əʊz/','/ˈbɛl.oʊz/','noun',["When wood fires were common, so were bellows for helping start them."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discount','n.折扣vt.把…打折扣；不全信，漠视，低估','/dɪsˈkaʊnt/','/dɪsˈkaʊnt/','noun',["This store offers discounts on all its wares. That store specializes in discount wares, too.","Merchants sometimes discount five or six per cent for prompt payment of bills.","the banks discount notes and bills of exchange"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rivalry','n.竞争；敌对','/ˈɹaɪ.vəl.ɹi/','/ˈɹaɪ.vəl.ɹi/','noun',["James and Polly have a bitter rivalry due to the latter''s inclusion in the Tea Time Teaser.","Common goods are those which are rivalrous in consumption but non-excludable","Binocular rivalry is a visual phenomenon in which perception alternates between different images presented to each eye."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('charisma','n.超凡魅力；感召力；号召力','/kəˈɹɪzmə/','/kəˈɹɪzmə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stalk','v.偷偷接近；跟踪；趾高气扬地走n.茎，梗，柄','/stɔːk/','/stɔk/','noun',["a stalk of wheat, rye, or oats;  the stalks of maize or hemp"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pancreas','n.胰腺','/ˈpæŋkɹɪəs/','/ˈpæŋkɹɪəs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supplier','n.供应者，供应商，供货方','/səˈplaɪə/','/səˈplaɪə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patriarchic','adj.家长的，族长的；德高望重的','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mimic','adj.模仿的，模拟的vt.模仿；像n.模仿者；小丑','/ˈmɪm.ɪk/','/ˈmɪm.ɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pitch','n.音高，音调；倾斜度；沥青，柏油；','/pɪtʃ/','/pɪtʃ/','noun',["It is hard to get this pitch off my hand.","It was pitch black because there was no moon."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incessant','adj.不断的，不停的','/ɪnˈsɛs.ənt/','/ɪnˈsɛs.ənt/','adjective',["The dog''s incessant barking kept the girl awake all night."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('torrent','n.洪流，急流；爆发，迸发','/ˈtɒɹ.ənt/','/ˈtɑɹ.ənt/','noun',["A torrent of green and white water broke over the hull of the sail-boat.","They endured a torrent of inquiries."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appreciation','n.欣赏；理解，体谅；感激；鉴定，评价','/əˌpɹiː.ʃiˈeɪ.ʃən/','/əˌpɹiː.ʃiˈeɪ.ʃən/','noun',["We give to you this trophy as a token of our appreciation of all your years of service.","an appreciation of colors"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brew','v.酿造；冲泡；酝酿，行将发生n.冲泡的饮料；啤酒','/bɹuː/','/bɹuː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pretension','n.要求，主张；自命不凡；虚饰','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deflect','v.偏斜，转向','/dɪˈflɛkt/','/dɪˈflɛkt/','verb',["The Prime Minister deflected some increasingly pointed questions by claiming he had an appointment."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('virtuous','adj.有道德的，品行端正的，品德高的；〈贬〉自命清高的，自以为是的','/ˈvɜːt͡ʃʊəs/','/ˈvɝt͡ʃuəs/','adjective',["Successful communities need strong, selfless leaders and a virtuous people."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invalid','adj.无效的；无可靠根据的，站不住脚的n.病弱者，残疾者','/ɪnˈvæl.ɪd/','/ɪnˈvæl.ɪd/','adjective',["This invalid contract cannot be legally enforced."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('legitimate','adj.合法的，法定的；正当合理的，合情合理的','','','noun',["legitimate reasoning; a legitimate standard or method","legitimate poems of Chaucer; legitimate inscriptions"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whereby','ad&conj.借以，凭','/wɛə(ɹ)ˈbaɪ/','/wɛə(ɹ)ˈbaɪ/','adverb',["Whereby goest thou?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ooze','v.渗出，慢慢流出；洋溢着，充满n.泥浆；缓慢渗出','/uːz/','/uːz/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('renown','n.名望，声誉','/ɹɪˈnaʊn/','/ɹɪˈnaʊn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('semantic','adj.语义的','/sɪˈmæntɪk/','/sɪˈmæntɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('upset','adj.心烦意乱的；不适的vt.使心烦意乱；颠覆，推翻；搅乱n.困扰，麻烦；出乎意料的结局；苦恼','','','noun',["My late arrival caused the professor considerable upset.","\"collision and upset\": impact with another object or an overturn for whatever reason.","I’m sure the bad news will upset him, but he needs to know."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diffusion','n.散布，扩散；传播','/dɪˈfjuːʒən/','/dɪˈfjuːʒən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curve','v.弄弯，成曲线形n.曲线；曲线图；弯曲','/kɜːv/','/kɝv/','noun',["You should slow down when approaching a curve.","She scribbled a curve on the paper.","The teacher was nice and graded the test on a curve."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skim','v.撇去；掠过，擦过；浏览，略读','/skɪm/','/skɪm/','noun',["I skimmed the newspaper over breakfast.","to skim milk; to skim broth","to skim cream"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skip','v.跳；跳过，略过，漏过；不出席n.跳；跳过','/skɪp/','/skɪp/','noun',["She will skip from one end of the sidewalk to the other.","The rock will skip across the pond.","I bet I can skip this rock to the other side of the pond."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disseminate','v.散布，传播','/dɪˈsɛmɪˌneɪt/','/dɪˈsɛmɪˌneɪt/','verb',["The values of the human rights movement have disseminated throughout the world."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liquefy','v.溶解，液化','/ˈlɪkwɪfaɪ/','/ˈlɪkwɪfaɪ/','verb',["We''ll liquefy this rock by heating it in a furnace until it melts and flows out.","The substance liquefied upon heating."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exodus','n.大批离去，成群外出','/ˈɛksədəs/','/ˈɛksədəs/','noun',["There was an exodus when the show ended."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mention','v.提及，说起','/ˈmɛnʃən/','/ˈmɛnʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laundry','n.洗衣店，洗衣房；洗好的衣服；待洗的衣服','/ˈlɑn.dɹi/','/ˈlɔːn.dɹi/','noun',["You''ve left your dirty laundry all over the house."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('digression','n.离题，扯到枝节上；题外话，枝节内容','/dɪˈɡɹɛʃən/','/dɪˈɡɹɛʃən/','noun',["The lectures included lengthy digressions on topics ranging from the professor''s dog to the meaning of life.","make digression... by way of digression..."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grudge','v.勉强做；不情愿地给n.怨恨，积怨','/ɡɹʌdʒ/','/ɡɹʌdʒ/','noun',["to have/hold/bear a grudge against someone"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('herald','vt.预示；宣布，宣告n.信使；预示，预兆','/ˈhɛɹəld/','/ˈhɛɹəld/','noun',["The herald blew his trumpet and shouted that the King was dead.","Daffodils are heralds of Spring.","Rouge Dragon is a herald at the College of Arms."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coalition','n.联盟，同盟；结合，联合','/koʊəˈlɪʃən/','/koʊəˈlɪʃən/','noun',["The Liberal Democrats and Conservative parties formed a coalition government in 2010."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dwarf','adj.矮小的vt.使显得矮小，使相形见绌n.侏儒，矮人','/dwɔːf/','/dwɔɹf/','noun',["dwarf honeysuckle","The newly-built skyscraper dwarfs all older buildings in the downtown skyline.","Bach dwarfs all other composers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crime','n.犯罪；罪行','/kɹaɪm/','/kɹaɪm/','noun',["Crime doesn’t pay."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leisure','n.空闲，闲暇','/ˈliːʒə(ɹ)/','/ˈliːʒəɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mat','n.垫子','/mæt/','/mæt/','noun',["Wipe your feet on the mat before coming in.","They put mats on the table during mealtimes.","The high jumper cleared the bar and landed safely on the mat."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('melanin','n.黑色素','/ˈmɛlənɪn/','/ˈmɛlənɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assimilate','v.透彻理解，吸收，消化；同化','/əˈsɪm.ɪ.leɪt/','/əˈsɪm.ɪ.leɪt/','noun',["Food is assimilated and converted into organic tissue.","The teacher paused in her lecture to allow the students to assimilate what she had said.","The aliens in the science-fiction film wanted to assimilate human beings into their own race."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ethical','adj.道德的','/ˈɛθɪkəl/','/ˈɛθɪkəl/','noun',["The philosopher Kant is particularly known for his ethical writings.","All employees must familiarize themselves with our ethical guidelines.","We are trying to decide what the most ethical course of action would be."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zealous','adj.狂热的，热烈的，充满激情的','/ˈzɛl.əs/','/ˈzɛl.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bait','n.鱼饵，诱饵vt.下诱饵；激怒','/beɪt/','/beɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dimensional','adj.…度空间的','/-ʃnəl/','/-ʃnəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disinterest','n.无兴趣，冷漠；客观，公正','/dɪsˈɪntɹɛst/','','noun',["She eyed him over her martini with cool disinterest."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lunge','vi&n.猛冲，猛扑','/lʌndʒ/','/lʌndʒ/','noun',["I lunged at the police officer and made a grab for her gun."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convene','v.召集，召开；聚集，集合','/kənˈvɪin/','/kənˈvɪin/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revenue','n.收入；税收','/ˈɹɛvənjuː/','/ˈɹɛvəˌn(j)u/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monopoly','n.垄断，专卖；垄断商品，专卖商品；独占，专利','/məˈnɒpəˌli/','/məˈnɑpəˌli/','noun',["A land monopoly renders its holder(s) nearly almighty in an agricultural society.","Granting monopolies in concession constitutes a market-conform alternative to taxation for the state, while the crown sometimes bestowed a monopoly as an outrageous gift."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negotiation','n.商议，谈判；流通','/nɪˌɡəʊʃiˈeɪʃən/','/nɪˌɡoʊʃiˈeɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fraudulent','adj.欺诈的，欺骗性的','/ˈfɹɔː.djə.lənt/','/ˈfɹɔː.djə.lənt/','adjective',["He tried to pass a fraudulent check."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('approximation','n.接近；近似值','/əˌpɹɒksɪˈmeɪʃn/','/əˌpɹɒksɪˈmeɪʃn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('syllable','n.音节','/ˈsɪləbəl/','/ˈsɪləbəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comedy','n.喜剧；喜剧性，滑稽，幽默','/ˈkɒmədi/','/ˈkɑmədi/','noun',["Why would you be watching comedy when there are kids starving right now?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('literacy','n.有文化，有教养；读写能力','/ˈlɪt.ɹə.si/','/ˈlɪt.əɹ.ə.si/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soloist','n.独奏者，独唱者，单独表演者','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nonetheless','adv.虽然如此，但是，依然','/ˌnʌnðəˈlɛs/','/ˌnʌnðəˈlɛs/','adverb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dispose','v.安排，布置；使倾向于','/dɪˈspəʊz/','/dɪsˈpoʊz/','noun',["I dispose of my trash in the garbage can.","In these uncertain times, I am disposed towards caution."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disconcert','vt.使惊慌，使不安；使困惑','/ˌdɪskənˈsɜːt/','/ˌdɪskənˈsɜːt/','noun',["The emperor disconcerted the plans of his enemy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paradigm','n.范例，典范','/ˈpæ.ɹə.daɪm/','/ˈpeɪɹ.ə.daɪm/','noun',["Thomas Kuhn''s landmark “The Structure of Scientific Revolutions” got people talking about paradigm shifts, to the point the word itself now suggests an incomplete or biased perspective.","The paradigm of \"go\" is \"go, went, gone.\""]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blend','v.混合，混杂n.混合；混合物','/blɛnd/','/blɛnd/','noun',["Our department has a good blend of experienced workers and young promise.","To make hummus you need to blend chickpeas, olive oil, lemon juice and garlic."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overact','v.把表演得过火；表现做作','/ˌəʊvəɹˈækt/','/ˌəʊvəɹˈækt/','verb',["He overacted his part."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fidelity','n.忠诚，忠实；精确，逼真','/faɪˈdɛl.ɪ.ti/','/faɪˈdɛl.ɪ.ti/','noun',["the fidelity of the civil servants"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conceive','v.构思，构想，设想；怀孕','/kənˈsiːv/','/kənˈsiːv/','verb',["Assisted procreation can help those trying to conceive."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incursion','n.袭击，突然入侵；介入','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nonsense','n.胡说，废话；冒失的行为','/ˈnɒnsəns/','/ˈnɑnsɛns/','noun',["After my father had a stroke, every time he tried to talk, it sounded like nonsense.","He says that I stole his computer, but that''s just nonsense."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stain','v.沾污；留下污渍n.污点，污渍','/steɪn/','/steɪn/','noun',["armour stained with blood","the stained glass used for church windows"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('balk','v.畏缩；阻止；妨碍n.障碍','/bɔːk/','/bɔːk/','noun',["The horse balked.","to balk expectation"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electrode','n.电极','/iˈlɛk.tɹəʊd/','/iˈlɛk.tɹəʊd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('airborne','adj.空气传播的；空运的','','','noun',["Airborne pollen can aggravate allergies.","airborne radar","airborne troops"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reckless','adj.轻率的，鲁莽的，无所顾忌的','/ˈɹɛkləs/','/ˈɹɛkləs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oversleep','v.睡过头；睡得过久','/ˈəʊvəɹˌsliːp/','/ˈəʊvəɹˌsliːp/','verb',["I overslept and was late for school.","to oversleep one''s usual hour of rising"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bald','adj.光秃的，秃头的；简单的，单调的','/bɔːld/','','noun',["The bald cypress is a tree that loses its leaves in winter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paradox','n.似非而是的论点；自相矛盾的话','/ˈpaɹədɒks/','/ˈpæɹədɑks/','noun',["\"This sentence is false\" is a paradox.","It is an interesting paradox that drinking a lot of water can often make you feel thirsty.","Not having a fashion is a fashion; that''s a paradox."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oratorio','n.清唱剧，宗教剧','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('X-ray','n.X射线，X光；X光照片','','','noun',["X-rays are light with a wavelength between 0.1 and 10 nm.","\"The doctor ordered some X-rays of my injured wrist.\"","Of course there was nothing wrong with my left wrist. They X-rayed the wrong arm!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('physical','adj.物理的；物质的，有形的；身体的，肉体的n.体检','/ˈfɪzɪkəl/','/ˈfɪzɪkəl/','noun',["How long has it been since your last physical?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('categorize','vt.将…分类，把…加以分类','','','verb',["First, categorize incoming messages according to the needed actions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mania','n.躁狂；狂热；癖好','/ˈmeɪ.ni.ə/','/ˈmeɪ.ni.ə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poetic','adj.诗歌的；诗意的','/poʊˈɛtɪk/','/poʊˈɛtɪk/','adjective',["Iambics are one form of poetic meter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opposed','adj.反对的；截然不同的','/əˈpəʊzd/','/əˈpoʊzd/','verb',["There is still time to oppose this plan.","Many religious leaders oppose cloning humans.","They are opposed to any form of hierarchy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('familiarize','vt.使熟悉','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apportionment','n.分派，分摊，分配','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thread','v.穿；穿过，通过n.线；线索；思路','[θɾ̪̊ɛd]','[θɾ̪̊ɛd]','noun',["All of these essays have a common thread.","thread a needle","I think I can thread my way through here, but it’s going to be tight."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enrollment','n.登记，注册；入学','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tyrannical','adj.专制的，残暴的，专横的','/tɪˈɹæ.nɪ.kəl/','/tɪˈɹæ.nɪ.kəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stake','n.股份；赌注；利害关系vt.以…打赌，拿…冒险','/steɪk/','/steɪk/','noun',["We have surveyor''s stakes at all four corners of this field, to mark exactly its borders.","Thomas Cranmer was burnt at the stake.","The owners let the managers eventually earn a stake in the business."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fortify','vt.支持，给…以勇气；加强，增强；筑防御工事于','/ˈfɔːtɪfaɪ/','/ˈfɔːtɪfaɪ/','verb',["Sherry is made by fortifying wine.","Soy milk is often fortified with calcium."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ripen','v.成熟','/ˈɹaɪpən/','/ˈɹaɪpən/','verb',["Grapes ripen in the sun.","The warm sun ripened the corn.","ripen the judgment"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conform','vi.遵守，服从；符合；适应','/kənˈfɔːm/','/kənˈfɔːm/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('authentic','adj.真正的，真实的；逼真的；可靠的','/ɒ.ˈθɛn.tɪk/','/ɒ.ˈθɛn.tɪk/','adjective',["The experts confirmed it was an authentic signature.","The report was completely authentic."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opal','n.蛋白石','/ˈəʊpəl/','/ˈəʊpəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lodge','v.正式提出；租住，借宿；为…提供住宿；寄存n.巢穴；旅社；乡间小屋','/lɒdʒ/','/lɑdʒ/','noun',["The tribe consists of about two hundred lodges, that is, of about a thousand individuals.","I''ve got some spinach lodged between my teeth.","The detective Sherlock Holmes lodged in Baker Street."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rayon','n.人造丝，人造纤维','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devoid','adj.全无的','/dɪˈvɔɪd/','/dɪˈvɔɪd/','verb',["The child will devoid the garbage after he devours his sandwich.","I went searching for a knife, but the kitchen was devoid of anything sharper than a spoon."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curl','v.卷曲，蜷缩n.卷发；卷曲状；卷曲物','/kəːl/','/kɝl/','noun',["The curl of the vector field \\vec{F}(x,y,z) is the vector field \\operatorname{curl}\\,\\vec{F} \\equiv \\vec{\\nabla}\\times\\vec{F}=\\left( \\frac{\\partial F_z}{\\partial y} - \\frac{\\partial F_y}{\\partial z}, \\frac{\\partial F_x}{\\partial z} - \\frac{\\partial F_z}{\\partial x}, \\frac{\\partial F_y}{\\partial x} - \\frac{\\partial F_x}{\\partial y} \\right).","The one-piece back is of a medium curl.","I curl at my local club every weekend."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inform','vt.通知，通告；了解，熟悉；告发，检举，告密','/ɪnˈfɔːm/','/ɪnˈfɔɹm/','verb',["His sense of religion informs everything he writes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dearth','n.缺乏，短缺','/dɜːθ/','/dɝθ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commit','vt.承诺；犯错；犯罪；忠于','/kəˈmɪt/','/kəˈmɪt/','noun',["Tony should be committed to a nuthouse!","to commit a series of heinous crimes","to commit oneself to a certain action"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patch','vt.修补，打补丁n.小片，小块；补丁；小块土地','/pætʃ/','/pætʃ/','noun',["His sleeves had patches on the elbows where different fabric had been sewn on to replace material that had worn away.","I can''t afford to replace the roof, which is what it really needs. I''ll have the roofer apply a patch.","\"This patch should hold until you reach the city,\" the mechanic said as he patted the car''s hood."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('presidency','n.职位；任期','/ˈpɹezɪdənsi/','/ˈpɹezɪdənsi/','noun',["After many years as a party leader, she finally ascended to the presidency.","Because of the president''s lame duck status, the presidency was often hampered by congressional actions.","Ernest was a historian specializing in the presidency of Herbert Hoover."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scurry','vi&n.急跑，疾行','/ˈskʌɹi/','/ˈskɝɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scornful','adj.轻蔑的，鄙视的','/ˈskɔːnfəl/','/ˈskɔːnfəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cholesterol','n.胆固醇','/kəˈlɛstəɹɒl/','/kəˈlɛstəɹɒl/','noun',["improve your cholesterol; lower your cholesterol"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beneficent','adj.有益的；行善的，慈善的','/bəˈnɛf.ə.sənt/','/bəˈnɛf.ə.sənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comprise','vt.包含；由…组成','/kəmˈpɹaɪz/','/kəmˈpɹaɪz/','verb',["The parts are comprised by the whole.","Our committee comprises a president, secretary, treasurer and five other members.","A team is comprised of its members."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moderate','adj.适度的；温和的；普通的v.缓和，使适中n.持温和意见的人','/ˈmɑdəɹeɪt/','/ˈmɑdəɹeɪt/','noun',["The moderates are the natural advocates of ecumenism against the fanatics of their churches.","to moderate rage, action, desires, etc.","to moderate a synod"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('upheaval','n.剧变，动乱，大变动','/ʌpˈhi.vəl/','/ʌpˈhi.vəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('receiver','n.接收器；听筒；接收者；官方接管人','/ɹəˈsiːvə/','/ɹəˈsivɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gilding','n.镀金；贴金层，镀金层；金色涂层','/ˈɡɪldɪŋ/','/ˈɡɪldɪŋ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('execute','vt.执行，履行，实施；将…处死，处决；完成','/ˈɛksɪˌkjuːt/','/ˈɛksɪˌkjuːt/','verb',["There are certain states where it is lawful to execute prisoners convicted of certain crimes.","I''ll execute your orders as soon as this meeting is adjourned.","to execute a difficult piece of music brilliantly"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('balm','n.香脂油，药膏；镇痛剂，安慰剂','/bɑːm/','/bɑlm/','noun',["There is a balm in Gilead... (Spiritual)","Classical music is a sweet balm for our sorrows."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boost','vt.提高，推进；替…做广告，宣扬n.增加，帮助','/buːst/','/buːst/','noun',["The controversy gave a boost to the author''s sales.","This campaign will boost your chances of winning the election."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sober','adj.清醒的，未醉的；持重的，冷静的；素净的v.清醒；变得冷静','/ˈsəʊ.bə(ɹ)/','/ˈsəʊ.bə(ɹ)/','verb',["It took him hours to sober up.","1890, John Charles, The Godly, Righteous, And Sober Life"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('male','adj.雄的，公的；','/meɪl/','/meɪl/','noun',["a male bird feeding a seed to a female","stereotypically male interests, an insect with typically male coloration","the male chromosome;   like testes, ovaries also produce testosterone and some other male hormones"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maternal','adj.母亲的，母系的','/məˈtɜːnəl/','/məˈtɜːnəl/','noun',["His weakness seemed to bring out her maternal instincts.","Toby is my maternal uncle."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prolific','adj.多产的；富有创造力的','/ˌpɹoʊˈlɪf.ɪk/','/ˌpɹoʊˈlɪf.ɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expel','vt.开除；驱逐；排出','/ɪkˈspɛl/','/ɪkˈspɛl/','verb',["He was expelled from school multiple times."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('externality','n.外部性，外界效应','/ekstəˈnælɪti/','/ekstəˈnælɪti/','noun',["Waste is a negative externality arising from consumption."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vigor','n.活力，精力','/ˈvɪɡɚ/','/ˈvɪɡɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scan','vt.细察，审视；扫描；粗略地看，浏览n.扫描检查；浏览','/skæn/','/skæn/','noun',["The operators vacated the room during the scan.","The doctors looked at the scans and made a diagnosis.","She scanned the passage carefully but could not find what she was looking for."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('augment','vt.增加，提高','/ɔːɡˈmɛnt/','/ɑɡˈmɛnt/','noun',["The money from renting out a spare room can augment a salary."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tangent','adj.切线的，相切的n.切线；正切','/ˈtæn.dʒənt/','/ˈtæn.dʒənt/','noun',["I believe we went off onto a tangent when we started talking about monkeys on unicycles at his retirement party."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('benign','adj.良性的；有利的；善良的，和蔼的','/bɪˈnaɪn/','/bɪˈnaɪn/','adjective',["an ozone-benign refrigerant"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquit','vt.宣告无罪；表现','/əˈkwɪt/','/əˈkwɪt/','verb',["The jury acquitted the prisoner of the charge.","The orator acquitted himself very poorly."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prosper','vi.繁荣，兴旺；成功','/ˈpɹɒspə(ɹ)/','/ˈpɹɒspə(ɹ)/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blizzard','n.暴风雪，大风雪','/ˈblɪ.zəd/','/ˈblɪ.zɚd/','noun',["a blizzard of political ads"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dedicate','vt.致力于，奉献给；题献词于上','/ˈdɛdɪkeɪt/','/ˈdɛdɪkeɪt/','verb',["dedicated their money to scientific research.","dedicated ourselves to starting our own business.","dedicate a monument."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monotonous','adj.单调的，无聊的','/məˈnɒtənəs/','/məˈnɒtənəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negate','vt.取消；否定','/nɪˈɡeɪt/','/nɪˈɡeɪt/','verb',["The investigation tending to negate any supernatural influences.","Persecution can be negated through exposure.","a pessimism that always negates"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impart','vt.传授；传达；给予','/ɪmˈpɑːt/','/ɪmˈpɑːɹt/','verb',["The sun imparts warmth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bureaucracy','n.官僚主义，官僚作风；政府机构，官僚机构','/bjʊəˈɹɒkɹəsi/','/bjʊəˈɹɒkɹəsi/','noun',["At that time the administration replaced the system of patronage in the civil service with a bureaucracy.","The bureaucracy is expanding to meet the needs of the expanding bureaucracy. (apocryphal quip)","The head of the civil service promised to clamp down on bureaucracy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('geometry','n.几何，几何学','/dʒiːˈɒmɪtɹi/','/dʒiˈɑmətɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devote','vt.为…付出；献身于','/dɪˈvəʊt/','/dɪˈvoʊt/','verb',["I devoted this afternoon to repainting my study, and nothing will get in my way.","The city was devoted to the flames."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delectable','adj.美味可口的；有吸引力的；令人喜爱的，赏心悦目的','/dɪˈlɛktəbəl/','/dɪˈlɛktəbəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alumnus','n.校友，毕业生','/əˈlʌmnəs/','/əˈlʌmnəs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('far-fetched','adj.牵强的','','','adjective',["He is full of far-fetched ideas to make money."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('craftsman','n.能工巧匠，手艺人，工艺师','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aberrant','adj.越轨的；异常的','/əˈbɛɹ.n̩t/','/əˈbɛɹ.n̩t/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lope','vi.轻松地大步跑n.轻快的步伐','/ləʊp/','/loʊp/','noun',["He loped along, hour after hour, not fast but steady and covering much ground."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lateral','adj.侧面的，旁边的；横向的','/ˈlæt.ɹəl/','/ˈlæt.ɹəl/','noun',["Instead of a promotion, I opted for a lateral move to a similar position in the marketing department.","A fish senses changes in hydrodynamic pressure with its lateral line."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hinterland','n.内地，腹地；内地贸易区','/ˈhɪntə(ɹ)ˌlænd/','/ˈhɪntə(ɹ)ˌlænd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nominate','vt.任命，指定；提名，推荐','/ˈnɒm.ə.neɪt/','/ˈnɒm.ə.neɪt/','verb',["1658: the City of Norwich [...] was enlarged, builded and nominated by the Saxons. — Sir Thomas Browne, Urne-Burial (Penguin 2005, p. 12)","the nominate subspecies"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tread','v.踏，践踏；行走n.轮胎面；脚步声；步法','/tɹɛd/','/tɹɛd/','verb',["Don''t tread on the lawn.","Actors tread the boards.","to tread a path; to tread land when too light; a well-trodden path"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barn','n.谷仓；牲口棚','[bɑːn]','[baːn]','noun',["Maple Leaf Gardens was a grand old barn."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bark','v.吠叫；厉声质问n.树皮；犬吠声','/bɑːk/','/bɑɹk/','noun',["The neighbour''s dog is always barking.","The sergeant barked an order."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kennel','n.狗窝；养狗场','/ˈkɛnəl/','/ˈkɛnəl/','noun',["She raises registered Dalmatians at her kennel.","While we''re away our friends will kennel our pet poodle."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ellipse','n.椭圆，椭圆形','/iˈlɪps/','/iˈlɪps/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sidewalk','n.人行道','/ˈsaɪdwɔːk/','/ˈsaɪdwɔːk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('formidable','adj.难对付的；强大的；令人敬畏的','/fɔːˈmɪdəbəl/','/fɔːɹˈmɪdəbəl/','adjective',["a formidable opponent"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abound','vi.富于；大量存在；充满','/əˈbaʊnd/','/əˈbaʊnd/','verb',["Wild animals abound wherever man does not stake his claim.","The wilderness abounds in traps."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suitcase','n.手提箱，衣箱','/ˈsutkeɪs/','/ˈsutkeɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invert','vt.使倒转，使倒置，使颠倒','','','noun',["to invert a cup, the order of words, rules of justice, etc.","invert sugar"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discrete','adj.分离的，个别的；离散的','/dɪsˈkɹiːt/','/dɪsˈkɹiːt/','adjective',["a government with three discrete divisions","\"I resign my life, but not my honour\" is a discrete proposition."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immutable','adj.不可改变的，永恒不变的','','','noun',["The government has enacted an immutable law.","Constants are immutable."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disrupt','vt.使中断；扰乱；使分裂，使瓦解','/dɪsˈɹʌpt/','','verb',["Hecklers disrupted the man''s speech.","Work on the tunnel was disrupted by a strike.","The internet makes it easier for leaner businesses to disrupt the larger and more unwieldy ones."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scar','vt.给…留下疤痕；给…留下精神创伤；损害…的外观n.疤痕；创伤','/skɑː(ɹ)/','/skɑː(ɹ)/','noun',["Seeing his parents die in a car crash scarred him for life."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abort','v.夭折，中止；使流产','/əˈbɔːt/','/əˈbɔɹt/','noun',["We''ve had aborts on three of our last seven launches.","We''ve had three aborts over the last two days."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hypothetical','adj.假设的','/ˌhaɪpəˈθɛtɪkl/','/ˌhaɪpəˈθɛtɪkl/','noun',["These hypotheticals serve no purpose until we have more information."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coefficient','n.系数','/ˌkəʊ.iˈfɪʃn̩t/','/ˌkəʊ.iˈfɪʃn̩t/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('converse','vi.交谈，会话adj.逆向的，相反的n.相反的事物；反面','/kənˈvɜːs/','/kənˈvɜːs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gospel','n.准则，信条；绝对真理；[G-]福音；福音音乐；训示','/ˈɡɒspəl/','/ˈɡɒspəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eccentric','adj.古怪的，反常的n.古怪的人','/ɪkˈsɛntɹɪk/','/ɛkˈsɛntɹɪk/','noun',["As of 2008, Margaret had the most eccentric orbit of any moon in the solar system, though Nereid''s mean eccentricity is greater."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appliance','n.用具，器具；装置','/əˈplaɪəns/','/əˈplaɪəns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alloy','n.合金vt.使成合金','','','noun',["gold without alloy"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defer','v.推迟，延期','/dɪˈfɜː(ɹ)/','/dɪˈfɜː(ɹ)/','verb',["We''re going to defer the decision until we have all the facts."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drowsy','adj.昏昏欲睡的；催眠的','/ˈdɹaʊzi/','/ˈdɹaʊzi/','adjective',["I was feeling drowsy and so decided to make a cup of coffee to try to wake myself up.","It was a warm, drowsy summer afternoon."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lore','n.学问，学识；传说，传统','/lɔː/','/lɔɹ/','noun',["the lore of the Ancient Egyptians"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mast','n.船桅；旗杆；天线塔','/mæst/','/mæst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mass','adj.大量的n.质量；块，团；众多；群众，平民百姓','/mæs/','/mæs/','noun',["I mass 70 kilograms.","There is evidence of mass extinctions in the distant past.","Mass unemployment resulted from the financial collapse."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('muggy','adj.闷热的','/ˈmʌɡi/','/ˈmʌɡi/','adjective',["muggy straw"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revoke','vt.撤销，撤回；取消，废除','','','noun',["I hereby revoke all former wills."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poisonous','adj.有毒的，有害的；恶毒的','/ˈpɔɪznəs/','/ˈpɔɪznəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('auction','n&v.拍卖','/ˈɒkʃən/','/ˈɔːkʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allot','vt.分配，配给，拨给','/əˈlɒt/','/əˈlɒt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('propel','vt.推进，驱使；激励','/pɹəˈpɛl/','/pɹəˈpɛl/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admit','v.承认；准许…进入，接纳','/ədˈmɪt/','/ədˈmɪt/','verb',["A ticket admits one into a playhouse.","the prisoner was admitted to bail","he admitted his guilt"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rampant','adj.猖獗的，肆虐的；蔓生的','/ˈɹæm.pənt/','/ˈɹæm.pənt/','adjective',["The Vienna riding school displays splendid rampant movement.","Weeds are rampant in any neglected garden.","There was rampant corruption in the city."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interest','n.兴趣，关注；业余爱好；利息；利害关系vt.使感兴趣，引起…关注','/ˈɪntəɹɪst/','/ˈɪntəɹst/','noun',["Our bank offers borrowers an annual interest of 5%.","He has a lot of interest in vintage cars.","I have business interests in South Africa."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uneven','adj.不平均的；不平坦的；不规则的；不势均力敌的；不公平的','/ʌnˈivən/','/ʌnˈivən/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immature','adj.未成熟的，未充分发展的','/ɪməˈtjʊə(ɹ)/','/ɪməˈtjʊə(ɹ)/','noun',["The man was immature for throwing a tantrum."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chaste','adj.贞洁的；简朴的，朴实的','/tʃeɪst/','/tʃeɪst/','adjective',["a chaste style in composition or art","a chaste mind;  chaste eyes"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evacuation','n.撤离','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patron','n.资助人，赞助人；老主顾，顾客','/ˈpeɪ.tɹən/','/ˈpeɪ.tɹən/','noun',["This car park is for patrons only."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stew','v.炖，煨；思考；不安，担忧n.炖菜；不安，担忧','/stʃʉː/','/stʃʉː/','noun',["to be in a stew","I''m going to stew some meat for the casserole."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overlook','vt.俯瞰，眺望；忽略；对…不予考虑','/əʊvəˈlʊk/','/oʊvəɹˈlʊk/','noun',["Our hotel room overlooks the lake.","These errors were overlooked by the proofreaders.","I’m not willing to overlook such bad behaviour."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incredible','adj.惊人的，难以置信的','/ɪŋˈkɹɛdɪbəl/','/ɪŋˈkɹɛdɪbəl/','adjective',["He was so wrapped up in watching the incredible special effects that he couldn''t keep track of the story.","I had such an incredible slice of pizza last night that I simply can''t think about anything else."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('layout','n.编排，版面设计；规划，布局','/ˈleɪ.aʊt/','/ˈleɪ.aʊt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('landing','n.登陆；着陆，降落','/ˈlændɪŋ/','/ˈlændɪŋ/','verb',["The plane is about to land.","It can be tricky to land a helicopter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('formula','n.公式，方程式；分子式；配方','/ˈfɔː.mjʊ.lə/','/ˈfɔː.mjʊ.lə/','noun',["H2O is the formula for water.","The company''s winning formula includes excellent service and quality products.","The formula of the rocket fuel has not been revealed."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('avalanche','n&v.雪崩；山崩','/ˈævəlɑːnʃ/','/ˈævəlæntʃ/','noun',["The shelf broke and the boxes avalanched the workers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revolt','v.反叛，反抗；违抗；厌恶，反感n.起义，叛乱，反抗','/ɹɪˈvɒlt/','/ɹɪˈvoʊlt/','noun',["The farmers had to revolt against the government to get what they deserved.","Your brother revolts me!","The stomach revolts at such food; his nature revolts at cruelty."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disgust','vt.厌恶，嫌恶','/dɪsˈɡʌst/','/dɪsˈɡʌst/','noun',["With an air of disgust, she stormed out of the room.","It disgusts me to see her chew with her mouth open."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tribute','n.贡品；颂词，称赞；悼念，致哀；礼物','/ˈtɹɪbjuːt/','/ˈtɹɪbjuːt/','noun',["Please accept this as a tribute of our thanks.","The Ancient Romans made their conquered countries pay tribute."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('endanger','vt.危及，危害','/ənˈdeɪndʒə/','/ənˈdeɪndʒə/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('base','adj.卑鄙的，不道德的vt.把设在；','/beɪs/','/beɪs/','noun',["The logarithm to base 2 of 8 is 3.","Peter adjusted the equalizer on his audio equipment to emphasize the bass.","The conductor preferred to situate the bass in the middle rear, rather than to one side of the orchestra."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subordinate','adj.次要的；下级的vt.使处于次要地位，使从属于n.部属，下属','','','noun',["In the sentence “The barbecue finished before John arrived”, the subordinate clause “before John arrived” specifies the time of the main clause, “The barbecue finished”."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mechanic','n.技工，机修工','/məˈkænɪk/','/məˈkænɪk/','noun',["This game has a mechanic where if you run toward a ledge you automatically jump off rather than just falling."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incentive','n.刺激；动机','/ɪnˈsɛntɪv/','/ɪnˈsɛntɪv/','noun',["I have no incentive to do housework right now.","Management offered the sales team a $500 incentive for each car sold."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preliminary','adj.预备的，初步的n.初步做法，起始行为','/pɹɪˈlɪmɪnəɹi/','/pɹɪˈlɪmɪnəɹi/','noun',["These are just the preliminary results."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leftover','adj.剩余的','','','noun',["It''s a leftover from yesterday, but it''s still perfectly good.","Not leftovers again!","Do you want some of the leftover supplies from the event?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collaborative','adj.合作的，协作的','','','noun',["No need to thank me - it was a collaborative effort."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indict','vt.控诉，起诉，控告','/ˌɪnˈdaɪt/','/ˌɪnˈdaɪt/','verb',["a book that indicts modern values","his former manager was indicted for fraud"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('courier','n.送急件的人，信使；旅游服务员','/ˈkʊɹ.ɪə/','/ˈkʊɹ.ɪə/','noun',["We''ll have the contract couriered to you."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mate','v.交配n.配偶；朋友，伙伴；同事；大副','/meɪt/','/meɪt/','noun',["He''s my best mate.","Excuse me, mate, have you got the time?","I found one of the socks I wanted to wear, but I couldn''t find its mate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stampede','v.狂奔，涌向；使仓促行事n.逃窜，狂奔；热潮，风尚','/stæmˈpiːd/','/stæmˈpiːd/','noun',["The annual Muslim Hajj in Mecca, Saudi Arabia, which is attended by millions of pilgrims, has increasingly suffered from stampedes.","a stampede toward US bonds in the credit markets"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gorge','v.狼吞虎咽n.山峡，峡谷','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terminate','v.停止，结束','/ˈtɜːmɪneɪt/','/ˈtɜːmɪneɪt/','verb',["to terminate a surface by a line","Mountains on the Moon cast shadows that are very dark, terminate and more distinct than those cast by mountains on the Earth.","One third is a recurring decimal, but one half is a terminate decimal."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mannerism','n.怪癖，癖性；过分的独特风格','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theory','n.理论，原理；学说；见解，看法','/ˈθiːəɹi/','/ˈθiːəɹi/','noun',["Knot theory classifies the mappings of a circle into 3-space.","A theory is consistent if it has a model."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extension','n.延长；延伸；电话分机，分机号码','/ɪkˈstɛnʃən/','/ɪkˈstɛnʃən/','noun',["Files with the .txt extension usually contain text.","a browser extension"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excise','vt.切除；删去','/ˈɛkˌsaɪz/','/ˈɛkˌsaɪz/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punch','vt.拳打；打孔；按，压n.重拳击打；冲床，打孔机','/pʌntʃ/','/pʌntʃ/','noun',["If she punches me, I''m gonna break her nose.","He punched a hit into shallow left field.","to punch one with the end of a stick or the elbow"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flexibility','n.灵活性；弹性，韧性；适应性','','','noun',["I had some flexibility in terms of whether to stay in a hotel or in a bed-and-breakfast."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mortgage','n.抵押贷款，按揭；抵押证书vt.用…作抵押','/ˈmɔː.ɡɪdʒ/','/ˈmɔɹ.ɡɪdʒ/','noun',["We''re renting a property in the city centre because we can''t afford to get a mortgage yet.","lands given in mortgage","We mortgaged our house in order to start a company."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('identity','n.身份；特征，特性；同一性','/aɪˈdɛntəti/','/aɪˈdɛntəti/','noun',["I''ve been through so many changes, I have no sense of identity.","This criminal has taken on several identities.","2013 April 4, \"Cricket identities consult lawyers\", New Zealand Herald"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('verify','v.检验，核实','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excursion','n.远足，短途旅游','/ɛks.kɜː(ɹ).ʃən/','/ɛks.kɜː(ɹ).ʃən/','noun',["While driving home I took an excursion and saw some deer."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inaugurate','vt.为…举行就职典礼；为…举行开幕式；开始，开创','/ɪˈnɔːɡjʊɹət/','/ɪˈnɔːɡjʊɹət/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cramp','n.痉挛，抽筋；vt.阻碍，阻止','/kɹæmp/','/kɹæmp/','noun',["You''re cramping my style.","You''re going to need to cramp the wheels on this hill.","to cramp boot legs"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solitude','n.孤独，单独；独处，独居；隐居处','/ˈsɒlɪˌtjuːd/','/ˈsɑlɪˌtud/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hockey','n.曲棍球','/ˈhɒki/','/ˈhɒki/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perquisite','n.津贴，利益；特权','/ˈpɜːkwɪzɪt/','/ˈpɜːkwɪzɪt/','noun',["The perquisites of this job include health insurance and a performance bonus.","After the wonderful service that evening he didn’t hesitate in laying a substantial perquisite on the table.","Private jets and motor yachts are a perquisite of the rich."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sting','v.刺，蜇；感觉刺痛n.尾刺；刺痛','/stɪŋ/','/stɪŋ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('juice','vt.榨出汁液n.汁，液','/d͡ʒuːs/','/d͡ʒus/','noun',["Squeeze the orange and some juice will come out.","I’d like two orange juices please."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('haste','v.赶快，匆忙n.急忙，急速，匆忙','/heɪst/','/heɪst/','noun',["We were running late so we finished our meal in haste."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nurture','vt.养育，养护，培养；扶植，支持；滋长，助长n.养育，培养','/ˈnɜːɹ.tʃəɹ/','/ˈnɜːɹ.tʃəɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('buckle','v.扣紧；变形，弯曲n.皮带扣环','/ˈbʌk(ə)l/','/ˈbʌk(ə)l/','verb',["It is amazing that he has never buckled after so many years of doing such urgent work."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('degenerate','vi.退化，衰退adj.堕落的；退化的','','','noun',["In the cult of degenerates, acts of decency, kindness and modesty could be seen as acts of apostasy.","His condition continued to degenerate even after admission to hospital."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monastery','n.男修道院，寺院','/ˈmɒnəstɹi/','/ˈmɑnəstəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devout','adj.虔敬的；诚恳的','/dɪˈvaʊt/','/dəˈvʌʊt/','noun',["devout sighs; devout eyes; a devout posture","devout wishes for one''s welfare"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('censor','n.审查员vt.审查，检查','/ˈsɛnsə/','/ˈsɛnsɚ/','noun',["The Ancient Roman censors were part of the cursus honorum, a series of public offices held during a political career, like consuls and praetors.","The headmaster was an even stricter censor of his boarding pupils’ correspondence than the enemy censors had been of his own when the country was occupied.","Occupying powers typically censor anything reeking of resistance"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devour','vt.狼吞虎咽地吃，吞食；吞没，吞噬；如饥似渴地读','/dɪˈvaʊ(w)ə(ɹ)/','','verb',["The fire was devouring the building.","She intended to devour the book.","After the death of his wife, he was devoured by grief."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stir','v.搅拌；煽动；激发，打动；行动，活动n.搅拌，搅动；激动，震动','/stɜː/','/stɝ/','noun',["Can you give the soup a little stir?","She stirred the pudding with a spoon.","Would you please stand here and stir this pot so that the chocolate doesn''t burn?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insult','vt.侮辱，凌辱n.侮辱，凌辱','/ɪnˈsʌlt/','/ɪnˈsʌlt/','noun',["The way the orchestra performed tonight was an insult to my ears."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('axis','n.轴；轴线，中心线','/ˈæksəs/','/ˈæksɪs/','noun',["The Earth rotates once a day on its axis"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maze','n.迷宫；复杂难懂的细节；困惑，迷惘vt.使混乱；使困惑，迷惑','/ˈmeɪz/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negligent','adj.忽略的；疏忽的；粗心大意的','/ˈnɛɡ.lɪ.dʒənt/','/ˈnɛɡ.lɪ.dʒənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conductivity','n.传导性；传导率','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('desolate','adj.荒凉的，无人烟的；不幸的，忧伤的vt.使感到悲惨，使感到凄凉；使荒芜','','','verb',["a desolate isle; a desolate wilderness; a desolate house","desolate altars","He was left desolate by the early death of his wife."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coarse','adj.粗糙的；粗俗的','/kɔːs/','/kɔːɹs/','adjective',["coarse language"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evade','v.逃避，回避；躲开，避开','/ɪˈveɪd/','/ɪˈveɪd/','verb',["He evaded his opponent''s blows."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('associative','adj.联想的；结合的；关联的','/əˈsoʊ.si.ə.tɪv/','/əˈsoʊ.si.ə.tɪv/','adjective',["AWK''s associative arrays may be indexed by strings."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cortex','n.皮层，皮质','/ˈkɔːtɛks/','/ˈkɔːtɛks/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('offset','n.分支；补偿；抵消vt.补偿；抵消','/ɒfˈsɛt/','/ɒfˈsɛt/','noun',["Today''s victory was an offset to yesterday''s defeat.","offset lithographs","An array of bytes uses its index as the offset, of words a multiple thereof."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('backhand','n.反手击球','/ˈbækhænd/','/ˈbækhænd/','noun',["He scored on a backhand shot."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cascade','vi.倾泻，流注n.小瀑布；倾泻','/kæsˈkeɪd/','/kæsˈkeɪd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('provision','n.供应，供应品；条款；准备，预备','/pɹəˈvɪʒ.ən/','/pɹəˈvɪʒ.ən/','noun',["We increased our provision for bad debts on credit sales going into the recession.","An arrest shall be made in accordance with the provisions of this Act.","to provision an army"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recruit','v.招募，征募n.新兵；新成员','/ɹɪˈkɹuːt/','/ɹɪˈkɹuːt/','noun',["These new recruits were hired after passing the interviews","We need to recruit more admin staff to deal with the massive surge in popularity of our products","the army was recruited for a campaign"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abolition','n.废除，废止；废奴运动','/ˌæb.əˈlɪʃ.n̩/','/ˌæb.əˈlɪʃ.n̩/','noun',["the abolition of debts;   the abolition of laws;   the abolition of slavery;   the abolition of police;;   the abolition of taxes"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sporadic','adj.偶发的，间或出现的，零星的','/spɒˈɹædɪk/','/spɔˈɹæɾɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turnout','n.出席人数；产量，产额','','','noun',["When towing a trailer, use the turnouts to let faster traffic pass.","A man with a showy carriage and horses is said to have a fine turnout."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('configuration','n.布局，格局；结构，构造，形状；配置','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spherical','adj.球形的，球状的','/sfiːɹɪkəl/','/sfiːɹɪkəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chunk','n.厚片，大块；相当大的部分；矮胖的人','/t͡ʃʌŋk/','/t͡ʃʌŋk/','noun',["The statue broke into chunks.","a chunk of granite","examples of chunks would include \"in accordance with\", \"the results of\", and \"so far\""]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commonplace','adj.普通的，平凡的n.平凡的事；老生常谈','/ˈkɒmənˌpleɪs/','/ˈkɑmənˌpleɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('libel','vt.诽谤n.诽谤；诽谤性文字','/ˈlaɪbəl/','/ˈlaɪbəl/','noun',["He libelled her when he published that."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parameter','n.参量，参数；界限，范围','/pəˈɹæm.ɪ.tə/','','noun',["Roughly, a tuple of arguments could be thought of as a vector, whereas a tuple of parameters could be thought of as a covector (i.e., linear functional). When a function is called, a parameter tuple becomes \"bound\" to an argument tuple, allowing the function instance itself to be computed to yield a return value. This would be roughly analogous to applying a covector to a vector (by taking their dot product (or, rather, matrix-product of row vector and column vector)) to obtain a scalar.","The parameter of the principal axis of a conic section is called the latus rectum."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forerunner','n.先驱者，开路人；先兆，预兆','','','noun',["Bakelite is a forerunner of today''s plastics."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cubism','n.立体派；立体主义','/ˈkjuː.bɪz.əm/','/ˈkjuː.bɪz.əm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agonize','vi.苦苦思索；焦虑不已','/ˈæ.ɡən.aɪz/','/ˈæ.ɡən.aɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('percolate','v.过滤；渗入，渗透；逐渐流传，传开n.滤液','/ˈpɜːkəleɪt/','/ˈpəɹkəleɪt/','noun',["Water percolates through sand.","I''ll percolate some coffee.","Reports on the pitiful state of many prisons have finally percolated through to the Home Office, which has promised to look into the situation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opaque','adj.不透明的，不透光的；难懂的，晦涩的','/əʊˈpeɪk/','/əʊˈpeɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humid','adj.湿的，潮湿的；湿润的','/ˈhjuːmɪd/','/ˈhjuːmɪd/','adjective',["humid earth"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('controversy','n.争论，辩论','/kənˈtɹɒvəsi/','/ˈkɑntɹəˌvɝsi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('command','n&v.命令；指挥，统率','/kəˈmɑːnd/','/kəˈmænd/','noun',["I was given a command to cease shooting.","to have command of an army","England has long held command of the sea"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compulsory','adj.必须做的，义务的；强制性的；必修的','/kəmˈpʌlsəri/','/kəmˈpʌlsəri/','noun',["The ten-dollar fee was compulsory.","Such compulsory measures are limited."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abortive','adj.落空的，失败的','/əˈbɔː.tɪv/','/əˈbɔː.tɪv/','noun',["an abortive child","an abortive attempt","an abortive organ"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swarm','vi.云集v.密集，云集；成群地飞行n.群，一大群','/swɔːm/','/swɔɹm/','noun',["a swarm of meteorites"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anticipate','v.预见，预期；先于…行动','/ænˈtɪs.ɪ.peɪt/','/ænˈtɪs.ə.peɪt/','verb',["The advocate plans to anticipate a part of her argument.","Please anticipate a journey of an hour from your house to the airport","Little Johnny started to anticipate the arrival of Santa Claus a week before Christmas."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slash','v.砍；大幅削减n.砍痕，伤痕；斜线号','/slaʃ/','/slaʃ/','noun',["Slash generated during logging may constitute a fire hazard.","The province''s traditional slash-and-burn agriculture was only sustainable with a much smaller population."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fabricate','vt.编造；制造','/ˈfæb.ɹɪ.keɪt/','/ˈfæb.ɹɪ.keɪt/','verb',["to fabricate a bridge or ship","to fabricate computer chips","to fabricate a lie or story"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uproot','v.根除；离开家园','/ʌpˈɹuːt/','/ʌpˈɹuːt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tally','v.吻合n.记录；账','/ˈtæli/','/ˈtæli/','interjection',["(Air Traffic Control): Speedbird 123, New York, traffic at two o’clock, seven miles, a Boeing 737, west-bound, at 4000 feet.”"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prevailing','adj.普遍的；流行的；一地常刮的，盛行的','/pɹɪˈveɪ.lɪŋ/','/pɹɪˈveɪ.lɪŋ/','verb',["Red colour prevails in the Canadian flag.","In his day and age, such practices prevailed all over Europe.","I prevailed on him to wait."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('temporary','adj.暂时的，临时的','/ˈtɛmpəɹi/','/ˈtɛmpəˌɹɛɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('optimal','adj.最佳的，最理想的','/ˈɒptɪməl/','/ˈɑptɪməl/','noun',["Finding the optimal balance between features and price is a common problem."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('desperate','adj.绝望的；不顾死活的，拼命的；极度渴望的','/ˈdɛsp(ə)ɹət/','','noun',["I hadn''t eaten in two days and was desperate for food.","I was so desperate at one point, I even went to see a loan shark.","a desperate effort"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awful','adj.不舒服的；糟糕的；可怕的；非常的','/ˈɔːfəl/','/ˈɔfəl/','adjective',["My socks smell awful.","I have learnt an awful amount today.","He was blubbering away something awful."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handy','adj.可用的；易使用的，便利的；手巧的','/ˈhæn.di/','/ˈhæn.di/','adjective',["Some people regard duct tape as a handy fix-all.","I keep a first-aid kit handy in case of emergency.","She''s very handy: she made all her own kitchen cupboards."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anguish','v.极度痛苦n.极度痛苦','/ˈæŋ.ɡwɪʃ/','/ˈæŋ.ɡwɪʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refraction','n.折射','/ɹəˈfɹækʃən/','/ɹəˈfɹækʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aerobics','n.有氧运动','/əˈɹoʊbɪks/','/əˈɹoʊbɪks/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inviting','adj.动人的，诱人的；引人注目的','/ɪnˈvaɪtɪŋ/','/ɪnˈvaɪtɪŋ/','verb',["We invited our friends round for dinner.","I invite you all to be seated.","I always invite criticism of my definitions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instruct','vt.指示；教授','/ˌɪnˈstɹʌkt/','/ˌɪnˈstɹʌkt/','noun',["Listen carefully when someone instructs you how to assemble the furniture.","The doctor instructed me to keep my arm immobilised and begin physiotherapy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agreeable','adj.使人愉快的；欣然同意的','/əˈɡɹiːəbl/','/əˈɡɹiːəbl/','noun',["agreeable manners","Agreeable to the order of the day, the House took up the report."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('community','n.社会；社团；群落；共同体','/k(ə)ˈmjunəti/','/k(ə)ˈmjunəti/','noun',["a community of goods"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ailment','n.小病','/ˈeɪlmənt/','/ˈeɪlmənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('charismatic','adj.蒙受神恩的；有超凡魅力的','/ˌkæɹɪzˈmætɪk/','/ˌkæɹɪzˈmætɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overload','vt.使超载，使过载；使超负荷；给…增加负担n.超载；超负荷','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('staunch','adj.坚定的，忠诚的','/stɑːntʃ/','/stɑːntʃ/','verb',["Somebody''s got to staunch those press leaks!","He''s been a staunch supporter of mine through every election.","Without our staunch front line the enemy would have split the regiment."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adolescence','n.青春','/ˌædəˈlɛsəns/','/ˌædəˈlɛsəns/','noun',["During adolescence, the body and mind go through many complex changes, some of which are difficult to deal with."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notch','n.等级，档次；','/nɒtʃ/','/nɒtʃ/','noun',["Can you speak a notch louder, please?","The tribe''s hunters notch their kills by notches on each''s axe''s handle.","The team notched a pair of shutout wins on Sunday."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subculture','n.亚文化行为观念，次文化','','','noun',["The goth subculture has its own mode of dress, and it has a characteristic musical style."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exhale','v.呼出；散发','/ɛksˈheɪl/','/ɛksˈheɪl/','noun',["The earth exhales vapor; marshes exhale noxious effluvia.","The sun exhales the moisture of the earth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abrasion','n.表面磨损','/əˈbɹeɪ.ʒn̩/','/əˈbɹeɪ.ʒn̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symphony','n.交响乐，交响曲；和谐，协调','/ˈsɪm.fə.ni/','/ˈsɪm.fə.ni/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eloquent','adj.雄辩的；动人的','/ˈɛl.əˌkwənt/','/ˈɛl.əˌkwənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('observatory','n.天文台，天文观测站','/əbˈzəːvət(ə)ɹi/','/əbˈzəɹvətɔɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('optimistic','adj.乐观的','/ˌɒptɪˈmɪstɪk/','/ˌɒptɪˈmɪstɪk/','adjective',["in an optimistic mood","optimistic concurrency"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insolvent','adj.财力不足的，破产的','','','noun',["an insolvent debtor","an insolvent estate"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('submarine','adj.水下的，海底的n.潜水艇','/sʌb.məˈɹiːn/','/sʌb.məˈɹiːn/','noun',["a submarine patent"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('empiricism','n.经验论，经验主义','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sleek','adj.光滑而有光泽的；线条流畅的；时髦的vt.使平整光亮','/sliːk/','/sliːk/','noun',["sleek hair"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('typify','vt.是…的典范；成为…的特征','/ˈtɪpɪfaɪ/','/ˈtɪpɪfaɪ/','verb',["His attitude typifies the attitude of young people today.","The angry captain typified all new sailors as incompetent.","The chosen specimen typifies plants belonging to that species."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stagnant','adj.不景气的；停滞的；迟钝的；因不流动而污浊的','/ˈstæɡnənt/','/ˈstæɡnənt/','adjective',["a stagnant pool","a stagnant economy"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perceptive','adj.感知的，知觉的；有洞察力的，理解力强的','/pəˈsɛptɪv/','/pəˈsɛptɪv/','adjective',["He is so perceptive when it comes to other people''s feelings."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('annotation','n.注释，注解','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sweep','v.打扫；席卷，横扫；挥动，舞动；迅速传播；','/swiːp/','/swiːp/','noun',["Give the front steps a quick sweep to get rid of those fallen leaves.","Bradman attempted a sweep, but in fact top edged the ball to the wicket keeper","Jim will win fifty dollars in the office sweep if Japan wins the World Cup."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('descend','v.遗传；下降；起源；降临，来临','/dɪˈsɛnd/','/dɪˈsɛnd/','verb',["The rain descended, and the floods came.","And on the suitors let thy wrath descend.","he descended from his high estate"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mechanics','n.机械学，力学；技巧，方法','','','noun',["the mechanics of a board game"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toed','adj.有趾的','/toʊd/','/toʊd/','adjective',["He become more pigeon-toed with age."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maglev','n.磁力悬浮火车','/ˈmæɡ.lɛv/','/ˈmæɡ.lɛv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('descent','n.血统，世系；下降','/dɪˈsɛnt/','','noun',["We climbed the mountain with difficulty, but the descent was easier.","We had difficulty in finding the correct descent.","The descent into the cavern was wet and slippery."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stunt','vt.阻碍生长；遏制n.特技表演；噱头；愚蠢行为','/stʌnt/','/stʌnt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weird','adj.怪异的，神秘的','/ˈwiːəd/','/ˈwiɚd/','noun',["There are lots of weird people in this place.","It was quite weird to bump into all my ex-girlfriends on the same day.","There was a weird light shining above the hill."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('farce','n.笑剧，滑稽剧；闹剧','/fɑːs/','/fɑɹs/','noun',["The farce that we saw last night had us laughing and shaking our heads at the same time.","The first month of labor negotiations was a farce.","The political arena is a mere farce, with all sorts of fools trying to grab power."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ridiculous','adj.荒唐的，可笑的','/ɹiːˈdɪkjʊləs/','/ɹiːˈdɪkjʊləs/','adjective',["It''s ridiculous to charge so much for a little souvenir.","Gaines is a classic motor player with a low center of gravity and ridiculous strength."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intrusion','n.侵扰，干扰；侵犯；侵入，闯入','/ɪnˈtɹuːʒən/','/ɪnˈtɹuːʒən/','noun',["He viewed sales calls as an unwelcome intrusion."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refute','vt.反驳，驳斥','/ɹəˈfjut/','/ɹəˈfjut/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exemplify','vt.是…的典型；例示，举例证明','/ɛɡˈzɛmplɪfaɪ/','/ɛɡˈzɛmplɪfaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lease','n.租约；租期vt.出租','/liːs/','/liːs/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eager','adj.渴望的，热切的','/ˈiːɡə/','/ˈiɡɚ/','adjective',["I was eager to show my teacher how much I''d learned over the holidays.","an eager algorithm"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evidence','vt.证明n.证据；迹象；根据','[ˈɛvəɾəns]','[ˈɛvəɾəns]','noun',["There is no evidence that anyone was here earlier.","She was furious, as evidenced by her slamming the door."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('republic','n.共和国；共和政体','[ɹɪˈpʌblɪk]','[ɹɪˈpʌblɪk]','noun',["The United States is a republic; the United Kingdom of Great Britain and Northern Ireland is a constitutional monarchy.","The Republic of Udmurtia is west of the Permian Oblast."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('errand','n.差事，差使','/ˈɛɹənd/','/ˈɛɹənd/','noun',["All the servants were on holiday or erranded out of the house.","She spent an enjoyable afternoon erranding in the city."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flamboyant','adj.艳丽的，绚丽夺目的；炫耀的','/flamˈbɔɪənt/','/flæmˈbɔɪ(j)ənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lethal','adj.致命的；破坏性极大的，极其有害的','/ˈliː.θəl/','/ˈliː.θəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stun','vt.使昏迷；使震惊；使…目瞪口呆，给以深刻印象','/stʌn/','/stʌn/','noun',["Williams will need a lot of stun to avoid going in the middle pocket","Bill tried to stun the snake by striking it on the head.","He stood there stunned, looking at the beautiful, breath-taking sunrise."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repetition','n.重复，反复；重复的事','/ɹɛpəˈtɪʃən/','/ɹɛpəˈtɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sled','v.乘雪橇，用雪橇运n.雪橇；摘棉机','/slɛd/','/slɛd/','noun',["The child zoomed down the hill on his sled.","\"Mush!\" he yelled at the dogs pulling the sled."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('polygamous','adj.一夫多妻的，一妻多夫的','/pəˈlɪɡəməs/','/pəˈlɪɡəməs/','adjective',["That Mormon community no longer practises polygamous relationships."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suspense','n.担心，焦虑；悬念，不确定','/səˈspɛns/','/səˈspɛns/','noun',[]);
