INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indignant','adj.愤慨的，恼怒的','/ɪnˈdɪɡ.nənt/','/ɪnˈdɪɡ.nənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decimal','adj.十进位的，小数的n.小数','[ˈdɛsɪməɫ]','/ˈdɛsɪməl/','noun',["Pi has a value of 3.142, to three decimals."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hardly','adv.几乎不，简直不；刚刚，仅仅','/ˈhɑːdli/','/ˈhɑɹdli/','adverb',["I can''t really deal hardly with people.","they hardly ever watch television;  I hardly think they''ll come in this bad weather;  it''s hardly possible he could lose the election.","I think the Beatles are a really overrated band. ― Hardly!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lasting','adj.持久的，永久的','/ˈlastɪŋ/','/ˈlastɪŋ/','verb',["Summer seems to last longer each year.","I don''t know how much longer we can last without reinforcements.","to last a boot"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cynical','adj.愤世嫉俗的，冷嘲热讽的','/ˈsɪnɪkəl/','/ˈsɪnɪkəl/','adjective',[]);
