INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precipitate','v.使…突然降临；加速；降水；使突然陷入；adj.仓促的，鲁莽的','/pɹəˈsɪpɪteɪt/','/pɹəˈsɪpɪteɪt/','verb',["it precipitated their success","we were precipitated into a conflict","Adding the acid will cause the salt to precipitate."]);
