INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prioritize','v.划分优先顺序；优先处理','/pɹaɪˈɒɹətaɪz/','/pɹaɪˈɒɹətaɪz/','verb',[]);
