INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appetite','n.胃口，食欲；欲望','/ˈæp.ə.taɪt/','/ˈæp.ə.taɪt/','noun',["appetite for reading"]);
