INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recount','v.讲述，描述；重新清点，重计','','','noun',["The old man recounted the tale of how he caught the big fish.","to recount one''s blessings"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flask','n.细颈瓶；烧瓶','/flæsk/','/flæsk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pliable','adj.易弯曲的，柔韧的；易受影响的；顺从的','/ˈplaɪəbəl/','/ˈplaɪəbəl/','adjective',["You will find the clay perfectly pliable as long as it stays moist."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disturbance','n.打扰；骚动；心神不安，烦恼','/dɪˈstɜːbn̩s/','/dɪˈstɝbn̩s/','noun',["That guy causes a lot of trouble, you know, he''s such a disturbance."]);
