INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('predation','n.掠夺；掠食','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recommend','vt.推荐；建议','/ɹɛkəˈmɛnd/','/ɹɛkəˈmɛnd/','verb',["The board recommends Philips, given his ample experience in similar positions.","A city that has much to recommend it.","The therapist recommends resting the mind and exercising the body."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('demobilize','vt.遣散；使复员','/diːˈməʊbɪlaɪz/','/diːˈməʊbɪlaɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leach','v.过滤；溶解n.过滤器；过滤剂','/liːtʃ/','/liːtʃ/','noun',["1670 Hannah Woolley The Queen-like Closet, Or, Rich Cabinet https//en.m.wikipedia.org/wiki/The_Queen-Like_Closet \"To make Leach and to colour it\""]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prodigious','adj.巨大的','/pɹəˈdɪd͡ʒəs/','/pɹəˈdɪd͡ʒəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lost-and-found','n.失物招领','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('knack','n.诀窍；技能，本领；习惯，癖好','/næk/','/næk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('default','vi.不履行义务，违约n.违约；弃权；缺省','','/dɪˈfɔːlt/','noun',["He failed to make payments on time and is now in default.","The team''s three losses include one default.","The man became the leader of the group as a default."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indolent','adj.懒惰的，懒散的；不活跃的','/ˈɪn.dəl.ənt/','/ˈɪn.dəl.ənt/','adjective',["The indolent girl resisted doing her homework.","indolent comfort"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beverage','n.饮料','/ˈbevəɹɪdʒ/','/ˈbevəɹɪdʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diction','n.措辞，用语','/ˈdɪkʃən/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ripe','adj.熟的；成熟的','/ɹaɪp/','/ɹaɪp/','noun',["ripe apples","ripe cheese"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('triumph','v.获胜，成功n.狂喜；胜利，成功','/ˈtɹaɪ.ʌmf/','/ˈtɹaɪ.əmf/','noun',["the triumph of knowledge","Scorsese''s latest film is a triumph."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slumber','vi.睡眠，安睡','/slʌmbə/','/ˈslʌmbɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arouse','vt.唤醒，唤起；激起，引起','/əˈɹaʊz/','/əˈɹaʊz/','verb',["The new building proposals in the village are arousing unneeded discomfort.","I can''t keep my eyes off the dancer; she arouses me greatly.","1996, Beruga (line translated by Dan Owsen), Terranigma. Nintendo of America."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nest','v.做窝，筑巢n.巢，窝','/nɛst/','/nɛst/','noun',["That nightclub is a nest of strange people!","I am aspiring to leave the nest.","I was forced to change trumps when I found the ace, jack, and nine of diamonds in the nest."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tout','v.吹捧；兜售','/taʊt/','/taʊt/','noun',["Be careful of the ticket touts outside the arena, they are famed for selling counterfeits.","Mary has been touted as a potential succesor to the current COE."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expropriate','vt.征用，没收','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consensus','n.共识，一致同意；舆论','','','noun',["After years of debate over the best wine to serve at Thanksgiving, no real consensus has emerged.","a financial consensus forecast"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embellish','vt.装饰；对…添枝加叶，渲染','/ɛm-/','/ɛm-/','verb',["The old book cover was embellished with golden letters","to embellish a story, the truth"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('metric','adj.米制的；公制的','/ˈmɛt.ɹɪk/','/ˈmɛt.ɹɪk/','noun',["How to measure marketing? Use these key metrics for measuring marketing effectiveness.","Customer satisfaction was metricked by the marketing department."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absolute','adj.完全的，绝对的；地道的；无疑的，确凿的；不受限制的，不受约束的','/ˈæb.səˌljuːt/','/ˈæb.səˌlut/','noun',["moral absolutes","1658, Samuel Hoard, God['']s Love to Mankind, Manifested, by disprooving his absolute decree for their damnation","absolute purity, absolute liberty"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retract','v.收回，撤销；缩回','','/ɹəˈtɹækt/','verb',["An airplane retracts its wheels for flight.","A cat can retract its claws.","I retract all the accusations I made about the senator and sincerely hope he won''t sue me."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gossip','vi.传播流言飞语，说长道短n.闲话，流言飞语；爱说长道短的人','/ˈɡɒs.ɪp/','/ˈɡɑs.ɪp/','noun',["Be careful what you say to him: he’s a bit of a gossip.","According to the latest gossip, their relationship is on the rocks.","a gossip blog"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grab','v.拿，抓，夺','/ɡɹæb/','/ɡɹæb/','noun',["I grabbed her hand to pull her back from the cliff edge.","The suspect suddenly broke free and grabbed at the policeman''s gun.","How does that idea grab you?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('antecedent','adj.先行的n.祖先，先辈','/ˌantɪˈsiːdənt/','/ˌantɪˈsiːdənt/','noun',["an antecedent cause","an antecedent improbability"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remains','n.剩余物，残留物；古代遗物，遗迹，遗址；遗骸','/ɹɪˈmeɪnz/','/ɹɪˈmeɪnz/','noun',["There was no food in the house, so I had to remain hungry.","The light remained red for two full minutes.","The victim''s remains were one small piece of bone."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('granular','adj.粒状的；含颗粒的','/ˈɡɹæn.jə.lə(ɹ)/','/ˈɡɹæn.jə.lə(ɹ)/','adjective',["a granular substance","It has a granular structure"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('graphite','n.石墨','','/ˈɡɹæfaɪt/','noun',["Modern tennis racquets are made of graphite, fibreglass and other man-made materials."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boast','v&n.自我夸耀','/bəʊst/','/boʊst/','noun',["It was his regular boast that he could eat two full English breakfasts in one sitting.","His family boasted a famous name."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reiterate','vt.反复说，重申','/ɹiˈɪt.əɹ.eɪt/','/ɹiˈɪt.əɹ.eɪt/','noun',["Let me reiterate my opinion."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flank','n.肋腹；侧面；侧翼vt.位于…的侧面','/flæŋk/','/flæŋk/','noun',["All ahead flank!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('counterpart','n.相对物；职位相当的人；副本','/ˈkaʊntəˌpɑːt/','/ˈkaʊntɚˌpɑɹt/','noun',["Those brass knobs and their hollow counterparts interlock perfectly"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stripe','n.条纹，斑纹','/st(ʃ)ɹʌɪp/','/st(ʃ)ɹʌɪp/','noun',["zebra stripes","persons of the same political stripe"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sovereign','adj.君主的；至高无上的；独立自主的n.君主，元首，最高统治者','/ˈsɒv.ɹɪn/','/ˈsɑv(ə)ɹɪn/','noun',["sovereign nation","Her voice was her sovereign talent."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gourd','n.葫芦；葫芦制成的容器','/ɡɔːd/','/ɡɔːɹd/','noun',["I got so stoned last night. I was out of my gourd."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attractive','adj.吸引人的，有魅力的；引起注意的','/əˈtɹæktɪv/','/əˈtɹæktɪv/','adjective',["That''s a very attractive offer.","He is an attractive fellow with a trim figure."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cater','v.迎合；提供饮食','/ˈkeɪtə/','/ˈkeɪdɚ/','noun',["The merchants are the purveyors of fine selections."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superb','adj.极好的，高质量的，上乘的；华丽的','/sjuːˈpɜːb/','/suˈpɝb/','adjective',["This champagne is superb.","a superb edifice;  a superb colonnade"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engineering','n.工程；工程学','/ˌen.dʒɪˈnɪə.ɹɪŋ/','/ˌen.dʒɪˈnɪə.ɹɪŋ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('duplicate','adj.完全相同的；副本的n.复制品；副本vt.复写；复制；使加倍','/ˈdjuː.plɪ.kət/','/ˈdjuː.plɪ.kət/','noun',["This is a duplicate, but a very good replica.","Can you duplicate this kind of key?","You don''t need to duplicate my efforts."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affable','adj.和蔼可亲的，易于交谈的，友善的','/ˈæf.ə.bəl/','/ˈæf.ə.bəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surmise','v.推测，猜测n.推测，猜测','/sɜːˈmaɪz/','/sɜːˈmaɪz/','noun',["surmises of jealousy or of envy"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eradicate','vt.根除，灭绝','/ɪˈɹæd.ɪ.keɪt/','/ɪˈɹæd.ɪ.keɪt/','verb',["Smallpox was globally eradicated in 1980."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('germinate','v.发芽，萌芽；发展','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trumpet','v.鼓吹，宣扬n.小号，喇叭','/ˈtɹʌmpɪt/','/ˈtɹʌmpɪt/','noun',["The royal herald sounded a trumpet to announce their arrival.","The trumpets were assigned to stand at the rear of the orchestra pit.","The large bull gave a basso trumpet as he charged the hunters."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conservationist','n.自然环境保护论者','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('despondent','adj.垂头丧气的，沮丧的','/dɪˈspɒndənt/','/dɪˈspɒndənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trifle','vi.不认真对待，怠慢n.少许；琐事，小事；无价值的东西','/ˈtɹaɪfəl/','/ˈtɹaɪfəl/','noun',["You must not trifle with her affections."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Easter','n.复活节','/ˈiː.stə/','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('submit','v.提交，呈递；屈从；主张，建议','/səbˈmɪt/','/səbˈmɪt/','verb',["They will not submit to the destruction of their rights.","I submit these plans for your approval."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affluent','adj.丰富的；富裕的','/ˈæf.lu.ənt/','/ˈæf.lu.ənt/','noun',["They were affluent, but aspired to true wealth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indigestion','n.消化不良','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intrude','vi.侵入，闯入；打扰，侵扰','/ɪnˈtɹuːd/','/ɪnˈtɹuːd/','verb',["to intrude on families at unseasonable hours; to intrude on the lands of another"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('simplicity','n.简单，容易；朴素，质朴','/sɪmˈplɪsɪti/','/sɪmˈplɪsɪti/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blink','v.眨眼睛；闪亮，闪烁n.眨眼睛','/blɪŋk/','/blɪŋk/','noun',["The loser in the staring game is the person who blinks first.","The blinking text on the screen was distracting.","to blink the question"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('summit','n.最高点，峰顶，极点；峰会','/ˈsʌmɪt/','/ˈsʌmɪt/','noun',["In summer, it is possible to hike to the summit of Mount Shasta.","They met for an international summit on environmental issues."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perfume','n.香味；香水vt.使充满香气；洒香水于','/ˈpɜːfjuːm/','/ˈpɜːfjuːm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('magnify','vt.放大，扩大；夸大','/ˈmaɡnɪfaɪ/','/ˈmaɡnɪfaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('redundant','adj.多余的；累赘的','/ɹɪˈdʌn.dənt/','/ɹɪˈdʌn.dənt/','adjective',["Four employees were made redundant."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preliterate','adj.文字出现以前的，没有文字的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('factor','n.要素，因素；因数；系数','/ˈfæktə/','/ˈfæktɚ/','noun',["The factor of the trading post bought the furs.","The economy was a factor in this year''s budget figures.","3 is a factor of 12, as are 2, 4 and 6."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pinch','v.捏，掐；夹痛；偷窃；逮捕n.捏，掐；一撮，微量','/pɪntʃ/','/pɪntʃ/','noun',["I gave the leather of the sofa a pinch, gauging the texture.","The children were scolded for pinching each other.","Someone has pinched my handkerchief!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mischievous','adj.恶作剧的，顽皮的，淘气的；恶意的','/ˈmɪs.t͡ʃə.vəs/','/ˈmɪs.t͡ʃə.vəs/','adjective',["Matthew had a twin brother called Edward, who was always mischievous and badly behaved."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wan','adj.苍白的，无血色的；憔悴的','/wɒn/','/wɒn/','noun',["A wan expression"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('continuity','n.连贯性，连续性','/ˌkɒntɪˈnjuːəti/','/ˌkɑntɪˈn(j)uːəti/','noun',["Considerable continuity of attention is needed to read German philosophy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wax','v.给…打蜡；渐满n.蜡；蜡状物','/wæks/','/wæks/','noun',["What role does the wax in your earhole fulfill?"]);
