INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arable','adj.可耕作的，适于耕作的n.可耕地','/ˈæɹəbl̩/','/ˈæɹəbl̩/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gist','n.主旨，要点，大意','/dʒɪst/','/dʒɪst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('urban','adj.城市的，市内的','/ˈɜːbən/','/ˈɜːbən/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refer','v.提到，谈及；查阅，参考','/ɹɪˈfɜː/','/ɹɪˈfɝ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stellar','adj.星的，恒星的，星球的；精彩的；优秀的','/ˈstɛlə/','/ˈstɛlə/','adjective',["The actress gave a stellar performance."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flame','v.燃烧；闪耀n.火舌，火焰；光芒，光辉；强烈的感情','/fleɪm/','/fleɪm/','noun',["The cello has a two-piece back with a beautiful narrow flame.","I flamed him for spamming in my favourite newsgroup."]);
