INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('criteria','n.[criterion的复数形式]标准，准则','/kɹaɪˈtɪəɹ.i.ə/','/kɹaɪˈtɪəɹ.i.ə/','noun',["Criterion of choice, of decision, of selection"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obscene','adj.淫秽的，下流的；骇人听闻的；可憎的，可恶的','/əbˈsiːn/','/əbˈsin/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attentive','adj.注意的，专心的；关心的','/əˈtɛntɪv/','/əˈtɛntɪv/','adjective',["She is an attentive listener, but does not like to talk much.","a husband attentive to his wife''s needs"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prohibitive','adj.禁止的，抑制的；高得令人难以承受的','','','noun',["Some countries are more prohibitive than others when it comes to hot topics like euthanasia and cloning.","I''d like to visit Europe someday, but the cost is prohibitive right now."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flair','n.才能，本领；天资','/flɛə̯/','/flɛɚ̯/','noun',["to have a flair for art","to dress with flair"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crush','vt.碾碎；使变形；镇压','/kɹʌʃ/','/kɹʌʃ/','noun',["a crush at a reception","I''ve had a huge crush on her since we met many years ago.","to crush grapes"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embed','vt.把…嵌入；使深留脑中','/əmˈbɛd/','/əmˈbɛd/','noun',["to embed something in clay, mortar, or sand","We wanted to embed our reporter with the Fifth Infantry Division, but the Army would have none of it.","The instructions showed how to embed a chart from the spreadsheet within the wordprocessor document."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('citadel','n.堡垒，要塞','/ˈsɪtədəl/','/ˈsɪtədəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('promising','adj.有希望的；有前途的','/ˈpɹɒmɪsɪŋ/','/ˈpɹɒmɪsɪŋ/','verb',["He promised to never return to this town again.","The clouds promise rain.","a promising young apprentice"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambivalent','adj.对立的，感情矛盾的','/æmˈbɪv.ə.lənt/','/æmˈbɪv.ə.lənt/','adjective',["He has an ambivalent relationship towards his parents."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('practicable','adj.能实行的，可行的，适用的','/ˈpɹæktɪkəbəl/','/ˈpɹæktɪkəbəl/','adjective',[]);
