INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('implicit','adj.含蓄的；绝对的；内含的','/ɪmˈplɪsɪt/','/ɪmˈplɪsɪt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('purity','n.纯度；纯洁，纯净，纯粹','/ˈpjɔːɹɪti/','/ˈpjɔːɹɪti/','noun',[]);
