INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pensive','adj.沉思的；忧虑的','/ˈpɛn.sɪv/','/ˈpɛn.sɪv/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reliever','n.救济者；缓解物','','','noun',["The first reliever got the last two outs of the sixth.","I''ll be the reliever today so that you can each take a break."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acumen','n.敏锐，聪明','/əˈkjuːmən/','/əˈkjuːmən/','noun',[]);
