INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noteworthy','adj.显著的，值得注目的','/ˈnəʊtˌwɜːði/','/ˈnəʊtˌwɜːði/','noun',["Zukertort represent the other most noteworthy tournaments."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shirk','v.逃避，规避','/ʃɜːk/','/ʃɝk/','noun',["If you have a job, don''t shirk from it by staying off work."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tentative','adj.试验性的；不确定的，暂定的；犹豫的','/ˈtɛntətɪv/','/ˈtɛntətɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cosmos','n.宇宙','/ˈkɒz.mɒs/','/ˈkɒz.mɒs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('climate','n.气候；气候区，地带；风气，氛围；思潮','/ˈklaɪmɪt/','/ˈklaɪmɪt/','noun',["Industries that require a lot of fossil fuels are unlikely to be popular in the current political climate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('staggering','adj.巨大的；势不可挡的；惊人的，令人吃惊的','','','verb',["The army suffered a staggering defeat."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incredulous','adj.怀疑的，不轻信的','/ɪnˈkɹɛdjʊləs/','/ɪnˈkɹɛdjʊləs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('condole','vi.向…吊唁；慰问','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grid','n.格子，栅格；地图上的坐标方格，网格；输电网，煤气输送网','/ɡɹɪd/','/ɡɹɪd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circumference','n.周围，周边；圆周；周长','/sɜːˈkʌm.fɹəns/','/sɝːˈkʌm.fɹəns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rage','v.猛烈地继续，激烈进行；发怒，怒斥；迅速蔓延，猖獗n.风靡一时的事物，时尚；狂怒','/ɹeɪdʒ/','/ɹeɪdʒ/','noun',["Miniskirts were all the rage back then."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('finalize','vt.使完成；把…最后定下来；定稿','/ˈfaɪnəlaɪz/','/ˈfaɪnəlaɪz/','verb',["As soon as we get the plane tickets, we''ll finalize our reservations with the hotel."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hull','n.外壳；船身，船体vt.给…去外壳','/hʌl/','/hʌl/','noun',["She sat on the back porch hulling peanuts."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preside','vi.担任主席；主持；掌管','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('economic','adj.经济的；经济上的；经济学的；合算的','/ˌiːkəˈnɒmɪk/','/ˌiːkəˈnɒmɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stuff','n.原料，材料vt.填满，塞满；让…吃饱','/stʌf/','/stʌf/','noun',["What is all that stuff on your bedroom floor?  He didn''t want his pockets to bulge so he was walking around with all his stuff in his hands.","I had to do some stuff.","Can I have some of that stuff on my ice-cream sundae?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whim','n.一时的兴致，冲动；怪念头，奇想','/wɪm/','/wɪm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arrest','n&vt.逮捕，拘留；停止，阻止；吸引','/əˈɹɛst/','/əˈɹɛst/','noun',["The police have arrested a suspect in the murder inquiry."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assortment','n.分类；各种各样','/əˈsɔːtmənt/','/əˈsɔːtmənt/','noun',["This box has an assortment of chocolates. There''s a picture on the cover so you know which is which."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rumor','n.传闻，谣言','/ˈɹuːmə(ɹ)/','/ˈɹuːmə(ɹ)/','noun',["There''s a rumor going round that he''s going to get married.","They say he used to be a thief, but that''s just rumor.","John is rumored to be next in line for a promotion."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overflow','v.泛滥，溢出n.溢出；容纳不下的物','/ˈəʊvəˌfləʊ/','/ˈəʊvəˌfləʊ/','noun',["The river overflowed the levee.","The flash flood overflowed most of the parkland and some homes.","The waters overflowed into the Ninth Ward."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('provoke','vt.挑动，激怒，挑衅；引发，引起','/pɹəˈvəʊk/','/pɹəˈvoʊk/','verb',["Don''t provoke the dog; it may try to bite you."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('marked','adj.显著的；有记号的；被监视的','/ˈmɑːkɪd/','/mɑɹkt/','adjective',["The eighth century BC saw a marked increase in the general wealth of Cyprus.","e.g. in author and authoress, the latter is marked for its gender by a suffix.","A marked man."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pathological','adj.病态的；病理学的；不理智的，无道理的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recital','n.音乐演奏会；诗歌朗诵会；赘述','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tangle','v.缠结，纠结n.混乱；纠纷，不和','/ˈtæŋ.ɡəl/','/ˈtæŋ.ɡəl/','noun',["I tried to sort through this tangle and got nowhere.","Her hair was tangled from a day in the wind.","Don''t tangle with someone three times your size."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recurring','adj.往复的，反复的，再次发生的','','','verb',["The theme of the prodigal son recurs later in the third act.","He has recurring asthma attacks.","Every rational number can be written as either a terminating decimal or a recurring decimal."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tranquil','adj.安静的，平静的','/ˈtɹæŋ.kwɪl/','/ˈtɹæŋ.kwɪl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pleasing','adj.令人高兴的，愉快的','/ˈpliːzɪŋ/','/ˈplizɪŋ/','verb',["Her presentation pleased the executives.","Just do as you please."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('keen','adj.灵敏的，敏锐的；热心的，渴望的；激烈的；锋利的','/kiːn/','/kin/','verb',["I’m keen on computers.","This boy has a keen appetite.","keen satire or sarcasm"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absenteeism','n.旷课；旷工','/æb.sənˈtiːˌɪz.m̩/','/æb.sənˈtiːˌɪz.m̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gait','n.步法，步态','/ɡeɪt/','/ɡeɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overhaul','n.仔细检查；彻底检修vt.仔细检查；彻底检修','/ˈəʊvəˌhɔːl/','/ˈoʊvɚˌhɔl/','noun',["The engine required a complete overhaul to run properly."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elementary','adj.初级的，基础的；基本的；简单的','/(ˌ)ɛlɪ̈ˈmɛnt(ə)ɹɪ/','/(ˌ)ɛlɪ̈ˈmɛnt(ə)ɹɪ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solemn','adj.庄严的，严肃的；隆重的','/ˈsɒləm/','/ˈsɑləm/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embarrass','vt.使尴尬，使困窘；使困惑','/ɪmˈbæ.ɹəs/','/ɪmˈbæ.ɹəs/','verb',["The crowd''s laughter and jeers embarrassed him.","The motion was advanced in order to embarrass the progress of the bill.","A man or his business is embarrassed when he cannot meet his pecuniary engagements."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acute','adj.严重的；极度的，激烈的；敏锐的','/əˈkjuːt/','/əˈkjut/','noun',["The word ‘cafe’ often has an acute over the ‘e’.","He acutes his rising inflection too much.","It was an acute event."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stigma','n.污点，耻辱；烙印；特征','/ˈstɪɡmə/','/ˈstɪɡmə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pathology','n.反常，变态；病理学；病状','/pəˈθɒlədʒi/','/pəˈθɒlədʒi/','noun',["The surgeon sent a specimen of the cyst to the pathology department for staining and analysis to determine its histologic subtype."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('silica','n.硅石，硅土；二氧化硅','/ˈsɪl.ɪ.kə/','/ˈsɪl.ɪ.kə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remark','v.评论；谈论；察觉n.评论，评语；注释','/ɹɪˈmɑːk/','/ɹɪˈmɑɹk/','noun',["a biting remark","He remarked that it was getting late."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dissenter','n.不同意者，反对者','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strive','vi.奋斗，努力；力求','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intelligible','adj.聪明的，理智的；易懂的，易理解的','/ɪnˈtɛlədʒəbl̩/','/ɪnˈtɛlədʒəbl̩/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('along','adv.向前；一起prep.沿着','/əˈlɑŋ/','/əˈlɔŋ/','adverb',["John played the piano and everyone sang along.","Don''t stop here. Just move along."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cashier','n.收银员，出纳员','/kəˈʃɪə/','/kəˈʃɪə/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inert','adj.无活动的，惰性的；不活泼的，迟钝的','/ɪnˈɝt/','/ɪnˈɝt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dissimulate','v.掩盖，掩饰，假装','/-jə-/','/-jə-/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soccer','n.足球','/ˈsɒk.ə/','/ˈsɒk.ə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breach','n.违背；破裂；缺口vt.打破；违反','[bɹiːtʃ]','[bɹiːtʃ]','noun',["A clear breach is when the waves roll over the vessel without breaking. A clean breach is when everything on deck is swept away.","They breached the outer wall, but not the main one."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wit','n.智力，才智；风趣；机智幽默的人','/wɪt/','/wɪt/','noun',["He''s gone completely out of his wits.","Where she has gone to is beyond the wit of man to say.","My father had a quick wit and a steady hand."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('respire','v.呼吸','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('selective','adj.选择的，选择性的；精挑细选的','/səˈlɛktɪv/','/səˈlɛktɪv/','adjective',["selective pressure","He''s very selective and spent hours in the store choosing a new shirt.","In the USA, military conscription is controlled by the Selective Service."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handful','n.一把；少数人','/ˈhæn(d)fəl/','/ˈhæn(d)fəl/','noun',["Those twins are a real handful to look after."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rebate','n.回扣，折扣；退还款','/ɹəˈbeɪt/','/ɹəˈbeɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('systematize','vt.使系统化，使条理化，使成体系','/ˈsɪstəməˌtaɪz/','/ˈsɪstəməˌtaɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barter','n&v.实物交易，以物易物','/ˈbɑːtə(ɹ)/','/ˈbɑːtə(ɹ)/','noun',["We had no money so we had to live by barter.","The man used his watch as barter to pay for his tab.","She bartered a bonsai for one of the rare books in my library."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bewilder','vt.使迷惑，使不知所措','/bɪˈwɪldə(ɹ)/','/bɪˈwɪldə(ɹ)/','verb',["All the different possible options may bewilder us."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diminish','v.降低，贬低；减少，减弱','/dɪˈmɪnɪʃ/','/dɪˈmɪnɪʃ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surpass','vt.超过，超越，胜过','/sɚˈpæs/','/sɚˈpæs/','verb',["The former problem student surpassed his instructor''s expectations and scored top marks on his examination."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('linguist','n.语言学家；通晓数国语言的人','/ˈliŋɡwɪst/','/ˈliŋɡwɪst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aloof','adj.远离的；冷淡的，冷漠的','/əˈluːf/','/əˈluːf/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('idealize','vt.将…理想化','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gouge','vt.挖出；敲竹杠n.凿子','/ɡaʊdʒ/','/ɡaʊdʒ/','noun',["The nail left a deep gouge in the tire.","Japanese and Chinese printers used to gouge characters in wood.","The company has no competition, so it tends to gouge its customers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('succumb','vi.屈服，屈从；死亡','/səˈkʌm/','/səˈkʌm/','verb',["Thai culture as in many other Asian cultures, is succumbing to the influence of westernization.","succumb to pneumonia"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disproportionate','adj.不成比例的','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('translucent','adj.半透明的','/tɹænzˈluː.sənt/','/tɹænzˈlu.sənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fin','n.鳍；鳍状物；翼','/fɪn/','/fɪn/','noun',["The fish''s fins minimize water flow.","a dolphin''s fin","The fin stabilises the plane in flight."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sauce','n.调味汁，佐料','/sɔːs/','/sɑs/','noun',["apple sauce; mint sauce","[meat] pie and [tomato] sauce","Maybe you should lay off the sauce."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('husk','n.外壳，外皮vt.去壳，削皮','/hʌsk/','/hʌsk/','noun',["A coconut has a very thick husk.","His attorney was a dried-up husk of a man."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perch','v.栖息，停留；把…置于较高处；坐于n.栖息处，栖木；高处，较高的位置；鲈鱼','/pɜːtʃ/','/pɝtʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ablaze','adj.着火的，燃烧的；闪耀的；情绪激动的','/əˈbleɪz/','/əˈbleɪz/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grouse','v.发牢骚，抱怨n.松鸡；怨言','/ɡɹaʊs/','/ɡɹaʊs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overcharge','v.讨价过高，索价过高；过量装填；渲染，夸张n.过高的要价；超载','','','noun',["to overcharge a description"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('saucy','adj.无礼的；俏皮的；漂亮的','/ˈsɔː.sɪ/','/ˈsɔ.si/','adjective',["She is a loud, saucy child who doesn''t show a lot of respect to her elders.","I enjoyed the dancing, but my wife found it a little too saucy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neglect','vt&n.忽略，忽视；疏忽','/nɪˈɡlɛkt/','/nɪˈɡlɛkt/','noun',["to neglect duty or business;  to neglect to pay debts","to neglect strangers"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gang','vi.合伙n.一帮，一伙；帮派','/ɡæŋ/','/ɡæŋ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vein','n.静脉；叶脉；纹理，纹路；方式，风格','/veɪn/','/veɪn/','noun',["in the same vein","The play is in a satirical vein."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shrink','v.收缩，缩小；退缩，畏缩','/ˈʃɹɪŋk/','/ˈʃɹɪŋk/','noun',["My shrink said that he was an enabler, bad for me.","The dryer shrank my sweater.","This garment will shrink when wet."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('veil','n.面纱；遮蔽物vt.以面纱掩盖；掩饰','/veɪl/','/veɪl/','noun',["a nun''s veil","The forest fire was veiled by smoke, but I could hear it clearly."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('league','n.联盟，同盟；等级，级别','/liːɡ/','/liːɡ/','noun',["the League of Nations","My favorite sports organizations are the National Football League and the American League in baseball.","Forget about dating him; he''s out of your league."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('locality','n.地点；位置','/ləʊˈkælɪti/','/loʊˈkælɪti/','noun',["locality of trial"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uncanny','adj.神秘的；易乎寻常的','/ʌnˈkæni/','/ʌnˈkæni/','noun',["He bore an uncanny resemblance to the dead sailor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('panic','n&v.惊慌','/ˈpænɪk/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fold','n.褶，褶层；褶皱；褶痕，褶缝；羊栏，','/fəʊld/','/foʊld/','noun',["After two reraises in quick succession, John realised his best option was probably a fold.","If you fold the sheets, they''ll fit more easily in the drawer.","Cardboard doesn''t fold very easily."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('canyon','n.峡谷','/ˈkænjən/','/ˈkænjən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impenetrable','adj.不能穿透的；不可理解的，高深莫测的','/ɪmˈpɛnətɹəbəl/','/ɪmˈpɛnətɹəbəl/','adjective',["The fortress is impenetrable, so it cannot be taken.","Business jargon makes this document impenetrable, I can''t understand it.","When night falls, she cloaks the world in impenetrable darkness."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurl','v.猛投；大声斥责','/hɝl/','/hɝl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frank','adj.坦白的，直率的','/fɹæŋk/','/fɹæŋk/','noun',["May I be frank with you?","The research probes whether treating pre-diabetes with metformin can prevent progression to frank diabetes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inscribe','v.写、题、铭刻；铭记','/ɪnˈskɹaɪb/','/ɪnˈskɹaɪb/','verb',["I inscribed my name into the book."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rape','vt&n.强奸；肆意破坏','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('metaphor','n.隐喻，暗喻','/ˈmɛt.ə.fɔː(ɹ)/','/ˈme.tə.fɚ/','noun',["desktop metaphor; wastebasket metaphor"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('genre','n.类型；流派','/(d)ʒɒn.ɹə/','/(d)ʒɑn.ɹə/','noun',["The computer game Half-Life redefined the first-person shooter genre."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('permanence','n.永久，持久','/ˈpɜmənəns/','/ˈpɜmənəns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humanity','n.人类；人性；人道，仁慈','/hjuˈmænɪti/','/hjuˈmænɪti/','noun',["Philosophy is a humanity while psychology is a science."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outstanding','adj.优秀的，杰出的，出色的；未解决的；未偿付的','','','verb',["outstanding contracts"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adobe','n.泥砖，土坯','/əˈdəʊ.bi/','/əˈdoʊ.bi/','noun',["Many people in Texas and New Mexico live in adobe houses."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unbridgeable','adj.不能架桥的；不能逾越的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('infuriate','vt.激怒','/ɪnˈfjʊəɹieɪt/','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flu','n.流行性感冒','/flʉː/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plunge','v.掉入；暴跌，突降n.跳水；猛跌，骤降；卷入','/plʌndʒ/','/plʌndʒ/','noun',["A plunge into the sea","to plunge the body into water","to plunge a dagger into the breast;   to plunge a nation into war"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skeptical','adj.怀疑的','/ˈskeptɪkəl/','/ˈskeptɪkəl/','adjective',["I can see why people are so skeptical [sic] about him, but I think he''s on to something here. (regarded by organizations such as the BBC as an error)"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decipher','vt.破译','/dɪˈsaɪfə(ɹ)/','/dɪˈsaɪfə(ɹ)/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burgeon','vi.迅速成长，发展','/ˈbɜː.d͡ʒən/','/ˈbɝː.d͡ʒən/','noun',["Gradually, the town burgeoned into a thriving city."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('naive','adj.天真的，率真的，质朴的；幼稚的，无知的，轻信的；稚拙派的','/naɪˈiːv/','/naɪˈiːv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sewage','n.污水，污物','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('essential','adj.基本的，本质的；极其重要的，必不可少的n.要素，实质；必需品','/ɪˈsɛn.ʃəl/','/ɪˈsɛn.ʃəl/','noun',["Don’t mind him being grumpy. That’s the essential Fred."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expenditure','n.花费，支出','/ɛkˈspɛndɪt͡ʃə/','/ɛkˈspɛndɪt͡ʃɚ/','noun',["The expenditure of time, money, and political capital on this project has been excessive."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clarify','vt.澄清，阐明','/ˈklæɹɪfaɪ/','/ˈklæɹɪfaɪ/','verb',["Leave the wine for 24 hours and it will clarify."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('haunt','vt.出没于；萦绕在心头；长期缠扰n.常去的地方','/hænt/','/hænt/','noun',["I went back the town I used to live and visited all my old haunts.","A couple of ghosts haunt the old, burnt-down house.","The memory of his past failures haunted him."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scarf','n.围巾，披巾，头巾','/skɑːf/','/skɑːf/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('congenial','adj.情投意合的；相宜的，适宜的；适当的，合适的','','','adjective',["The congenial bartender makes the Hog’s Head an inviting place to hang out during the weekends."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('graphics','n.图形，图像；制图法，制图学','/ˈɡɹæfɪks/','/ˈɡɹæfɪks/','noun',["This game is really fun, but the graphics aren''t very good."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('furnish','vt.提供，供应；布置，为…配备家具','/ˈfɜːnɪʃ/','/ˈfɝnɪʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('larynx','n.喉','/ˈlæɹɪŋks/','/ˈlæɹɪŋks/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excavation','n.挖掘，发掘；出土文物；挖掘现场','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exclude','vt.把…排除在外','/ɪksˈkluːd/','/ɪksˈkluːd/','verb',["to exclude young animals from the womb or from eggs","Count from 1 to 30, but exclude the prime numbers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amalgamation','n.融合，合并；联合，结合','/əˌmælɡəˈmeɪʃən/','/əˌmælɡəˈmeɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('creativity','n.创造力，创造性','/kɹieɪˈtɪvɪti/','/-ɾi/','noun',["His creativity is unsurpassed by his fellow students in the art class."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enlighten','vt.启发，启迪；开导；阐明','/ənˈlaɪtn̩/','/ənˈlaɪtn̩/','verb',["The sun enlightens the Earth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('needy','adj.贫穷的，贫困的','/ˈniːdi/','/ˈniːdi/','adjective',["Needy people want to give too, but have few material goods to offer.","It''s emotionally exhausting to be around her because she''s so needy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('utmost','adj.最大限度的n.最大限度；最大量','/ˈʌt.məʊ̯st/','/ˈʌt.moʊ̯st/','noun',["the utmost limits of the land;  the utmost extent of human knowledge","the utmost assiduity;  the utmost harmony;  the utmost misery or happiness"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deduct','vt.扣除，减去；推论，演绎','/dɪˈdʊkt/','/dɪˈdʊkt/','verb',["I will deduct the cost of the can of peas from the money I owe you."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('image','n.形象，印象；画像；影像，映像；意象，比喻','/ˈɪmɪd͡ʒ/','/ˈɪmɪd͡ʒ/','noun',["The Bible forbids the worship of graven images.","Most game console emulators do not come with any ROM images for copyright reasons.","The number 6 is the image of 3 under f that is defined as f(x) = 2x."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('voracious','adj.狼吞虎咽的，贪婪的；求知欲强的','/vɔːˈɹeɪ.ʃəs/','/vɔːˈɹeɪ.ʃəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('topography','n.地形学；地形，地貌','/təˈpɒɡɹəfi/','/təˈpɒɡɹəfi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ribbon','n.带状物；丝带，缎带；绶带；色带','/ˈɹɪbən/','/ˈɹɪbən/','noun',["a steel or magnesium ribbon"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trance','n.恍惚；昏睡状态','/tɹɑːns/','/tɹɑːns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scrub','v.擦洗；取消n.灌木丛；丛林地带','/skɹʌb/','/skɹʌb/','noun',["What a scrub! Instead of washing the dishes she put the used food on her face!","oak scrub"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affirm','v.断言，坚持声称；证实，确认','/əˈfɜːm/','/əˈfɝm/','verb',["She affirmed that she would go when I asked her.","They did everything they could to affirm the children''s self-confidence."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('homogeneous','adj.同类的，相似的，同质的','/ˌhɒ.mə(ʊ)ˈdʒiː.nɪəs/','/ˌhɒ.mə(ʊ)ˈdʒiː.nɪəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('marble','n.大理石；子弹','/ˈmɑːbəl/','/ˈmɑɹbəl/','noun',["The Elgin Marbles were originally part of the temple of the Parthenon.","a marble mantel","a marble heart"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('waggle','v&n.摆动','/ˈwaɡəl/','/ˈwaɡəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garb','n.服装，装束vt.穿着，装扮','/ɡɑː(ɹ)b/','/ɡɑː(ɹ)b/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('necessity','n.必需品；必要，需要；必然性','/nɪˈsɛsəti/','/nɪˈsɛsəti/','noun',["I bought a new table out of necessity. My old one was ruined.","A tent is a necessity if you plan on camping.","doctrine of necessity"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salon','n.营业性的厅；沙龙；客厅，会客厅','/səˈlɒn/','/səˈlɒn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vocal','adj.声音的，嗓音的，发声的；直言不讳的','/ˈvəʊ.kəl/','/ˈvəʊ.kəl/','noun',["vocal problems","vocal melody","a vocal sound"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clasp','n.搭扣，扣环；紧抱；紧握vt.握紧；抱紧；扣住，扣牢','/klɑːsp/','/klæsp/','noun',["I always have a hard time working the clasp on this necklace!","He took her hand in a firm clasp.","They clasped hands and parted as friends."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hover','vi.徘徊，彷徨；翱翔，盘旋','/ˈhɒ.və(ɹ)/','/ˈhʌ.vɚ/','noun',["The hummingbird hovered by the plant.","His pen hovered above the paper.","Filling in the voting form, I hovered between Labour and Liberal Democrat."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('personality','n.个性；性格；名人','/-i/','/-i/','noun',["The president has a unique personality.","In his final act, the comedian takes on a child''s personality.","Johnny Carson was a respected television personality."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terminology','n.专门用语，术语；术语学','/ˌtɜːməˈnɒləd͡ʒi/','/ˌtɜːməˈnɒləd͡ʒi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alert','adj.警觉的，警惕的vt.警告，提醒n.警戒；警报','/əˈlɜːt/','/əˈlɝt/','noun',["an airborne alert; ground alert"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rate','v.估价；评级，评价；把…列为n.率，比率；速度；价格；等级','/ɹeɪt/','/ɹeɪt/','noun',["At the height of his powers, he was producing pictures at the rate of four a year.","The car was speeding down here at a hell of a rate.","The rate of production at the factory is skyrocketing."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plot','n.情节；阴谋，密谋；','/plɒt/','/plɑt/','noun',["The assassination of Lincoln was part of a larger plot.","They had plotted a robbery.","They plotted the number of edits per day."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sanction','vt.同意，许可；惩罚，实施制裁n.同意，许可；约束；制裁','/ˈsæŋkʃən/','','noun',["The whalers had been operating in the contested waters off the island with sanction from the Japanese government.","The United States enacted a new round of sanctions against the apartheid regime of South Africa."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mosaic','n.马赛克；镶嵌工艺','/məʊˈzeɪ.ɪk/','/məʊˈzeɪ.ɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proprietor','n.所有者，业主','/pɹəˈpɹaɪətɚ/','/pɹəˈpɹaɪətɚ/','noun',["From 10 September 1621 till 12 June 1632, Sir William Alexander, styled Earl of Stirling and Viscount of Canada, was proprietor of the Scottish colony Nova Scotia."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rehearse','v.预演，排练；默诵；照搬，重复','[ɹɪˈhɜːs]','[ɹɪˈhɜːs]','verb',["There''s no need to rehearse the same old argument; we''ve heard it before, and we all agree.","The witness rehearsed the events of the night before for the listening detectives.","The lawyer advised her client to rehearse her testimony before the trial date."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thwart','vt.阻碍；使…受挫','/θwɔːt/','/θwɔːt/','noun',["The fisherman sat on the aft thwart to row.","A well-made dugout canoe rarely needs a thwart.","Our plans for a picnic were thwarted by the thunderstorm."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gamble','n&v.投机，冒险；赌博，打赌','/ˈɡæm.bəl/','/ˈɡæm.bəl/','noun',["I had a gamble on the horses last weekend.","The sailors had taken many gambles with the sea and always won.","He gambled his reputation on the outcome."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pesticide','n.杀虫剂，农药','/ˈpɛstɨsaɪd/','/ˈpɛstɨsaɪd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deport','vt.驱逐出境','/dɪˈpɔːt/','/dɪˈpɔɹt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('syrup','n.糖浆','/ˈsɪ.ɹəp/','/ˈsi.ɹəp/','noun',["maple syrup","cough syrup"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('counter','adv.相反地adj.相反的n.柜台；','/ˈkaʊntə/','/ˈkaʊntə/','noun',["He''s only 16 months, but is already a good counter – he can count to 100.","He rolled a six on the dice, so moved his counter forward six spaces.","He put his money on the counter, and the shopkeeper put it in the till."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Gothic','adj.哥特式的，哥特风格的n.哥特式建筑','','','adjective',["Gothic arches","Gothic tales","Gothic letters"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rash','adj.鲁莽的，轻率的n.疹，皮疹；一连串令人不快的事物','/ɹæʃ/','/ɹæʃ/','adjective',["rash words spoken in the heat of debate"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('starch','n.淀粉；','/stɑːtʃ/','/stɑɹtʃ/','noun',["She starched her blouses."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depose','vt.革除，罢免，废黜','/dɪˈpəʊz/','/diˈpoʊz/','verb',["A deposed monarch may go into exile as pretender to the lost throne, hoping to be restored in a subsequent revolution.","After we deposed the claimant we had enough evidence to avoid a trial."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('correspondent','n.报道者，记者；通信者','/ˌkɒɹɪˈspɒndənt/','/ˌkɔɹɪˈspɑndənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('renew','vt.使…续期；重新开始；重申；修复','/ɹɪˈnjuː/','','verb',["I''d like to renew these three books.  Did you know that you can renew online?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('withdraw','v.取消；撤销；提取；撤退，撤离','/wɪðˈdɹɔː/','/wɪðˈdɹɔː/','verb',["to withdraw false charges"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('languish','vi.憔悴；凋谢，枯萎；受煎熬','/ˈlæŋ.ɡwɪʃ/','/ˈlæŋ.ɡwɪʃ/','verb',["He languished without his girlfriend","He languished in prison for years","The case languished for years before coming to trial."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('melodic','adj.旋律的，曲调的；音调优美的','','[mɨˈlɑɾɪk]','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('divine','adj.神的，神圣的；非凡的，超人的；极好的，','/dɪˈvaɪn/','/dɪˈvaɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abhor','vt.憎恨，厌恶','/əbˈhɔː(ɹ)/','/æbˈhɔɹ/','verb',["I absolutely abhor being stuck in traffic jams"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('legislative','adj.立法的，有立法权的；根据法规执行的n.立法机关','/ˈlɛ.dʒɪ.slə.tɪv/','/ˈlɛ.dʒɪˌsleɪ.tɪv/','noun',["Although enormously influential in shaping the laws of the land, The House of Lords are not actually a legislative body."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transcribe','vt.记录，抄录；转录；改编','/trænˈskɹaɪb/','/trænˈskɹaɪb/','verb',["The doctor made several recordings today which she will transcribe into medical reports tomorrow."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foul','adj.污秽的，肮脏的；充满脏话的，辱骂性的；邪恶的','/faʊl/','/faʊl/','adjective',["A ship''s bottom is foul when overgrown with barnacles","His foul language causes many people to believe he is uneducated.","He has a foul set of friends."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intricate','adj.错综复杂的','/ˈɪn.tɹɪ.kət/','/ˈɪn.tɹɪ.kət/','adjective',["The architecture of this clock is very intricate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contemplate','v.思量，考虑，思忖；注视，凝视；打算','/ˈkɒn.təmˌpleɪt/','/ˈkɑn.təmˌpleɪt/','verb',["I contemplated doing the project myself, but it would have taken too long."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rodent','adj.啮齿目的；咬的n.啮齿目动物','/ˈɹəʊdənt/','/ˈɹəʊdənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advisory','adj.顾问的，咨询的；劝告的n.警报','/ədˈvaɪzəɹi/','/ədˈvaɪzəɹi/','noun',["The Coast Guard issued a small craft advisory, warning little boats to watch out for bad weather.","The advisory committee could only offer advice, but since that was almost always accepted they had real power.","The consultant''s advisory recommendations were selectively adopted."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maturity','n.成熟；完备','/məˈtjʊəɹəti/','/məˈtʊəɹəti/','noun',["Some foods and drinks, like wine, only reach their full taste at maturity, which literally comes at a price","The note was cashed at maturity."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subsistence','n.生存，生计','/səbˈsɪstəns/','/səbˈsɪstəns/','noun',["the subsistence of qualities in bodies"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frail','adj.体弱的，虚弱的；易碎的','/fɹeɪl/','/fɹeɪl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('announce','vt.宣布；通知；声称，宣称；广播，播音','/əˈnaʊns/','/əˈnaʊns/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mechanize','vt.使机械化','/ˈmɛkənaɪz/','/ˈmɛkənaɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decree','v.判决；颁布n.政令，法令；裁定，判决','/dɪˈkɹiː/','/dɪˈkɹiː/','noun',["A court decrees a restoration of property."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('traditional','adj.传统的，惯例的；口传的，传说的','/tɹəˈdɪʃnəl/','/tɹəˈdɪʃnəl/','noun',["I think her traditional values are antiquated.","traditional expositions of the Scriptures.","The traditional form of the character has twice as many strokes as the simplified form."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('malleable','adj.有延展性的，易成型的；易受影响的，可塑的','/ˈmæli.əbəl/','/ˈmæli.əbəl/','adjective',["My opinion on the subject is malleable."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('well-heeled','adj.富有的，有钱的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brittle','adj.易碎的；脆弱的；尖利的','/ˈbɹɪtl̩/','/ˈbɹɪtl̩/','noun',["As a child, my favorite candy was peanut brittle.","A diamond is hard but brittle.","Shortbread is my favorite cold pastry, yet being so brittle it crumbles easily, and a lot goes to waste."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affinity','n.密切关系；吸引力；喜爱','/əˈfɪnɪti/','/əˈfɪnɪti/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mediate','v.调解，调停，斡旋','/ˈmidi.ət/','/ˈmidi.ət/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amplify','vt.放大；增强；详述，充实','/ˈæmp.lɪ.faɪ/','/ˈæmp.lɪ.faɪ/','verb',["amplify a microscopes","amplify a signal"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inflation','n.通货膨胀，物价上涨；膨胀','/ɪnˈfleɪʃən/','/ɪnˈfleɪʃən/','noun',["The inflation of the balloon took five hours."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disposal','n.清除，外理，处置；变卖','[dɪsˈpəʊzəɫ]','[dɪsˈpəʊzəɫ]','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('matrimony','n.婚姻，婚配','/ˈmatɹɪməni/','/ˈmatɹɪməni/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recede','vi.退，后退；渐渐远去；逐渐减弱','/ɹɨˈsiːd/','/ɹɨˈsiːd/','verb',["to recede conquered territory"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delegate','n.代表vt.委派…为代表，授权','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suffragist','n.妇女政权论者','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('melodious','adj.旋律优美的，悦耳的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ethnology','n.民族学，文化人类学','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ability','n.能力，才干','/əˈ.bɪl.ɪ.ti/','/əˈ.bɪl.ɪ.ti/','noun',["This phone has the ability to have its software upgraded wirelessly.","She has an uncanny ability to defuse conflict."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('veto','n.否决权；禁止vt.否决；禁止','/ˈviːtəʊ/','/ˈviːtəʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delight','v.愉快，高兴n.快乐，高兴；令人高兴的事，乐趣','/dəˈlaɪt/','/dəˈlaɪt/','noun',["A beautiful landscape delights the eye."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proficient','adj.熟练的，精通的','/pɹəˈfɪʃ.ənt/','/pɹoʊˈfɪʃ.ənt/','noun',["He was a proficient writer with an interest in human nature."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('continuum','n.统一体','/kənˈtɪnjuəm/','/kənˈtɪnjuəm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contender','n.竞争者，争夺者，对手','','/kənˈtɛn.dɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slender','adj.细长的；苗条的，纤细的；微薄的，不足的','/ˈslɛndə/','/ˈslɛndɚ/','adjective',["A rod is a long slender pole used for angling.","Being a person of slender means, he was unable to afford any luxuries."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terminus','n.终点站','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conscious','adj.自觉的，意识到的；有知觉的，有意识的；有意的，刻意的','/ˈkɒn.ʃəs/','/ˈkɑn.ʃəs/','noun',["The noise woke me, but it was another few minutes before I was fully conscious.","Only highly intelligent beings can be fully conscious.","I was conscious of a noise behind me.   a very class-conscious analysis"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transaction','n.交易，业务；办理，处理','/tɹænˈzækʃən/','/tɹænˈzækʃən/','noun',["The transaction was made on Friday with the supplier.","I made the transaction with the vendor as soon as she showed me the pearls."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accomplishment','n.成就；完成；才艺，技艺','/ə.ˈkʌm.plɪʃ.mənt/','/ə.ˈkɑm.plɪʃ.mənt/','noun',["the accomplishment of an enterprise, of a prophecy, etc"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pants','n.内裤，短裤；裤子','/pænts/','/pænts/','noun',["The film was a load [or pile] of pants.","Your mobile is pants — why don’t you get one like mine?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('placid','adj.平静的，安静的；温和的，文静的','/ˈplæs.ɪd/','','adjective',["a placid disposition"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solitary','adj.孤独的；单独的，独自的；单个的；唯一的，仅有的','/ˈsɒlɪtɹi/','/ˈsɑlɪtɛɹi/','noun',["The prisoners who started the riot were moved to solitary.","a solitary journey","a solitary residence or place"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('second','adj.第二的；次等的，二等的v.赞成，附和num.第二n.秒；瞬间，片刻','/ˈsɛkɪnd/','/ˈsɛk.(ə)nd/','noun',["They were discounted because they contained blemishes, nicks or were otherwise factory seconds.","That was good barbecue. I hope I can get seconds.","I second the motion."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laudable','adj.值得赞美的，值得称赞的','/lɔːdəbl/','/lɔːdəbl/','adjective',["laudable actions","laudable juices of the body"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('antique','n.古物，','/ænˈtiːk/','/ænˈtiːk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thaw','v.融化，解冻；化冻；变暖；变得友善n.解冻时期；缓和','/θɔː/','/θɔː/','noun',["the ice thaws","It''s beginning to thaw.","Her anger has thawed."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fasten','v.使固定；系牢，扎牢；握住，抓牢','/ˈfɑːsn̩/','/ˈfæsn̩/','verb',["Can you fasten these boards together with some nails?","to fasten a blow"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contest','vt.竞争；争辩，就…提出异议n.竞赛；辩论；争夺','/ˈkɒn.tɛst/','/ˈkɑn.tɛst/','noun',["no contest","The child entered the spelling contest.","I will contest for the open seat on the board."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('asymmetrical','adj.不均匀的，不对称的','','','adjective',["Question six is asymmetrical: \"Are things going in the right direction or on the wrong track?\" (The West Wing, Season 1, Episode 21, Toby)"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turmoil','n.骚动，混乱；焦虑','/ˈtɜːmɔɪl/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clench','v&n.握紧，抓牢；咬紧','/klɛntʃ/','/klɛntʃ/','noun',["He clenched his fist in anger."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modernity','n.现代性','/məˈdɜː(ɹ)n.ɪ.ti/','/məˈdɜː(ɹ)n.ɪ.ti/','noun',["He was impressed by the architecture''s modernity.","The organization survived from ancient times to modernity."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('schematic','adj.图解的；纲要的；严谨的','/skiːˈmætɪk/','/skiːˈmætɪk/','noun',["I''ll have to study the schematics for the new integrated circuit before I can create a good layout."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rekindle','vt.重新点燃；使振作','','','verb',["After being abroad for a decade, when he came back he rekindled his obsession with cricket."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wrench','v.扭伤；猛拉，猛扭；使痛苦n.扭伤；痛苦，难受；扳手','/ɹɛnt͡ʃ̩̩/','/ɹɛnt͡ʃ̩̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('license','n.许可证，执照vt.批准，许可','/ˈlaɪsəns/','/ˈlaɪsəns/','noun',["In order to enter the building, I need to show my license.","It was decided to license Wikipedia under the GFDL.","I am licensed to practice law in this state."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('puff','v.喘气，喘息；喷出n.吸；一缕；喘息','/pʌf/','/pʌf/','noun',["out of puff","puff of smoke","cream puff"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('squander','vt.浪费，挥霍','/ˈskwɒnd.ə/','/ˈskwɒnd.ə/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('synchronizer','n.同步装置','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perimeter','n.周长；外缘，边缘','/pəˈɹɪmɪtə(ɹ)/','/pəˈɹɪmɪtə(ɹ)/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('essay','n.散文，随笔；短文；评论','/ˈɛˌseɪ/','/ˈɛˌseɪ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('malice','n.恶意，怨恨','/ˈmælɪs/','/ˈmælɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('postpone','v.延期，推迟','/poʊstˈpoʊn/','/poʊstˈpoʊn/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('codify','vt.把…编成法典，使法律成文化；整理，系统化','/ˈkəʊ.dɨˌfaɪ/','/ˈkəʊ.dɨˌfaɪ/','verb',["The company president codified the goal as a one-line mission statement."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dorsal','adj.背部的，背脊的','/ˈdɔɹsəl/','/ˈdɔɹsəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('code','vt.编纂；把…编码n.法典，法规；密码，代码','/kəʊd/','/kəʊd/','noun',["This flavour of soup has been assigned the code WRT-9.","The medical code is a system of rules for the regulation of the professional conduct of physicians.","I wrote some code to reformat text documents."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('potassium','n.钾','/pəˈtæsiəm/','/pəˈtæsiəm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('displace','vt.取代；撤职；迫使…离开家园','/dɪsˈpleɪs/','/dɪsˈpleɪs/','verb',["Electronic calculators soon displaced the older mechanical kind."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hammer','v.锤打n.锤，槌；锤子','/ˈhæm.ə(ɹ)/','/ˈhæmɚ/','noun',["Bobby used a hammer and nails to fix the two planks together","The nail is too loose - give it a hammer.","The sound the piano makes comes from the hammers striking the strings"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ideology','n.思想体系；意识形态','/ˌaɪ.diːˈɒl.ə.d͡ʒiː/','/aɪ.di.ˈɑl.ə.d͡ʒi/','noun',["A dictatorship, in order to secure its reign, bans things that do not conform to its ideology."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('investigate','v.研究，调查','[ɪn.ˈves.tɪ.ɡeɪ̯t]','[ɪn.ˈves.tɪ.ɡeɪ̯t]','verb',["to investigate the causes of natural phenomena","to investigate an unsolved murder"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('troposphere','n.对流层','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swindle','vt&n.诈骗，骗取','/ˈswɪnd(ə)l/','/ˈswɪnd(ə)l/','noun',["The two men swindled the company out of $160,000.","She swindled more than £200 out of me."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subsist','vi.存活，生存','/səbˈsɪst/','/səbˈsɪst/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dive','vi&n.跳水；潜水','/ˈdaɪv/','/ˈdaɪv/','noun',["the dive of a hawk after prey","to dive into home plate","She dove right in and started making improvements."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sympathy','n.同情，同情心；赞同，支持','/ˈsɪmpəθi/','/ˈsɪmpəθi/','noun',["Many people in Hollywood were blacklisted merely because they were suspected of Communist sympathies."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rescue','vt&n.营救，搭救','/ˈɹɛs.kjuː/','/ˈɹɛs.kjuː/','noun',["The rescue of Jerusalem was the original motive of the Crusaders","The dog was a rescue with some behavior issues.","The well-trained team rescued everyone after the avalanche."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('influx','n.注入，涌入','/ˈɪnˌflʌks/','/ˈɪnˌflʌks/','noun',["I''ll buy a new computer when I get an influx of cash."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('determine','v.查明，确定；决心，决定；支配，影响','/dɪˈtɜːmɪn/','/dɪˈtɝmɪn/','verb',["The news of his father''s illness determined him to depart immediately.","The court has determined the cause.","I determined to go home at once."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devastate','vt.破坏，毁坏；令人震惊，使难以承受','/ˈdɛvəsteɪt/','/ˈdɛvəsteɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embark','v.上船','/ɛmˈbɑːk/','/ɛmˈbɑːk/','verb',["All passengers please embark now.","Phil embarked on his journey yesterday.","He embarked his fortune in trade."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cousin','n.堂兄弟，堂姐妹','/ˈkʌz.n̩/','/ˈkʌz.n̩/','noun',["I think my cousin is a good man."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intelligent','adj.有才智的，聪明的','/ɪnˈtɛlɪd͡ʒənt/','/ɪnˈtɛlɪd͡ʒənt/','adjective',["The engineer had a very intelligent design proposal for the new car.","My girlfriend and I had an intelligent conversation.","The hunt for intelligent life."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confer','v.授予；协商，商讨','/kənˈfɜː/','/kənˈfɜː/','verb',["The college has conferred an honorary degree upon the visiting Prime Minister.","They were in a huddle, conferring about something."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('walnut','n.胡桃；胡桃木','/ˈwɔːlnʌt/','/ˈwɑlnət/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incessantly','adv.不断地','/ɪnˈsɛs.ənt.li/','/ɪnˈsɛs.ənt.li/','adverb',["He jabbered incessantly and annoyed everyone."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imagist','adj.意象派的n.意象派诗人','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diagonal','adj.斜线的，','/daɪˈæɡnəl/','/daɪˈæɡnəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('knit','v.编结，编织；紧密结合，使紧凑；愈合；皱紧，皱','/ˈnɪt/','/ˈnɪt/','noun',["The first generation knitted to order; the second still knits for its own use; the next leaves knitting to industrial manufacturers.","The fight for survival knitted the men closely together.","All those seedlings knitted into a kaleidoscopic border."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aroma','n.芳香，香味；气氛，氛围','/əˈɹəʊmə/','/əˈɹoʊmə/','noun',["I love the aroma of cinnamon."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subversive','adj.颠覆性的，破坏性的n.颠覆分子','/səbˈvɜɹsɪv/','/səbˈvɜɹsɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strategic','adj.对全局有重要意义的，关键的；战略性的','/stɹəˈtiː.dʒɪk/','/stɹəˈtiː.dʒɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wholesome','adj.健康的，有利健康的；有道德的','','/ˈhoʊlsəm/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convenience','n.便利；便利设施','/kənˈviːnɪəns/','/kənˈvinjəns/','noun',["Fast food is popular because of its cost and convenience.","We will come over and begin the work at your convenience.","These are equally viable times and I propose we alternate between the two times in order to convenience as many people as possible."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('calculus','n.微积分；结石','/ˈkæl.kjʊ.ləs/','/ˈkæl.kjʊ.ləs/','noun',["lambda calculus","renal calculus ( = kidney stone)"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expedient','adj.得当的，可取的n.权宜之计，应急办法，临时手段','/ɪkˈspiːdi.ənt/','/ɪkˈspiːdi.ənt/','noun',["Most people, faced with a decision, will choose the most expedient option."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ensconce','vt.使安顿，安置，使安坐','/ɛnˈskɒns/','/ɛnˈskɑns/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inevitably','adv.不可避免地，必然地','/ɪˈnɛvətəbli/','/ɪˈnɛvətəbli/','adverb',["Despite the town''s best efforts, the dam inevitably gave way.","Inevitably, the next-door neighbour began to mow his lawn just as she lays down her head after a long night shift."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brand','vt.铭刻；打烙印于；丑化，败坏名声n.商标，品牌；类型；烙印','/bɹand/','/bɹand/','noun',["To burn something to brands and ashes.","Some brands of breakfast cereal contain a lot of sugar.","I didn''t appreciate his particular brand of flattery."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suspension','n.暂停；暂缓，推迟，延期；悬架；悬浮液','/səˈspɛnʃən/','','noun',["suspension from a hook","suspension from school as a disciplinary measure"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vibrant','adj.振动的；活泼的，充满生气的','/ˈvaɪbɹənt/','/ˈvaɪbɹənt/','adjective',["He has a vibrant personality."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insanity','n.精神错乱，疯狂','/ɪnˈsænɪti/','/ɪnˈsænɪti/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recreation','n.娱乐，消遣','/ɹɛkɹiˈeɪʃən/','/ɹɛkɹiˈeɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('portable','adj.轻便的，便携的，手提式的','/ˈpɔː(ɹ)təbl̩/','/ˈpɔː(ɹ)təbl̩/','noun',["a portable pension plan"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ancient','adj.古代的；古老的','/ˈeɪn.ʃənt/','/ˈeɪn.ʃənt/','noun',["an ancient city  an ancient forest","an ancient author  an ancient empire"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('antecede','vt.居先；高于','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attorney','n.辩护律师；代理人','/əˈtɜː(ɹ)ni/','/əˈtɜː(ɹ)ni/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expire','vi.到期，期满，失效；断气，去世','/ɛkˈspaɪ.ə(ɹ)/','/ɛkˈspaɪ.ə(ɹ)/','verb',["The patient expired in hospital.","My library card will expire next week."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('viral','adj.病毒的，病毒引起的','/ˈvaɪɹəl/','/ˈvaɪɹəl/','noun',["viral DNA","viral infection"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('singular','adj.单数的；突出的，卓越的；异常的','/ˈsɪŋɡjʊlə/','/ˈsɪŋɡjəlɚ/','noun',["A singular experiment cannot be regarded as scientific proof of the existence of a phenomenon.","She has a singular personality.","a man of singular gravity or attainments"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commentary','n.评论，注释；实况报道，现场解说','','','noun',["Caesar''s Commentaries on the Gallic War","We listened to the football commentary while watching the match."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('homosexuality','n.同性恋；同性恋行为','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minus','adj.减的，负的prep.减n.负数；减号；不足','/ˈmaɪnəs/','/ˈmaɪnəs/','noun',["a minus number","minus seven degrees","He got a grade of B minus for his essay."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conservative','adj.保守的，守旧的；不时新的，传统的n.保守派','/kənˈsɜːvətɪv/','/kənˈsɜːvətɪv/','noun',["The curriculum committee at this university is extremely conservative.","At a conservative estimate, growth may even be negative next year."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skeletal','adj.骨骼的，骸骨的；梗概的；轮廓的','/skəˈliːt(ə)l/','/skəˈliːt(ə)l/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unsubstantiated','adj.未经证实的，无事实根据的','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cabin','n.小屋；机舱，船舱','/ˈkæbɪn/','/ˈkæbɪn/','noun',["Abraham Lincoln was born in a log cabin.","the captain''s cabin:  Passengers shall remain in their cabins."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seem','v.好像，似乎','/siːm/','/siːm/','verb',["He seems to be ill.   Her eyes seem blue.   It seems like it is going to rain later.   How did she seem to you?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apprenticeship','n.学徒的身份；学徒的年限','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('persist','vi.坚持；持续','/pəˈsɪst/','/pɚˈsɪst/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pierce','v.刺穿，刺破；穿孔，打眼','/pɪəs/','/pɪɹs/','verb',["The diver pierced the surface of the water with scarcely a splash.","Can you believe he pierced his tongue?","A scream pierced the silence."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('calendar','n.日历，挂历，月历；日程表','/ˈkæl.ən.də/','/ˈkæl.ən.dɚ/','noun',["The three principal calendars are the Gregorian, Jewish, and Islamic calendars.","Write his birthday on the calendar hanging on the wall.","The club has a busy calendar this year."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patriarch','n.家长，族长','/ˈpeɪtɹɪɑːk/','/ˈpeɪtɹɪɑːk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intern','n.实习生vt.拘禁，软禁','/ɪnˈtɜːn/','/ɪnˈtɜːn/','noun',["The US government interned thousands of Japanese-Americans during World War II."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sensual','adj.感觉的，感官的；肉欲的；耽于感官享受的','/ˈsɛnsjuːəl/','/ˈsɛnsjuːəl/','adjective',["That massage was a very sensual experience!","Plato believed that this sensual world in which we live is inferior to the heavenly realm."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('righteous','adj.正直的，公正的；正义的，正当的','/ˈɹaɪtʃəs/','/ˈɹaɪtʃəs/','verb',["Human beings should take a righteous path, and so should art. We should promote kindness and beauty through art.","righteous indignation"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('speculate','v.推测；深思，沉思；投机，做投机买卖','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heed','n&v.注意，留心','/hiːd/','/hiːd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adorn','vt.装饰，装扮','/əˈdɔː(ɹ)n/','/əˈdɔɹn/','noun',["a character adorned with every Christian grace"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monster','adj.巨大的，庞大的n.怪物；庞然大物；恶魔','/ˈmɒnstə(ɹ)/','/ˈmɑnstɚ/','noun',["The children decided Grover was a cuddly monster.","Get away from those children, you meatheaded monster!","Sit still, you little monster!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scourge','vt.鞭笞；使受苦，折磨n.鞭子；祸害；鞭笞','/skɜːdʒ/','/skɔɹdʒ/','noun',["Graffiti is the scourge of building owners everywhere.","He flogged him with a scourge."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquaint','vt.使认识；使熟悉','/əˈkweɪnt/','/əˈkweɪnt/','verb',["I think you should acquaint him with the realities of the situation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('atrophy','n.萎缩','/ˈæ.tɹə.fi/','/ˈæ.tɹə.fi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pulp','vt.使成浆状n.纸浆；浆状物','/pʌlp/','/pʌlp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('undergraduate','n.大学肄业生；大学本科生','','','noun',["After completing my undergraduate studies, I embarked on a career in publishing."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('antibiotic','adj.抗菌的','/ˌæn.taɪ.baɪˈɒt.ɪk/','/ˌæn.taɪ.baɪˈɒt.ɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('joint','adj.连接的；共同的，共有的，联合的n.关节，骨节；接头，接合处','/dʒɔɪnt/','/dʒɔɪnt/','noun',["This rod is free to swing at the joint with the platform.","The water is leaking out of the joint between the two pipes.","The dovetail joint, while more difficult to make, is also quite strong."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('endangered','adj.濒危的，将要灭绝的','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('haphazard','adj.偶然的，任意的；无计划的，无秩序的','/ˌhæpˈhæz.əd/','/ˌhæpˈhæz.ɚd/','adjective',["Do not make such haphazard changes to the settings; instead, adjust the knobs carefully, a bit at a time."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wick','n.蜡烛芯；灯芯','/wɪk/','/wɪk/','noun',["Trim the wick fairly short, so that the flame does not smoke.","The fabric wicks perspiration away from the body.","The moisture slowly wicked through the wood."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('biannual','adj.一年两次的','/bʌɪˈanjuːəl/','/bʌɪˈanjuːəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elicit','vt.得出，引出；诱出','/ɪˈlɪsɪt/','/ɪˈlɪsɪt/','verb',["Did you elicit a response?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relegate','vt.使贬职，使降级；放逐，贬谪','/ˈɹɛlɪɡeɪt/','/ˈɹɛlɪɡeɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambiguity','n.模棱两可的话；歧义','/æmbɪˈɡjuːɪti/','/æmbɪˈɡjuːɪti/','noun',["His speech was made with such great ambiguity that neither supporter nor opponent could be certain of his true position."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trivial','adj.琐碎的，微不足道的','/ˈtɹɪ.vi.əl/','/ˈtɹɪ.vi.əl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('postcard','n.明信片','/ˈpoʊstˌkɑɹd/','/ˈpoʊstˌkɑɹd/','noun',["to postcard one''s friends","to postcard one''s news"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('longevity','n.长寿；寿命','/lɒnˈdʒɛ.vɪ.ti/','/lɒnˈdʒɛ.vɪ.ti/','noun',["Grandfather had incredible longevity: he lived to be 105 years old!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reluctant','adj.不情愿的，勉强的','/ɹɪˈlʌktənt/','/ɹɪˈlʌktənt/','adjective',["She was reluctant to lend him the money"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conscientious','adj.凭良心的；认真谨慎的，一丝不苟的','/ˌkɒnʃiˈɛnʃəs/','/ˌkɑnʃiˈɛnʃəs/','adjective',["He was a thoughtful and conscientious worker.","The advice of wise and conscientious women."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coil','v.盘绕，卷n.卷；线圈','/kɔɪl/','/kɔɪl/','noun',["the sinuous coils of a snake","A simple transformer can be made by coiling two pieces of insulated copper wire around an iron heart.","The sailor coiled the free end of the hawser on the pier."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('authoritative','adj.官方的；权威性的，可信的；专断的，命令式的','/ɔːˈθɒɹɪtətɪv/','/ɔːˈθɒɹɪtətɪv/','adjective',["The authoritative rules in this school come not from the headmaster but from the aged matron.","This book is the world''s most authoritative guide to insect breeding habits.","He instructed us in that booming, authoritative voice of his."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('organism','n.生物，有机物；有机体','/ˈɔː.ɡən.ɪ.zəm/','/ˈɔɹ.ɡən.ɪ.zəm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('epidemic','adj.流行性的，传染性的n.流行；流行病','/ˌɛpɪˈdɛmɪk/','/ˌɛpɪˈdɛmɪk/','noun',["Epidemic hysteria occurred upon the incumbent’s reelection."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suppose','v.假设，推测；认为，料想；要不','/səˈpəʊz/','/səˈpoʊz/','verb',["Suppose that A implies B and B implies C. Then A implies C.","I suppose we all agree that this is the best solution.","Purpose supposes foresight."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scruple','n&vi.踌躇，顾忌，顾虑','/ˈskɹuːpəl/','/ˈskɹupəl/','noun',["I do not scruple to admit that all the Earth seeth but only half of the Moon."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flavor','n.风味，滋味；调味品vt.给…调味','/ˈfleɪvə/','/ˈfleɪvɚ/','noun',["The flavor of this apple pie is delicious.","Flavor was added to the pudding.","What flavor of bubble gum do you enjoy?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recess','n.休会期；休庭；暂停；凹室，','/ɹɪ.ˈsɛs/','/ɹɪ.ˈsɛs/','noun',["Spring recess offers a good chance to travel.","Put a generous recess behind the handle for finger space.","Students who do not listen in class will not play outside during recess."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outspoken','adj.直言不讳的，坦率的','','','verb',["an outspoken man"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obscure','adj.暗的，模糊的，朦胧的；费解的，晦涩的；不著名的，不重要的vt.使变模糊；使费解','/əbˈskjɔː(ɹ)/','/əbˈskjɝ/','verb',["an obscure passage or inscription;    The speaker made obscure references to little-known literary works.","The etymological roots of the word \"blizzard\" are obscure and open to debate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noxious','adj.有害的；有毒的','/ˈnɒkʃəs/','/ˈnɒkʃəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bolster','vt.支持；改善n.垫子，枕垫','/ˈbəʊlstə/','/ˈbəʊlstə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('region','n.层；地区，区域；范围','/ˈɹiːd͡ʒn̩/','/ˈɹiːd͡ʒn̩/','noun',["the equatorial regions","the abdominal regions"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deceive','v.欺骗','/dɪˈsiːv/','/dɪˈsiːv/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ingenious','adj.巧妙的；聪明的，机敏的；善于创造发明的；设计独特的，别致的','/ɪnˈdʒiːniəs/','/ɪnˈdʒiːniəs/','adjective',["This fellow is ingenious; he fixed a problem I didn''t even know I had.","That is an ingenious model of the atom.","He sent me an ingenious reply for an email."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breakthrough','n.突破，重大进展','/ˈbɹeɪkθɹuː/','/ˈbɹeɪkθɹuː/','noun',["Albert Einstein is credited with making some of the greatest breakthroughs in modern physics.","a breakthrough technological advance"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snack','n.快餐，小吃，点心','/snæk/','/snæk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amphibious','adj.两栖的；水陆两用的','[æmˈfɪbi.əs]','[æmˈfɪbi.əs]','adjective',["an amphibious attack"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('destination','n.目的地，终点','/dɛstɪˈneɪʃən/','/dɛstɪˈneɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yoke','n.裤腰；牛轭；奴役，束缚vt.使结合，连接','/jəʊk/','/jəʊk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reciprocal','adj.相互的；互惠的；相应的；','/ɹɪˈsɪpɹək(ə)l/','/ɹɪˈsɪpɹək(ə)l/','noun',["0.5 is the reciprocal of 2.","reciprocal love; reciprocal duties","a reciprocal invitation to lunch"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perpetuate','vt.使永存，使持续','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('damp','adj.潮湿的n.潮湿；湿气vt.弄湿；减弱，抑制','/dæmp/','/dæmp/','noun',["to damp cloth","The lawn was still damp so we decided not to sit down."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brighten','v.更明亮；快活起来；有希望','/ˈbɹaɪtən/','/ˈbɹaɪtən/','verb',["We brightened the room with a new coat of paint.","to brighten one''s prospects;  Having Mark around the place really brightens things up.","The sun starts to brighten around this time of the year.  The sky brightened as the storm moved on."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concomitant','adj.伴随的n.伴随物','/kənˈkɒmɪtənt/','/kənˈkɑːmətənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cumbersome','adj.笨重的；麻烦的；累赘的，冗长的','/ˈkʌmbɚsəm/','/ˈkʌmbɚsəm/','adjective',["Cumbersome machines can endanger operators and slow down production.","A slaves'' work was as cumbersome as toiling on the fields, or in the mines."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('belie','vt.给人以错觉；掩饰；证明…不正确','/bɪˈlʌɪ/','/bəˈlaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('premature','adj.早熟的；过早的；不成熟的，仓促的n.早产儿','/ˈpɹɛ.mə.tjə/','/ˈpɹɛ.mə.tjə/','noun',["a premature birth"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choir','vi.合唱n.唱诗班，合唱队','/kwaɪə(ɹ)/','/kwaɪɚ/','noun',["The church choir practices Thursday nights.","Seraphim, Cherubim, and Thrones are three of the choirs of angels."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compensation','n.补偿，赔偿；赔偿金','/ˌkɒmpɛnˈseɪʃən/','/ˌkɒmpɛnˈseɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accessory','adj.辅助的n.附件，零件；配饰；从犯，同谋','/ækˈsɛs(ə)ɹi/','/ækˈsɛsəɹi/','adjective',["She was accessory to the riot."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seminar','n.研讨会；研讨班','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pupil','n.小学生；瞳孔','/ˈpjuːpəl/','/ˈpjuːpəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('venom','n.毒液；恶意，怨恨','/ˈvɛnəm/','/ˈvɛnəm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hazard','n.危险；风险vt.尝试着做；冒…风险，使处于危险','/ˈhazəd/','/ˈhæzɚd/','noun',["He encountered the enemy at the hazard of his reputation and life.","The video game involves guiding a character on a skateboard past all kinds of hazards.","I''ll hazard a guess."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('melodrama','n.情节剧，通俗剧；戏剧性的事件','/ˈmɛləˌdɹɑːmə/','/ˈmɛləˌdɹɑːmə/','noun',["the melodrama in the grave digging scene of Beethoven''s \"Fidelio\"."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vegetative','adj.植物的；有生长力的','/ˈvɛdʒəteɪtɪv/','/ˈvɛdʒəteɪtɪv/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proof','adj.耐…的，防…的n.证据，证明；证词；检验，证实；校样','/pɹʉːf/','/pɹuf/','noun',["a proof load; a proof charge","proof against harm"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('militant','adj.好战的，好暴力的n.激进分子','/ˈmɪlɪtənt/','/ˈmɪlɪtənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dilute','adj.冲淡的，稀释的vt.冲淡，稀释；淡化，削弱','/daɪˈljuːt/','/daɪˈljuːt/','noun',["It dilutes easily.","Clean the panel with a dilute, neutral cleaner.","a cat with a dilute tortoiseshell coat"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('method','n.方法，办法，措施；秩序','/ˈmɛθəd/','/ˈmɛθəd/','noun',["If one method doesn''t work, you should ask a friend to help you.","The company employs extensive use of 3D modelling combined with solidification simulation to ensure that critical castings are properly methoded."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scroll','n.卷轴；纸卷，画卷；名册','/skɹoʊl/','/skɹoʊl/','noun',["I ordered a glass of lemonade and a coffee scroll.","She scrolled the offending image out of view.","The rising credits slowly scrolled off the screen."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sluggish','adj.行动迟缓的；不活泼的；无精打采的，怠惰的','/ˈslʌɡɪʃ/','/ˈslʌɡɪʃ/','adjective',["a sluggish man","Inflation has been rising despite sluggish economy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yolk','n.蛋黄，卵黄','/jəʊk/','/joʊk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vascular','adj.血管的，脉管的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('susceptible','adj.易受感染的；易受影响的；过敏的；感情丰富的；能经受…的，容许…的','/səˈsɛptɪbl̩/','/səˈsɛptɪbl̩/','noun',["He was susceptible to minor ailments.","A properly prepared surface is susceptible of an enduring paint job."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insight','n.洞察力；领悟','/ˈɪnsaɪt/','/ˈɪnsaɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quiescent','adj.静止的，寂静的；静态的','/ˈkwaɪ̯.ɛsn̩t/','/ˈkwaɪ̯.ɛsn̩t/','adjective',["The bats were quiescent at that time of day, so we slowly entered the cave.","The k is quiescent in \"knight\" and \"know\"."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assail','vt.抨击，指责；猛攻；困扰','/əˈseɪl/','/əˈseɪl/','verb',["Muggers assailed them as they entered an alley."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('centigrade','adj.百分度的；摄氏温度的','','','noun',["a temperature of 34 centigrades"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cerebral','adj.大脑的；理智的','/səˈɹiː.bɹəl/','/səˈɹiː.bɹəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mural','adj.墙壁的；在墙上的n.壁画，壁饰','/ˈmjʊəɹəl/','/ˈmjɝəl/','noun',["a mural quadrant","a mural precipice"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seismology','n.地震学','/saɪzˈmɑlədʒi/','/saɪzˈmɑlədʒi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slander','n.诽谤，中伤，诋毁vt.诽谤，诋毁','/ˈslændɚ/','/ˈslændɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gem','n.宝石，珍品；美丽绝伦的事物','/d͡ʒɛm/','/d͡ʒɛm/','noun',["She''s an absolute gem.","a gem of wit"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sedentary','adj.久坐的，固定不动的；土生的，不迁徙的；沉积的','/ˈsɛd(ə)ntɛɹi/','/ˈsɛd(ə)ntɛɹi/','noun',["The oyster is a sedentary mollusk; the barnacles are sedentary crustaceans."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hemp','n.大麻；由大麻制成的麻醉药','/hɛmp/','/hɛmp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('counterfeit','adj.伪造的，假冒的n.赝品vt.伪造，仿造','/ˈkaʊn.tɚˌfɪt/','/ˈkaʊn.tɚˌfɪt/','noun',["to counterfeit the signature of another, coins, notes, etc.","to counterfeit the voice of another person","This counterfeit watch looks like the real thing, but it broke a week after I bought it."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barber','v.为…理发；当理发师n.理发师','/ˈbɑː.bə/','/ˈbɑɹ.bɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sensible','adj.可察觉的，可感知的；明智的；切合实际的；意识到的','/ˈsen.sə.bl̩/','/ˈsɛn.sɪ.bl̩/','noun',["a sensible thermometer"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suspect','v.怀疑，猜想adj.可疑的；不信任的n.嫌疑犯，可疑分子','/ˈsʌs.pɛkt/','/ˈsʌs.pɛkt/','noun',["to suspect the presence of disease","to suspect the truth of a story","I suspect him of being the thief."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apologize','vi.道歉，认错；辩解','/əˈpɒləd͡ʒaɪz/','/əˈpɑləd͡ʒaɪz/','verb',["My correspondent apologized for not answering my letter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mingle','v.混合；交往','/ˈmɪŋ.ɡəl/','/ˈmɪŋ.ɡəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('braid','n.穗带，饰带；发辫vt.编织；编成辫子','/bɹeɪd/','/bɹeɪd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unravel','v.澄清；解体，瓦解；解开','/ʌnˈɹævəl/','/ʌnˈɹævəl/','verb',["Mother couldn''t unravel the ball of wool after the cat had played with it.","to unravel a mystery","to unravel the broad consensus which was created"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('edible','adj.可食用的','/ˈɛdɪbl/','/ˈɛdɪbl/','noun',["edible fruit","Although stale, the bread was edible."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chorus','n.合唱曲；合唱队；副歌，叠句；齐声，','/ˈkɔːɹəs/','/ˈkɔːɹəs/','noun',["The performance of the chorus was awe-inspiring and exhilarating.","The catchiest part of most songs is the chorus.","a chorus of crickets"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prone','adj.平卧的，俯卧的；易于做…的，倾向于…的','/pɹəʊn/','/pɹəʊn/','adjective',["prone position","prone to failure"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('asset','n.资产，财产；有价值的人；长处，优点','/ˈæsɪt/','/ˈæsɪt/','noun',["These shares are a valuable asset."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depot','n.库房，仓库；公共汽车站，火车站','/ˈdepɐʉ/','/ˈdiːpoʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theoretical','adj.不切实际的；理论的','/ˌθi.əˈɹɛtɪkəl/','/ˌθi.əˈɹɛtɪkəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('owl','n.猫头鹰','/aʊl/','/aʊl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sound','adj.可靠的；健康的，完好无损的；合理的v.似乎；测量…的深度','/saʊnd/','/saʊnd/','adjective',["He was safe and sound.","Fred assured me the floorboards were sound.","\"How are you?\" - \"I''m sound.\""]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vibrate','v.颤动，振动','/vaɪˈbɹeɪt/','/ˈvaɪ.bɹeɪt/','noun',["Please put your cellphones on vibrate for the duration of the meeting.","Her mind was vibrating with excitement.","to vibrate a sword or a staff"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hospitable','adj.宜人的；好客的，殷勤的；开通的','/hɒsˈpɪtəbl̩/','/hɒsˈpɪtəbl̩/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('multiplicative','adj.倍增的；乘法的','/ˈmʌltɪplɪˌkeɪtɪv/','/ˈmʌltɪplɪˌkeɪtɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impetus','n.促进，推动；刺激；推动力','/ˈɪm.pə.təs/','/ˈɪm.pə.təs/','noun',["The outbreak of World War II in 1939 gave a new impetus to receiver development."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('healing','adj.有治疗功用的n.康复，治疗；复原','/ˈhiːlɪŋ/','/ˈhiːlɪŋ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revitalize','vt.使恢复生机，使再生；使更强壮','','','verb',["Japanese investment has revitalised this part of Britain!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('caribou','n.北美驯鹿','/ˈkɛɹəbu/','/ˈkɛɹəbu/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('simmer','vi.充满；煨，炖n.煨，炖','/ˈsɪmə/','/ˈsɪmə/','noun',["The kettle was kept on the simmer.","The soup simmered on the stove.","Simmer the soup for five minutes, then serve."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eviscerate','vt.取出内脏；除去主要部分','/ɪˈvɪsəˌɹeɪt/','/ɪˈvɪsəˌɹeɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brace','vt.绷紧肌肉；使顶住；使防备；加强，加固n.支架，托架','/bɹeɪs/','/bɹeɪs/','noun',["All hands, brace for impact!","He braced himself against the crowd.","to brace the yards"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brisk','adj.清新的；敏捷的，活泼的','/bɹɪsk/','/bɹɪsk/','verb',["We took a brisk walk yesterday.","brisk cider","This morning was a brisk fall day. It wasn''t cold enough for frost, but you wanted to keep moving."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nightmare','n.噩梦；无法摆脱的恐惧；可怕的事','/ˈnaɪt.mɛə/','/naɪt.mɛəɹ/','noun',["I had a nightmare that I tried to run but could neither move nor breathe.","Cleaning up after identity theft can be a nightmare of phone calls and letters."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prolonged','adj.长期的，持久的','/pɹoʊˈlɑŋd/','/pɹoʊˈlɑŋd/','verb',["The government shouldn''t prolong deciding on this issue any further."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prestige','n.威望；声望','/pɹəˈsti(d)ʒ/','/pɹəˈsti(d)ʒ/','noun',["Oxford has a university of very high prestige."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spontaneity','n.自发性；自发行为','/ˈspɒn.tə.neɪ.ə.ti/','/ˈspɒn.tə.neɪ.ə.ti/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('famish','v.饥饿','/ˈfamɪʃ/','/ˈfamɪʃ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fraud','n.骗子，冒名顶替者；冒牌货；欺骗','/fɹɔːd/','/fɹɔːd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('council','n.委员会；地方议会','/ˈkaʊn.səl/','/ˈkaʊn.səl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dazzling','adj.令人眼花缭乱的，耀眼的','/ˈdæz.lɪŋ/','/ˈdæz.lɪŋ/','verb',["Dazzled by the headlights of the lorry, the deer stopped in the middle of the street.","The delegates were dazzled by the originality of his arguments."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rectangle','n.长方形，矩形','/ˈrɛktæŋɡ(ə)l/','/ˈrɛkˌtæŋɡəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rotational','adj.旋转的；轮流的','','','noun',["A steam turbine converts heat into rotational motion."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quash','vt.撤销，废止；镇压；平息','/kwɒʃ/','/kwɑʃ/','verb',["The army quashed the rebellion."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sprawl','vi.伸开四肢坐；扩展，蔓延n.扩展，蔓延；蔓延物','/spɹɔːl/','/spɹɔːl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concrete','adj.混凝土制的；具体的；确凿的n.混凝土','/kɵnˈkɹiːt/','/ˈkɑnkɹiːt/','noun',["The road was made of concrete that had been poured in large slabs.","I hate grass, so I concreted over my lawn.","Fuzzy videotapes and distorted sound recordings are not concrete evidence that bigfoot exists."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rustproof','adj.不锈的','','','verb',["We''ll rustproof the metal with a good coat of paint and then we''ll be able to leave it outdoors for years without damage.","This is supposed to be a rustproof trashcan, but it can''t handle the salt they use on our roads."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shrimp','n.小虾','/ʃɹɪmp/','/ʃɹɪmp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abridge','vt.缩短，删节，节略，精简','/əˈbɹɪd͡ʒ/','/əˈbɹɪd͡ʒ/','verb',["He had his rights abridged by the crooked sheriff."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('penalty','n.处罚，惩罚；罚金；犯规的处罚','/ˈpɛnəlti/','/ˈpɛnəlti/','noun',["The penalty for his crime was to do hard labor.","A penalty was called when he tripped up his opponent."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gin','n.杜松子酒；弹棉机，','/dʒɪn/','/dʒɪn/','noun',["Johnny Chan held jack-nine, and hit gin when a queen-ten-eight board was dealt out."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engaging','adj.迷人的','/ɪnˈɡeɪd͡ʒɪŋ/','/ɪnˈɡeɪd͡ʒɪŋ/','verb',["I found the first of the Harry Potter books a very engaging read.","Beauty, of course, and a bright, engaging personality — or at least the ability to fake one — are prerequisites for entering the Miss World competition."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contributor','n.投稿者；贡献者，捐助者；促成物','','','noun',["I am a longstanding financial contributor to Amnesty International.","He was a regular contributor to Greenpeace protests.","With her strength and intelligence, she was an important contributor to the victorious effort."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subdivide','v.再分，细分','/ˌsʌb.dɪˈvaɪd/','/ˌsʌb.dɪˈvaɪd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nosy','adj.爱管闲事的，好打听的','/ˈnəʊziː/','/ˈnoʊzi/','noun',["I might wander down to the construction site for a nosy at what they''re building.","They built tall fences, yet the nosy neighbors always seemed to know everything about them."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salient','adj.显著的，突出的','/ˈseɪ.li.ənt/','/ˈseɪ.li.ənt/','noun',["The article is not exhaustive, but it covers the salient points pretty well.","a lion salient","a salient angle"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feeble','adj.虚弱的，衰弱的，无力的','/ˈfiːbəl/','/ˈfiːbəl/','verb',["Though she appeared old and feeble, she could still throw a ball.","That was a feeble excuse for an example."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('limb','n.肢，臂；主枝','/lɪm/','/lɪm/','noun',["They limbed the felled trees before cutting them into logs."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prose','n.散文','/ˈpɹəʊz/','/ˈpɹoʊz/','noun',["Though known mostly for her prose, she also produced a small body of excellent poems."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inverse','adj.相反的，反向的n.反面；倒数','/ɪnˈvɝs/','/ɪnˈvɝs/','noun',["321 is the inverse of 123.","Multiplication is the inverse operation to division.","A circle inversion maps a given generalized circle to its inverse generalized circle."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cognition','n.感知，认知，认识','/kɒɡˈnɪʃən/','/kɑɡˈnɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confidence','n.信任；信心','/ˈkɒnfɪdəns/','/ˈkɒnfɪdəns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cuisine','n.烹饪；烹调法，烹调风格','/kwɪˈziːn/','/kwɪˈziːn/','noun',["French cuisine is considered to be one of the world''s most refined and elegant styles of cooking."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arbitrary','adj.任意的；专制的，专断的','/ˈɑɹ.bɪ.tɹɛ(ə).ɹi/','/ˈɑɹ.bɪ.tɹɛ(ə).ɹi/','noun',["Benjamin Franklin''s designation of \"positive\" and \"negative\" to different charges was arbitrary.","The equation is true for an arbitrary value of x."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intent','adj.专心的，专注的；急切的n.意图，目的','/ɪnˈtɛnt/','/ɪnˈtɛnt/','noun',["a mind intent on self-improvement"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('readability','n.可读性','','','noun',["The book had a clever plot, but lacked readability."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interrogate','vt.审问，讯问，盘问','','','verb',["The police interrogated the suspect at some length before they let him go.","to interrogate a database"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astute','adj.机敏的，精明的','/əsˈtjuːt/','/əsˈtjuːt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dignity','n.尊严，庄严；高贵，尊贵；自尊，自重','/ˈdɪɡnɪti/','/ˈdɪɡnɪti/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unearth','vt.掘出，发掘；揭露','','','verb',["to unearth a fox or a badger","to unearth a secret"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snap','v.猛咬；折断，断裂；打开，关上；呵斥，厉声说；拍照adj.仓促的，匆忙的n.啪嗒声；照片','/snæp/','/snæp/','noun',["We took a few snaps of the old church before moving on.","a ginger snap","I can fix most vacuum cleaners in a snap."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sleigh','n.雪橇','/sleɪ/','/sleɪ/','noun',["Santa travels in a sleigh."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seismic','adj.地震的，地震引起的；影响深远的，重大的','/ˈsaɪzmɪk/','/ˈsaɪzmɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cafeteria','n.自助餐厅，自助食堂','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rupture','v.破裂；决裂，断绝','/ˈɹʌptʃə/','/ˈɹʌptʃə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('afflict','vt.使苦恼，折磨','/əˈflɪkt/','/əˈflɪkt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rancorous','adj.怨恨的，满怀恶意的','/ˈɹæŋ.kəɹ.əs/','/ˈɹæŋ.kəɹ.əs/','adjective',["rancorous speech"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('persistent','adj.坚持的，百折不挠的；持续的','/pəˈsɪstənt/','/pəˈsɪstənt/','adjective',["She has had a persistent cough for weeks.","There was a persistent knocking on the door.","There have been persistent rumours for years."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('authorize','vt.授权；批准，许可','/ˈɑθəɹaɪz/','/ˈɑθəɹaɪz/','verb',["The General Assembly authorized the Council to take up the matter.","The judge authorized the wiretapping."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trauma','n.精神创伤；外伤；痛苦经历','/ˈtɹaʊ.mə/','/ˈtɹaʊ.mə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('groom','v.刷洗；梳理毛发；培养，','/ɡɹuːm/','/ɡɹuːm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dedication','n.献身，奉献；献词；奉献仪式','/ˌdɛdɪˈkeɪʃən/','/ˌdɛdɪˈkeɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neutral','adj.中性的；中立的','/ˈnjuːtɹəl/','/ˈnuːtɹəl/','noun',["I am neutral regarding the issue of gay marriage."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('optional','adj.可以任选的，非强制的','','','noun',["On that beach clothing is entirely optional."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('journalism','n.新闻业，新闻工作','/ˈdʒɜːn(ə)lɪzəm/','/ˈdʒɜːn(ə)lɪzəm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chronical','adj.慢性的，延续很长的','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exposure','n.暴露，显露；揭露；曝光；面临，遭受','/ɪkˈspoʊʒɚ/','/ɪkˈspoʊʒɚ/','noun',["Limit your exposure to harsh chemicals.   Get as much exposure to a new language as you can.","They rented a cabin with a beautiful southern exposure."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evacuate','v.疏散，撤离；排空','/ɪˈvæk.ju.eɪt/','/ɪˈvæk.ju.eɪt/','verb',["The firefighters told us to evacuate the area as the flames approached.","The firefighters decided to evacuate all the inhabitants from the street.","The scientist evacuated the chamber before filling it with nitrogen."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clutch','v.企图抓住，抓紧n.一次所孵的卵；离合器；掌握，控制；把握，抓紧','/klʌt͡ʃ/','/klʌt͡ʃ/','noun',["to clutch power","She clutched her purse tightly and walked nervously into the building."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dawn','n.破晓，黎明；开始，发端','/doːn/','/dɔn/','noun',["She rose before dawn to meet the train.","the dawn of civilization","A new day dawns."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humble','adj.谦卑的；卑贱的；简陋的，低劣的vt.降低，贬抑','/ˈhʌmbəl/','/ˈhʌmbəl/','noun',["He lives in a humble one-bedroom cottage."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glossy','adj.光滑的；光彩夺目的；浮华的','','','noun',["The supermarket glossies are full of celebrity gossip and fad diets."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blur','v.变模糊，难以区分；玷污n.模糊形状；模糊的记忆；污点','/blɜ(ɹ)/','/blɜ(ɹ)/','noun',["to blur a photograph by moving the camera while taking it","to blur a manuscript by handling it while damp"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plausible','adj.似有道理的，似乎正确的','/ˈplɔːz.ə.bəl/','','adjective',["a plausible excuse","a plausible pretext; plausible manners; a plausible delusion"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cider','n.苹果酒；苹果汁','/ˈsaɪ̯.də/','/ˈsaɪ̯.dɚ/','noun',["She liked an aged cider. He liked a harder cider."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hearsay','n.谣言，传闻，道听途说','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mundane','adj.世俗的；平凡的','/mʌnˈdeɪn/','/mʌnˈdeɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fortuitous','adj.偶然的，意外的','/fɔːˈtjuːɪtəs/','/fɔːˈtjuːɪtəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sexism','n.性别歧视','/ˈsɛksɪzm̩/','/ˈsɛksɪzm̩/','noun',["The notion that either gender is superior is sexism.","The fact that there is only one woman in a management position in that company makes it easy to believe that sexism runs rampant there.","the sexism of making and promoting violent films for men and romantic comedies for women"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incapacitate','vt.使无资格；使失去能力；使不胜任','/ˌɪn.kəˈpæ.sɪ.teɪt/','/ˌɪn.kəˈpæ.sɪ.teɪt/','verb',["The police officer was incapacitated by a blow to the head."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deceitful','adj.欺诈的，惯于欺骗的，不诚实的','/-fl̩/','/-fl̩/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('audition','n.旁听；试演','','','noun',["I''ve been to five auditions this week.","His audition was poor.","We auditioned several actors for the part."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('editorial','adj.社论的；编辑的n.社论，重要评论','/ˌɛdɪˈtɔːɹɪəl/','/ˌɛdɪˈtɔɹiəl/','noun',["editorial labours; editorial remarks"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sharpen','v.削尖，磨快；使敏锐；变得清晰','','/ˈʃɑɹpɨn/','verb',["to sharpen a pencil or a knife or a musical note"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('committee','n.委员会','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kernel','n.仁；粒；核心，要点','/ˈkɜːnəl/','/ˈkɜːnəl/','noun',["the kernel of an argument","The Linux kernel is open-source.","The Dirichlet kernel convolved with a function yields its Fourier series approximation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stingy','adj.吝啬的，小气的','/ˈstɪndʒi/','/ˈstɪndʒi/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wipe','v&n.擦，揩，抹','/waɪp/','/waɪp/','noun',["multiple wipes of a computer''s hard disk","I wiped the sweat from my brow with the back of my hand.","I accidentally wiped my hard drive."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foliage','n.叶','/ˈfəʊliɪdʒ/','/ˈfəʊliɪdʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suite','n.套，组；套房','/swiːt/','/swiːt/','noun',["the ambassador''s suite","a suite of minerals","The Presidential suite is well appointed and allows for good security."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overwhelm','vt.淹没，漫过；压倒，击败，制服；使难以忍受；使应接不暇','/ˌovɚˈʍɛlm/','/ˌovɚˈʍɛlm/','noun',["The dinghy was overwhelmed by the great wave.","In December 1939 the Soviet Union attacked Finland with overwhelming force.","He was overwhelmed with guilt."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('morgue','n.停尸房，太平间','/mɔːɡ/','/mɔːɡ/','noun',["Kwapil, Joseph F. (2 July 1921) \"Librarian Talks of Newspaper Morgue\", Fourth Estate page 5."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unprecedented','adj.空前的','/ʌnˈpɹɛsɪdɛntɪd/','/ʌnˈpɹɛsɪdɛntɪd/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pocketbook','n.钱袋，皮夹；财政状况，财力','','','noun',["The publishers brought out small format pocketbooks of the whole of their nature series."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('charcoal','n.木炭','/ˈtʃɑː.kəʊl/','/ˈtʃɑɹ.koʊl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disguise','vt&n.掩饰；伪装，假装','/dɪsˈɡaɪz/','/dɪsˈɡaɪz/','noun',["A cape and moustache completed his disguise.","Any disguise may expose soldiers to be deemed enemy spies.","Spies often disguise themselves."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imperial','adj.帝国的，帝王的；至尊的；专横的','/ɪmˈpɪ.ɹi.əl/','/ɪmˈpɪ.ɹi.əl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wrap','vt.包，裹n.披肩，围巾；包装材料','/ɹæp/','/ɹæp/','verb',["A snake wraps itself around its prey.","I wrapped the text so that I wouldn''t need to scroll to the right to read it.","The row counter wraps back to zero when no more rows can be inserted."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('facet','n.小平面；方面','/ˈfæsɪt/','/ˈfæsɪt/','noun',["This facet of the diamond was masterfully cut to enhance its value.","The child''s learning disability was only one facet of the problems contributing to his delinquency.","We had just about completed the research facet of the project when the order came to cancel it."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tedium','n.单调，乏味','/ˈtiː.di.əm/','/ˈtiː.di.əm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('genial','adj.亲切的，和蔼的；温和的，温暖的','/ˈdʒiːnɪəl/','/-ni.əl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('epitome','n.摘要，梗概；典型，典范','/əˈpɪt.ə.mi/','/əˈpɪt.ə.mi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sharply','adv.急剧地；猛烈地；尖刻地；鲜明地','/ʃɑːpli/','/ʃɑɹpli/','adverb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('afoul','adv.相抵触，有冲突','/əˈfaʊl/','/əˈfaʊl/','adverb',["The ships’ lines and sails were all afoul.","He had a knack for running afoul of the law."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chill','adj.寒冷的v.变冷，冷却n.寒冷，寒意','/tʃɪl/','/tʃɪl/','noun',["There was a chill in the air.","Close the window or you''ll catch a chill.   I felt a chill when the wind picked up.","Despite the heat, he felt a chill as he entered the crime scene.   The actor''s eerie portrayal sent chills through the audience.   His menacing presence cast a chill over everyone."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compute','v.计算，估算','/kəmˈpjuːt/','/kəmˈpjuːt/','noun',["Can anyone here compute the square root of 10201?","Does that compute, or do I need to explain further?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pastel','adj.彩色蜡笔的；柔和的n.彩色蜡笔','/ˈpæstəl/','/ˈpæstəl/','noun',["Wool was dyed in the pastel vat."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('homestead','n.家宅，农庄；宅地','/ˈhoʊmˌstɛd/','/ˈhoʊmˌstɛd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('middleman','n.中间人，调解人；经纪人','[ˈmɪdɫ̩ˌmæn]','[ˈmɪdɫ̩ˌmæn]','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('avert','vt.避免，规避；转移','/əˈvɜːt/','/əˈvɜːt/','verb',["To avert the eyes from an object.","How can the danger be averted?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conversation','n.交谈，会话','/ˌkɒn.vəˈseɪ.ʃən/','/ˌkɑn.vəɹˈseɪ.ʃən/','noun',["I had an interesting conversation with Nicolas yesterday about how much he''s getting paid."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monarchy','n.君主制；君主国','/ˈmɒnəki/','/ˈmɑnɚki/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('manifestation','n.显示，表明；','/ˌmænɪfəˈsteɪʃən/','/ˌmænɪfəˈsteɪʃən/','noun',["The last known manifestation of the ghost was over ten years ago.","This particular manifestation resembled a young girl crying."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vicious','adj.危险的，罪恶的；残酷的，凶残的；恶性的','/ˈvɪʃəs/','/ˈvɪʃəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lace','v.用带子束紧n.蕾丝；缎带；鞋带，系带','/leɪs/','/leɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invitation','n.邀请；请柬；吸引，诱惑','/ɪn.vɪˈteɪ.ʃn̩/','/ɪn.vɪˈteɪ.ʃn̩/','noun',["an invitation to a party, to a dinner, or to visit a friend","We need to print off fifty invitations for the party."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lithosphere','n.岩石圈','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revival','n.复兴，再流行；复苏；苏醒，复活；重演','/ɹɪˈvaɪvəl/','/ɹɪˈvaɪvəl/','noun',["the revival of hot pants","the revival of a debt barred by limitation; the revival of a revoked will"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paramount','adj.至为重要的；最高权力的，至尊的','/ˈpa.ɹə.maʊnt/','/ˈpa.ɹə.maʊnt/','noun',["Getting those credit cards paid off is paramount."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emerald','n.祖母绿，绿宝石；翡翠绿','/ˈɛm(ə)ɹəld/','/ˈɛm(ə)ɹəld/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('legislature','n.立法机关，立法团体','/ˈlɛdʒɪsləˌtʃʊə/','/ˈlɛdʒɪsˌleɪtʃɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sociable','adj.好交际的，合群的；友善的，友好的','','','noun',["He''s normally pretty quiet, but he gets much more sociable around women.","a sociable party"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exhilarating','adj.令人高兴的，使人兴奋的','','','verb',["Good news exhilarates the mind; wine exhilarates the drinker."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Saturn','n.土星','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('avenge','vt.复仇，报仇；向…报仇','/əˈvɛnd͡ʒ/','/əˈvɛnd͡ʒ/','noun',["to avenge the murder of his brother"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obsolete','adj.过时的；废弃的','/ˈɒbsəliːt/','/ɑbsəˈliːt/','adjective',["It is speculated that, within a few years, the Internet''s speedy delivery of news worldwide will make newspapers obsolete."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gasoline','n.汽油','/ˈɡæs.ə.lin/','/ɡæsl̩ˈin/','noun',["The refinery produces a wide range of gasolines."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interface','n.界面，分界面；接口','/ˈɪntəfeɪs/','/ˈɪntəfeɪs/','noun',["Public relations firms often serve as the interface between a company and the press.","If water and oil are mixed together, they tend to separate, and at equilibrium they are in different strata with an oil-water interface in between.","The data is sent over the air interface to the remote system."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sculpt','vt.雕刻','','','noun',["They sculpted a statue out of clay."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lipid','n.脂质，类脂','/ˈlɪpɪd/','/ˈlɪpɪd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fatal','adj.致命的；毁灭性的；命中注定的','[ˈfeɪ.ɾɫ̩]','[ˈfeɪ.ɾɫ̩]','noun',["a fatal wound; a fatal disease; that fatal day; a fatal mistake","a fatal error; a fatal exception"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('psychology','n.心理学；心理，心理特征','/saɪˈkɒlədʒɪ/','/saɪˈkɑlədʒi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outgas','vt.除去气','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('puritanical','adj.极守道德的','/pjʊəɹ.ɪˈtæn.ɪ.kəl/','/pjʊəɹ.ɪˈtæn.ɪ.kəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('twine','v.缠绕，盘绕，围绕n.细绳','/twaɪn/','/twaɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retrospective','adj.回顾的，追想的；有追溯效力的','/ˌɹɛtɹə(ʊ)ˈspɛktɪv/','/ˌɹɛtɹə(ʊ)ˈspɛktɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lucrative','adj.赚钱的，获利的，有利可图的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inanity','n.空虚，空洞；无意义的事物','/ɪˈnænɪti/','/ɪˈnænɪti/','noun',["Working in any bureaucracy means being bedeviled by inanities daily."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acidity','n.酸度；酸性','/əˈsɪdɪti/','/əˈsɪdɪti/','noun',["Empty stomachs lead to acidity and leave a sour taste in the mouth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complaint','n.诉苦，抱怨；投诉；控告','/kəmˈpleɪnt/','/kəmˈpleɪnt/','noun',["I have no complaints about the quality of his work, but I don''t enjoy his company.","Don''t come too close; I''ve got this nasty complaint."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pinnacle','n.山顶，顶峰；鼎盛时期；小尖塔','/ˈpɪnəkəl/','/ˈpɪnəkəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inject','vt.注射；注入，灌输；投入','/ɪnˈdʒɛkt/','/ɪnˈdʒɛkt/','verb',["The nurse injected a painkilling drug into the veins of my forearm.","Punk injected a much-needed sense of urgency into the British music scene.","Now lie back while we inject you with the anesthetic."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cannibalism','n.嗜食同类','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indifference','n.冷漠，不关心','/ɪnˈdɪf.ə.ɹəns/','/ɪnˈdɪf.ə.ɹəns/','noun',["His daughter''s indifference towards the sexist group made him wonder if she was even human."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('copious','adj.丰富的，富饶的','/ˈkoʊpi.əs/','/ˈkoʊpi.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inception','n.开端，开始','/ɪnˈsɛpʃn/','/ɪnˈsɛpʃn/','noun',["From its inception, the agency has been helping people obtain and properly install car seats for children."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hamper','vt.妨碍，阻挠n.大篮子','','/ˈhæmpɚ/','noun',["a clothes hamper","Competition pigeons are hampered for the truck trip to the point of release where the race back starts."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('usher','v.引领，引导n.领座员，招待员','[ˈaʃ.ə(ɹ)]','[ˈaʃ.ə(ɹ)]','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decisive','adj.决定性的；果断的','/dɪˈsaɪsɪv/','/dɪˈsaɪsɪv/','adjective',["A decisive battle is fatal for one side''s war chances","A noble instance of this attribute of the decisive character. -J. Foster."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pollinate','vt.给…授粉','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concise','adj.简明的，简练的','/kənˈsaɪs/','/kənˈsaɪs/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thesis','n.论文；论题，论点','/ˈθisɪs/','/ˈθisiz/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bump','v.碰撞n.肿块；撞击；碰撞声','/bʌmp/','/bʌmp/','noun',["the bump of veneration; the bump of acquisitiveness","US presidential nominees get a post-convention bump in survey ratings.","I bumped the font size up to make my document easier to read."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precursor','n.先驱；先兆，前兆；前身','/pɹɨˈkɜɹ.səɹ/','/pɹɨˈkɜɹ.səɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revive','v.恢复；苏醒；重新利用','/ɹɪˈvaɪv/','/ɹɪˈvaɪv/','verb',["Her grandmother refused to be revived if she lost consciousness.","Classical learning revived in the fifteenth century.","This new paint job should revive the surgery waiting room."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fumigate','vt.烟熏，香薰','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aria','n.独唱曲，咏叹调','/ˈɑː.ɹɪə/','/ˈɑː.ɹɪə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dismiss','v.不再考虑，不接受；消除，摒除；免职，解雇；解散，遣散；驳回，不受理','/dɪsˈmɪs/','/dɪsˈmɪs/','verb',["The company dismissed me after less than a year.","The soldiers were dismissed after the parade.","He dismissed all thoughts of acting again."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abysmal','adj.深不可测的；极坏的，糟透的','/əˈbɪz.məl/','/əˈbɪz.məl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('verbiage','n.冗词，赘言，废话','/ˈvɜː(ɹ).bi.ɪdʒ/','/ˈvɜː(ɹ).bi.ɪdʒ/','noun',["Bureaucratic verbiage."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('underlying','adj.潜在的；基础的','','','verb',["A stratum of clay underlies the surface gravel.","a doctrine underlying a theory","We dug down to the underlying rock."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intelligence','n.智力，智慧；情报','/ɪnˈtɛl.ɪ.d͡ʒəns/','/ɪnˈtɛl.ɪ.d͡ʒəns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('utilitarian','adj.实用的；功利主义的n.功利主义者','/juːˌtɪlɪˈtɛːɹi.ən/','/juːˌtɪlɪˈtɛːɹi.ən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('even','adv.甚至，连；甚至可以说adj.平滑的，平坦的；平稳的，均匀的；均衡的；平均的；偶数的v.平坦；相等','/ˈiːvən/','/ˈivn̩/','noun',["So let''s see. There are two evens here and three odds.","We need to even this playing field; the west goal is too low.","Thrice nine evens twenty seven."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambience','n.周围环境，气氛','/ˈæm.bi.əns/','/ˈæm.bi.əns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('install','vt.安置，安装','/ɪnˈstɔːl/','/ɪnˈstɔːl/','noun',["After inserting the disk, you need to run the install.","I haven''t installed the new operating system yet because of all the bugs.","He was installed as Chancellor of the University."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cuneiform','adj.〔古代美索不达米亚人使用的〕楔形文字的','/kjʊˈneɪ.ɪ.fɔːm/','/kjʊˈneɪ.ɪ.fɔːm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bulk','n.容积，体积；主体，大部分','/bʌlk/','/bʌlk/','noun',["I understood the bulk of what you were saying, just one of two points I need to hear again."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vacancy','n.空房间；空位，空缺；空虚','/ˈveɪkənsi/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('champion','n.冠军；拥护者vt.声援','/ˈtʃæmpiən/','/ˈtʃæmpiən/','noun',["The defending champion is expected to defeat his challenger.","Barcelona is eligible to play in FIFA Club World Cup as the champion of Europe.","champion of women''s suffrage"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plumage','n.鸟类羽毛','/ˈpluːmɪdʒ/','/ˈpluːmɪdʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('circuit','n.电路；线路；巡回；环行；环行路线','[ˈsəɾ.kɪʈ]','[ˈsɝ.kət]','noun',["Having circuited the air."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('piracy','n.海盗行为；抢劫行为；剽窃行为','/ˈpaɪɹəsi/','/ˈpaɪɹəsi/','noun',["How should the international community respond to Somali piracy?","Some video game consoles use specially designed cartridges to make software piracy more difficult."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('locomotion','n.移动；运动','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('magnificent','adj.极好的；宏伟的，华丽的；崇高的，高尚的','/mæɡˈnɪfəsənt/','/mæɡˈnɪfəsənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mason','n.石匠，泥瓦匠','/ˈmeɪsən/','/ˈmeɪsən/','noun',["to mason in a kettle or boiler"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('legislate','v.制定法律；通过立法','/ˈlɛdʒɪsˌleɪt/','/ˈlɛdʒɪsˌleɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imperative','adj.迫切的，重要紧急的；必要的；命令的；','','/ɪmˈpɛɹ.ə.tɪv/','noun',["The verbs in sentences like \"Do it!\" and \"Say what you like!\" are in the imperative.","Visiting Berlin is an imperative.","It is imperative that you come here right now."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('documentary','adj.文件的，文献的；记录的，纪实的n.纪录片','/ˌdɒk.jəˈmɛn.tɹi/','/ˌdɒk.jəˈmɛn.tɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hitherto','adv.迄今，至今','/ˈhɪðəˌtuː/','/ˈhɪðɚˌtu/','adverb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('linear','adj.线的，直线的；线性的；长度的','/ˈlɪn.i.ə/','/ˈlɪn.i.ɚ/','adjective',["a linear medium","a linear meter"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('robust','adj.健壮的，强壮的','/ɹəʊˈbʌst/','/ɹəʊˈbʌst/','adjective',["A robust wall was put up.","robust employment"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('raven','adj.乌黑光亮的n.渡鸦','/ˈɹeɪvən/','/ˈɹeɪvən/','noun',["She was a tall, sophisticated, raven-haired beauty."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heading','n.标题；主题','[ˈhɛɾ.ɪŋ]','[ˈhɛɾ.ɪŋ]','verb',["Who heads the board of trustees?","A group of clowns headed the procession.","How does the ship head?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('denounce','vt.谴责，公开指责，抨击；告发','/diˈnaʊns/','/diˈnaʊns/','verb',["to denounce someone as a swindler, or as a coward","to denounce a confederate in crime","to denounce war; to denounce punishment"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swampy','adj.沼泽的，湿地的；松软的','','','adjective',["swampy armpits"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('verge','vi.接近，濒临n.草地','/vɜːd͡ʒ/','/vɝd͡ʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('framework','n.框架，构架；原则，准则；机制，结构','/ˈfɹeɪm.wɜːk/','/ˈfɹeɪm.wɜːk/','noun',["These ‘three principles of connexion’ compose the framework of principles in Hume''s account of the association of ideas."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('milieu','n.出身背景；社会环境','/mɪlˈjɜː/','/mɪlˈjɜː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('microorganism','n.微生物','/ˌmaɪ.kɹəʊˈɔː.ɡən.ɪ.zəm̩/','/ˌmaɪ.kɹəʊˈɔː.ɡən.ɪ.zəm̩/','noun',["The cud is then reswallowed and further digested by specialized microorganisms that live in the rumen."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entity','n.实体，独立存在物','/ˈen.tɪ.ti/','/ˈen.tɪ.ti/','noun',["The group successfully maintains its tribal entity."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chronicle','vt.把…载入编年史n.编年史，年代记','/ˈkɹɒnɪkəl/','/ˈkɹɒnɪkəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prohibit','v.禁止，阻止','/pɹəʊˈhɪbɪt/','/pɹoʊˈhɪbɪt/','verb',["The restaurant prohibits smoking on the patio."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frugal','adj.节约的，节俭的；少量的','/ˈfɹuːɡəl/','/ˈfɹuːɡəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('franchise','n.特权，特许；特许经销权；选举权vt.赋予特权；赋予选举权','/ˈfɹænt͡ʃaɪ̯z/','/ˈfɹænt͡ʃaɪ̯z/','noun',["McDonalds has exported its franchise.","The Whalers'' home city of Hartford was one of many for the franchise.","the Star Wars franchise"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('replica','n.复制品','/ˈɹɛplɪkə/','/ˈɹɛplɪkə/','noun',["The statue on the museum floor is an authentic replica.","He collected replicas of old cars."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laureate','adj.享有殊荣的n.桂冠诗人；荣誉获得者','/ˈlɒ.ɹi.ət/','/ˈlɒ.ɹi.ət/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reign','n.统治，支配；','[ɹeɪn]','[ɹeɪn]','noun',["England prospered under Elizabeth I''s reign.","The reign of Victoria was a long one.","He reigned in an autocratic manner."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('infirm','adj.虚弱的；不坚定的','/ɪnˈfɝm/','/ɪnˈfɝm/','verb',["The thought is that you see an episode of observation, experiment, or reasoning as confirming or infirming a hypothesis depending on whether your probability for it increases or decreases during the episode.","He was infirm of body but still keen of mind, and though it looked like he couldn''t walk across the room, he crushed me in debate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tempo','n.速度，节奏；行进速度','/ˈtɛm.pəʊ/','/ˈtɛm.pəʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scrupulous','adj.多顾虑的，谨慎的；一丝不苟的，严谨的；审慎正直的，恪守道德规范的','/ˈskɹu.pjə.ləs/','/ˈskɹu.pjə.ləs/','adjective',["He is scrupulous in his finances.","He is a scrupulous businessman and always acts in the best interest of his company."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gleam','vi.闪光，闪烁；流露出n.微光；一丝，一线；表露','/ɡliːm/','/ɡliːm/','noun',["The rescue workers preserved a gleam of optimism that they might still survive."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glean','vt.点滴搜集，四处收集','/ɡliːn/','/ɡliːn/','noun',["to glean a field"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('detract','v.减损；贬低，诋毁','/dɪˈtɹækt/','/dɪˈtɹækt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pin','vt.钉住；固定n.大头针；钢钉；胸针；徽章','/pɪn/','/pɪn/','noun',["Pull the pin out of the grenade before throwing it at the enemy.","I''m not so good on my pins these days.","The UK standard connector for domestic mains electricity has three pins."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swap','v.交换，掉换n.交换，掉换；交换物，被调换者','/swɒp/','/swɒp/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resolute','adj.坚决的，果断的','/ˈɹɛ.zəˌl(j)uːt/','/ˈɹɛ.zəˌl(j)uːt/','noun',["He was resolute in his decision to stay."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tutor','v.辅导n.导师；家庭教师','/ˈtjuːtə/','/ˈtutɚ/','noun',["He passed the difficult class with help from his tutor.","To help pay her tuition, the college student began to tutor high school students in calculus and physics."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('senator','n.参议员','/ˈsɛn.ə.tə/','/ˈsɛn.ə.tə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reconcile','vt.使协调；使和解；使顺从','/ˈɹɛkənsaɪl/','/ˈɹɛkənsaɪl/','verb',["to reconcile people who have quarrelled","to reconcile differences"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quantify','vt.以数量表示，量化','/ˈkwɑːn.tə.faɪ/','/ˈkwɑːn.tə.faɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('annul','vt.宣布无效，取消，废除','/əˈnʌl/','/əˈnʌl/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tempt','vt.引诱，诱惑；吸引','/tɛmpt/','/tɛmpt/','verb',["She tempted me to eat the apple.","Its glossy skin tempted me.","It would be tempting fate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ethic','n.伦理；道德体系','/ˈɛθɪk/','/ˈɛθɪk/','noun',["I think the golden rule is a great ethic."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absolve','vt.赦免；免除；宽恕','/əbˈzɒlv/','/æbˈsɑlv/','verb',["You will absolve a subject from his allegiance."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seclusion','n.独处，隐居；隔离；与世隔绝，归隐','','','noun',["warm seclusion"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boulder','n.巨石，巨砾','/ˈbəʊl.də(ɹ)/','/ˈboʊldəɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Mesolithic','adj.中石器时代的n.中石器时代','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bush','n.灌木；荒野','/bʊʃ/','/bʊʃ/','noun',["bushes to support pea vines","to bush peas","to bush a piece of land; to bush seeds into the ground"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('muse','v.沉思，冥想n.灵感','/mjuːz/','/mjuz/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('combat','v&n.战斗，格斗','/ˈkɒmˌbæt/','/kəmˈbæt/','noun',["It has proven very difficult to combat drug addiction."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('despise','vt.鄙视，看不起','/dɪˈspaɪz/','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grievous','adj.令人忧伤的；极严重的','/ɡɹiː.viː.əs/','/ɡɹiː.viː.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oblong','adj.矩形的，长方形的；椭圆形的n.矩形，长方形；椭圆形','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unity','n.团结一致，统一，联合；协调；统一体','/ˈjuːnɪtɪ/','/ˈjunɪti/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('genetics','n.遗传学','/dʒɛˈnɛ.tɪks/','/dʒɛˈnɛ.tɪks/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pursue','v.继续；从事于；追击，追踪；追求','/pəˈsjuː/','/pɚˈsu/','verb',["Her rival pursued a quite different course."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vulgar','adj.下流的，粗俗的；普通的，通俗的','/ˈvʌl.ɡə/','/ˈvʌl.ɡɚ/','noun',["The construction worker made a vulgar suggestion to the girls walking down the street."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convey','vt.运送，运输；传达，表达','/kənˈveɪ/','/kənˈveɪ/','verb',["Air conveys sound. Water is conveyed through the pipe.","to convey an impression; to convey information","He conveyed ownership of the company to his daughter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('redeem','vt.赎回；偿清，付清；兑换；弥补，补偿；履行，遵守','/ɹɪˈdiːm/','/ɹɪˈdiːm/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rationality','n.理性；合理性','','','noun',["His sudden loss of rationality was brought on by excess drink.","Such a discussion deserves rationality, not emotion a gut reaction."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monogamy','n.一夫一妻制','/məˈnɑɡəmi/','/məˈnɑɡəmi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allude','vi.暗指，影射，间接提到','/əˈluːd/','/əˈluːd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('torpor','n.迟钝；死气沉沉','/ˈtɔːpə(ɹ)/','/ˈtɔɹpɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chagrin','n.懊恼，失望','/ˈʃæɡ.ɹɪn/','/ʃəˈɡɹɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accord','v.与…一致，符合n.协议，条约','/əˈkɔːd/','/ə.ˈkɔɹd/','noun',["the accord of light and shade in painting","The Geneva Accord of 1954 ended the French-Indochinese War.","Nobody told me to do it. I did it of my own accord."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forfeit','vt.被没收，丧失n.罚款；没收物','/ˈfɔː.fɪt/','/ˈfɔɹ.fɪt/','noun',["He who murders pays the forfeit of his own life.","He forfeited his last chance of an early release from jail by repeatedly attacking another inmate.","Because only nine players were present, the football team was forced to forfeit the game."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foremost','adj.最先的；最著名的，最重要的','/ˈfɔː.məʊst/','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('automatic','adj.自动的；无意识的；必然的，自然的n.自动手枪；自动换挡汽车','/ˌɔːtəˈmætɪk/','/ˌɔtəˈmætɪk/','noun',["I never learned to drive a stick. I can only drive an automatic.","The G-men raiding the speakeasy were equipped with .45 automatics, while the local policemen were carrying revolvers and shotguns.","The automatic clothes washer was a great labor-saving device."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disintegrate','v.瓦解；碎裂','/dɪsˈɪntɪɡɹeɪt/','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consecutive','adj.连续不断的，连贯的','/kɒnsɛkjʊtɪv/','/kɒnsɛkjʊtɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assimilation','n.同化；吸收','/əˌsɪməˈleɪʃən/','/əˌsɪməˈleɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quotient','n.商；份额','/ˈkwəʊʃənt/','/ˈkwoʊʃənt/','noun',["The quotient of 12 divided by 4 is 3."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('groan','vi.呻吟；叹息；发出呻吟般的声音n.呻吟；抱怨；呻吟声，叹息声','/ɡɹəʊn/','/ɡɹoʊn/','noun',["The wooden table groaned under the weight of the banquet."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('merchandise','n.商品，货物vt.买卖，经营','/ˈmɜːtʃənˌdaɪs/','','noun',["good business depends on having good merchandise","He started his career merchandising in a small clothing store chain.","He got hired to merchandise some new sporting goods lines."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('livelihood','n.生计，谋生手段','/ˈlaɪvlɪhʊd/','/ˈlaɪvlɪhʊd/','noun',["an independent livelihood; to make / earn / gain a good livelihood"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reunion','n.团圆，重聚','/ɹiːˈjuːnjən/','/ɹiːˈjuːnjən/','noun',["It was a tearful and heartfelt reunion as the trapped miners finally saw their dear loved ones again.","Are you going to the reunion this year?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fantastic','adj.荒诞的，奇异的；极好的；极大的','/fænˈtæstɪk/','/fænˈtæstɪk/','noun',["He told fantastic stories of dragons and goblins.","She entered the lab and stood gaping for a good ten minutes at the fantastic machinery at work all around her.","\"I had a simply fantastic vacation, and I can''t wait to tell you all about it!\""]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('semiotics','n.符号学','/sɛmiˈɒtɪks/','/sɛmiˈɒtɪks/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indecipherable','adj.无法破译的；难以领悟的','/ɪndə-/','/ɪndə-/','adjective',["The doctor''s handwriting was indecipherable."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immigrate','vi.移居入境','/ˈɪmɪɡɹeɪt/','/ˈɪmɪɡɹeɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apparatus','n.器械，器具，设备，装置；机构，组织；器官','/æpəˈɹɑːtəs/','/æ.pəˈɹæ.təs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incidental','adj.偶然的；附带发生的，伴随而来的','[ɪnsɪˈdɛ.ɾ̃əl]','[ɪnsɪˈdɛ.ɾ̃əl]','noun',["She''s costing us a lot in incidentals.","That character, though colorful, is incidental to the overall plot."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('induct','vt.使正式就任；使了解，传授；使入伍','/ɪnˈdʌkt/','/ɪnˈdʌkt/','verb',["Franklin was inducted into the Rock and Roll Hall of Fame in 1987, the first female inductee  [...]","It is my pleasure to induct the new Officers for this coming term.","She was inducted into the ways of the legal profession."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lessen','v.变小，变少，减轻','/ˈlɛsən/','/ˈlɛsən/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('championship','n.锦标赛，冠军赛','/ˈtʃæmpi.ənʃɪp/','/ˈtʃæmpi.ənʃɪp/','noun',["His championship of civil rights eventually bore fruit."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recycle','vt.回收利用，再应用','/ɹiˈsaɪkəl/','/ɹiˈsaɪkəl/','noun',["Both paper and plastic can be recycled.","Sulfur recycles in the sulfur cycle."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sapphire','adj.天蓝色，蔚蓝色的n.蓝宝石，青石；蔚蓝色','/ˈsæf.aɪ̯ə(ɹ)/','/ˈsæf.aɪ̯ɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anthropology','n.人类学','/ˌænθɹəˈpɒlədʒi/','/ˌænθɹəˈpɑːlədʒi/','noun',["According to anthropology, there are six basic patterns of kinship terminology (i.e., \"kin naming systems\"): Sudanese, Hawaiian, Eskimo, Crow, Omaha, and Iroquois."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chaos','n.混乱','/ˈkeɪ.ɒs/','/ˈkeɪ.ɑs/','noun',["After the earthquake, the local hospital was in chaos"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absorption','n.吸收；全神贯注，专心致志','/əbˈsɔːp.ʃn̩/','/æbˈsɔɹp.ʃn̩/','noun',["absorption in some employment"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deteriorate','v.变坏，恶化；变质','/dɪˈtɪəɹɪəɹeɪt/','/dɪˈtɪəɹɪəɹeɪt/','verb',["to deteriorate the mind"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('warehouse','n.仓库，货栈','','','noun',["the warehousing of syndicated TV shows"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bisect','vt.把…二等分，对半分','/baɪˈsɛkt/','/baɪˈsɛkt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('induce','vt.引起，导致；诱使，劝诱；感应','/ɪnˈdjuːs/','/ɪnˈduːs/','verb',["His meditation induced a compromise.   Opium induces sleep."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abnormal','adj.反常的，变态的','/əbˈnɔɹ.ml̩/','/əbˈnɔɹ.ml̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wane','vi.衰退，减弱；减少；亏，缺n.月亏；衰落','/weɪn/','/weɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shrewd','adj.敏捷的，机灵的；精明的','/ʃɹuːd/','/ʃɹuːd/','adjective',["a shrewd guess","a shrewd blow, or assault","a shrewd wind"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('baffle','vt.使困惑，难住','/ˈbæfl̩/','/ˈbæfl̩/','noun',["Tanker trucks use baffles to keep the liquids inside from sloshing around.","I am baffled by the contradictions and omissions in the instructions.","A ship baffles with the winds."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sewerage','n.排水系统；污水处理；污水','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resign','v.辞去，辞职；放弃；顺从，听从','/ɹɪˈzaɪn/','/ɹɪˈzaɪn/','verb',["He resigned the crown to follow his heart.","After fighting for so long, she finally resigned to her death."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diligent','adj.勤奋的，刻苦的，勤勉的','/ˈdɪlɪdʒənt/','','adjective',["Scientists are very diligent in their work."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seasoning','n.调味品，调料','','','noun',["Some of our gentlemen officers, happening to stop at a tavern, or rather a sort of grogshop, took such a seasoning that two or three of them became “quite frisky.”"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sophisticated','adj.老练的，见多识广的；精密的；复杂的，先进的；高雅的，有教养的','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anomaly','n.反常，异常；异常的人','/əˈnɒməlɪ/','/əˈnɑməli/','noun',["He is an anomaly among his friends in that he''s the only one who''s unmarried.","She disregarded some of the anamolies in the experiment, putting them down to miscalculation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chivalrous','adj.有骑士精神的；彬彬有礼的，殷勤的','/ˈʃɪv.əl.ɹʌs/','/ˈʃɪv.əl.ɹʌs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dateline','n.日期栏；国际日期变更线','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grazing','n.放牧；牧场','/ˈɡɹeɪzɪŋ/','/ˈɡɹeɪzɪŋ/','verb',["1999: Although it is perfectly good meadowland, none of the villagers has ever grazed animals on the meadow on the other side of the wall. — Stardust, Neil Gaiman, page 4 (2001 Perennial Edition).","Cattle graze in the meadows.","the bullet grazed the wall"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reside','vi.居住于，定居；存在，在于','/ɹɪˈzaɪd/','/ɹɪˈzaɪd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accident','n.意外事件，事故','/ˈæk.sə.dənt/','/ˈæk.sə.dənt/','noun',["to die by an accident","My insurance went up after the second accident in three months.","Beauty is an accident."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ravine','n.沟壑，溪谷','/ɹəˈviːn/','/ɹəˈviːn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incompatible','adj.不兼容的；不协调的，合不来的','/ˌɪŋkəmˈpætɪbəl/','/ˌɪŋkəmˈpætɪbəl/','noun',["the incompatibles of iron"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('routine','adj.例行的；常规的n.例行公事；惯例，常规','/ɹuːˈtiːn/','/ɹuːˈtiːn/','noun',["Connie was completely robotic and emotionless by age 12; her entire life had become one big routine.","stand-up comedy routine"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distasteful','adj.令人反感的，讨厌的；味道不佳的','/dɪsˈteɪstfəɫ/','/dɪsˈteɪstfəɫ/','adjective',["Scrubbing the floors was a distasteful duty to perform.","distasteful language"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tariff','n.关税；价目表，收费表','/ˈtæɹəf/','/ˈtæɹəf/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enlist','v.征募；从军，参军；谋取','/ɪnˈlɪst/','/ɪnˈlɪst/','noun',["The army wants potential soldiers to enlist.","We enlisted fifty new members.","They enlisted the government''s support."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convict','vt.定罪，宣告…有罪n.服刑囚犯','/ˈkɒnvɪkt/','/ˈkɒnvɪkt/','noun',["His remarks convicted him of a lack of sensitivity."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('validate','vt.使有效，使生效；证实','/ˈvæl.ɪ.deɪt/','/ˈvæl.ɪ.deɪt/','verb',["The data file cannot be imported because it doesn''t validate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dynamical','adj.动态的；动力的；充满活力的','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grading','n.评分；等级','/ˈɡɹeɪdɪŋ/','/ˈɡɹeɪdɪŋ/','verb',["a graded reader"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decadent','adj.堕落的，颓废的','/ˈdɛkədənt/','/ˈdɛkədənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gradient','n.坡度；倾斜度，斜率；梯度','','','noun',["gradient automata","the gradient line of a railroad"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weathering','n.侵蚀，风化','','','verb',["to weather a cape; to weather another ship","Joshua weathered a collision with a freighter near South Africa."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intimate','adj.亲密的，密切的；详尽的，精通的；个人隐私的v.暗示，透露n.至交，密友','/ˈɪn.tɪ.mət/','/ˈɪn.tɪ.mət/','noun',["Only a couple of intimates had ever read his writing.","You''ll find bras and panties in the women''s intimates section upstairs.","He intimated that we should leave before the argument escalated."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disclose','vt.泄露，透露；揭发','/dɪsˈkləʊz/','/dɪsˈkləʊz/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diagram','n.图表；图解','/ˈdaɪ.ə.ɡɹæm/','/ˈdaɪ.ə.ɡɹæm/','noun',["Electrical diagrams show device interconnections."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disparate','adj.迥然不同的','/ˈdɪsp(ə)ɹət/','/dɪˈspæɹət/','noun',["The board of the company was decidedly disparate, with no two members from the same social or economic background."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defiant','adj.反叛的，挑衅的，公然违抗的','/dɪˈfaɪ(j)ənt/','/dɪˈfaɪənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tragedy','n.惨事，灾难；悲剧','/ˈtɹæd͡ʒɪdi/','/ˈtɹæd͡ʒɪdi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oxide','n.氧化物','/ˈɒksaɪd/','/ˈɒksaɪd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('startling','adj.惊人的，令人吃惊的','/ˈstɑː.tl̩.ɪŋ/','/ˈstɑː.tl̩.ɪŋ/','verb',["a horse that startles easily"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bison','n.美洲野牛','/ˈbaɪ̯sən/','/ˈbaɪ̯sən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evoke','vt.唤起，引起，激起','/ɪˈvəʊk/','/ɪˈvoʊk/','verb',["Being here evokes long forgotten memories."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attend','v.出席，参加；照料，看管；专心，注意；陪同','/əˈtɛnd/','/əˈtɛnd/','verb',["Secretaries attend to correspondence.","Servants attend the king day and night.","Children must attend primary school."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shovel','vt.铲；把…大量投入n.铲，铁铲；挖掘机','/ˈʃʌvəl/','/ˈʃʌvəl/','noun',["After the blizzard, we shoveled the driveway for the next two days.","Already late for work, I shovelled breakfast into my mouth as fast as possible."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embryo','n.胚，胚胎；雏形','/ˈɛmbɹi.əʊ/','/ˈɛmbɹi.əʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accounting','n.会计学；会计','/ə.ˈkaʊn.tɪŋ/','/ə.ˈkaʊn.tɪŋ/','verb',["He was required to give a thorough accounting of his time.","General accepted accounting principles"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('align','v.结盟；排整齐；校准；使一致','/æˈlaɪn/','/æˈlaɪn/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intoxication','n.醉，醉酒；极度兴奋','','','noun',["He suffered acute intoxication from the combined effects of several drugs."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wasp','n.黄蜂','/wɒsp/','/wɑsp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neutron','n.中子','/ˈn(j)uːtɹɒn/','/ˈn(j)uːtɹɒn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('locomotive','adj.运动的；移动的n.机车，火车头','/ˌləʊkəʊˈməʊtiv/','/ˌloʊkəˈmoʊtiv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('avenue','n.途径，手段；大街','/ˈæv.əˌnjuː/','/ˈæv.əˌn(j)u/','noun',["There are several avenues by which we can approach this problem."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vacate','vt.腾出，空出；离，退','','','verb',["I have to vacate my house by midday, as the new owner is moving in.","He vacated his coaching position because of the corruption scandal.","The judge vacated the earlier decision when new evidence was presented."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inherent','adj.固有的；内在的','/ɪnˈhɛɹənt/','/ɪnˈhɛɹənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advantageous','adj.有利的','/ˌædvənˈteɪd͡ʒəs/','/ˌædvənˈteɪd͡ʒəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('given','adj.规定的，特定的；假定的prep.考虑到，鉴于','/ˈɡɪ.vən/','/ˈɡɪ.vən/','verb',["I give it a 95% chance of success.","One pillar gave, then more, and suddenly the whole floor pancaked onto the floor below.","They''re giving my favorite show!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hay','n.干草','/heɪ/','/heɪ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('encroach','vi.侵占；侵蚀，蚕食','/ɛŋˈkɹəʊtʃ/','/ɛŋˈkɹəʊtʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pronounced','adj.显著的；明确的','/pɹəˈnaʊnst/','/pɹəˈnaʊnst/','verb',["I hereby pronounce you man and wife.","The doctor pronounced them legally dead.","The judge had pronounced often before, but never in front of such a crowd."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perish','v.灭亡；湮灭，毁灭；老化','/ˈpɛɹɪʃ/','/ˈpɛɹɪʃ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('definite','adj.清楚的，确切的；肯定的','/ˈdɛfɪnɪt/','/ˈdɛfənɪt/','noun',["definite dimensions; a definite measure; a definite period or interval","definite knowledge","the definite article"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stipulate','v.规定，明确要求；约定','/ˈstɪpjuˌleɪt/','/ˈstɪpjuˌleɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wary','adj.小心翼翼的，留神的，警惕的','/ˈwɛəɹ.i/','/ˈwɛəɹ.i/','adjective',["He is wary of dogs."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('batch','v.分批处理n.一批，一组，一群；一批生产的量','/bæt͡ʃ/','/bæt͡ʃ/','noun',["We made a batch of cookies to take to the party.","We poured a bucket of water in at the top, and the ice-maker dispensed a batch of ice-cubes at the bottom.","The system throttled itself to batches of 50 requests at a time to keep the thread count under control."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stagecoach','n.公共马车，驿站马车','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intrinsic','adj.固有的，本质的，内在的','/ɪn.ˈtɹɪn.zɪk/','/ɪn.ˈtɹɪn.zɪk/','noun',["You can acquire the fire-resistance intrinsic by eating dragon meat.","the intrinsic merit of an action"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guilty','adj.有罪的，犯罪的；内疚的','/ˈɡɪl.ti/','/ˈɡɪl.ti/','noun',["He was guilty of cheating at cards.","The guilty man was led away.","Do you have a guilty conscience?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vestige','n.遗迹，残余；丝毫，一点儿','/ˈvɛ.stɪd͡ʒ/','/ˈvɛ.stɪd͡ʒ/','noun',["the vestiges of ancient magnificence in Palmyra"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interstellar','adj.星际的','','','adjective',["It can take centuries for light to travel interstellar distances.","Space is littered with interstellar particles."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('luminous','adj.发光的，明亮的','/ˈluːmɪnəs/','/ˈluːmɪnəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lash','v.将系牢，捆绑；猛烈打击；鞭打；猛烈抨击，严厉斥责n.鞭打；睫毛','/læʃ/','/læʃ/','noun',["The culprit received thirty-nine lashes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maritime','adj.海的，海事的；航海的','/ˈmæ.ɹɪˌtaɪm/','','adjective',["I enjoy maritime activities such as yachting and deep sea diving.","the maritime states; a maritime people","a maritime bird or animal"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rattle','v.发出咔嗒声；使紧张，使恐惧n.咔嗒声；拨浪鼓','/ˈɹæt.l̩/','/ˈɹæt.l̩/','noun',["I wish they would fix the rattle under my dashboard.","The rattle of the rattlesnake is composed of the hardened terminal scales, loosened in succession, but not cast off, and modified in form so as to make a series of loose, hollow joints.","Rattle the can of cat treats if you need to find Fluffy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('warp','v.扭曲，弯曲，变形；','/woːp/','/wɔɹp/','noun',["a warp of fish"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('basement','n.地下室，地窖；建筑物的底部','/ˈbeɪsmənt/','/ˈbeɪsmənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('injurious','adj.侮辱的，诽谤的；造成伤害的，有害的','/ɪnˈdʒɔːɹɪəs/','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chant','v.唱圣歌；反复呼喊n.圣歌；单调的吟唱；反复呼喊的话语','/tʃænt/','/tʃænt/','noun',["The football fans chanted insults at the referee."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commune','vi.与…亲密地交谈n.群体，公社','/ˈkɒmjuːn/','/ˈkɑmjuːn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('babble','v.胡言乱语；含糊不清地说；喋喋不休','/ˈbæb.l̩/','/ˈbæb.l̩/','noun',["The men were babbling, so we couldn''t make sense of anything.","Hounds are said to babble, or to be babbling, when they are too noisy after having found a good scent."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('focalize','v.调节焦距；使聚焦；使集中','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toady','vi.谄媚，奉承n.谄媚者，马屁精','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('squabble','vi.发生口角，','/ˈskwɒbl/','/ˈskwɑːbl/','noun',["The children got into a squabble about who should ride in the front of the car.","The brothers were always squabbling with each other.","to squabble type"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rustic','adj.乡村的；淳朴的；用粗糙木材制作的','/ˈɹʌstɪk/','/ˈɹʌstɪk/','noun',["rustic manners","rustic country where the sheep and cattle roamed freely"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minimal','adj.最小的；最低限度的','/mɪnəməl/','/mɪnəməl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('venomous','adj.有毒的，分泌毒液的；恶意的，狠毒的','/ˈvɛnəməs/','/ˈvɛnəməs/','adjective',["The villain tricked him into drinking the venomous concoction.","His attitude toward me is utterly venomous.","Do venomous spiders have glands?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('courageous','adj.勇敢的，有胆量的','/kəˈɹeɪdʒəs/','/kəˈɹeɪdʒəs/','adjective',["the most courageous person I have ever met","a courageous deed"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prudent','adj.谨慎的；深谋远虑的','/ˈpɹuːdənt/','/ˈpɹuːdənt/','adjective',["His prudent career moves reliably brought him to the top","Only prudent expenditure may provide quality within a restrictive budget"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overview','n.梗概，概述','/ˈəʊvə(ɹ)ˌvjuː/','/ˈəʊvə(ɹ)ˌvjuː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notwithstanding','ad&prep.虽然，尽管如此','/ˌnɒtwɪðˈstændɪŋ/','/ˌnɑtwɪθˈstændɪŋ/','noun',["He, notwithstanding, persisted in his inquiries."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('volatile','adj.挥发性的，易挥发的；不稳定的；反复无常的','/ˈvɒl.əˌtaɪ.(ə)l/','/ˈvɑl.ə.tl̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ideomotor','adj.观念运动的','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generic','adj.种类的，属的；一般的，普通的','/dʒɪˈnɛɹɪk/','','noun',["\"Shrimp\" is the generic name for a number of species of sea creature."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('endorse','vt.签名；宣传，代言；签署；赞同，支持','/ɪnˈdɔːs/','/ɪnˈdɔːs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alike','adv.一样地，相似地；同样程度地adj.相同的，相似的','/əˈlaɪk/','/əˈlaɪk/','adjective',["The twins were alike.","We are all alike concerned in religion."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('infrastructure','n.基础设施，基础结构','/ˈɪnfɹəˌstɹʌk(t)ʃɚ/','/ˈɪnfɹəˌstɹʌk(t)ʃɚ/','noun',["The parasitic tyranny''s infrastructure depends on secrecy in order to be effective."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embargo','n.禁止贸易令；','/ɪmˈbɑːɡəʊ/','/ɪmˈbɑːɡəʊ/','noun',["This copy of the federal budget is under embargo until 2 p.m."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wither','v.枯萎，凋谢；衰退；萎缩；破灭','/ˈwɪðə/','/ˈwɪðə/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quotation','n.引文，引语，语录；报价','/kwoʊˈteɪʃən/','/kwoʊˈteɪʃən/','noun',["\"Where they burn books, they will also burn people\" is a famous quotation from Heinrich Heine.","Let''s get a quotation for repairing the roof before we decide whether it''s worth doing."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nocturnal','adj.夜行性的；夜间发生的','/nɒkˈtɜː(ɹ)nəl/','/nɑkˈtɚnəl/','noun',["nocturnal birds","a suspicious nocturnal outing"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corrosion','n.腐蚀，侵蚀','/kəˈɹəʊʒən/','/kəˈɹəʊʒən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notorious','adj.臭名昭著的，声名狼藉的','/nəʊˈtɔːɹɪəs/','/noʊˈtɔɹiəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('illustrative','adj.作为例证的；用做说明的；解释性的','/ɪˈlʌs.tɹə.tɪv/','/ɪˈlʌs.tɹə.tɪv/','adjective',["This latest incident is illustrative of his continued bad behavior."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superimpose','vt.使重叠，使叠加；添加','','','verb',["He superimposed the company logo over the image."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('artifact','n.人工制品，手工艺品','/ˈɑːtɪfækt/','/ˈɑːtɪfækt/','noun',["The spot on his lung turned out to be an artifact of the X-ray process.","The dig produced many Roman artifacts.","This JPEG image has been so highly compressed that it has unsightly compression artifacts, making it unsuitable for the cover of our magazine."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tantalizing','adj.诱人的','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swoop','v.猛扑；突然袭击n.突然行动','/ˈswuːp/','/ˈswuːp/','noun',["The quality of decision is like the well-timed swoop of a falcon which enables it to strike and destroy its victim. – Sun Tzu","The lone eagle swooped down into the lake, snatching its prey, a small fish.","The dog had enthusiastically swooped down on the bone."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('floral','adj.花的，像花的；饰以花的，绘有花的','/ˈflɔːɹəl/','/ˈflɔːɹəl/','noun',["I really like the floral pattern on this Chinese vase."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pest','n.害虫；令人讨厌的人','/pɛst/','/pɛst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swoon','vi&n.昏厥，昏倒；痴迷','/swuːn/','/swuːn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('magnesium','n.镁','/ˌmæɡˈniːzi.əm/','/ˌmæɡˈnizi.əm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('infancy','n.幼年；初期','/ˈɪnfənsi/','/ˈɪnfənsi/','noun',["Space tourism is still in its infancy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heritage','n.遗产；传统','/ˈhɛɹɪtɪd͡ʒ/','/ˈhɛɹɪtɪd͡ʒ/','noun',["The university requires heritage Spanish students to enroll in a specially designed Spanish program not available to non-heritage students."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supreme','adj.至高无上的','/ˌs(j)uːˈpɹiːm/','','noun',["supreme disgust; supreme courage"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outrageously','adv.令人不能容忍地；肆无忌惮地','','','adverb',["The hotel was wonderful, but the food was outrageously expensive."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lapse','vi.期满终止，失效；衰退；背弃n.失误；失足','/læps/','/læps/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regenerate','v.复兴，振兴；再生','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('latent','adj.潜在的，隐伏的；潜伏的；休眠的','/ˈleɪ.tənt/','/ˈleɪ.tənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forestall','vt.预防，预先阻止；先发制人','/fɔː(ɹ)ˈstɔːl/','/fɔː(ɹ)ˈstɔːl/','verb',["Fred forestalled disaster by his prompt action."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terrific','adj.极好的；非常的，极度的；可怕的','/təˈɹɪfɪk/','/təˈɹɪfɪk/','adjective',["I''ve got a terrific hangover this morning.","I say! She''s a terrific tennis player."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stanza','n.节，段','/ˈstænzə/','/ˈstænzə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worship','n&v.祭拜；崇拜，崇敬','/ˈwɜːʃɪp/','/ˈwɝʃɪp/','noun',["We worship at the church down the road."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lawn','n.草地，草坪；操场','/lɔːn/','/lɔn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('infection','n.传染，感染；传染病','/ɪnˈfɛkʃən/','/ɪnˈfɛkʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ponderous','adj.笨重的；笨拙的；沉闷的','/ˈpɒn.dəɹ.əs/','/ˈpɑn.dɚ.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stubborn','adj.顽固的，倔强的；难对付的','/ˈstʌbən/','/ˈstʌbɚn/','noun',["Blood can make a very stubborn stain on fabrics if not washed properly."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imprecise','adj.不精确的；不严密的','/ɪmpɹɪˈsaɪs/','/ɪmpɹɪˈsaɪs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('formulate','vt.阐明，确切表达；规划，构想；制定','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glorify','vt.吹捧，美化；赞美，赞扬','/ˈɡlɔɹɪfaɪ/','/ˈɡlɔɹɪfaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emigrate','v.移民，移居国外','/ˈɛmɪɡɹeɪt/','/ˈɛmɪɡɹeɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sinuous','adj.蜿蜒的；迂回的','/ˈsɪn.ju.əs/','/ˈsɪn.ju.əs/','adjective',["We followed every bend of the sinuous river.","We were entranced by her sinuous dance."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('triangle','n.三角形；三角形物体','/ˈtɹaɪəŋɡəl/','/ˈtɹaɪˌæŋɡəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alien','n.外星人；组织之外的人；外国人，','/ˈeɪ.li.ən/','/ˈeɪ.li.ən/','noun',["alien subjects, enemies, property, or shores","principles alien to our religion"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('layer','n.层，层次','/leɪə/','/ˈleɪ.ɚ/','noun',["After the first coat of paint dried, he applied another layer.","I find seven-layer cake a bit too rich.","mired in layers of deceit"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sanitation','n.卫生；卫生设施，卫生设备','/ˌsænɪˈteɪʃən/','/ˌsænɪˈteɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chubby','adj.丰满的，圆胖的','/ˈtʃʌbi/','/ˈtʃʌbi/','noun',["Obviously the chubby child was eating too much.","It’s quite normal for babies to have chubby cheeks."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ivory','n.象牙；象牙制品；象牙色，乳白色','/ˈaɪvəɹi/','/ˈaɪvəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anomalous','adj.异常的；不规则的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deficient','adj.不足的，缺乏的；有缺陷的，不完善的','/dɪˈfɪʃənt/','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('henceforth','adv.从此以后','/hɛnsˈfɔɹθ/','/hɛnsˈfɔɹθ/','adverb',["I will try to do a better job, henceforth, now that I know the proper technique!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preponderance','n.优势','/pɹɪˈpɒnd(ə)ɹəns/','/pɹɪˈpɒnd(ə)ɹəns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barrel','n.桶','/ˈbæɹəl/','/ˈbæɹəl/','noun',["a cracker barrel","the barrel of a windlass;  the barrel of a watch, within which the spring is coiled.","Throw it into the trash barrel."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unify','vt.统一，联合','/ˈjuːnɪfaɪ/','/ˈjuːnɪfaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ravage','vt.毁坏；抢劫，掠夺','/ˈɹævɪdʒ/','/ˈɹævɪdʒ/','noun',["the ravage of a lion; the ravages of fire or tempest; the ravages of an army, or of time"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fungi','n.[fungus的复数]真菌','/ˈfʌn.dʒaɪ/','/ˈfʌn.dʒaɪ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('receptacle','n.容器；插座','/ɹɪˈsɛp.tə.kl̩/','/ɹɪˈsɛp.tə.kl̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('summarize','v.概括，总结','/ˈsʌməˌɹaɪz/','/ˈsʌməˌɹaɪz/','verb',["Jim was asked to summarize the document by Wednesday.","After the meeting, Jim summarized the major decisions made."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gregarious','adj.群居的；合群的，爱社交的','/ɡɹɪˈɡɛə.ɹɪ.əs/','/ɡɹɨˈɡɛɹ.i.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beak','n.鸟嘴，喙','/biːk/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aviation','n.航空，航空学；飞行','/eɪviˈeɪʃən/','/eɪviˈeɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appointment','n.约会，约定；任命，委派；职位','/əˈpɔɪnt.mɛnt/','/əˈpɔɪnt.mɛnt/','noun',["His appointment was deemed suitable","the appointment of treasurer","I''m leaving work early because I have a doctor''s appointment."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('synthesize','vt.合成；综合','/ˈsɪnθəsaɪz/','/ˈsɪnθəsaɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trek','n&v.艰苦跋涉','/tɹɛk/','/tɹɛk/','noun',["We''re planning a trek up Kilimanjaro.","I would drive to the shops from here; you can walk, but it''s quite a trek."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('squash','v.压碎，挤压；挤进，塞入；制止n.软式墙网球，壁球；果汁汽水','/skwɒʃ/','/skwɔʃ/','noun',["When I''m thirsty I drink squash; it tastes much nicer than plain water.","It''s a bit of a squash in this small room.","Somehow, she squashed all her books into her backpack, which was now too heavy to carry."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('major','vi.主修，专攻adj.较大的；主要的；主修的n.专业','/ˈmeɪ.dʒə(ɹ)/','/ˈmeɪ.dʒɚ/','noun',["He used to be a major in the army."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('playwright','n.剧作家','/ˈpleɪˌɹaɪt/','/ˈpleɪˌɹaɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interrupt','v.打扰；中断；阻碍','/ˌɪntəˈɹʌpt/','/ˌɪntəˈɹʌpt/','noun',["The interrupt caused the packet handler routine to run.","A maverick politician repeatedly interrupted the debate by shouting.","The evenness of the road was not interrupted by a single hill."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beat','v.打拍子，指挥；敲打；打败，胜过；跳动adj.疲惫的n.跳动；节拍，节奏；有规律的敲击','/biːt/','/biːt/','noun',["a beat of the heart; the beat of the pulse","the beat of him","a dead beat"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feasible','adj.可行的，行得通的','/ˈfiːzəbəl/','/ˈfiːzəbəl/','adjective',["His plan to rid Trafalgar Square of pigeons by bringing in peregrine falcons to eat them was dismissed as not feasible."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prescribe','v.开处方；规定；指示','/pɹɪˈskɹaɪb/','/pɹɪˈskɹaɪb/','verb',["The doctor prescribed aspirin.","The property meets the criteria prescribed by the regulations."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proofread','v.校对，校正','/ˈpɹuːfɹiːd/','/ˈpɹuːfɹiːd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lounge','vi.懒洋洋地站n.等候室，休息室','/laʊndʒ/','/laʊndʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gross','adj.总的，毛的；粗俗的，粗野的；令人不快的vt.总收入为n.一罗；','/ɡɹəʊs/','/ɡɹoʊs/','noun',["The movie grossed three million on the first weekend.","a gross mistake;  gross injustice;  gross negligence; a gross insult","gross domestic product; gross income; gross weight"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('archive','n.档案室vt.存档','/ˈɑɹkaɪv/','/ˈɑɹkaɪv/','noun',["His archive of Old High German texts is the most extensive in Britain.","soil archive; peat archive","I was planning on archiving the documents from 2001."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disarm','v.解除武装；裁军；消除，消解','/dɪsˈɑː(ɹ)m/','/dɪsˈɑː(ɹ)m/','noun',["to disarm a man''s wrath"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extrapolate','v.外推；推断，推知','/ɛkˈstɹæp.əˌleɪt/','/ɛkˈstɹæp.əˌleɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reciprocity','n.互惠，互助；互惠主义','','','noun',["In a friendship, reciprocity occurs where the contribution of each party meets the expectations of the other party."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eclipse','vt.遮住光；使相形见绌n.日食，月食','/iˈklɪps/','/iˈklɪps/','noun',["The Moon eclipsed the Sun."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('square','adj.正方形的；成直角的，方的；平方的n.正方形；广场；平方vt.使成正方形；求平方；使打成平局','/skwɛə(ɹ)/','/skwɛɚ/','noun',["64 is the square of 8.","Why do you always wear a tie? Don''t be such a square!","Enter your account number followed by a square."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('careless','adj.粗心的，疏忽的；无忧无虑的；不关心的，冷漠的','/ˈkɛələs/','/ˈkɛɹləs/','adjective',["Jessica was so careless that she put her shorts on backwards."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soak','v.浸泡，浸湿，浸透','/səʊk/','/səʊk/','noun',["After the strenuous climb, I had a nice long soak in a bath.","I''m going to soak in the bath for a couple of hours.","Soak the beans overnight before cooking."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('counteract','vt.消除；抵消','/ˈkaʊntəɹˌækt/','/ˈkaʊntəɹˌækt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deserted','adj.荒废的，空无一人的；被离弃的，被遗弃的','/dɪˈzɜːtəd/','','verb',["You can''t just drive off and desert me here, in the middle of nowhere.","Anyone found deserting will be punished."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commute','v.上下班往返，经常往返；代偿；减刑','/kəˈmjuːt/','/kəˈmjuːt/','verb',["to commute tithes into rentcharges for a sum; to commute market rents for a premium, to commute daily fares for a season ticket","A pair of matrices share the same set of eigenvectors if and only if they commute."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anarchist','n.无政府主义者','/ˈæn.ə.kɪst/','/ˈæn.ə.kɪst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('numeric','adj.数字的','/n(j)uːˈmɛɹɪk/','/n(j)uːˈmɛɹɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('debut','n.首次演出；初次亮相','/dəˈbʉː/','/deɪˈbjuː/','noun',["Since making its debut two years ago, the program has gained cult status.","Amalgamated Software Systems debuted release 3.2 in Spring of 2004.","Release 3.2 debuted to mixed reviews in Spring of 2004."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uphold','vt.支持，维护；维持','/ˌʌpˈhold/','/ˌʌpˈhold/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dimension','n.维，元；尺寸；方面；特点；','/daɪˈmɛnʃən/','/daɪˈmɛnʃən/','noun',["The dimension of velocity is length divided by time."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nostalgia','n.思乡病，乡愁；怀旧之情，恋旧','/nɒˈstaldʒə/','/nɒˈstaldʒə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deserve','v.应得，值得','/dɪˈzɜːv/','/dɪˈzɝv/','verb',["After playing so well, the team really deserved their win."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('process','vt.加工，处理n.过程；程序，手续；工序，制作法','/ˈpɹəʊsɛs/','/ˈpɹɑsɛs/','noun',["This product of last month''s quality standards committee is quite good, even though the process was flawed.","1960, Mack Tyner, Process Engineering Calculations: Material and Energy Balances – Ordinarily a process plant will use a steam boiler to supply its process heat requirements and to drive a steam-turbine generator.","We have processed the data using our proven techniques, and have come to the following conclusions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sprout','v.发芽，抽条，生长；迅速出现，涌现出n.新芽，嫩枝，苗','/spɹʌʊt/','/spɹaʊt/','noun',["I sprouted beans and radishes and put them in my salad.","to sprout potatoes","Whiskers sprouted from the old man''s chin."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('restore','vt.恢复；修复；归还，交还','/ɹɪˈstɔː/','/ɹɪˈstɔɹ/','noun',["We backed up the data successfully, but the restore failed.","He restored my lost faith in him by doing a good deed.","There was a crash last night, and we''re still restoring the file system."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('viscous','adj.黏滞的，黏性的','/ˈvɪs.kəs/','/ˈvɪs.kəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nostalgic','adj.思乡的；怀旧的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('banner','n.横幅','/ˈbænə/','/ˈbænɚ/','noun',["The mayor hung a banner across Main Street to commemorate the town''s 100th anniversary.","They usually make their case under the banner of environmentalism."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('landslide','n.山崩，塌方；压倒性胜利','/ˈlænd.slaɪd/','/ˈlænd.slaɪd/','noun',["The candidate won by a landslide."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prairie','n.大草原','/ˈpɹɛəɹi/','/ˈpɹɛəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('approve','v.批准；赞成','/əˈpɹuːv/','/əˈpɹuːv/','verb',["Although we may disagree with it, we must nevertheless approve the sentence handed down by the court-martial.","We approve the measure of the administration, for it is an excellent decision.","Her mother never approves of any of her boyfriends. She thinks nobody is good enough for her little girl."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chafe','v.擦破，擦痛；恼怒，焦躁','/tʃeɪf/','/tʃeɪf/','noun',["to chafe a cable","A cable chafes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chew','v.咀嚼；思量，熟思','/tʃuː/','/tʃu/','noun',["I popped the gum into my mouth and gave it a chew.","Phillip purchased a bag of licorice chews at the drugstore.","The school had banned chew and smokes from the school grounds, even for adults."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('domicile','n.住处，住所','/ˈdɑmɪsaɪl/','/ˈdɑmɪsaɪl/','noun',["The call to jury duty was sent to my legal domicile; too bad I was on vacation at the time.","The answer depends on which state he was domiciled in at his death."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pedestrian','adj.徒步的；缺乏想象力的n.步行者，行人','/pəˈdɛst.ɹi.ən/','/pəˈdɛst.ɹi.ən/','noun',["pedestrian crossing","His manner of dress was pedestrian but tidy.","The choreographer prefers pedestrian movements."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurry','v.使加快，催促；赶快，匆忙n.急忙，匆忙，仓促','/ˈhʌ.ɹi/','/ˈhʌ.ɹi/','noun',["Why are you in such a big hurry?","There is no hurry on that paperwork.","He''s hurrying because he''s late."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radioactive','adj.放射性的，有辐射的','/ˌɹeɪdioʊˈaktɪv/','/ˌɹeɪdioʊˈaktɪv/','noun',["Even sleazy tactics and his radioactive mouth may not be able to contain this debacle."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('innocent','adj.天真的；清白的；无恶意的','/ˈɪnəsn̩t/','/ˈɪnəsn̩t/','noun',["The slaughter of the innocents was a significant event in the New Testament.","an innocent trade","innocent goods carried to a belligerent nation"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alphabet','n.字母表','/ˈæl.fə.bɛt/','/ˈæl.fə.bɛt/','noun',["In the first year of school, pupils are taught to recite the alphabet.","Let L be a regular language over the alphabet \\Sigma."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stride','n.大步；步法；','/stɹaɪd/','/stɹaɪd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advance','v.前进，向前移动；发展，进步；促进；预付adj.预先的；先头的n.前进；进展；预付','/ədˈvaːns/','/ədˈvæns/','noun',["an advance in health or knowledge","an advance on the prime cost of goods","He made an advance payment on the prior shipment to show good faith."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bleach','v.变白，漂白n.漂白剂','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rally','v.集合，召集；恢复，重新振作n.集会，大会','/ˈɹæ.li/','/ˈɹæ.li/','noun',["a campaign rally","a political rally"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fictitious','adj.虚构的；假的；假装的，虚伪的','/fɪkˈtɪʃəs/','/fɪkˈtɪʃəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prime','adj.主要的；最初的；最好的；首先的n.全盛时期，盛年vt.使准备好；事先指点','/pɹaɪ̯m/','/pɹaɪ̯m/','noun',["3 is a prime.","I''m threatening to build a prime here.","Our prime concern here is to keep the community safe."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intellect','n.智力，理解力；知识分子','/ˈɪntəlɛkt/','/ˈɪntəlɛkt/','noun',["Intellect is one of man''s greatest powers.","They were chosen because of their outstanding intellect.","Some of the world''s leading intellects were meeting there."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amble','vi.缓行，漫步','/ˈæm.bəl/','/ˈæm.bəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loyal','adj.忠诚的，忠贞的','/ˈlɔɪəl/','/ˈlɔɪəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mainstream','n.主流，主要倾向；主流思想','','','noun',["His ideas were well outside the mainstream, but he presented them intelligently, and we were impressed if not convinced.","Mainstreaming has become more common in recent years, as studies have shown that many mainstreamed students with mild learning disabilities learn better than their non-mainstreamed counterparts.","They often carry stories you won''t find in the mainstream media."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dissolute','adj.放荡的，放纵的，道德沦丧的','/ˈdɪsəljuːt/','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chapel','n.教堂；祈祷室','/ˈtʃæ.pəl/','/ˈtʃæ.pəl/','noun',["The village butcher is chapel."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subsidiary','adj.次要的；辅助的，附设的；附属的n.子公司；附属机构；支流','/sʌbˈsɪ.di.əɹ.i/','/sʌbˈsɪ.di.əɹ.i/','noun',["a subsidiary stream","subsidiary payments to an ally"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('venture','v.敢于去；冒险n.冒险，投机；投机活动，风险项目','/ˈvɛn.t͡ʃə/','/ˈvɛn.t͡ʃɚ/','noun',["Nothing ventured, nothing gained.","to venture a horse to the West Indies"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interrelate','v.相互关联，紧密联系','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corrosive','adj.腐蚀的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enthusiasm','n.热情；积极性；热衷的事物','/-θuː-/','/-θuː-/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discern','vt.洞悉；识别','','','verb',["He was too young to discern right from wrong."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('propensity','n.倾向，癖好','/pɹəˈpɛnsɪti/','/pɹəˈpɛnsɪti/','noun',["He has a propensity for lengthy discussions of certain favorite topics."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entreat','v.乞求，恳求，请求','/ənˈtɹiːt/','/ənˈtɹiːt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agile','adj.敏捷的，灵活的','/ˈæd͡ʒ.aɪl/','/ˈæd͡ʒ.aɪl/','adjective',["an agile creature","agile movements","agile methods"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('replenish','vt.添加，补充','/ɹɪˈplɛn.ɪʃ/','/ɹɪˈplɛn.ɪʃ/','verb',["It''s a popular product, and they have to replenish their stock of it frequently."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hoe','vt.用锄头锄n.锄头','/həʊ/','/həʊ/','noun',["Every year, I hoe my garden for aeration.","to hoe corn"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amenable','adj.顺从的，服从劝导的；有服从义务的','/əˈmɛn.ə.bəl/','/əˈmɛn.ə.bəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sustainable','adj.不破坏生态平衡的，可持续的；足可支撑的；可忍受的','/səˈsteɪnəbəl/','/səˈsteɪnəbəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('secede','vi.正式脱离，退出','/sɪˈsiːd/','/sɪˈsiːd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interweave','v.交织，编结','/ɪntəɹˈwiːv/','/ɪntəɹˈwiːv/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rouse','vt.唤起，唤醒；激起，鼓舞；激怒','/ˈɹaʊz/','/ˈɹaʊz/','noun',["to rouse the faculties, passions, or emotions","to rouse a deer or other animal of the chase","He roused on her for being late yet again."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('capability','n.能力；性能；容量；潜质','/keɪpəˈbɪləti/','/keɪpəˈbɪləti/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spark','v.激发，引发，触发；','/spɑːk/','/spɑɹk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('integral','adj.构成整体所必需的，不可或缺的；完整的','/ˈɪntɪɡɹəl/','/ˈɪntɪɡɹəl/','noun',["The integral of x\\mapsto x^2 on [0,1] is \\frac{1}{3}.","The integral of x^2 is \\frac{x^3}{3} plus a constant."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assembly','n.集会；集会者；装配，安装；立法机构，议会','/əˈsɛmb.lɪ/','/əˈsɛmb.li/','noun',["In order to change the bearing, you must first remove the gearbox assembly.","assembly line","freedom of assembly"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smelting','n.冶炼，熔炼','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spare','adj.备用的；空闲的vt.抽出；免除n.备用品','/ˈspɛə(ɹ)/','/ˈspɛəɹ/','noun',["a spare diet","I have no spare time.","a spare anchor; a spare bed or room"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('replicate','v.复制；再制，再生','/ˈɹɛpləˌkeɪt/','/ˈɹɛpləˌkeɪt/','noun',["On entering a host cell, a virus will start to replicate.","a replicate leaf or petal"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emotional','adj.感情的，情绪的；引起情感的；易动感情的','/ɪˈməʊʃnəl/','/ɪˈməʊʃnəl/','adjective',["emotional crisis","emotional decision","emotional speech"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noticeable','adj.明显的，值得注意的','/ˈnəʊtɪsəbl̩/','/ˈnəʊtɪsəbl̩/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hibernation','n.冬眠；休眠，蛰伏','/ˌhaɪ.bəːˈneɪ.ʃən/','/ˌhaɪ.bəːˈneɪ.ʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('march','v.前进，进发；行进，齐步走；游行示威n.行进，行军；示威游行；进行曲；进行，进展','/mɑːtʃ/','/mɑɹtʃ/','noun',["the march of time"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blast','v.爆炸；发出尖响；猛烈抨击n.一阵；爆炸；冲击波；响声','/blɑːst/','/blɑːst/','noun',["many tons of iron were melted at a blast","We had a blast at the party last night.","an e-mail blast; a fax blast"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repel','v.击退，驱逐；排斥；抵制，拒绝；使反感，使厌恶','/ɹɪˈpɛl/','/ɹɪˈpɛl/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('publicize','vt.宣传，推广，宣扬','/ˈpʌblɪˌsaɪz/','/ˈpʌblɪˌsaɪz/','verb',["The scandal was so publicised that he lost the next election.","They''re already publicising next month''s concert."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('underscore','vt.强调；在…之下画线n.底线','/ˈʌn.də(ɹ)ˌskɔː(ɹ)/','','noun',["I wish to underscore the importance of proper formatting."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seashore','n.海岸，海滨','/ˈsiːʃɔː/','/ˈsiːʃɔː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imaginative','adj.富有想象力的；创新的','/-ənətɪv/','/-ənətɪv/','adjective',[]);
