INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corpus','n.文集，文献，汇编；语料库','/ˈkɔːpəs/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inconvenient','adj.不便的；让人不舒服的','','','noun',[]);
