INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absurd','adj.可笑的，荒唐的','/æbˈzɝd/','/æbˈsɝd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trait','n.特性，特点','/tɹeɪ/','/tɹeɪ/','noun',["The number one personality trait I hate is hypocrisy. Why can''t you be consistent!?","Traits are somewhat between an interface and a mixin."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('landmark','n.路标，地标；〈喻〉里程碑','','/ˈlændmɑɹk/','noun',["a landmark paper in neurosurgery"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vanish','vi.消失；灭绝','/ˈvænɪʃ/','/ˈvænɪʃ/','noun',["a as in ale ordinarily ends with a vanish of i as in ill.","The French drop is a well-known vanish involving sleight of hand.","The function f(x)=x^2 vanishes at x=0."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vault','v.跳过n.拱顶；金库，保险库；撑杆跳','/vɒlt/','/vɑlt/','noun',["Family members had been buried in the vault for centuries.","The bank kept their money safe in a large vault."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concave','adj.凹的','/ˈkɒŋkeɪv/','/ˈkɒŋkeɪv/','noun',["Aristotle makes [Fire] to move to the concave of the Moon. - Thomas Salusbury (1661)."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dolphin','n.海豚','/ˈdɒlfɪn/','/ˈdɑlfɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enactment','n.制订，颁布；法律，法规','','','noun',["The actors'' powerful enactment of the play was breathtaking.","The enactments passed by the council that year included sweeping reforms."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('planet','n.行星','/ˈplænət/','/ˈplænɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ornithology','n.鸟类学','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prerequisite','adj.必备的，作为先决条件的n.先决条件，前提','/pɹiːˈɹɛkwɪzɪt/','/pɹiːˈɹɛkwɪzɪt/','noun',["A degree is a prerequisite for entry into this profession.","Algebra is typically a prerequisite for physics.","The prerequisite warm-up to the match was ignored."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('creep','vi.缓慢行进；爬行；悄悄地移动','/kɹiːp/','/kɹiːp/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deciduous','adj.落叶的；非永久的，短暂的','/dɪˈsɪdʒʊəs/','/dəˈsɪd.ju.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contradictory','adj.对立的，矛盾的；反驳的n.对立物；矛盾因素','/ˌkɑntɹəˈdɪktəɹi/','/ˌkɑntɹəˈdɪktəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perspicuous','adj.明白易懂的；明了的','/pəˈspɪkjuːəs/','/pəˈspɪkjuːəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blame','vt.谴责，责备n.过失，责备；责任','/bleɪm/','/bleɪm/','noun',["Blame came from all directions.","The blame for starting the fire lies with the arsonist.","They accepted the blame, but it was an accident."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confusion','n.困惑；混乱，混淆','/kənˈfjuːʒən/','/kənˈfjuːʒən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('platitude','n.陈词滥调，老生常谈','/ˈplatɪtjuːd/','/ˈplætɪt(j)ud/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('auditorium','n.礼堂；观众席','/ɔː.dɪˈtɔː.ɹɪ.əm/','/ɔː.dɪˈtɔː.ɹɪ.əm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('session','n.会议；开庭；开庭期；一节','/ˈsɛʃən/','/ˈsɛʃən/','noun',["\"Are we having a recording session?\" / \"Yes. We''ve even got some session musicians to provide some brass.\"","This court is now in session.","Logging out or shutting down the computer will end your session."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tactile','adj.触觉的；有触觉的；可感触的','/ˈtæktaɪl/','/ˈtæktaɪl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extrinsic','adj.外来的，外在的，非本质的','/ɛks.ˈtɹɪn.zɪk/','/ɛks.ˈtɹɪn.zɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bland','adj.平淡的，乏味的；清淡的；沉稳的','/blænd/','/blænd/','adjective',["a bland diet","The coffee was bland."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('microbe','n.微生物，细菌','/ˈmaɪkɹoʊb/','/ˈmaɪkɹoʊb/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reception','n.招待会；反响；接纳，接待；接收','/ɹɪˈsɛp.ʃn̩/','/ɹɪˈsɛp.ʃn̩/','noun',["The new system provides exceptional quality of the reception signal.","After the wedding we proceeded to the reception.","The ambassador''s jokes met a cold reception."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sole','adj.单独的；唯一的n.鞋底，脚底','/səʊl/','/soʊl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lumber','v.笨拙地移动；迫使担负n.木材，木料；杂物','/ˈlʌm.bə/','/ˈlʌm.bɚ/','noun',["I got lumbered with that boring woman all afternoon.","to lumber up a room"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sledding','n.进展','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solo','adv.独自，单独地adj.单独的；独唱的，独奏的n.独唱，独奏，独舞','/ˈsoʊ.loʊ/','/ˈsoʊ.loʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tuition','n.学费；教学，讲授','/ˈtjuːʃən/','/ˈtjuːʃən/','noun',["These rosemaling workshops are no place for anyone who wants to pester me or the students with the \"white privilege\" card, inter alia. Therefore, I reserve the right to refund the tuition of such men and women, kick them out the door, and bar them from at least two of my future events."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Fahrenheit','adj.华氏温度的n.华氏温度计','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tangible','adj.可触摸的，可感知的；明确的，确凿的；有形的，实际的','/ˈtæn(d)ʒɪb(ə)l/','/ˈtændʒəbəl/','noun',["Yes, but what are the tangibles?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('congest','v.充满，拥塞；充血','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('postage','n.邮资，邮费','/ˈpəʊstɪdʒ/','/ˈpəʊstɪdʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tame','adj.驯服的；沉闷的，乏味的vt.驯化；控制并利用','/teɪm/','/teɪm/','verb',["He tamed the wild horse.","to tame a rebellion","They have a tame wildcat."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cavern','n.大洞穴，大山洞','/ˈkæv.ən/','/ˈkæv.ən/','noun',["catacombs caverning the hillsides"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('material','adj.物质的，身体上的；重要的；实质性的，客观存在的n.材料，原料；素材，资料','/məˈtɪəɹɪəl/','/məˈtɪəɹɪəl/','noun',["Asphalt, composed of oil and sand, is a widely used material for roads.","We were a warm-up act at the time; we didn''t have enough original material to headline.","You''ll need about a yard of material to make this."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adjoin','v.贴近，紧挨，毗连','/əˈdʒɔɪn/','/əˈdʒɔɪn/','verb',["The living room and dining room adjoin each other."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hue','n.颜色；色度，色调；信仰，观点；形式，样子','/hjʉː/','/hju/','noun',["In digital arts, HSV color uses hue together with saturation and value."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('idiom','n.习惯用语；术语；风格，特色','/ˈɪdɪəm/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diplomat','n.外交官；有手腕的人','/ˈdɪ.plə.mæt/','/ˈdɪ.plə.mæt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('landmass','n.大片陆地','/ˈlænd.mæs/','/ˈlænd.mæs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('muscular','adj.肌肉的；肌肉发达的；强健的，强壮的','/ˈmʌs.kjə.lə/','/ˈmʌs.kjə.lə/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('staple','n.主要产品；原材料；主食；订书钉','/ˈsteɪ.pəl/','/ˈsteɪ.pəl/','noun',["Rice is a staple in the diet of many cultures.","to staple cotton","a staple town"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('memo','n.备忘录','/ˈmɛməʊ̯/','/ˈmɛməʊ̯/','noun',["I made sure to memo him about the client''s complaints."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('artifice','n.诡计，奸计；策略','/ˈɑː(ɹ)tɪfɪs/','/ˈɑː(ɹ)tɪfɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collaborate','v.协作，合作；勾结，通敌','/kəˈlabəɹeɪt/','/kəˈlabəɹeɪt/','verb',["Let''s collaborate on this project, and get it finished faster.","If you collaborate with the occupying forces, you will be shot."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collaborator','n.合作者，协作者；通敌者','/kəˈlæbəɹeɪtə/','/kəˈlæbəɹeɪtə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superficial','adj.肤浅的，浅薄的；表面的，外表的，外层的','/ˌs(j)uːpəˈfɪʃəl/','/ˌsupɚˈfɪʃəl/','noun',["He always concentrates on the superficials and fails to see the real issue."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('executive','adj.执行的，实施的；行政的n.执行者；管理人员；行政负责人','/ɛɡˈzɛkjʊtɪv/','','noun',["an executive officer","an executive bathroom"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hook','v.连接到无线电设备；勾住n.钩，吊钩；钩状物','/huːk/','/huːk/','noun',["He is not handling this job, so we''re giving him the hook.","The song''s hook snared me.","We''ve added hooks to allow undefined message types to be handled with custom code."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stadium','n.竞走场；运动场','/ˈsteɪ.di.əm/','/ˈsteɪ.di.əm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refrigerate','vt.冷冻，冷藏；使冷却，使变冷','/ɹɪˈfɹɪdʒəɹeɪt/','/ɹɪˈfɹɪdʒəɹeɪt/','verb',["Please refrigerate your uncooked meats at or below 40° Fahrenheit."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('casualty','n.伤亡事故；伤亡','/ˈkaʒ(ʊ)əlti/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spatial','adj.空间的','/ˈspeɪʃəl/','/ˈspeɪʃəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gauge','n.标准，规格；测量仪表，计量器vt.测量，度量','/ˈɡeɪdʒ/','/ˈɡeɪdʒ/','noun',["A vessel has the weather gauge of another when on the windward side of it, and the lee gauge when on the lee side of it."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('belt','n.地带，地区；腰带，皮带；带状物','/bɛlt/','/bɛlt/','noun',["As part of the act, the fat clown''s belt broke, causing his pants to fall down.","Keep your belt fastened; this is going to be quite a bumpy ride.","The motor had a single belt that snaked its way back and forth around a variety of wheels."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ridicule','vt.嘲笑，奚落n.嘲笑，奚落','/ˈɹɪdɪkjuːl/','/ˈɹɪdɪkjuːl/','noun',["His older sibling constantly ridiculed him with sarcastic remarks."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('protest','v.抗议，反对n.抗议，反对','/ˈpɹəʊ.tɛst/','/ˈpɹoʊ.tɛst/','noun',["They lodged a protest with the authorities.","We held a protest in front of City Hall.","How dare you, I protest!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vacant','adj.空的；闲置的；茫然的，空虚的','/ˈveɪkənt/','/ˈveɪkənt/','adjective',["a vacant stare"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hoof','n.蹄','/huːf/','/huːf/','noun',["Get your hooves off me!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appease','vt.平息；安抚，抚慰；绥靖','/əˈpiːz/','/əˈpiːz/','verb',["to appease the tumult of the ocean","They appeased the angry gods with burnt offerings."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reddish','adj.微红的','/ˈɹɛdɪʃ/','/ˈɹɛdɪʃ/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impede','vt.妨碍，阻碍，阻止','/ɪmˈpiːd/','/ɪmˈpiːd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acting','adj.代理的n.演戏，表演','/ˈæk.tɪŋ/','/ˈæk.tɪŋ/','verb',["If you don''t act soon, you will be in trouble.","I started acting at the age of eleven in my local theatre.","A dog which acts aggressively is likely to bite."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anatomy','n.解剖；解剖构造；剖析','/əˈnætəmi/','/əˈnætəmi/','noun',["Animal anatomy is also called zootomy; vegetable anatomy, phytotomy; and human anatomy, anthropotomy.","Burton''s famous treatise, \"The Anatomy of Melancholy\"","I went to the Venice beach body-building competition and noticed the competitor from Athens, and let me tell you, that''s what I call classic Greek anatomy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instantaneous','adj.瞬间的，即刻的，立即的','/ɪnstənˈteɪni.əs/','/ɪnstənˈteɪni.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quarterly','adv.按季度，一季一次adj.季度的，每季一次的n.季刊','','','noun',["quarterly rent payments","The arms of Hohenzollern is quarterly argent and sable."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notify','vt.通报','/ˈnoʊtɪfaɪ/','/ˈnoʊtɪfaɪ/','verb',["Once a decision has been reached and notified to the parties it becomes binding."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smirk','vi.假笑，得意地笑','/smɜːk/','/smɜːk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barbecue','v.在烤架上烧烤n.烧烤野餐；金属烤架','/ˈbɑːbɪˌkjuː/','/ˈbɑɹbɪˌkju/','noun',["We cooked our food on the barbecue.","We''re having a barbecue on Saturday, and you''re invited.","She ordered a plate of barbecue with a side of slaw."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abbey','n.修道院；大教堂','/ˈæb.i/','/ˈæb.i/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alienable','adj.可转让的','','','adjective',["Land is alienable according to the laws of the state."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('buoyant','adj.有浮力的，漂浮的；轻快的，快乐的；繁荣的；看涨的','/ˈbɔɪ.ənt/','/ˈbɔɪ.ənt/','adjective',["I’m in a buoyant mood."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intrepid','adj.勇敢的，无畏的','/ɪnˈtɹɛpɪd/','/ɪnˈtɹɛpɪd/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generalize','v.概括，归纳；推广','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accredit','vt.委任，授权；把…归于；正式认可','/ə.ˈkɹɛd.ɪt/','/ə.ˈkɹɛd.ɪt/','verb',["The school was an accredited college."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nourish','vt.滋养；养育','/ˈnʌɹ.ɪʃ/','/ˈnɝ.ɪʃ/','noun',["to nourish rebellion"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('faucet','n.龙头，旋塞','/ˈfɔːsɪt/','/ˈfɔsɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lengthen','v.延长，变长','/ˈlɛŋ(k)θən/','/ˈlɛŋ(k)θən/','verb',["The shadows on the lawn lengthened as the sun began to set."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unconsolidated','adj.松散的，疏松的','','','adjective',["unconsolidated backfill"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subdue','vt.制服，征服；抑制，克制','/səbˈdjuː/','/səbˈdjuː/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allege','vt.断言，宣称','/əˈlɛdʒ/','/əˈlɛdʒ/','verb',["The agency alleged my credit history had problems."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('segregate','vt.隔离，使分开','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maize','n.玉米','/meɪz/','/meɪz/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meticulous','adj.细心的，小心翼翼的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rental','adj.租用的；出租的n.租金额；租赁，出租','/ˈɹɛntəl/','/ˈɹɛntəl/','noun',["It''s just a rental, so I don''t need to take very good care of it."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prospect','v.勘探，勘察n.前景，前途；可能性；景象；期望','/ˈpɹɒspɛkt/','/ˈpɹɑspɛkt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radar','n.雷达','/ˈɹeɪdɑː(ɹ)/','/ˈɹeɪdɚ/','noun',["His sensitive radar for hidden alliances keeps him out of trouble."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('withhold','vt.拒绝给，不给；抑制；忍住','/wɪðˈhəʊld/','/wɪðˈhoʊld/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kinetic','adj.运动的，运动引起的；动力学的','/kɪˈnɛtɪk/','/kɪˈnɛtɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consonant','adj.和谐的，协调的，符合的n.辅音','/ˈkɒn.sə.nənt/','/ˈkɑn.sə.nənt/','noun',["The 19 unquestionable consonants in the English alphabet are B, C, D, F, G, H, J, K, L, M, N, P, Q, R, S, T, V, X, Z.","consonant tones; consonant chords"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engulf','vt.吞没','','','verb',["Desperation engulfed her after her daughter''s death.","Only Noah and his family survived when the Flood engulfed the world."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inheritance','n.遗产，继承物；继承；遗传','/ɪnˈhɛɹətəns/','/ɪnˈhɛɹətəns/','noun',["The Indo-European languages share various similarities as a result of their inheritance from a common ancestor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cassette','n.盒式录音带','/kæˈsɛt/','/kæˈsɛt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('receptive','adj.接受得快的；善于接受的，能接纳的','/ɹɪˈsɛptɪv/','/ɹɪˈsɛptɪv/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blade','n.刀刃，刀片；叶片；草叶；桨叶','/bleɪd/','/bleɪd/','noun',["Want to go blading with me later in the park?","The gang member got bladed in a fight."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foreshorten','vt.用透视法缩小；缩短，节略','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diverge','vi.分开，叉开；分歧；偏离','/daɪˈvɜːdʒ/','/daɪˈvɜːdʒ/','verb',["Both stories start out the same way, but they diverge halfway through.","The sidewalk runs next to the street for a few miles, then diverges from it and turns north.","The software is pretty good, except for a few cases where its behavior diverges from user expectations."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emblem','n.徽章；标记，象征','/ˈɛmbləm/','/ˈɛmbləm/','noun',["The rampant poverty in the ethnic slums was just an emblem of the group''s disenfranchisement by the society as a whole."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confiscate','vt.没收，充公，征用','','','verb',["In schools it is common for teachers to confiscate electronic games and other distractions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('filial','adj.子女的；子孙后代的','/ˈfɪl.i.əl/','/ˈfi.li.əl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barge','v.冲撞，乱闯n.驳船','/bɑːdʒ/','/bɑːdʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meteorology','n.气象学','/ˌmiːtɪəˈɹɒlədʒi/','/ˌmiːtɪəˈɹɒlədʒi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('occur','vi.发生，出现；存在于','/əˈkɜː/','/əˈkɝ/','verb',["The liftoff will occur in exactly twelve seconds.","I will write if the opportunity occurs.","The chemical monofluoroacetate occurs in all parts of Dichapetalum cymosum, and is responsible for its toxic effects."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scuba','n.水中呼吸器，水肺','/ˈskuːbə/','/ˈskuːbə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('definitive','adj.确定的，最后的，决定性的；','/dɪˈfɪn.ɪt.ɪv/','/dɪˈfɪn.ɪt.ɪv/','noun',["a definitive word"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breeze','vi.飘然移动n.微风，和风','/bɹiːz/','/bɹiːz/','noun',["The breeze rustled the papers on her desk.","After studying Latin, Spanish was a breeze.","The discovery produced a breeze."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trash','n.无价值之物，废物；拙劣的文学作品；没用的人vt.捣毁，破坏','/tɹæʃ/','/tɹæʃ/','noun',["I am Harry Potter trash.","The burglars trashed the house.","to trash the rattoons of sugar cane"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horn','n.角；号角，喇叭','/hɔːn/','/hɔɹn/','noun',["an umbrella with a handle made of horn","hunting horn","The shot was after the horn and therefore did not count."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('troupe','n.剧团；马戏团；芭蕾舞团','/tɹuːp/','/tɹuːp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transit','n.运输，运送；中转；转变；交通运输系统','/ˈtɹæn.sɪt/','/ˈtɹæn.sɪt/','noun',["the transit of goods through a country","Beufort road, Birkenhead, about 17.15 June 19 2013, white transit overtakes and swerves left into junction almost taking my front wheel.","I always take the transit to work."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sore','adj.疼痛的；恼火的n.疮口，痛处','/sɔː/','/sɔɹ/','noun',["They put ointment and a bandage on the sore.","Her feet were sore from walking so far.","The school was in sore need of textbooks, theirs having been ruined in the flood."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curtail','vt.缩短，缩减，削减','/kɜːˈteɪl/','/kɚˈteɪl/','noun',["Curtailing horses procured long horse-hair.","When the audience grew restless, the speaker curtailed her speech."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glow','vi.发光；发红，发热；洋溢n.暗淡的光；容光焕发；喜悦','/ɡləʊ/','/ɡloʊ/','noun',["He had a bright red glow on his face.","The fire was still glowing after ten hours.","The zealots glowed with religious fervor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sheath','n.鞘，外壳；套；护皮；紧身连衣裙','/ʃiːθ/','/ʃiθ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pollen','n.花粉','/ˈpɒlən/','/ˈpɑlən/','noun',["\"...and ther was good wyne of Gascoyne,... as well of pollen, as of other vitailes...\" Froissart, Jean, 1338?-1410?; Berners, John Bourchier, Lord https//archive.org/details/chroniclefroiss00froigoog"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remodel','vt.重新塑造，改造；改编；改变','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('groove','n.沟；槽；唱片上的纹路','/ɡɹuːv/','/ɡɹuːv/','noun',["I was just starting to groove to the band when we had to leave."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('certificate','n.证书，证明书；文凭，结业证书','','','noun',["The film is certificate 15."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quantum','n.量子','[ˈkwɑɾ̃əm]','/ˈkwɑntəm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('racket','n.球拍；喧嚷，吵闹；勒索，诈骗','/ˈɹækɪt/','/ˈɹækɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mess','n.肮脏，杂乱；混乱，困境vt.弄脏，弄乱；搞糟','/mɛs/','/mɛs/','noun',["He made a mess of it.","My boss dumped a whole mess of projects on my desk today.","Parked under a tree, my car was soon covered in birds'' mess."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sour','v.变酸；变馊；变坏，恶化adj.酸的；馊的；乖戾的，尖酸刻薄的；酸痛的','/ˈsaʊə/','/ˈsaʊ(ə)ɹ/','noun',["Too much lemon juice will sour the recipe.","We broke up after our relationship soured.","Lemons have a sour taste."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('magnitude','n.巨大；重要性；星等，星球的亮度','/ˈmæɡnɪtjuːd/','/ˈmæɡnɪtjuːd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('genuine','adj.真的，非人造的；真诚的，诚实的','/ˈdʒɛnjuːˌaɪn/','/ˈdʒɛnjuːˌaɪn/','adjective',["a genuine text;  a genuine production;  genuine materials; genuine friendship"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agitate','v.鼓动，煽动；激怒，使激动，使不安；搅动','/ˈæ.dʒɪ.teɪt/','/ˈæ.dʒɪ.teɪt/','verb',["He was greatly agitated by the news.","the wind agitates the sea","politicians agitate desperate designs"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('microwave','n.微波；微波炉','/ˈmaɪkɹəʊˌweɪv/','/ˈmaɪkɹəʊˌweɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gorilla','n.大猩猩','/ɡəˈɹɪl.ə/','/ɡəˈɹɪl.ə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brochure','n.小册子，说明书','/ˈbɹəʊ.ʃə(ɹ)/','/bɹoʊˈʃɝ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('downside','n.缺点，负面；底侧；下降趋势','/ˈdaʊnˌsaɪd/','/ˈdaʊnˌsaɪd/','noun',["The downside of obtaining a higher rank is that far more work is expected."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equation','n.等式，方程式；等同，相等；均衡','/ɪˈkweɪʃən/','/ɪˈkweɪʃən/','noun',["We need to bring the balance of power into equation"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prospector','n.勘探者，采矿者','/pɹəˈspɛktə/','/pɹəˈspɛktə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discredit','vt.使丧失声誉；使怀疑n.名誉丧失','','','noun',["Later accounts have brought the story into discredit.","The candidate tried to discredit his opponent."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spawn','v.产卵；产生，促成n.卵','/ˈspɔːn/','/ˈspɔːn/','verb',["The Web server spawns a new process to handle each client''s request."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sensory','adj.感觉的，感官的','/ˈsɛnsəɹi/','/ˈsɛnsəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suburb','n.市郊，郊区','/ˈsʌbɜːb/','/ˈsʌbɜːb/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('taut','adj.绷紧的；肌肉结实的；结构严谨的，紧凑的','/tɔːt/','/tɔt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lubricant','n.润滑剂','/ˈljuːbɹɪkənt/','/ˈlubɹəkənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glue','vt.胶合，黏合；紧附于n.胶，胶水','/ɡluː/','/ɡluː/','noun',["I need to glue the chair-leg back into place.","His eyes were glued to the screen."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('orbital','adj.轨道的','','','noun',["The M25 is an orbital motorway around London."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solder','vt.焊接n.焊料，焊锡','/ˈsɒldə(ɹ)/','/ˈsɑdɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('envelop','vt.包围','/ɛnˈvɛləp/','/ɛnˈvɛləp/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adventitious','adj.偶然的，偶发的','/ˌæd.vənˈtɪʃ.əs/','/ˌæd.vənˈtɪʃ.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ongoing','adj.正在进行的；不间断的；继续存在的n.前进，发展','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outfit','n.全套装备；全套服装','/ˈaʊtfɪt/','/ˈaʊtfɪt/','noun',["She wore a fashionable outfit with matching purse and shoes.","Should we buy it here, or do you think the outfit across town will have a better deal?","The expedition was outfitted with proper clothing, food, and other necessities."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ignorant','adj.无知的，愚昧的；无知觉的','/ˈɪɡnəɹənt/','/ˈɪɡnəɹənt/','noun',["His manner was at best off-hand, at worst totally ignorant."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extort','vt.勒索，敲诈，强夺','/ɪkˈstɔː(ɹ)t/','/ɪkˈstɔː(ɹ)t/','verb',["to extort a promise"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trample','v.踩碎；践踏，摧残','/ˈtɹæmpəl/','/ˈtɹæmpəl/','noun',["to trample grass or flowers"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negligible','adj.可以忽略的，微不足道的；无关紧要的','/ˈnɛɡlɪdʒɪbəl/','/ˈnɛɡlɪdʒɪbəl/','adjective',["We found errors, but their effects were negligible."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('setback','n.挫折，阻碍；倒退','/ˈsɛtbæk/','/ˈsɛtbæk/','noun',["After some initial setbacks, the expedition went safely on its way.","Setbacks were initially used for structural reasons, but now are often mandated by land use codes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('primordial','adj.原始的，最初的；基本的','/pɹaɪˈmɔː.di.əl/','/pɹaɪˈmɔɹ.di.əl/','noun',["a primordial leaf; a primordial cell"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('husbandry','n.耕种，务农，农牧业','/ˈhʌzb(ə)ndɹi/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('haircut','n.理发','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pointed','adj.尖的，尖角的；尖锐的，尖刻的','/ˈpɔɪntɪd/','/ˈpɔɪntɪd/','verb',["It''s rude to point at other people.","The arrow of a compass points north","to point a gun at a wolf, or a cannon at a fort"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enthusiastic','adj.热情的，热心的','/ɪnˌθjuːzɪˈæstɪk/','/ɪnˌθjuːzɪˈæstɪk/','adjective',["an enthusiastic lover of art"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elongate','v.延长，伸长','/ɪ.ˈlɔŋ.ˌɡeɪt/','/ɪ.ˈlɔŋ.ˌɡeɪt/','verb',["Painted turtles lay oval, elongate eggs."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fray','vi.磨损，磨破；烦躁，恼火n.争斗','/fɹeɪ/','/fɹeɪ/','verb',["The ribbon frayed at the cut end.","The hectic day ended in frayed nerves. (Metaphorical use; nerves are visualised as strings)"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wield','vt.支配，掌权，行使','/wiːld/','/wiːld/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disastrous','adj.灾难性的','/dɪˈzɑːstɹəs/','/dɪˈzɑːstɹəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crystallize','v.结晶；明确','/ˈkɹɪstəlaɪz/','/ˈkɹɪstəlaɪz/','verb',["I crystallized the copper sulphate by slowly cooling a saturated solution.","The copper sulphate crystallized from solution.","After some thought, I crystallized my ideas for the paper."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subspecies','n.亚种','/-siːz/','/-siːz/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shower','v.淋浴；下阵雨；洒落，纷纷降落；抛撒n.阵雨，暴雨；淋浴；一阵，一大批','/ˈʃaʊ.ə(ɹ)/','/ˈʃaʊ.ə(ɹ)/','noun',["Today there will be frequent showers and some sunny spells.","I′m going to have a shower.","a shower of sparks;  a meteor shower;  a Gatorade shower"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('infectious','adj.传染性的，传染病的；有感染力的','','','adjective',["Cancer is not infectious.","Despite feeling better, the patient is still infectious.","Her enthusiasm for work can be really infectious."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concur','v.同时发生；意见一致','/kənˈkɜː/','/kənˈkɜː/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insulin','n.胰岛素','/ˈɪnsjʊlin/','/ˈɪnsjʊlin/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ironic','adj.说反话的，讽刺的；出乎意料的','/aɪˈɹɒn.ɪk/','/aɪˈɹɒn.ɪk/','adjective',["It''s ironic to have a blizzard in the middle of the summer.","It''s ironic that we are eating a sandwich in Sandwich, Massachusetts."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hieratic','adj.僧侣的；','/ˌhaɪ(ə)ˈɹætɪk/','/ˌhaɪ(ə)ˈɹætɪk/','noun',["Some of the more hieratic sculptures leave the viewer curiously unmoved."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entitle','vt.使…有权；给题名','/ənˈtaɪtəl/','/ənˈtaɪtəl/','verb',["A passport entitles the bearer to travel to other countries."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monotony','n.单调，千篇一律','/məˈnɒtəni/','/məˈnɑtəni/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('counselor','n.顾问；律师','/ˈkaʊnsələ(ɹ)/','/ˈkaʊnsələ(ɹ)/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overdue','adj.过期未付的，逾期的；过度的，过火的；迟到的，延误的','/ˌəʊ.vəˈdju/','/ˌoʊ.vəɹˈdu/','adjective',["his library books were three days overdue;  my car is overdue for an oil change;  she finally left on a long overdue vacation"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nominal','adj.名义上的；微不足道的','/ˈnɑm.ɪnl̩/','/ˈnɑm.ɪnl̩/','noun',["This sentence contains two nominals.","Numeric codes of characters used in programming are nominals.","a nominal difference"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intervening','adj.介于中间的，发生于期间的','','','verb',["The police had to be called to intervene in the fight.","An instant intervened between the flash and the report.","Nothing intervened to prevent the undertaking."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clump','v.聚集，成群；以沉重的脚步行走n.丛，簇，束；块，团；群，组','/klʌmp/','/klʌmp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thorough','adj.彻底的；详尽的；一丝不苟的','/ˈθʌɹə/','/ˈθɜɹoʊ/','noun',["He is the most thorough worker I have ever seen."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('democracy','n.民主政体，民主制度；民主国家；民主精神','/dɪˈmɒkɹəsi/','/dɪˈmɒkɹəsi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('congratulation','n.祝贺，道喜','/kənˌɡɹætjʊˈleɪʃ(ə)n/','/kənˌɡɹætjʊˈleɪʃ(ə)n/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extol','vt.赞美，颂扬','/ɪkˈstəʊl/','/ɪkˈstəʊl/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adverse','adj.负面的；不利的；逆的','/ədˈvɜ(ɹ)s/','/ədˈvɜ(ɹ)s/','adjective',["adverse criticism","adverse circumstances","the adverse page"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bulletin','n.新闻简报；公告，布告；简报','/ˈbʊlətɪn/','/ˈbʊlətɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('junction','n.交叉点，汇合处；连接，接合','/ˈdʒʌŋkʃən/','/ˈdʒʌŋkʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electrolysis','n.电解作用；电解术','/ɪlɛkˈtɹɒləsɪs/','/ɪlɛkˈtɹɒləsɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bandanna','n.色彩鲜艳的围巾','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gourmet','adj.美味的n.美食家','/ˈɡɔːmeɪ/','/ˈɡɔːmeɪ/','noun',["The restaurant offered gourmet coffee and cigars after the meal."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reputation','n.名声，声望，名誉','/ˌɹɛpjʊˈteɪʃən/','/ˌɹɛpjʊˈteɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spike','n.长钉，大钉；猛增，急升','/spaɪk/','/spaɪk/','noun',["The trap was lined with spikes.","oil of spike","to spike down planks"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('genesis','n.起源，开端','/ˈd͡ʒɛn.ə.sɪs/','/ˈd͡ʒɛn.ə.sɪs/','noun',["Some point to the creation of Magna Carta as the genesis of English common law."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subliminal','adj.下意识的，潜意识的','/səˈblɪmɪnəl/','/səˈblɪmɪnəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tavern','n.小旅馆，客栈；小酒店','/ˈtævən/','/ˈtævən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glimmer','vi.发微光；隐约出现n.闪烁的微光；隐约的迹象；一丝，一线','/ˈɡlɪmə(ɹ)/','/ˈɡlɪmɚ/','noun',["The glimmer of the fireflies was pleasant to watch.","A glimmer of hope.","The fireflies glimmered in the dark."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awkward','adj.别扭的；笨拙的；难处理的，棘手的；难操纵的','/ˈɑkwɚd/','/ˈɔkwɚd/','noun',["John was awkward at performing the trick. He''ll have to practice to improve.","An awkward silence had fallen.","I''m very awkward at parties."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adhesive','adj.带黏性的n.胶合剂','/ædˈhi.sɪv/','/ædˈhi.sɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ruin','vt.破坏，毁灭；使破产n.毁灭，毁坏；','/ˈɹuː.ɪn/','/ˈɹuː.ɪn/','noun',["The monastery has fallen into ruin.","Gambling has been the ruin of many.","the ruin of a ship or an army;  the ruin of a constitution or a government;  the ruin of health or hopes"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spill','v.溢出，溅出；蜂拥而出n.溢出，泄漏','/spɪl/','/spɪl/','noun',["The bruise is from a bad spill he had last week.","I spilled some sticky juice on the kitchen floor.","Some sticky juice spilled onto the kitchen floor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('celebrate','v.赞美；庆祝','/ˈsɛl.ə.bɹeɪt/','/ˈsɛl.ə.bɹeɪt/','verb',["to celebrate the name of the Most High","to celebrate a birthday","I was promoted today at work—let’s celebrate!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cradle','n.摇篮；发源地','/ˈkɹeɪdəl/','/ˈkɹeɪdəl/','noun',["a cradle of crime","from the cradle to the grave","The cradle was ill-made. One victim fell into the sea and was lost and the ensuing delay cost three more lives."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abut','v.邻接，毗邻','/əˈbʌt/','/əˈbʌt/','verb',["His land abuts on the road."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('folkway','n.社会风俗','/ˈfəʊkweɪ/','/ˈfəʊkweɪ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mountainous','adj.多山的；巨大的','/ˈmaʊntɪnəs/','/ˈmaʊntɪnəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inspect','vt.检查，视察','/ɪnˈspɛkt/','/ɪnˈspɛkt/','verb',["Inspect the system for leaks.","The general inspected the troops and their barracks."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('campaign','vi.竞选；参加战斗n.竞选活动；活动；战役','/kæmˈpeɪn/','/kæmˈpeɪn/','noun',["The company is targeting children in their latest advertising campaign.","She campaigned for better social security."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lawsuit','n.诉讼','/ˈlɔˌs(j)ut/','/ˈlɔˌs(j)ut/','noun',["The lawyer advised his client against filing a lawsuit as it would take a lot of time and money to resolve."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sequential','adj.序列的；连续的；随之而来的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('derivative','adj.派生的，引出的；无创意的n.派生词，衍生词；派生物','/dɪˈɹɪvətɪv/','','noun',["a derivative conveyance; a derivative word"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amateur','adj.业余爱好的；业余的n.业余爱好者；外行','/ˈæ.mə.tə/','/ˈæ.mə.tɚ/','noun',["The contest is only open to amateurs.","The entire thing was built by some amateurs with screwdrivers and plywood.","amateur sports"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rodeo','n.牛仔竞技表演','/ɹoʊ.ˈdeɪ.oʊ/','/ɹoʊ.ˈdeɪ.oʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assistance','n.帮助，援助','/əˈsɪs.təns/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('canvass','v.游说，拉选票；细查','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('causal','adj.原因的，因果关系的','/ˈkɔːz.əl/','/ˈkɔːz.əl/','noun',["There is no causal relationship between eating carrots and seeing in the dark."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tectonics','n.构造地质学','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mansion','n.公寓，府邸；大厦','/ˈmæn(t)ʃən/','/ˈmæn(t)ʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('summary','adj.概括的，概要的；即刻的，立即的n.摘要，概要','/ˈsʌməɹi/','/ˈsʌməɹi/','noun',["A summary review is in the appendix.","They used summary executions to break the resistance of the people.","Summary justice is bad justice."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('illusory','adj.虚幻的，幻觉的','/ɪˈluːs(ə)ɹi/','/ɪˈluːs(ə)ɹi/','adjective',["Enron''s profits were all illusory."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nickel','n.镍；五分镍币','/ˈnɪk.əl/','/ˈnɪk.əl/','noun',[]);
