INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inferior','adj.劣等的，较差的；次要的；级别低的n.下级，下属，晚辈','/ɪnˈfɪəɹɪə/','/ɪnˈfɪ(ə)ɹiɚ/','noun',["As you are my inferior, I can tell you to do anything I want.","Anna had always felt inferior to her brother due to poor school grades.","an inferior officer"]);
