INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vaporize','v.蒸发，汽化','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transcend','vt.超越','/tɹæn(t)ˈsɛnd/','/tɹæn(t)ˈsɛnd/','verb',["lights in the heavens transcending the region of the clouds"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spiny','adj.长满刺的，多刺的，带刺的；棘手的','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chronological','adj.按年代顺序排列的，年代学的','/ˌkɹɒnəˈlɒd͡ʒɪkəl/','/ˌkɹɒnəˈlɒd͡ʒɪkəl/','adjective',["He is 67 in chronological age, but has the mind and body of someone 55."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humanitarian','adj.人道主义的，慈善的n.人道主义者，博爱者，慈善家','/hjʊˌmæ.nɪˈtɛː.ɹɪ.ən/','/hjuˌmæ.nəˈtɛ.ɹi.ən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surcharge','n.额外费用，增收费，附加费vt.收取额外费用','/ˈsɜː(ɹ)t͡ʃɑː(ɹ)d͡ʒ/','/ˈsɜː(ɹ)t͡ʃɑː(ɹ)d͡ʒ/','noun',["Our airline tickets cost twenty dollars more than we expected because we had to pay a fuel surcharge.","to surcharge an animal or a ship; to surcharge a cannon"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sturdy','adj.健壮的，结实的；稳固的；顽强的','/ˈstɜːdi/','/ˈstɜrdi/','noun',["a sturdy oak tree","It was a sturdy building, able to withstand strong winds and cold weather.","a man of sturdy piety or patriotism"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fable','n.寓言；谎言','/ˈfeɪbəl/','/ˈfeɪbəl/','noun',[]);
