INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instill','vt.慢慢灌输；逐渐培养','/ɪnˈstɪl/','/ɪnˈstɪl/','verb',["It is important to instill discipline in a child at an early age."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('palatable','adj.美味的，可口的；合意的，认可的','/ˈpæl.ə.tə.bəl/','/ˈpæl.ə.tə.bəl/','adjective',["For some instant noodles make a palatable, if not especially nutritious, meal.","The agreement was palatable to both of them."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compatible','adj.协调的，一致的；兼容的；能和睦相处的','/kəmˈpætəbəl/','/kəmˈpætəbəl/','noun',["a computer company that sells IBM compatibles","This printer isn''t compatible with my computer.","My neighbours and I are not very compatible: they''re loud and I''m an introvert."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tenement','n.廉租公寓','/ˈtɛnɪmənt/','/ˈtɛnɪmənt/','noun',["The island of Brecqhou is a tenement of Sark."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('photosynthesis','n.光合作用','/ˌfəʊ.təʊ.ˈsɪn.θə.sɪs/','/ˌfəʊ.təʊ.ˈsɪn.θə.sɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sidebar','n.补充报道','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crest','v.达到顶点n.顶峰，顶点；浪尖；羽冠','/kɹɛst/','/kɹɛst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deplore','vt.悲叹，哀叹，公开谴责','/dɪˈplɔː/','/dɪˈplɔː/','verb',["I deplore my neighbour for having lost his job.","I deplore how you treated him at the party."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grimly','adv.冷酷地；严肃地；坚定地','/ˈɡɹɪmli/','/ˈɡɹɪmli/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cherish','vt.爱护，珍爱；怀有，抱有','/ˈtʃɛɹɪʃ/','/ˈtʃɛɹɪʃ/','verb',["I cherish your friendship."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outlive','vt.比…长命，比…耐久','/aʊtˈlɪv/','/aʊtˈlɪv/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patronize','v.以高人一等的态度对待；光顾；赞助，资助','/ˈpeɪt(ʃ)ɹənaɪz/','/ˈpeɪt(ʃ)ɹənaɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eminent','adj.显著的，杰出的','/ˈɛmɪnənt/','/ˈɛmɪnənt/','adjective',["His eminent good sense has been a godsend to this project.","In later years, the professor became known as an eminent historian."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('underneath','adv.在下面prep.在…下面','/ʌndəˈniθ/','/ʌndɚˈnið/','noun',["The underneath of the aircraft was painted blue.","You can have the underneath bunk.","Underneath the water, all was calm."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prolong','vt.拉长，延长','/pɹoʊˈlɑŋ/','/pɹoʊˈlɑŋ/','verb',["The government shouldn''t prolong deciding on this issue any further."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refund','n.偿还额；退款vt.退还，偿付','','','noun',["If the camera is faulty, you can return it to the store where you bought it for a full refund.","If you find this computer for sale anywhere at a lower price, we''ll refund you the difference.","to refund a railroad loan"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distress','n.痛苦，忧伤；贫困，窘迫；遇难vt.使痛苦，使悲伤，使忧虑','/dɪˈstɹɛs/','/dɪˈstɹɛs/','noun',["She distressed the new media cabinet so that it fit with the other furniture in the room."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remnant','n.残余物；布头；遗迹','/ˈɹɛmnənt/','/ˈɹɛmnənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compressible','adj.可压缩的','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steep','adj.陡的，陡峭的；急剧的；过高的v.浸泡；沉浸','/stiːp/','/stiːp/','noun',["a steep hill or mountain; a steep roof; a steep ascent; a steep barometric gradient","Twenty quid for a shave? That''s a bit steep.","The steep rake of the windshield enhances the fast lines of the exterior. http//legacy.sandiegouniontribune.com/uniontrib/20070303/news_lz1dd3maynard.html"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immunity','n.免疫力；保护；免除，豁免','/ɪˈmjuːnəti/','/ɪˈmjuːnəti/','noun',["Superbugs are bacteria that develop an immunity to antibiotics."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('privilege','vt.给予特权，特别优待n.特权，特殊待遇；特殊利益，优惠；荣耀，荣幸','/ˈpɹɪv(ɪ)lɪdʒ/','/ˈpɹɪv(ɪ)lɪdʒ/','noun',["All first-year professors here must teach four courses a term, yet you''re only teaching one! What entitled you to such a privilege?","Your honor, my client is not required to answer that; her response is protected by attorney-client privilege.","to privilege representatives from arrest"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shroud','vt.隐藏，遮蔽n.裹尸布，寿衣；遮蔽物','/ʃɹaʊd/','/ʃɹaʊd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('criss-cross','v.构成十字形图案；交叉往来adj.纵横交错的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choppy','adj.波浪起伏的，不平静的；不连贯的，支离破碎的','/ˈtʃɒ.pi/','/ˈtʃɒ.pi/','adjective',["The sound is choppy in this video."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blaze','vi.燃烧，着火；发光，放光彩；怒视n.火焰；光辉，强烈的光；迸发','/bleɪz/','/bleɪz/','noun',["to seek shelter from the blaze of the sun","The palomino had a white blaze on its face."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bountiful','adj.慷慨的；大量的，充足的','/ˈbaʊntɪfʌl/','[ˈbaʊ̯n(ɾ)əfəɫ]','adjective',["They enjoyed a wet summer and a bountiful harvest."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meager','adj.不足的，贫乏的；消瘦的','/ˈmiːɡə/','/ˈmiːɡə/','verb',["A meager piece of cake in one bite."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violate','vt.违反，违背；亵渎；侵犯，干扰','/ˈvaɪəˌleɪt/','/ˈvaɪəˌleɪt/','verb',["Accessing unauthorized files violates security protocol."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('methanol','n.甲醇','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steer','v.驾驶，为…操舵；引导n.食用公牛','/stɪə(ɹ)/','/stɪə(ɹ)/','noun',["I steered homeward.","I find it very difficult to steer a skateboard.","The boat steers easily."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('buddy','n.密友；搭档，伙伴','/bʌd.i/','/bʌd.i/','noun',["They have been buddies since they were in school.","drinking buddies","Hey, buddy, I think you dropped this."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outlying','adj.边远的，偏僻的；无关的，题外的','','','noun',["The more outlying villages were never visited by their member of parliament.","When the map was redrawn after the war, our cousin found herself living in outlying territory."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delineate','vt.描绘，描述；解释','/dɪˈlɪniːeɪt/','/dɪˈlɪniːeɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coupon','n.礼券，优惠券；配给券，票证','/ˈkuːˌpɒn/','/ˈkjuːˌpɑn/','noun',["Jenna coupons and she goes through three magazines a day to find the coupons."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('multitude','n.大量，众多；群众，民众；人群','/ˈmʌltɪtjuːd/','/ˈməl-/','noun',["Pilate, wishing to please the multitude, released Barabbas to them."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('innate','adj.天生的，固有的；内在的，直觉的','/ɪˈneɪt/','/ɪˈneɪt/','verb',["innate ideas","an innate anther"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('siege','n.包围，围困；封锁','/siːdʒ/','/siːdʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gratify','vt.使满意，使高兴；满足','/ˈɡrætɪfaɪ/','/ˈɡrætɪfaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fascinating','adj.迷人的，醉人的','/ˈfæsɪˌneɪtɪŋ/','/ˈfæsɪˌneɪtɪŋ/','verb',["The flickering TV fascinated the cat.","We were fascinated by the potter''s skill.","Her gait fascinates all men."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agenda','n.议程，议程表','/əˈdʒɛn.də/','/əˈdʒɛn.də/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quasar','n.类星体','/ˈkweɪ.zɑː/','/ˈkweɪ.zɑɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anonymous','adj.匿名的，不具名的；无特色的，无个性特征的','/əˈnɒnəməs/','/əˈnɒnəməs/','adjective',["an anonymous pamphlet","No customer personal data will be retained unless it is rendered anonymous.","an anonymous office block in a soulless industrial estate"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fake','v.伪造；伪装','/feɪk/','/feɪk/','noun',["to fake a marriage","Which fur coat looks fake?"]);
