INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('girder','n.主梁，大梁','/ɡɜː(ɹ)də(ɹ)/','/ɡɜː(ɹ)də(ɹ)/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bizarre','adj.奇形怪状的，古怪可笑的，怪诞的','/bəˈzɑː(ɹ)/','/bəˈzɑɹ/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astronomical','adj.天文学的；极大的，庞大的','/ˌæs.tɹəˈnɒm.ɪk.əl/','/ˌæstɹəˈnɑːmɪkəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ascribe','vt.把…归于；归咎于','/əˈskɹaɪb/','/əˈskɹaɪb/','verb',["One may ascribe these problems to the federal government; however, at this stage it is unclear what caused them.","It is arguable as to whether we can truly ascribe this play to Shakespeare."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minority','n.少数；少数民族','/maɪˈnɒɹ.ɪ.ti/','/maɪˈnɑɹ.ɪ.ti/','noun',["Most people agreed, but a sizable minority were upset by the decision.","The company claims it has hired several minorities since the complaint was lodged.","They hold a minority interest in the company."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allure','n&v.诱惑，吸引','/əˈl(j)ʊɚ/','/əˈl(j)ʊɚ/','noun',[]);
