INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exponent','n.解释者；倡导者，拥护者；指数，幂','/ɛkˈspəʊnənt/','/ɛkˈspəʊnənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accordion','n.手风琴','/əˈkɔ(ɹ).di.ˌən/','/ə.ˈkɔɹ.di.ən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incongruity','n.不一致，不和谐','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solicit','v.恳请；乞求；征求；勾引；招揽','/səˈlɪsɪt/','/səˈlɪsɪt/','noun',["to solicit alms, or a favour","If you want to lose your virginity, you should try to solicit some fine looking women.","My girlfriend tried to solicit me for sex, but I was tired."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rhyme','v.押韵；和…同韵n.押韵；同韵词，押韵词','/ɹaɪm/','/ɹaɪm/','noun',["Many editors say they don''t want stories written in rhyme.","Tennyson’s rhymes","Norse poetry is littered with rhymes like \"sól ... sunnan\"."]);
