INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disciple','n.门徒，弟子，追随者','/dɪˈsaɪpl̩/','/dɪˈsaɪpl̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arthritis','n.关节炎','/ɑː(ɹ)θˈɹaɪtɪs/','/ɑː(ɹ)θˈɹaɪtɪs/','noun',[]);
