INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('squid','n.鱿鱼，枪乌贼','/skwɪd/','/skwɪd/','noun',["Can you lend me five squid? I feel like a bacon sarnie."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slogan','n.标语，口号；广告语','/ˈsləʊ.ɡ(ə)n/','/ˈsloʊ.ɡən/','noun',[]);
