INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('powder','n.粉，粉末；散剂；火药，炸药','/ˈpaʊ.də(ɹ)/','','noun',["to powder one''s hair","Expert skiers love skiing on powder snow."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bestow','vt.赠与，授予，献给','/bɪˈstəʊ/','/bɪˈstəʊ/','verb',["Medals were bestowed on the winning team."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aggregate','n.聚集物；总计vt.聚集；总计','','','noun',["The aggregated soil.","There are ten loads, aggregating five hundred bushels.","aggregate glands"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('differential','adj.差别的，有区别的；微分的n.差别，差异；微分','[dɪfəˈɹənʃəɫ]','[dɪfəˈɹənʃəɫ]','noun',["differential characteristics"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forsake','vt.遗弃，放弃，抛弃','/fɔɹˈseɪk/','/fɔɹˈseɪk/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rust','v.生锈n.锈，铁锈；锈病','/ɹʌst/','/ɹʌst/','noun',["The rust on my bicycle chain made cycling to work very dangerous.","aerugo. Green or blue-green copper rust; verdigris. (American Heritage Dictionary, 1973)"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stylized','adj.非写实的；程式化的','/ˈstaɪ.ə.laɪzd/','/ˈstaɪ.ə.laɪzd/','verb',["The symbol for the planet Mars is a stylized representation of the shield and spear of the god Mars."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('array','n.一系列；阵列vt.布置，排列；部署','/əˈɹeɪ/','/əˈɹeɪ/','noun',["drawn up in battle array","We offer a dazzling array of choices.","He was arrayed in his finest robes and jewels."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terrorism','n.恐怖主义','/ˈtɛɹəɹɪzəm/','/ˈtɛɹəɹɪzəm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nominee','n.被提名者，被任命者','/ˌnɒmɪˈniː/','/ˌnɒmɪˈniː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discriminate','v.区别；歧视','/dɪsˈkɹɪmɪneɪt/','/dɪsˈkɹɪmɪneɪt/','verb',["The law prohibits discriminating against people based on their skin color."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('camouflage','n&vt.掩饰，伪装','/ˈkæ.məˌflɑːʒ/','/ˈkæ.məˌflɑːʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('annex','vt.兼并；附加','/ˈænɛks/','/əˈnɛks/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enslave','vt.奴役','/ɪnˈsleɪv/','/ɪnˈsleɪv/','verb',["The migrants will be enslaved once they''re no longer useful to the oligarchs; make no mistake about that."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('centennial','n.百年纪念','/sɛnˈtɛnɪəl/','/sɛnˈtɛnɪəl/','noun',["a centennial ode","a centennial jubilee; a centennial celebration"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monetary','adj.金钱的，货币的','/ˈmʌnɪtəɹi/','/ˈmɑnɪteɹi/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('demolish','vt.拆除；破坏；驳倒，推翻','/dəˈmɒl.ɪʃ/','','verb',["They demolished the old mill and put up four townhouses."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shellfish','n.贝类，有壳的水生动物','/ˈʃɛlˌfɪʃ/','/ˈʃɛlˌfɪʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trade','v.交易，买卖；互相交换n.贸易，商业；交易；职业，行业','/tɹeɪd/','/tɹeɪd/','noun',["I did no trades with them once the rumors started.","The skilled trades were the first to organize modern labor unions.","It is not a retail showroom. It is only for the trade."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gush','v.滔滔不绝地说；喷涌n.喷出，涌出；迸发，发作','/ˈɡʌʃ/','/ˈɡʌʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('derivation','n.起源，发源；派生','/ˌdɛ.ɹɪˈveɪ.ʃ(ə)n/','/ˌdɛ.ɹɪˈveɪ.ʃ(ə)n/','noun',["the derivation of a word from an Indo-European root"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spew','v.喷涌；射出；呕吐，呕出n.喷出物','/spjuː/','/spjuː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comic','adj.可笑的，滑稽的；喜剧的n.喜剧演员','/ˈkɒmɪk/','/ˈkɑmɪk/','noun',["a comic stereotype"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('normally','adv.通常地；正常地','','','adverb',["Normally, I eat breakfast at 6am, but today, I got up late and didn''t eat until 9.","He was abnormally agitated, she only normally so."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vague','adj.模糊的；不明确的','/veɪɡ/','/veɪɡ/','noun',["a vague term of abuse","I haven’t the vaguest idea.","a vague longing"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fare','vi.进展n.费用','/fɛə(ɹ)/','/feɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('juridical','adj.法律的，司法的','/dʒʊˈɹɪdɪkəl/','/dʒʊˈɹɪdɪkəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ephemeral','adj.短暂的，转瞬即逝的','/əˈfɛ.mə.ɹəl/','/əˈfɛ.mə.ɹəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accuracy','n.准确，精确','[ˈækjʊrəsɪ]','/ˈæk.jɚ.ə.si/','noun',["The value of testimony depends on its accuracy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curtsy','vi.行屈膝礼n.屈膝礼','','','noun',["I refused to make so much as a curtsey for the passing nobles, as I am a staunch egalitarian.","The hotel''s staff variously curtsied, nodded, and bowed to the owner as she passed."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('setting','n.环境；背景；布景；曲；底座，底板','/ˈsɛtɪŋ/','/ˈsɛtɪŋ/','verb',["Set the tray there.","I have set my heart on running the marathon.","to set a coach in the mud"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quote','v.引用；','/kwəʊt/','/kwəʊt/','noun',["After going over the hefty quotes, the board decided it was cheaper to have the project executed by its own staff.","The writer quoted the president.","The writer quoted the president''s speech."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unanimous','adj.全体一致的，一致同意的','/juːˈnanɪməs/','/juːˈnanɪməs/','adjective',["The debate went on for hours, but in the end the decision was unanimous.","We were unanimous: the President had to go."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quota','n.配额，限额，定额','/ˈkwoʊtə/','/ˈkwoʊtə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scorn','v.轻蔑，鄙视；不屑于n.轻蔑，鄙视','/skɔːn/','/skɔɹn/','noun',["He scorned her romantic advances.","She scorned to show weakness."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thermal','adj.热的，热量的；保暖的，防寒的n.上升的热气流','/ˈθɝməl/','/ˈθɝməl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('percussion','n.打击乐器','/pɚˈkʌʃən/','/pɚˈkʌʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nationalism','n.国家主义；民族主义，民族优越感','/ˈnæʃənəlɪzəm/','/ˈnæʃənəlɪzəm/','noun',["Basque nationalism"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sulfur','n.硫；硫黄','/ˈsʌl.fə/','/ˈsʌl.fɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('culpable','adj.有罪的；该谴责的，难辞其咎的','/ˈkʌlpəbəl/','/ˈkʌlpəbəl/','adjective',["I am culpable for stealing your money."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sprinkle','v.撒，洒，喷n.少量','/ˈspɹɪŋkəl/','/ˈspɹɪŋkəl/','noun',["He decorated the Christmas card with a sprinkle of glitter.","The confectioner sprinkled icing sugar over the cakes.","The confectioner sprinkled the cakes with icing sugar."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('backlighting','n.逆光','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('municipal','adj.市政的；内政的；地方性的','/mjuˈnɪsɪpəl/','/mjuˈnɪsɪpəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('institute','vt.设立；制定；开创n.研究所，学院','/ˈɪnstɪt(j)uːt/','/ˈɪnstɪt(j)uːt/','noun',["I work in a medical research institute."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feign','vt.装作，假装；伪造','/feɪn/','/feɪn/','verb',["The pupil feigned sickness on the day of his exam.","He feigned that he had gone home at the appointed time.","Jessica feigned the fact that she had not done her homework."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poster','n.海报，招贴画；发布消息的人','/ˈpoʊstɚ/','/ˈpoʊstɚ/','noun',["He has posters of his favorite band, sports teams and holiday resorts up.","I saw a poster for the film on the side of a bus.","Some posters left the online message board after the squabble."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shortly','adv.不久；简要地；不耐烦地','/ʃɔːɹtli/','/ʃɔːɹtli/','adverb',["Ideas are generally expressed more shortly in verse than in prose"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('essence','n.本质，精髓','/ˈɛsəns/','/ˈɛsəns/','noun',["essence of Jojoba","vanilla essence"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambient','adj.周围的，周围环境的；产生轻松氛围的','/ˈæm.biː.ənt/','/ˈæm.biː.ənt/','noun',["A cup of tea eventually cools to the ambient temperature.","ambient food"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insistence','n.坚持，坚决主张','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('manual','adj.手工的；体力的n.手册，指南','/ˈman.j(ʊ)əl/','/ˈmænjə(wə)l/','noun',["The dishwasher isn''t working; can you remember where we put the manual?","do a manual"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ornamental','adj.装饰性的，装饰用的n.装饰物','/ˌɔːnəˈmɛntl/','/ˌɔːnəˈmɛntl/','noun',["Some think it most ornamental to wear their bracelets on their wrists; others, about their ankles."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sentimental','adj.情感的；伤感的，多愁善感的','/ˌsɛntiˈmɛntl̩/','/ˌsɛntiˈmɛntl̩/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maneuver','v.操纵，控制；耍花招n.策略；花招','/məˈnuːvə/','/məˈnuːvɚ/','noun',["Joint NATO maneuvers are as much an exercise in diplomacy as in tactics and logistics.","Parallel parking can be a difficult maneuver.","The patriarch maneuvered till his offspring occupied countless key posts"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dual','adj.双的，二重的','/ˈdjuː.əl/','/ˈdjuː.əl/','noun',["The octahedron is the dual of the cube.","a dual-headed computer","Modern Arabic displays a dual number, as did Homeric Greek."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retire','v.退休，引退，退役；退出；撤退；就寝','/ɹəˈtaɪə(ɹ)/','/ɹəˈtaɪə(ɹ)/','noun',["At the retire, the cavalry fell back.","Having made a large fortune, he retired.","The steamship made thousands of trips over several decades before it was retired by the shipping company."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dexterous','adj.惯用右手的；灵巧的，熟练的','/ˈdɛkstɹəs/','/ˈdɛkstɹəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vegetarian','adj.素食者的n.素食者','/vɛd͡ʒɪˈtɛəɹi.ən/','/vɛd͡ʒɪˈtɛəɹi.ən/','noun',["I have a vegetarian brother"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resilience','n.弹力，弹性；复原力；适应力','/ɹə.zɪl.ɪ.əns/','/ɹə.zɪl.ɪ.əns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corona','n.日冕，日华；光环','','/kəˈɹoʊnə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('midterm','adj.中间的，期中的n.期中考试；中期；期中','/ˈmɪdˌtəɹm/','/ˈmɪdˌtəɹm/','noun',["The administration is suffering from the usual midterm drop in approval ratings."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('signify','v.意味；表示，预示；要紧，有重要性','/ˈsɪɡnɪfaɪ/','/ˈsɪɡnɪfaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suction','n.吸，抽吸；吸力','/ˈsʌkʃən/','/ˈsʌkʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('holistic','adj.整体的，全面的；功能整体性的','/həʊˈlɪs.tɪk/','/həʊˈlɪs.tɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swing','v.摆动，摇荡；突然转向，突然转身n.摆动，摇摆；秋千','/ˈswɪŋ/','/ˈswɪŋ/','noun',["Door swing indicates direction the door opens.","The plant swung in the breeze.","The children laughed as they swung."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turbulent','adj.动乱的；狂暴的，汹涌的','/ˈtɜːbjələnt/','/ˈtɜːbjələnt/','adjective',["It is dangerous to sail in turbulent seas.","The mid-19th century was a turbulent time in American history."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overt','adj.公开的，非秘密的','/ə(ʊ)ˈvɜːt/','/ə(ʊ)ˈvɜːt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invasion','n.侵入，侵略，侵犯','/ɪnˈveɪʒən/','/ɪnˈveɪʒən/','noun',["an invasion of bees"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forefront','n.最前沿，最前线；中心','/ˈfɔːfɹʌnt/','/ˈfɔɹfɹʌnt/','noun',["That laboratory researches topics at the forefront of technology."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grocery','n.杂货店；杂货','/ˈɡɹəʊs(ə)ɹi/','/ˈɡɹəʊs(ə)ɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scout','v.侦察；寻找；搜索n.侦察员；侦察机；童子军','[skʌʊt]','[skʌʊt]','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('edifice','n.大厦，宏伟的建筑物','/ˈɛd.ɪ.fɪs/','/ˈɛd.ɪ.fɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('register','v&n.登记，注册','/ˈɹɛdʒ.ɪs.tə/','/ˈɹɛdʒ.ɪs.tɚ/','noun',["The teacher took the register by calling out each child''s name.","a register of deeds","My ex-boss used \"let go\", in the euphemistic register, when he sacked me."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('persuasive','adj.有说服力的，让人信服的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('couple','n.对，双；夫妇，情侣；几个人，几件事vt.连接，结合','/ˈkʌpəl/','/ˈkʌpəl/','noun',["I''ve coupled our system to theirs."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('saddle','n.马鞍；车座vt.给…备鞍','/ˈsædəl/','/ˈsædəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acclaim','n&vt.喝彩，称赞','','/ə.ˈkleɪm/','verb',["a highly-acclaimed novel"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concord','n.和睦；公约','/ˈkɒn.kɔɹd/','/ˈkɒn.kɔɹd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blush','vi.脸红；羞愧n.脸上泛起的红晕','/blʌʃ/','/blʌʃ/','noun',["He wasn''t used to this much attention, so he blushed as he saw dozens of pairs of eyes watching him.","I wasn''t surprised, but it was embarrassing enough that I blushed a little pink.","Looking at me with a knowing glare, she blushed her discomfort with the situation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overgraze','v.过度放牧','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dubious','adj.怀疑的，拿不准的；可疑的，靠不住的','/ˈdjuːbi.əs/','/ˈdu.bi.əs/','adjective',["After he made some dubious claims about the company, fewer people trusted him.","She was dubious about my plan at first, but later I managed to persuade her to cooperate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clipper','n.快速帆船；剪刀','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swift','adj.敏捷的，速度快的n.雨燕','/swɪft/','/swɪft/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ductile','adj.有延性的，韧性的；易引导的，易受影响的','/ˈdʌk.taɪl/','/ˈdʌk.taɪl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conciliate','vt.安抚，抚慰；调和','/ˌkənˈsɪlieɪt/','/ˌkənˈsɪlieɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('utensil','n.用具；器皿','/juˈtɛn.səl/','/juˈtɛn.səl/','noun',["We have convenient storage for all the kitchen utensils.","He stocked up on old-style writing utensils."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accede','vi.即位，就任；同意','/əkˈsiːd/','/ækˈsid/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ratify','vt.正式批准，使正式生效','/ˈɹætəfaɪ/','/ˈɹætəfaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vivify','vt.赋予生气；使生动，使活跃','/ˈvɪvɪfʌɪ/','/ˈvɪvɪfʌɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amend','vt.修正，修订','/əˈmɛnd/','/əˈmɛnd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('erupt','v.突然发生，爆发；喷出','/ɪˈɹʌpt/','/ɪˈɹʌpt/','verb',["The volcano erupted, spewing lava across a wide area.","The third molar tooth erupts late in most people, and sometimes does not appear at all.","The crowd erupted in anger."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('benevolent','adj.慈善的；善心的','/bəˈnɛvələnt/','/bəˈnɛvələnt/','adjective',["Chinese and Eastern mythologies describe dragons as benevolent."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consent','vi&n.同意，赞成，准许','/kənˈsɛnt/','/kənˈsɛnt/','noun',["After reflecting a little bit, I''ve consented."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fusion','n.熔化，熔解；熔合；核聚变；联合，合并','/ˈfjuː.ʒən/','/ˈfjuː.ʒən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parachute','v.跳伞；空投n.降落伞','/ˈpæɹəʃuːt/','/ˈpæɹəʃuːt/','noun',["The soldiers were parachuted behind enemy lines."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behaviorism','n.行为主义','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carnivore','n.食肉动物','/ˈkɑːnɪvɔː/','/ˈkɑːnɪvɔː/','noun',["As juveniles the crocodiles are frequently predated by larger carnivores.","The panda and the panther are both carnivores."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pharmacy','n.药店；药剂学','/ˈfɑːməsi/','/ˈfɑɹməsi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crooked','adj.不诚实的；欺诈的；弯曲的','/kɹʊkt/','/kɹʊkt/','verb',["He crooked his finger toward me."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contiguous','adj.接壤的，毗邻的；不间断的','/kənˈtɪɡjuəs/','/kənˈtɪɡjuəs/','adjective',["the forty-eight contiguous states"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nourishment','n.营养，营养品','/ˈnʌɹɪʃmənt/','/ˈnʌɹɪʃmənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('connote','v.意味着；暗示','/kɒˈnəʊt/','/kəˈnoʊt/','verb',["Racism often connotes an underlying fear or ignorance.","Poverty connotes hunger."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('puddle','n.水坑，水洼','/ˈpʌdəl/','/ˈpʌdəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('primal','adj.最初的；主要的，首要的','/ˈpɹaɪməl/','/ˈpɹaɪməl/','noun',["primal man"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paste','v.粘贴；拼贴n.面团；糨糊','/peɪst/','/peɪst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('directory','n.人名地址录，电话号码簿；目录','/daɪˈɹɛktəɹi/','/daɪˈɹɛktəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jeans','n.牛仔裤','/d͡ʒiːnz/','/d͡ʒiːnz/','noun',["She wore a tattered jean jacket.","Traditionally most jeans are dyed dark blue."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monarch','n.君主，帝王','/ˈmɒnək/','/ˈmɑnɑɹk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overnight','adv.整夜；一夜之间adj.通宵的，一整夜的；一夜之间的','','','noun',["Have you looked at the overnights yet?","We can overnight you the documents for signature.","The overnight ferry docked at 10AM."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laser','n.激光；激光器','/ˈleɪz.ə(ɹ)/','/ˈleɪz.ə(ɹ)/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scope','n.范围，界限；眼界，见识；余地，机会','/ˈskoʊp/','/ˈskoʊp/','noun',["the scope of an adverb","The surgeon will scope the football player''s knee to repair damage to a ligament.","If we locally scope the user''s login name, it won''t be accessible from outside this function."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notate','vt.以符号表示，把…写成记号','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('molecular','adj.分子的；摩尔的；由分子组成的','/məˈlɛkjʊlə/','/məˈlɛkjʊlə/','noun',["molecular dishes"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('morale','n.士气，斗志','/məˈɹæl/','/məˈɹæl/','noun',["Morale is an important quality in soldiers. With good morale they''ll charge into a hail of bullets; without it they won''t even cross a street."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('periphery','n.外围，边缘','/pəˈɹɪfəɹi/','/pəˈɹɪfəɹi/','noun',["The suburbs are a city''s periphery."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fresco','v.绘湿壁画于n.湿壁画；湿壁画技法','/ˈfɹɛskəʊ/','/ˈfɹɛskəʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embrace','v.拥抱；包含；欣然接受n.拥抱','/ɛmˈbɹeɪs/','/əm-/','noun',["I wholeheartedly embrace the new legislation.","Natural philosophy embraces many sciences."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('artesian','adj.自流水的，喷水的','/ɑːˈtiːʒən/','/ɑːˈtiːʒən/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('label','vt.标记n.标签；称号','/ˈleɪbəl/','/ˈleɪbəl/','noun',["Although the label priced this poster at three pounds, I got it for two.","Ever since he started going to the rock club, he''s been given the label \"waster\".","The label signed the band after hearing a demo tape."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aquarium','n.养鱼缸；水族馆','/-ɛɹiəm/','/-ɛɹiəm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soprano','n.女高音','/səˈpɹænoʊ/','/səˈpɹænoʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mortify','vt.使蒙受屈辱，使难堪','/ˈmɔːtɪfaɪ/','/ˈmɔːtɪfaɪ/','verb',["Some people seek sainthood by mortifying the body.","I was so mortified I could have died right there; instead I fainted, but I swore I''d never let that happen to me again."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cram','v.填塞，塞满；匆忙准备，临时死记硬背','/kɹæm/','/kɹæm/','noun',["a cram from an examination","to cram fruit into a basket; to cram a room with people","The boy crammed himself with cake"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clone','n.克隆动物，无性繁殖动物；复制品，翻版vt.克隆，以无性繁殖技术复制','/kləʊn/','/kloʊn/','noun',["The scientists were able to clone a sheep."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('detest','v.憎恶','/dɪˈtɛst/','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enunciate','v.清晰地发音；表达，阐明','/ɪˈnʌnsiˌeɪt/','/ɪˈnʌnsiˌeɪt/','verb',["You must enunciate all the syllables.","Enunciate when you speak."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exempt','adj.被免除的，被豁免的vt.免除，豁免','/ɛɡˈzɛm(p)t/','/ɛɡˈzɛm(p)t/','noun',["Citizens over 45 years of age were exempted from military service.","His income is so small that it is exempt from tax."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('degenerative','adj.衰退的，堕落的；变性的','/dɪˈdʒɛn(ə)ɹətɪv/','/dɪˈdʒɛn(ə)ɹətɪv/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feminist','n.女权主义者','/ˈfɛmənɪst/','/ˈfɛmənɪst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('backup','n.后援，增援；','/ˈbækˌʌp/','/ˈbækˌʌp/','noun',["If the goalkeeper is injured, we have a backup.","After the power failure, we had to restore the database from backup.","The accident caused a mile-long backup on the highway."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arithmetic','n.算术','','','noun',["arithmetic geometry","arithmetic progression"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hardy','adj.强壮的；耐寒的；能吃苦耐劳的','/ˈhɑːdi/','/ˈhɑɹdi/','noun',["A hardy plant is one that can withstand the extremes of climate, such as frost."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('caption','n.说明文字；标题；字幕vt.给加说明文字','/ˈkæp.ʃən/','/ˈkæp.ʃən/','noun',["Only once the drawing is done will the letterer caption it."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mismanage','vt.对…管理不当，处理不当','','','verb',["She mismanaged my finances and left me bankrupt.","The fundamental reason why the company failed is that the CEO and other top managers simply mismanaged."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subconscious','adj.下意识的，潜意识的n.下意识，潜意识','','','noun',["A person can sometimes wake up knowing the solution to a problem that their subconscious has been working on.","The sense of smell can be a subconscious influence on our actions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eject','v.逐出，驱赶；喷出，喷射；弹出','/ɪˈdʒɛkt/','/ɪˈdʒɛkt/','verb',["Andrew was ejected from his apartment for not paying the rent.","In other news, a Montreal man was ejected from his car when he was involved in an accident.","The pilot lost control of the plane and had to eject."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meteorologist','n.气象学者','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defect','vi.变节，叛变n.瑕疵，缺陷；过失','','','noun',["a defect in the ear or eye; a defect in timber or iron; a defect of memory or judgment"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obedience','n.服从，顺从','/ə(ʊ)ˈbiːdɪəns/','','noun',["Obedience is essential in any army."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reinforce','vt.加固，加强；增援','/ˌɹiːɪnˈfɔː(ɹ)s/','/ˌɹiːɪnˈfɔː(ɹ)s/','verb',["He reinforced the handle with a metal rod and a bit of tape.","The right homework will reinforce and complement the lesson!","Advertising for fast food can reinforce unhealthy dietary tendencies."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('casual','adj.非正式的，随便的；漫不经心的；漠不关心的，冷淡的；偶然的，碰巧的；临时的','/ˈkɛʒɘl/','/ˈkɛʒɘl/','noun',["The devs dumbed the game down so the casuals could enjoy it.","They only had casual meetings.","The purchase of donuts was just a casual expense."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rim','n.边，轮缘；边界vt.给…镶边','/ɹɪm/','/ɹɪm/','noun',["A walking path rims the island.","The basketball rimmed in and out."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rip','v.扯破，撕坏n.裂口，裂缝','/ɹɪp/','/ɹɪp/','noun',["to rip a garment; to rip up a floor","My shirt ripped when it was caught on a bramble."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scuffle','n&vi.扭打，混战','/ˈskʌfəl/','/ˈskʌfəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('luster','n.光亮，光泽；荣耀','/ˈlʌstɚ/','/ˈlʌstɚ/','noun',["He polished the brass doorknob to a high luster.","After so many years in the same field, the job had lost its luster.","He spoke with all the lustre a seasoned enthusiast should have."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('urbanization','n.都市化','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tough','adj.坚韧的；棘手的，困难的；强健的，吃苦耐劳的；粗暴的；严格的；老的','/tʌf/','/tʌf/','noun',["They were doing fine until they encountered a bunch of toughs from the opposition.","The tent, made of tough canvas, held up to many abuses.","To soften a tough cut of meat, the recipe suggested simmering it for hours."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yeast','n.酵母，发酵粉','/iːst/','/iːst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('melody','n.旋律，曲调；乐曲，歌曲','/ˈmel.ə.di/','/ˈmɛl.ə.di/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trilogy','n.三部剧，三部曲','/ˈtɹɪlədʒi/','/ˈtɹɪlədʒi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sterile','adj.不育的；贫瘠的；无菌的；无结果的，没有实际价值的；刻板的','/ˈstɛɹaɪl/','/ˈstɛɹaɪl/','adjective',["a sterile kitchen table"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('watercourse','n.水道，河道','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('catholic','adj.广泛的，包罗万象的；[C-]天主教的n.[C-]天主教','/ˈkaθ(ə)lɪk/','/ˈkæθ(ə)lɪk/','adjective',["Christmas is celebrated at different dates in the Catholic and Orthodox calendars.","Catholic churches are built differently than Protestant ones."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mighty','adj.强有力的；巨大的','/ˈmaɪti/','/ˈmaɪti/','noun',["He''s a mighty wrestler, but you are faster than him.","He gave the ball a mighty hit.","She''s a mighty cook."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('partial','adj.部分的，不完全的；偏爱的，癖好的；偏袒的','/ˈpɑːʃəl/','/ˈpɑːʃəl/','noun',["So far, I have only pieced together a partial account of the incident.","It''s easy to prove partial correctness, but it''s not obvious that it is also totally correct.","The referee is blatantly partial!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pictorial','adj.图示的，有图片的；绘画的，图画的n.画报，画刊','/pɪkˈtɔɹi.əl/','/pɪkˈtɔɹi.əl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slough','vt.使脱落n.泥坑，沼泽；绝境','/slʌf/','/slʌf/','noun',["That is the slough of a rattler; we must be careful.","This is the slough that came off of his skin after the burn.","Snakes slough their skin periodically."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drench','vt.使湿透','/dɹɛntʃ/','/dɹɛntʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drastic','adj.剧烈的，猛烈的，激烈的','/ˈdɹɑːs.tɪk/','/ˈdɹæs.tɪk/','noun',["If our third attempt fails, we may need drastic ideas."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retail','adv.以零售方式v.零售；以…价格销售n.零售','/ˈɹiˌteɪl/','/ˈɹiˌteɪl/','noun',["She works in retail.","I never pay retail for clothes.","We''ve shut shown our reseller unit. We''re only selling retail now."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crew','n.全体船员；全体工作人员','','','verb',["He’s been crowing all day about winning the game of cards."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('innovate','v.革新，创新','/ˈɪnəveɪt/','','verb',["to innovate a word or an act"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extravagant','adj.放肆的，过分的；奢侈的，铺张的','/ɪkˈstɹævəɡənt/','/ɪkˈstɹævəɡənt/','adjective',["extravagant acts, praise, or abuse","an extravagant man;  extravagant expense"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accommodate','v.提供；容纳；适应，顺应','/əˈkɒməˌdeɪt/','/əˈkɑməˌdeɪt/','verb',["to accommodate ourselves to circumstances","to accommodate differences","to accommodate an old friend for a week"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('protagonist','n.主角，主人公；领导者，倡导者','/pɹəˈtæ.ɡə.nɪst/','/pɹoʊˈtæ.ɡə.nɪst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vacation','vi.度假n.假期','/veɪˈkeɪʃ(ə)n/','/veɪˈkeɪʃən/','noun',["The Conservative Party’s vacation of the centre ground gave an opportunity to its opponents.","This year, we’re vacationing in Mexico."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sacred','adj.宗教的；上帝的，神圣的','/ˈseɪkɹɪd/','/ˈseɪkɹɪd/','adjective',["a sacred day"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outcome','n.结果，成果','/ˈaʊtkʌm/','/ˈaʊtkʌm/','noun',["A quality automobile is the outcome of the work of skilled engineers and thousands of workers.","Three is a possible outcome of tossing a six-sided die.","The outcomes of this course are outlined in your syllabus."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tender','adj.嫩的；脆弱的；温柔的，亲切的v.提出；投标n.投标','/ˈtɛn.də(ɹ)/','/ˈtɛn.də/','noun',["tender plants; tender flesh; tender fruit","Suzanne was such a tender mother to her children.","tender expressions; tender expostulations; a tender strain"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curriculum','n.课程','/kəˈɹɪk.jə.ləm/','/kəˈɹɪkjələm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meditate','v.沉思，冥想；考虑；谋划','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prototype','n.原型，雏形','/ˈpɹəʊtətʌɪp/','/-ɾə-/','noun',["The prototype had loose wires and rough edges, but it worked.","A robin is a prototype of a bird; a penguin is not."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meantime','n&ad.其时，同时','/ˈmiːntaɪm/','/ˈmiːntaɪm/','noun',["I''ll get started tomorrow but, in the meantime, let''s see if we can get a few more opinions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dehydrate','v.脱水','/diːhaɪdˈɹeɪt/','/diːhaɪdˈɹeɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cite','vt.引用，引证；传唤，传讯；表彰，嘉奖','/saɪt/','/saɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blurt','vt.脱口而出','/ˈblɜːt/','/ˈblɝt/','noun',["Please think about your reply and don''t just blurt out the first thing that comes to mind."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('internship','n.实习期','/ˈɪntɝnʃɪp/','/ˈɪntɝnʃɪp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pertain','vi.存在；适用','/pəˈteɪn/','/pəˈteɪn/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spun','adj.拉成丝的','/ˈspʌn/','/ˈspʌn/','verb',["I spun myself around a few times.","They spin the cotton into thread.","to spin along the road in a carriage, on a bicycle, etc."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tolerable','adj.可忍受的，可容忍的；尚好的，过得去的','/ˈtɒləɹəbl̩/','/ˈtɒləɹəbl̩/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bicameral','adj.两院制的，有两个议院的','/bʌɪˈkaməɹəl/','','adjective',["the bicameral anatomy of the brain"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spur','n.刺激；激励；马刺vt.激励，鼓舞；刺激，促进','/spɜː/','/spɝ/','noun',["to spur boots"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rear','adj.后部的，后面的vt.养育，抚养，培养；饲养n.后部，后方；臀部','/ɹɪə/','/ɹiɹ/','verb',["The family has been rearing cattle for 200 years.","The horse was shocked, and thus reared.","The monster slowly reared its head."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elapse','vi.消逝，流逝','','','verb',["He allowed a month to elapse before beginning the work."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symmetry','n.对称；相似，相仿','/ˈsɪmɪtɹi/','/ˈsɪmɪtɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complement','vt.补充，补足，使完善；与…相配n.补充物，补足物；足数，足额；补足语','/ˈkɒmpləmənt/','/ˈkɒmpləmənt/','noun',["The complement of blue is orange.","The complement of the odd numbers is the even numbers, relative to the natural numbers.","The complement of 01100101_2 is 10011010_2."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('qualify','v.具有资格，合格；有权；限定，修饰','/ˈkwɒl.ɪ.faɪ/','/ˈkwɑl.ɪ.faɪ/','noun',["to qualify seven balls you need at least fourteen catches"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bode','vi.预示','/bəʊd/','/bəʊd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('applicable','adj.可应用的，可实施的；适当的，合适的','/əˈplɪkəbəl/','/əˈplɪkəbəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adhere','vi.黏附，附着；坚持；遵守','/ædˈhiɹ/','/ædˈhiɹ/','verb',["wax adhered to his finger"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sediment','n.沉淀物，沉积物','/ˈsɛd.ɪ.mənt/','/ˈsɛd.ɪ.mənt/','noun',["The Nile delta is composed of sediment that was washed down and deposited at the mouth of the river."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tremulous','adj.发抖的，颤抖的；害怕的','/ˈtɹɛmjuləs/','/ˈtɹɛmjuləs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hybrid','adj.杂交产生的；混合的，合成的n.杂交植物；混合物，合成物','/ˈhaɪ.bɹɪd/','/ˈhaɪ.bɹɪd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('panorama','n.全景，全貌；概观，综述','/ˌpæ.nəˈɹæ.mə/','/ˌpæ.nəˈɹæ.mə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adaptable','adj.能适应的；可改编的','/əˈdæptəbəl/','/əˈdæptəbəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mock','v.嘲笑，嘲弄；模仿；蔑视，n.模拟考试','/mɒk/','/mɑk/','noun',["He got a B in his History mock, but improved to an A in the exam.","What''s the best way to mock a database layer?","mock leather"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('credence','n.可信性，真实性；信任；信念','/ˈkɹiː.dəns/','/ˈkɹiː.dəns/','noun',["Based on the scientific data, I give credence to this hypothesis."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gear','n.齿轮，传动装置；挡；设备vt.调节，使适应','/ɡɪə(ɹ)/','/ɡɪə(ɹ)/','noun',["They have geared the hotel mainly at tourists."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rob','vt.抢夺，抢掠；剥夺，使失去','/ɹɒb/','/ɹɑb/','verb',["He robbed three banks before he was caught.","The best way to rob a bank is to own one.","Working all day robs me of any energy to go out in the evening."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rod','n.杆，棒','/ɹɒd/','/ɹɑd/','noun',["When I hooked a snake and not a fish, I got so scared I dropped my rod in the water.","The judge imposed on the thief a sentence of fifteen strokes with the rod.","I notched a rod and used it to measure the length of rope to cut."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('roe','n.鱼卵','/ˈɹəʊ/','/ˈɹoʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quiver','vi.颤动，抖动n.颤抖；箭筒','/ˈkwɪvəɹ/','/ˈkwɪvəɹ/','noun',["He''s got lots of sales pitches in his quiver."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('encase','vt.包住','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('telegraph','v.打电报，发电报n.电报；电报机','/ˈtɛl.ə.ɡɹæf/','','noun',["Her frown telegraphed her displeasure."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disappoint','v.失望，扫兴','/dɪsəˈpɔɪnt/','/dɪsəˈpɔɪnt/','verb',["His lack of respect disappointed her."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rebellious','adj.反叛的，叛逆的；叛乱的','/ɹəˈbɛliəs/','/ɹəˈbɛliəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gloss','v.有光泽n.光泽，色泽；亮光漆；注解','/ɡlɑs/','/ɡlɔs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ration','n.配给量，定量；给养，口粮vt.配给，定量供应','/ˈɹæʃən/','','noun',["We rationed ourselves to three sips of water a day until we were rescued.","By the third day on the raft, we had to ration our water.","Our present health care system is rationed only to those who can afford it because of unnecessary high cost, lack of insurance coverage by 47 million people, and exorbitant prescription prices."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dump','vt.丢弃，倾倒；抛弃；推卸；倾销n.垃圾场','/dʌmp/','/dʌmp/','noun',["A toxic waste dump.","The new XML dump is coming soon.","Don''t feel bad about moving away from this dump."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subjective','adj.主观的，个人的','/səbˈdʒɛktɪv/','/səbˈdʒɛktɪv/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blossom','vi.开花；长成n.花','/ˈblɒ.səm/','/ˈblɑ.səm/','noun',["The blossom has come early this year.","The orchard is in blossom."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radical','adj.根本的；激进的，极端的；全新的，不同凡响的n.激进分子；游离基，自由基','/ˈɹædɪkəl/','/ˈɹædɪkəl/','noun',["His beliefs are radical.","The spread of the cancer required radical surgery, and the entire organ was removed.","a radical quantity; a radical sign"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blunt','adj.钝的；不敏感的；直率的vt.使迟钝；使减弱','/blʌnt/','/blʌnt/','noun',["2005: to make his point, lead rapper B-Real fired up a blunt in front of the cameras and several hundred thousand people and announced, “I''m taking a hit for every one of y''all!” — Martin Torgoff, Can''t Find My Way Home (Simon & Schuster 2005, p. 461)","the blunt admission that he had never liked my company"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('irresistible','adj.无法抗拒的，诱人的；不能自已的','/ˌɪɹɪˈzɪstəbl̩/','/ˌɪɹɪˈzɪstəbl̩/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('doodle','vi.乱涂，胡画','/ˈduː.dəl/','/ˈduː.dəl/','noun',["The bored student doodled a submarine in his notebook."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intuitive','adj.直觉的','/ɪnˈtjuːɪtɪv/','/ɪnˈtjuːɪtɪv/','noun',["The intuitive response turned out to be correct.","Designing software with an intuitive interface can be difficult."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('analogy','n.类比，类推','/əˈnæləd͡ʒi/','/əˈnæləd͡ʒi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transcendent','adj.卓越的，出众的','/tɹæn(t)ˈsɛndənt/','/tɹæn(t)ˈsɛndənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swirl','v.打旋，旋转n.漩涡；螺旋形','/swɜːl/','/swɜːl/','noun',["I swirled my brush around in the paint."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('productive','adj.生产的；能产的，多产的；富有成效的','/pɹəˈdʌktɪv/','/pɹəˈdʌktɪv/','adjective',["a productive set"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hummingbird','n.蜂鸟','/ˈhʌmɪnˌbɜːd/','/ˈhʌmɪŋˌbɝd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('semester','n.学期','/sɪˈmɛstə/','/sɪˈmɛstə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collapse','v&n.崩溃，倒塌；虚脱','/kəˈlæps/','/kəˈlæps/','noun',["She suffered a terrible collapse after slipping on the wet floor.","Pyramid schemes tend to generate profits for a while and then collapse.","Hurry up and collapse the tent so we can get moving."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dull','adj.乏味的，单调的；迟钝的；无光泽的；萧条的；阴沉的，昏暗的','/dəl/','/dʌl/','verb',["Years of misuse have dulled the tools.","He drinks to dull the pain.","A razor will dull with use."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ferment','v.发酵；骚动n.发酵；动乱，骚动','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comprehend','v.理解，领会；包括，由…组成','/kɒmpɹɪˈhɛnd/','/kɑmpɹɪˈhɛnd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('potency','n.影响力，支配力；效力','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('octopus','n.章鱼','/ˈɒk.tə.pəs/','/ˈɑːk.tə.pəs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prostitution','n.卖淫；出卖灵魂，堕落；滥用','','','noun',["Her addiction brought her to the point that prostitution was the only means she had to survive.","The television advertising job was a prostitution of the talents of one of the great writers of the century."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('legend','n.传奇故事，传说；传奇文学','/ˈlɛdʒ.ənd/','/ˈlɛdʒ.ənd/','noun',["According to the legend on the map, that building is a school."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paraphrase','v.解释；改写n.释义','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('erect','adj.直立的vt.建立；竖立','/ɪˈɹɛkt/','/ɪˈɹɛkt/','adjective',["The penis should be fully erect before commencing copulation.","OK, baby, I''m erect now. Let''s get it on!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exalted','adj.崇高的，高贵的，显赫的','/ɪɡˈzɔːltɪd/','/ɪɡˈzɔːltɪd/','verb',["They exalted their queen.","The man was exalted from a humble carpenter to a minister."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('identification','n.身份证明；辨认，鉴定','/aɪˌdɛntɪfɪˈkeɪʃən/','/aɪˌdɛntɪfɪˈkeɪʃən/','noun',["Much education and experience is required for proper identification of bird species","information necessary to make a good identification","The authorities asked for his identification"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exclusive','adj.独占的；除外的，排他的；奢华的n.独家新闻','/ɪkˈsklu.sɪv/','/ɪkˈsklu.sɪv/','noun',["The editor agreed to keep a lid on a potentially disastrous political scoop in exchange for an exclusive of a happier nature.","Exclusive clubs tend to serve exclusive brands of food and drinks, in the same exorbitant price range, such as the ''finest'' French châteaux.","The teacher''s pet commands the teacher''s exclusive attention."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jar','v.震动；冲突，抵触；感到不快n.坛子；广口瓶','/dʒɐː/','/dʒɑɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poverty','n.贫穷，贫困','/ˈpɒvəti/','/ˈpɑːvɚti/','noun',["poverty of soil"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repertoire','n.常备剧目，保留剧目；可表演节目；全部才能','/ˈɹɛp.ə.twɑː/','/ˈɹɛp.ə.twɑː/','noun',["The conjurer expanded his repertoire with some new tricks."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resort','vi.求助n.度假胜地；手段','/ɹɨˈzɔ(ɹ)t/','/ɹɨˈzɔ(ɹ)t/','noun',["to have resort to violence"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dwindle','v.减少；缩小','/ˈdwɪn.dəl/','/ˈdwɪn.dəl/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jaw','n.颌，颚；','/d͡ʒɔː/','/d͡ʒɑ/','noun',["His jaw dropped in amazement.","the jaws of a pass; the jaws of darkness; the jaws of death.","the jaw of a railway-car pedestal."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reef','n.礁，暗礁','/ɹiːf/','/ɹiːf/','noun',["Reef the paddles."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nail','n.指甲，爪；钉vt.将…钉牢，钉住','/neɪl/','/neɪl/','noun',["When I''m nervous I bite my nails."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tarnish','v.失去光泽；玷污，败坏n.污点；瑕疵','/ˈtɑɹnɪʃ/','/ˈtɑɹnɪʃ/','noun',["Careful storage of silver will prevent it from tarnishing.","He is afraid that he will tarnish his reputation if he disagrees."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sunlit','adj.阳光照射的','/ˈsʌnˌlɪt/','/ˈsʌnˌlɪt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coexist','vi.共存','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquiesce','vi.默许，默认','/ˌækwiˈɛs/','/ˌækwiˈɛs/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pathetic','adj.可怜的，引起怜悯的，令人怜惜的','/pəˈθɛtɪk/','/pəˈθɛtɪk/','adjective',["The child’s pathetic pleas for forgiveness stirred the young man’s heart.","You can''t even run two miles? That’s pathetic."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turkey','n.火鸡；失败','/ˈtɜːki/','/ˈtɝki/','noun',["All week after Thanksgiving, I had turkey sandwiches for lunch.","That film was a turkey.","The turkey cut in front of me and then berated me for running into him."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overtime','adv.加班adj.超时的，加班的','/ˈoʊvɚˌtaɪm/','/ˈoʊvɚˌtaɪm/','noun',["Workers are usually paid extra for working overtime.","That last-second shot ties the game 99-99 and sends it to overtime!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scorch','v.烧焦；枯萎，枯黄n.焦痕','/skɔːtʃ/','/skɔɹtʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mound','n.土墩，土丘；堆，垛','/maʊnd/','/maʊnd/','noun',["He mounded up his mashed potatoes so they left more space on the plate for the meat."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gentility','n.有教养，文雅','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accuse','vt.谴责；指责，归咎；指控，控告','/əˈkjuːz/','/əˈkjuz/','noun',["For the U.S. President to be impeached, he must be accused of a high crime or misdemeanor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('algebra','n.代数','/ˈæl.dʒɪ.bɹə/','/ˈæl.dʒə.bɹə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('espouse','vt.支持，拥护，赞成','/ɪˈspaʊz/','/ɪˈspaʊz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('predecessor','n.前辈；前任；原有事物','/ˈpɹiːdɪsɛsə(ɹ)/','/ˈpɹiːdɪsɛsɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notion','n.概念，观念；想法','/ˈnəʊʃən/','/ˈnoʊʃən/','noun',["Yankee notions","I have a notion to do it."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('captive','adj.被监禁的，被困住的；受控制的n.俘虏，战俘','/ˈkæptɪv/','/ˈkæptɪv/','noun',["captive chains; captive hours"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dividend','n.红利，股息；回报，效益；被除数','/ˈdɪvɪdɛnd/','/ˈdɪvɪdɛnd/','noun',["In \"42 ÷ 3\" the dividend is the 42.","His 10,000 hours of practice and recitals eventually paid dividends when he become first-chair violinist."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vice','n.恶行，恶习；副，代理','/vaɪs/','/vaɪs/','noun',["Gluttony is a vice, not a virtue."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('esteem','n&vt.尊重，敬重','[ɛsˈtiːm]','[ɛsˈtiːm]','noun',["We hold her in high esteem.","Mary is an esteemed member of the community.","The Earth, which I esteem unable to reflect the rays of the Sun."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outweigh','vt.超过','/ˌaʊtˈweɪ/','/ˌaʊtˈweɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shear','v.剪；切断，剪切','/ʃɪə(ɹ)/','/ʃiɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wedge-shaped','adj.楔形的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alga','n.水藻','/ˈæl.ɡə/','/ˈæl.ɡə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dupe','n.上当者vt.欺骗，愚弄','/djuːp/','/djuːp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meteor','n.流星','/ˈmiːtɪɔː/','/ˈmitiɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('empower','v.授权，准许；使控制局势','','','verb',["John found that starting up his own business empowered him greatly in social situations."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gravitational','adj.重力的，万有引力的','/ˌɡɹævɪˈteɪʃənəl/','/ˌɡɹævɪˈteɪʃənəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wrinkle','v.起皱纹n.皱纹','/ˈɹɪŋkl̩/','/ˈɹɪŋkl̩/','noun',["Spending time out in the sun may cause you to develop wrinkles sooner.","Three months later, we''re still discovering new wrinkles.","Be careful not to wrinkle your dress before we arrive."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('calm','adj.平静的；镇静的，沉着的vt.使平静，使镇定，平息','/kam/','/kɑlm/','noun',["to calm a crying baby"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supervise','vt.监督；指导','','','verb',["Without someone to supervise them, the group will lack direction."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fabulous','adj.寓言式的；难以置信的；极好的','/ˈfæbjʊləs/','/ˈfæbjʊləs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dilemma','n.困境，进退两难的局面','/daɪˈlɛmə/','/daɪˈlɛmə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rub','n&v.擦，摩擦','/ɹʌb/','/ɹʌb/','noun',["Give that lamp a good rub and see if any genies come out","a heat rub intended for muscular strains","I rubbed my hands together for warmth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('through','adv.从头到尾，自始至终；直达，径直；彻底，完全adj.完成的，结束的；直达的，直通的prep.穿过，通过；从头到尾，自始至终；经由，以；因为，由于','/θɹuː/','/θɹu/','noun',["Interstate highways form a nationwide system of through roads.","They were through with laying the subroof by noon.","After being implicated in the scandal, he was through as an executive in financial services."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rug','n.地毯；围毯','/ɹʌɡ/','/ɹʌɡ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hieroglyph','n.象形文字，象形符号','/ˈhaɪɹəˌɡlɪf/','/ˈhaɪɹəˌɡlɪf/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('towering','adj.高耸的；杰出的','/ˈtaʊəɹɪŋ/','/ˈtaʊəɹɪŋ/','verb',["The office block towered into the sky."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('occasional','adj.偶然的，不经常的；临时的','/əˈkeɪʒ(ə)nəl/','/əˈkeɪʒ(ə)nəl/','noun',["He took an occasional glass of wine.","Elgar''s music was not created to be occasional music for high-school graduations.","What your living room needs are some occasional chairs."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enact','v.制定法律，颁布；扮演','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deviant','adj.不正常的，越出常规的n.不正常的人','/ˈdiː.vi.ənt/','/ˈdiː.vi.ənt/','noun',["He was branded as a deviant and ostracized.","As the graph shows, the March sales trend is the deviant.","At the trial, the extent of his deviant behavior became clear."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pharaoh','n.法老','/ˈfɛəɹəʊ/','/ˈfɛəɹəʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scrutinize','v.仔细检查，细察','/ˈskɹuːtɨnaɪz/','/ˈskɹuːtɨnaɪz/','verb',["to scrutinize the conduct or motives of individuals"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('realtor','n.房地产经纪人','/ˈɹi(ə)l.tɔɹ/','/ˈɹi(ə)l.tɔɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spacecraft','n.航天器，宇宙飞船','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extinguish','vt.熄灭，扑灭；消灭，毁灭，使破灭','/ɪkˈstɪŋ.ɡwɪʃ/','/ɪkˈstɪŋ.ɡwɪʃ/','verb',["She extinguished all my hopes.","The rays of the sun were extinguished by the thunder clouds.","Many patients can extinguish their phobias after a few months of treatment."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preach','v.布道，讲道；竭力鼓吹，宣讲，宣传；说教','/pɹiːt͡ʃ/','/pɹiːt͡ʃ/','noun',["A learned local Muslim used to preach in the small mosque every Friday."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fibrous','adj.含纤维的；纤维状的','/ˈfaɪbɹəs/','/ˈfaɪbɹəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recollection','n.记忆力；回忆，记忆；回想起来的事','/ɹɛkəˈlɛkʃən/','/ɹɛkəˈlɛkʃən/','noun',["Alas that distant event isn''t within my recollection anymore.","From such an education Charles contracted habits of gravity and recollection."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subjugate','vt.征服，制伏，使服从','/ˈsʌbdʒuɡeɪt/','/ˈsʌbdʒuɡeɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('donate','vt.捐赠；赠送','/dəʊˈneɪt/','/doʊˈneɪt/','verb',["He donated an etching from his own collection to the new art gallery."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bonanza','n.富矿带；带来好运的事；兴盛，繁荣','/bəˈnænzə/','/bəˈnænzə/','noun',["The popular show quickly became a ratings bonanza for the network."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nicotine','n.尼古丁','/ˈnɪkətiːn/','/ˈnɪkətiːn/','noun',["He is addicted to nicotine."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('taboo','adj.忌讳的n.禁忌，忌讳；禁止，避讳','/tæˈbuː/','/tæˈbuː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bold','adj.大胆的；冒失的；粗体的；醒目的','/bəʊld/','/boʊld/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tentacle','n.触角，触须，触手','/ˈtɛntəkəl/','/ˈtɛntəkəl/','noun',["the tentacles of the criminal underworld"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overlap','v.交叠，部分重叠n.重叠；重叠的部分','/ˈəʊvəˌlæp/','/ˈəʊvəˌlæp/','noun',["The mouse-mat overlapped the edge of the desk.","The two maps overlapped at the east and west edges.","The set (all men) overlaps the set (vegetarians)."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assassinate','vt.暗杀，行刺；诋毁','/əˈsasɪneɪt/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bolt','v.逃跑；闩上n.插销，门闩；闪电','/bɒlt/','/boʊlt/','noun',["The problem''s solution struck him like a bolt from the blue.","24 March 1774 - Newspaper: Stamford Mercury - \"Mr. Cole, Basket-maker...has lost near 300 boults of rods\" https//www.britishnewspaperarchive.co.uk/viewer/bl/0000254/17740324/001/0001","The horse made a bolt."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('congressional','adj.立法机构的；代表大会的；国会的','/kəŋˈɡɹɛʃn̩əl/','/kəŋˈɡɹɛʃn̩əl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boon','n.恩惠，恩赐；益处','/buːn/','/buːn/','noun',["Anaesthetics are a great boon to modern surgery."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abolish','vt.废止，废除','/əˈbɒlɪʃ/','/əˈbɑl.əʃ/','verb',["Slavery was abolished in the nineteenth century."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('critique','n.批评，评论vt.写评论','/kɹɪˈtiːk/','/kɹɪ.ˈtik/','noun',["Bob liked most of my presentation, but offered three minor critiques.","I want you to critique this new idea of mine."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cautious','adj.小心的，谨慎的','/ˈkɔːʃəs/','/ˈkɔːʃəs/','adjective',["He took a few cautious steps toward the cave."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recession','n.衰退，衰退时期，萧条时期；撤回，退回','/ɹɪˈsɛʃn̩/','/ɹɪˈsɛʃn̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('situated','adj.坐落在…的；处于…境地的','/ˈsɪt͡ʃueɪtɪd/','/ˈsɪt͡ʃueɪtɪd/','verb',["The statue is situated in a corner hardly visible to the public, except through a window from an outside maintenance area situated behind the building.","The mayor is situated between probable censure and possible recall."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('malicious','adj.怀有恶意的，恶毒的','/məˈlɪʃəs/','/məˈlɪʃəs/','adjective',["He was sent off for a malicious tackle on Jones."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vigilance','n.警戒，警惕','/ˈvɪdʒɪləns/','/ˈvɪdʒɪləns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ally','v.结盟n.同盟国；结盟者，支持者','','','noun',["the two countries were allies in WWI","Gruiformes — cranes and allies"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concentric','adj.同心的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outrageous','adj.残暴的；骇人的；反常的，过度的','/aʊtˈɹeɪdʒəs/','/aʊtˈɹeɪdʒəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abbreviate','vt.缩略，缩写','/ə.ˈbɹiː.vi.eɪt/','/əˈbɹi.vi.eɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lavish','adj.大方的，慷慨的；大量的；浪费的vt.慷慨给予，滥用；浪费，挥霍','/ˈlævɪʃ/','/ˈlævɪʃ/','verb',["They lavished money on the dinner.","They lavished him with praise.","lavish of money;   lavish of praise"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('varnish','vt.上清漆n.清漆','/ˈvɑː(ɹ)nɪʃ/','/ˈvɑː(ɹ)nɪʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('momentum','n.动量；动力，冲力；势头','/ˌmoʊˈmɛntəm/','/ˌmoʊˈmɛntəm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discourse','vi.讲述，论述n.演讲；论文；话语','/dɪsˈkɔː(ɹ)s/','/dɪsˈkɔː(ɹ)s/','noun',["The preacher gave us a long discourse on duty."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obstruct','vt.妨碍，阻挠；阻塞','/əbˈstɹʌkt/','/əbˈstɹʌkt/','verb',["They obstructed my progress."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bony','adj.瘦骨嶙峋的；似骨的；多骨的','/ˈbəʊni/','/ˈbəʊni/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('labyrinth','n.迷宫；错综复杂的事件','/ˈlab.(ə)ɹ.ɪnθ/','/ˈlæb.ɚ.ɪnθ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aquatic','adj.水生的；水上的','/ɘˈkwɔ.tɘk/','/əˈkwæ.tɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cape','n.海角，岬；斗篷，披肩','/keɪp/','/keɪp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('microprocessor','n.微处理器','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rebel','vi.造反，起义，反抗n.叛逆者，起义者','/ˈɹɛbəl/','/ˈɹɛbəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modeling','n.立体感；建模，造型','','','verb',["She modelled the shoes for her friends to see.","They modelled the data with a computer to analyze the experiment’s results.","He takes great pride in his skill at modeling airplanes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bounce','v.弹起，反弹n.弹跳；反弹力','/baʊns/','/baʊns/','noun',["Them pro-ballers got bounce!","The tennis ball bounced off the wall before coming to rest in the ditch.","He bounces nervously on his chair."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cart','n.运货马车；手推车vt.用车装运','/kɑːt/','/kɑɹt/','noun',["The grocer delivered his goods by cart.","I''ve been carting these things around all day."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anxious','adj.渴望的；担忧的；令人焦虑的','/ˈaŋ(k)ʃəs/','/ˈæŋ(k).ʃəs/','adjective',["I could tell she was anxious as she was biting her nails.","There was an anxious wait before the results were revealed.","All the voters were anxious to hear the election result."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slice','n.薄片；部分，份额vt.把…切成片','/slaɪs/','/slaɪs/','noun',["Jim was munching on a slice of toast.","I bought a ham and cheese slice at the service station.","Slice the cheese thinly."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('auditory','adj.耳的；听觉的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burrow','v.挖掘，挖地洞；寻找，','/ˈbʌɹəʊ/','/ˈbɜɹoʊ/','noun',["The young girl burrowed into the bed.","The journalist burrowed into the origins of the mayor''s corruption."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incline','v.倾斜；倾向于n.斜坡，斜面','','','noun',["To reach the building, we had to climb a steep incline.","He had to incline his body against the gusts to avoid being blown down in the storm.","Over the centuries the wind made the walls of the farmhouse incline."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('olfactory','adj.嗅觉的','/ɒlˈfæk.təɹ.ɪ/','/oʊlˈfæk.təɹ.i/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elevate','vt.举起，抬高；提升职位；使情绪高昂，使兴高采烈','/ˈɛləveɪt/','/ˈɛləveɪt/','verb',["The doctor told me elevating my legs would help reduce the swelling.","The traditional worldview elevates man as the pinnacle of creation.","A talented chef can elevate everyday ingredients into gourmet delights."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slick','adj.光滑的；熟练的；圆滑的，口齿伶俐的；精巧的，巧妙的','/slɪk/','/slɪk/','noun',["Careful in turn three — there''s an oil slick on the road.","You''ll go much faster if you put on slicks.","The project was delayed because the slick had not been delivered to the printer."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oppressive','adj.压迫的，压制的；令人焦虑的','','','adjective',["The oppressive tax laws made it difficult to start a small company.","The oppressive land-owners kept a grip on the labourers.","Will the oppressive heat of summer never end?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('canvas','n.画布；油画；帆布','/ˈkæn.vəs/','/ˈkæn.vəs/','noun',["The author takes rural midwestern life as a canvas for a series of tightly woven character studies.","He spent the night under canvas."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superintendent','n.主管，负责人；指挥者，管理者；警长','/ˌsjuːpəɹɪnˈtɛndənt/','/ˌsjuːpəɹɪnˈtɛndənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invasive','adj.侵入的，侵略的；开刀的','/ɪnˈveɪsɪv/','/ɪnˈveɪsɪv/','noun',["an invasive species"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('calculable','adj.可计算的；能预测的；可信的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shipwright','n.造船者，造船工人；修船工','/ˈʃɪpɹaɪt/','/ˈʃɪpɹaɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('epic','adj.史诗般的；艰苦卓绝的；壮丽的，宏大的n.史诗；史诗般的电影；壮举','/ˈɛp.ɪk/','/ˈɛp.ɪk/','noun',["The Icelandic epic took all night to recite.","The book was an epic in four volumes.","Beowulf is an epic poem."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('downtown','adv.在市中心；往市中心adj.市中心的','','','noun',["John walked every day to his downtown job.","You need to go downtown four blocks.","That shot came from way downtown!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moor','v.停泊，系泊n.沼泽；旷野，荒野','/mɔː/','/mɔɹ/','noun',["A cold, biting wind blew across the moor, and the travellers hastened their step."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hydrothermal','adj.热液的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sticky','adj.黏的，黏性的；闷热的；棘手的','/ˈstɪki/','/ˈstɪki/','noun',["Her desk is covered with yellow stickies.","Is this tape sticky enough to stay on that surface?","This is a sticky situation. We could be in this for weeks if we''re not careful."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grill','vt.烧烤；拷问，盘问n.烤架','/ɡɹɪl/','/ɡɹɪl/','noun',["I put some peppers and mushrooms on the grill to go with dinner.","a packet of frozen cauliflower cheese grills","These coupons will get you a discount at Johnny''s Bar and Grill."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pattern','n.模式，方式；样式，图案；样品，样本vt.仿制；使形成，促成','/ˈpat(ə)n/','/ˈpat(ə)n/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('increment','n.增加；增量；定期的加薪','/ˈɪŋkɹɪmn̩t/','/ˈɪŋkɹɪmn̩t/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smother','vt.使窒息而死；厚厚地覆盖；抑制，扼杀；把闷熄','','/ˈsmʌðɚ/','verb',["to smother a fire with ashes","The committee''s report was smothered.","beefsteak smothered with onions"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cramped','adj.狭小的，狭窄的；受限制的；密小难认的','/kɹæmpt/','/kɹæmpt/','verb',["You''re cramping my style.","You''re going to need to cramp the wheels on this hill.","to cramp boot legs"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scrape','v.刮掉，擦掉；发出刺耳的刮擦声；','/skɹeɪp/','/skɹeɪp/','noun',["He fell on the sidewalk and got a scrape on his knee.","He got in a scrape with the school bully.","I''m in a bit of a scrape — I''ve no money to buy my wife a birthday present."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bleak','adj.阴冷的；无望的，令人沮丧的；乏味的；荒凉的','/bliːk/','/bliːk/','adjective',["A bleak and bare rock.","A bleak future is in store for you."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meteorological','adj.气象学的；气象的','/ˌmiːtɪəɹəˈlɒd͡ʒɪkl̩/','/ˌmiːtɪəɹəˈlɒd͡ʒɪkl̩/','adjective',["The trip was postponed because the meteorological conditions were so bad."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cushion','vt.起缓冲作用n.垫子','/ˈkʊʃən/','/ˈkʊʃən/','noun',["to cushion a sofa","to cushion a blow"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glorious','adj.壮丽的，辉煌的；光荣的；令人愉快的，极好的','/ˈɡlɔː.ɹi.əs/','/ˈɡlɔɹ.i.əs/','adjective',["glorious deeds"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bilateral','adj.有两边的；双边的','/baɪˈlætəɹəl/','/baɪˈlætəɹəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plateau','vi.保持稳定水平n.高原；稳定期，停滞期','/ˈplætəʊ/','/plæˈtoʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aptitude','n.适合，恰当；天资，才能，资质','/ˈæptɪˌtjuːd/','/ˈæptɪˌtjuːd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('daisy','n.雏菊；一流的人物','/ˈdeɪ.zi/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gnaw','v.啃，咬','/nɔː/','/nɔː/','verb',["The dog gnawed the bone until it broke in two.","Her comment gnawed at me all day and I couldn''t think about anything else."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disorder','n.混乱，凌乱；动乱，骚乱；失调，紊乱','/dɪsˈɔːdə(ɹ)/','/dɪsˈɔːɹdɚ/','noun',["After playing the children left the room in disorder.","The army tried to prevent disorder when claims the elections had been rigged grew stronger.","Bulimia is an eating disorder."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aggravate','vt.恶化，加重；激怒','/ˈæɡ.ɹə.veɪ̯t/','/ˈæɡ.ɹə.veɪ̯t/','verb',["He aggravated the story."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disquiet','v.不安，忧虑n.不安，忧虑','/dɪsˈkwaɪət/','','noun',["He felt disquieted by the lack of interest the child had shown."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('addictive','adj.使人上瘾的；使人沉醉的，醉心的','/əˈdɪktɪv/','/əˈdɪktɪv/','noun',["These are addictive drugs.","Have you seen that new TV show? It''s so addictive.","He has an addictive personality."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yarn','n.纱，纱线；故事','/jɑːn/','/jɑɹn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spurn','vt&n.拒绝；摈弃','/spɜːn/','/spɚn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plaque','n.匾额；牙斑','/plaːk/','/plæk/','noun',["blown plaques  concussion plaques","amyloid plaque  pleural plaque  senile plaque"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('membrane','n.薄膜；细胞膜','/ˈmembɹeɪn/','/ˈmembɹeɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scavenger','n.捡破烂的人，拾荒者；食腐动物','/ˈskæv.ən.dʒə(ɹ)/','/ˈskæv.ən.dʒə(ɹ)/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alleviate','vt.减轻，缓解，缓和','/əˈli.vi.eɪt/','/əˈli.vi.eɪt/','verb',["Alcohol is often a cheap tool to alleviate the stress of a hard day."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('talent','n.天赋；才干；人才','/ˈtalənt/','/ˈtælənt/','noun',["He has a real talent for drawing.","The director searched their talent pool to fill the new opening.","Not much talent in this bar tonight—let''s hit the clubs."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scoff','vi.嘲笑，讥笑','/skɒf/','/skɔːf/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sacrificial','adj.供奉的，献祭的，牺牲的','/ˈsæk.ɹə.fɪʃ.əl/','/ˈsæk.ɹə.fɪʃ.əl/','adjective',["The old sacrificial well is still there, but animals aren''t thrown into it to appease monsters anymore.","The ceremony involves the ritual slaying of a sacrificial lamb."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negotiate','v.谈判，商议；商定，达成；通过，越过','/nəˈɡəʊ.ʃi.eɪt/','/nəˈɡoʊ.ʃi.eɪt/','verb',["The client and server computers must first negotiate a network protocol to be used.","Although the car was quite rickety, he could negotiate the curves very well."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('germ','n.微生物，细菌；萌芽','/d͡ʒɜːm/','/d͡ʒɝm/','noun',["the germ of civil liberty"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shatter','v.粉碎，破碎；破灭；散开，吹散；给予极大打击','/ˈʃæt.ə(ɹ)/','/ˈʃæt.ɚ/','noun',["to break a glass into shatters","The miners used dynamite to shatter rocks.","to be shattered in intellect; to have shattered hopes, or a shattered constitution"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('credentialism','n.文凭主义','/kɹəˈdɛn.ʃə.lɪ.zəm/','/kɹəˈdɛn.ʃə.lɪ.zəm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glimpse','n.一看，一瞥vt.瞥见','/ɡlɪmps/','/ɡlɪmps/','noun',["I only got a glimpse of the car, so I can tell you the colour but not the registration number.","I have only begun to glimpse the magnitude of the problem."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moss','n.苔藓','/mɑs/','/mɔs/','noun',["Irish moss","the mosses of the Scottish border","An oak whose boughs were mossed with age."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('detective','adj.侦探的n.侦探，私人侦探','/dɪˈtɛktɪv/','/dɪˈtɛktɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resin','n.树脂','/ˈɹɛzɪn/','/ˈɹɛzɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affection','n.喜爱，钟爱；','/əˈfɛkʃən/','/əˈfɛkʃən/','noun',["I have a lot of affection for my little sister."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diversion','n.消遣，娱乐；转移，转换','/daɪˈvɜːʃən/','/daɪˈvɝʒən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('omit','vt.省略，删去；遗漏，忽略','/oʊˈmɪt/','/oʊˈmɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('courteous','adj.谦恭的，有礼貌的','/ˈkɜːti.əs/','/ˈkɝti.əs/','adjective',["a courteous gentleman   a courteous gesture"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jog','vi.慢跑；轻轻触碰','/dʒɒɡ/','/dʒɑɡ/','noun',["jog one''s elbow","I tried desperately to jog my memory.","to jog a horse"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ascertain','vt.弄清，查明','/ˌæsəˈteɪn/','/ˌæsɚˈteɪn/','verb',["As soon as we ascertain what the situation is, we can plan how to proceed."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jot','vt.草草记下，匆匆记下','/dʒɒt/','/dʒɒt/','noun',["He didn''t care a jot for his work.","Tell me your order, so I can jot it down."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('highlight','vt.强调，突出；以强烈光线照射n.最精彩部分','/ˈhaɪ.ˌlaɪt/','/ˈhaɪ.ˌlaɪt/','noun',["Meeting my future wife was the highlight of my trip to Spain."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('database','n.数据库','/ˈdeɪtəˌbeɪs/','/ˈdeɪtəˌbeɪs/','noun',["I have a database of all my contacts in my personal organizer.","The \"books\" database will have three tables, and the \"customers\" database will have two tables.","Which database do you use: MySQL or Oracle?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sac','n.囊，液囊','/sæk/','/sæk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patient','adj.有耐心的，能忍耐的n.病人，患者','/ˈpeɪʃənt/','/ˈpeɪʃənt/','noun',["The subject of a passive verb is usually a patient.","Be patient: your friends will arrive in a few hours.","patient endeavour"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compliment','vt.赞美，称赞n.赞美；','/ˈkɒmplɪmənt/','/ˈkɑmpləmənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miracle','n.奇事，奇迹','/ˈmiɹəkəl/','/ˈmiɹəkəl/','noun',["An example of a miracle associated with Muhammad is the splitting of the moon."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rinse','vt.冲洗，漂洗，冲刷n.漂洗，冲洗，洗涤；染发剂','/ɹɛns/','/ɹɛns/','noun',["I''ll just give this knife a quick rinse.","You''d better rinse that stain before putting the shirt in the washing machine.","Rinse the dishes after you wash them."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amount','vi.总计n.总额','/əˈmaʊnt/','/əˈmaʊnt/','noun',["The amount of atmospheric pollution threatens a health crisis.","Pour a small amount of water into the dish.","It amounts to three dollars and change."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comply','vi.服从；遵守','/kəmˈplaɪ/','/kəmˈplaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sap','vt.使衰竭；削弱，逐渐破坏n.液，汁；精力；笨蛋','/sæp/','/sæp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spellbind','vt.用妖术迷惑；迷住，使入迷','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nectar','n.花蜜；甘美的饮料，琼浆玉液','/ˈnɛk.tə/','/ˈnɛk.tə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feudal','adj.封建的','[ˈfju.ɾɫ̩]','[ˈfju.ɾɫ̩]','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kingdom','n.王国；领域，界','/ˈkɪŋdəm/','/ˈkɪŋdəm/','noun',["the kingdom of the dead"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('puppet','n.木偶；玩偶；傀儡，受人操纵的人','/ˈpʌpɪt/','/ˈpʌpɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('educated','adj.受过教育的，有教养的','/ˈɛdjuːkeɪtɪd/','/ˈɛdjuːkeɪtɪd/','verb',["Wang said such changes to the Baishui glacier provide the chance to educate visitors about global warming."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clinic','n.门诊部，诊所','/ˈklɪnɪk/','/ˈklɪnɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affiliate','vt.使隶属于n.分公司','/əˈfɪl.i.et/','/əˈfɪl.i.et/','noun',["Our local TV channel is an affiliate of NBC.","to affiliate the child to (or on or upon) one man rather than another"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recessive','adj.隐性的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('momentary','adj.片刻的，瞬间的，暂时的','/ˈməʊmənt(ə)ɹi/','/ˈməʊmənt(ə)ɹi/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hypocritical','adj.伪善的，虚伪的','/hɪpəˈkɹɪtɪkəl/','/hɪpəˈkɹɪtɪkəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('constricted','adj.狭窄的；收缩的；抑制的，约束的','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sensational','adj.轰动性的，引起哗然的，耸人听闻的；〈口〉极好的，绝妙的','','','adjective',["sensational nerves"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('canoe','vi.乘独木舟，划独木舟n.独木舟','/kəˈnuː/','/kəˈnuː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wedge','n.楔子；楔形物vt.■入，塞入','/wɛdʒ/','/wɛdʒ/','noun',["Stick a wedge under the door, will you? It keeps blowing shut.","Can you cut me a wedge of cheese?","I made a big fat wedge from that job."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alienate','vt.使疏远，使不友好；转让，让渡','/ˈeɪ.li.ə.neɪt/','/ˈeɪ.li.ə.neɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awake','v.唤醒；醒；觉醒，醒悟adj.醒着的；警觉的','/əˈweɪk/','/əˈweɪk/','adjective',["They were awake to the possibility of a decline in sales."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plague','vt.困扰，使苦恼；纠缠n.鼠疫；传染病；祸患，灾害','/pleɪɡ/','/pleɪɡ/','noun',["Ten Biblical plagues over Egypt, ranging from locusts to the death of the crown prince, finally forced Pharaoh to let Moses''s people go.","Bart is an utter plague; his pranks never cease.","Natural catastrophes plagued the colonists till they abandoned the pestilent marshland."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perpetual','adj.连续不断的；永久的，长期的','/pəˈpɛtjʊəl/','/pɚˈpɛtʃuəl/','adjective',["By means of artificial hybridization, practised for a series of years, he has succeeded in producing a race of carnations which are perpetual bloomers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retrospect','n.回顾，反顾','/ˈɹɛtɹoˌspɛkt/','/ˈɹɛtɹoˌspɛkt/','noun',["1800: Alexander Hamilton, Letter from Alexander Hamilton, Concerning the Public Conduct and Character of John Adams, Esq. President of the United States - To give a correct idea of the circumstances.., it may be useful to retrospect to an early period."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fascinate','v.深深吸引，迷住','/ˈfæsɪneɪt/','/ˈfæsɪneɪt/','verb',["The flickering TV fascinated the cat.","We were fascinated by the potter''s skill.","Her gait fascinates all men."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diplomatic','adj.外交的，从事外交的；有策略的，有手腕的，老练的','/ˌdɪpləˈmætɪk/','/ˌdɪpləˈmætɪk/','noun',["Albania immediately severed diplomatic relations with Zimbabwe.","Thoughtful corrections can be diplomatic as well as instructional.","Whereas a diplomatic edition uses as its base text a single, \"best\" manuscript, to which other textual evidence is collated and organized into an apparatus, a critical text of the LXX/OG [= Septuagint or Old Greek] may be described as a collection of the oldest recoverable texts, carefully restored book by book (or section by section), aiming at achieving the closest approximation to the original translations (from Hebrew or Aramaic) or compositions (in Greek), systematically reconstructed from the widest array of relevant textual data (including controlled conjecture).  The International Organization for Septuagint and Cognate Studies, Critical Editions of Septuagint/Old Greek Texts."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('draft','adj.供役使的n.草图，草稿；汇票；气流vt.起草；征募，选派','/dɹæft/','/dɹæft/','noun',["She took a deep draft from the bottle of water.","His first drafts were better than most authors'' final products.","He left the country to avoid the draft."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loath','adj.不情愿的，勉强的','/ləʊθ/','/ləʊθ/','adjective',["I was loath to return to the office without the Henderson file."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pamphlet','n.小册子','/ˈpæmf.lɪt/','/ˈpæmf.lɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('healthful','adj.有益健康的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('posit','vt.安排；假定','/ˈpɒzɪt/','/ˈpɒzɪt/','noun',["Chief of Staff is the second-highest position in the army.","My position on this issue is unchanged.","Stand in this position, with your arms at your side."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ornate','adj.华丽的，豪华的','','/ɔɹˈneɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('documentation','n.文件；归档，文献记录','/ˌdɒkjʊmənˈteɪʃən/','/ˌdɒkjʊmənˈteɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proliferate','vi.激增，迅速繁殖','/pɹəˈlɪf.əɹ.eɪt/','/pɹəˈlɪf.əɹ.eɪt/','verb',["The flowers proliferated rapidly all spring."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('onslaught','n.冲击；攻击，猛攻','/ˈɒnslɔːt/','/ˈɒnslɔːt/','noun',["They opened the doors and prepared for the onslaught of holiday shoppers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transient','adj.短暂的，转瞬即逝的；临时的','','','noun',["a transient pleasure","a transient disease"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disrepute','n.坏名声，不光彩','/dɪsɹɪˈpjuːt/','/dɪsɹɪˈpjuːt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plank','n.木板；政策要点，政纲的核心','/plæŋk/','/plæŋk/','noun',["Germanization was a central plank of German conservative thinking in the 19th and 20th centuries.","to plank a floor or a ship","to plank money in a wager"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heyday','n.全盛期','/ˈheɪdeɪ/','/ˈheɪdeɪ/','noun',["The early twentieth century was the heyday of the steam locomotive."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sponge','v.用海绵擦，揩n.海绵；寄生虫','/spʌnd͡ʒ/','/spʌnd͡ʒ/','noun',["He has been sponging off his friends for a month now.","to sponge a breakfast"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spaghetti','n.意大利式细面条','[spəˈɡɛɾi]','[spəˈɡɛɾi]','noun',["The cables spaghettied onto the shoulder of the technician.","He spaghettied the referee when he landed on him."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smoothly','adv.顺利地；平稳地；平静地','/ˈsmuːðli/','/ˈsmuːðli/','adverb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indicate','v.表明，显示；指出，指示；象征，预示；暗示，间接提及','/ˈɪndɪkeɪt/','/ˈɪndɪkeɪt/','verb',["The guard blew his whistle to indicate imminent departure.","Great prostration of strength indicates the use of stimulants."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('metabolic','adj.新陈代谢的','','','noun',["metabolic activity"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('completion','n.完成，实现；结束','/kəmˈpliːʃən/','/kəmˈpliːʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contain','vt.包含，容纳；控制；防止…蔓延','/kənˈteɪn/','/kənˈteɪn/','verb',["I''m so excited, I can hardly contain myself!","A group contains a unique inverse for each of its elements."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('litter','v.乱扔；使凌乱n.废弃物，垃圾；一窝幼崽','/ˈlɪtə(ɹ)/','/ˈlɪtɚ/','noun',["sleep in the litter","drop litter","the cat''s litter"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sew','v.缝，做针线活；缝补，缝上','/səʊ/','/soʊ/','verb',["Balls were first made of grass or leaves held together by strings, and later of pieces of animal skin sewn together and stuffed with feathers or hay.","to sew money into a bag"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oval','adj.卵形的，椭圆形的n.卵形，椭圆形','/ˈəʊvəl/','/ˈəʊvəl/','noun',["oval conceptions"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indigent','adj.贫困的，贫穷的','/ˈɪndɪd͡ʒənt/','/ˈɪndɪd͡ʒənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('biography','n.传记','/baɪˈɒɡɹəfi/','/baɪˈɑːɡɹəfi/','noun',["There are many biographies of Benjamin Franklin."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('operant','adj.运转中的；生效的；操作性的n.起作用的人','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cellist','n.大提琴演奏家','/ˈt͡ʃɛlɪst/','/ˈt͡ʃɛlɪst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('applicant','n.申请者','/ˈæp.lə.kɪnt/','/ˈæp.lə.kɪnt/','noun',["Our job advertisement attracted seven applicants."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awesome','adj.使人敬畏的；使人恐惧的','/ˈɔːsəm/','/ˈɔs.əm/','noun',["pure awesome; made of awesome","The tsunami was awesome in its destructive power.","Awesome, dude!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admiration','n.钦佩，赞赏，羡慕','/ˌæd.mɚˈeɪʃ.ən/','/ˌæd.mɚˈeɪʃ.ən/','noun',["They looked at the landscape in admiration."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pique','vt.激怒；激起，引起n.恼怒，生气；怨恨','/piːk/','/piːk/','noun',["I believe this will pique your interest."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('planetary','adj.行星的','/ˈplæ.nə.ˌtɛr.i/','/ˈplæ.nə.ˌtɛr.i/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ultraviolet','adj.紫外的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diagnose','v.诊断；判断','/daɪəɡˈnəʊz/','/daɪəɡˈnəʊz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('petition','v.请愿，正式请求n.请愿；请愿书；诉状','/pəˈtɪ.ʃən/','/pəˈtɪ.ʃən/','noun',["The villagers petitioned the council to demolish the dangerous building."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vicinity','n.邻近，附近','/vəˈsɪnəti/','/vəˈsɪnəti/','noun',["There was a crackling sound in the vicinity of my right ear.","There is a hurricane in the vicinity of the Bahamas.","I weigh in the vicinity of 80kg."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('earnest','adj.认真的；真诚的n.诚挚；认真','/ˈɜːnɪst/','/ˈɝnɪst/','noun',["earnest prayers","earnest attention.","an earnest disposition"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('validity','n.合法性；符合逻辑','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crevice','n.缺口，裂缝','/ˈkɹɛvɪs/','/ˈkɹɛvɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humorous','adj.幽默的，滑稽的，诙谐的','/ˈhjuːməɹəs/','/ˈhjuːməɹəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bet','v.打赌；敢说，确信n.打赌；赌注','/ˈbɛt/','/ˈbɛt/','noun',["Dylan owes Fletcher $30 from an unsuccessful bet.","It’s a safe bet that it will rain tomorrow.","Fancy going for a drink after work?\nYou bet I do!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('differentiate','v.不同，区别','/dɪf.əˈɹɛn.ʃi.eɪt/','/ˌdɪ.fəˈɹɛnt.ʃi.eɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plaster','v.在…上抹灰泥，厚厚地涂n.灰浆，灰泥，石膏','/ˈplastə/','/ˈplæstɚ/','noun',["to plaster a wall","to plaster a wound","Her face was plastered with mud."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('metropolitan','adj.大都市的；本土的','/mɛtɹəˈpɒlɪtən/','/mɛtɹəˈpɒlɪtən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eclecticism','n.折中主义','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garbage','n.垃圾，废物；废话，无聊的东西；垃圾箱','/ˈɡɑːbɪd͡ʒ/','/ɡɑ(ɹ)ˈbɑːʒ/','noun',["Garbage is collected on Tuesdays; rubbish on Fridays","The garbage truck collects all residential municipal waste.","He threw the newspaper into the garbage."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suspicious','adj.可疑的，令人怀疑的；不信任的，猜疑的，多疑的','/səˈspɪ.ʃəs/','/səˈspɪ.ʃəs/','adjective',["His suspicious behaviour brought him to the attention of the police.","I have a suspicious attitude to get-rich-quick schemes.","She gave me a suspicious look."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complain','v.诉苦，抱怨；投诉；控告','/kəmˈpleɪn/','/kəmˈpleɪn/','verb',["Joe was always complaining about the noise made by his neighbours.","They''ve complained about me to the police again.","the complaining bed-springs"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('polygamy','n.一夫多妻制，一妻多夫制，多配偶制','/pəˈlɪɡəmi/','/pəˈlɪɡəmi/','noun',["Are there countries where polygamy is legal for both men and women?","An insect queen actually practices polygamy only one day, while for an alpha-male defending his harem is the very essence of both his status and polygamy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('renovate','vt.修复；更新，翻新','/ˈɹenəʊveɪt/','/ˈɹenəʊveɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perpendicular','adj.成直角的，垂直的n.垂直线','/ˌpɜː.pənˈdɪk.jə.lə(ɹ)/','/pɝ.pənˈdɪk.jə.lɚ/','noun',["In most houses, the walls are perpendicular to the floor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ordinate','n.纵坐标','/ˈɔːdənət/','/ˈɔːdənət/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deem','vt.认为，相信','/diːm/','/diːm/','noun',["She deemed his efforts insufficient."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stiffen','v.变僵硬；变坚定，变强硬','/ˈstɪfən/','/ˈstɪfən/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compel','vt.驱使，强迫','/kəmˈpɛl/','/kəmˈpɛl/','verb',["Logic compels the wise, while fools feel compelled by emotions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depress','vt.降低，削弱；使沮丧；使萧条','/dɪˈpɹɛs/','/dɪˈpɹɛs/','verb',["Depress the upper lever to start the machine.","Winter depresses me.","Lower productivity will eventually depress wages."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pendant','n.垂饰，下垂物','/ˈpɛnd(ə)nt/','/ˈpɛnd(ə)nt/','noun',["One vase is the pendant to the other vase."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('riddle','n.谜；谜语；难解之谜；粗筛vt.使布满窟窿','/ˈɹɪdəl/','/ˈɹɪdəl/','noun',["Here''s a riddle: It''s black, and white, and red all over. What is it?","Riddle me this."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apprise','vt.通知，告诉','/əˈpɹaɪ̯z/','/əˈpɹaɪ̯z/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('candid','adj.坦白的，直率的，直言不讳的','/ˈkæn.dɪd/','/ˈkæn.dɪd/','noun',["His portraits looked stiff and formal but his candids showed life being lived."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conversion','n.转变，变换；改变信仰，皈依','/-ʒ(ə)n/','/kənˈvɝʒən/','noun',["His conversion to Christianity","the conversion of a horse","the conversion of equations; the conversion of proportions"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deductive','adj.演绎的，推论的','/dɪˈdʊktɪv/','/dɪˈdʊktɪv/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breathing','n.呼吸','/ˈbɹiːðɪŋ/','/ˈbɹiːðɪŋ/','verb',["Fish have gills so they can breathe underwater.","While life as we know it depends on oxygen, scientists have speculated that alien life forms might breathe chlorine or methane.","I will not allow it, as long as I still breathe."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('falter','v.衰退，衰落；发抖，结巴地说；蹒跚','/ˈfɒltə(r)/','/ˈfɒltə(r)/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elusive','adj.难以理解的，难懂的；难捕捉的；逃避的','/iˈluːsɪv/','/ɪˈluːsɪv/','adjective',["The elusive criminal was arrested","A precise definition of diarrhea is elusive (Robbin''s pathology, 8th ed)"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appraise','vt.估价；估量；评价，评定','/əˈpɹeɪz/','/əˈpɹeɪz/','verb',["to appraise goods and chattels","At the end of the contract, you will be appraised by your line manager."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pyramid','n.金字塔；锥体；金字塔形物；金字塔式的组织','/ˈpɪɹəmɪd/','/ˈpɪɹəmɪd/','noun',["Build your pyramid with all cards face down, except the cards in the bottom row."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comprehensive','adj.全面的；综合的','/ˌkɒm.pɹɪˈhɛn.sɪv/','/ˌkɑːm.pɹəˈhɛn.sɪv/','noun',["When there are diametrically opposing views on a big issue that concerns millions of people, doing comprehensive research just makes sense."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entourage','n.〈总称〉随从，随行人员','/ˈɑ̃ː.tʊ.ɹɑːʒ/','/ˈɑ̃ː.tʊ.ɹɑːʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prompt','adj.敏捷的；及时的，迅速的vt.促进，推动；提示；鼓励n.提词，提示','/pɹɒmpt/','/pɹɒmpt/','noun',["I filled in my name where the prompt appeared on the computer screen but my account wasn''t recognized.","I prompted him to get a new job.","If he forgets his words I will prompt him."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advanced','adj.先进的；高级的，高等的；晚期的，后期的','/ədˈvɑːnst/','/ədˈvænst/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fatigue','n.劳累；疲劳','/fəˈtiːɡ/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inactive','adj.不活动的；怠惰的','/ɪnˈæktɪv/','/ɪnˈæktɪv/','adjective',["An inactive boy, he rarely exercised and preferred to stay indoors.","The photocopier is inactive pending repair.","Admiral Jones is now on the inactive list."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crown','v.加冕；使圆满，使完美n.王冠；花冠','/kɹaʊn/','/kɹaʊn/','noun',["the martyr''s crown","Treasure recovered from shipwrecks automatically becomes property of the Crown.","The mother was in the second stage of labor and the fetus had just crowned, prompting a round of encouragement from the midwives."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inquire','v.打听，询问','/ɪnˈkwaɪə/','/ɪnˈkwaɪɹ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gymnasium','n.体育馆；健身房','/dʒɪmˈneɪ.zi.əm/','/dʒɪmˈneɪ.zi.əm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vain','adj.徒然的，无效的；自负的，虚荣的','/veɪn/','/veɪn/','adjective',["vain toil;  a vain attempt"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harmonious','adj.和谐的，协调的；和睦的，融洽的','/hɑːˈməʊnɪəs/','/hɑːˈməʊnɪəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('filament','n.灯丝；细丝','/ˈfɪləmənt/','/ˈfɪləmənt/','noun',["galaxy filament"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spheroid','n.球状体，椭球体','','','noun',["UFOs are reported as being either oblate (saucer-shaped) or prolate (cigar-shaped) spheroids."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('verdict','n.裁定；判断；意见','/ˈvɝ.dɪkt/','/ˈvɝ.dɪkt/','noun',["The jury returned a “not guilty” verdict.","a “not out” verdict from the umpire"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stereo','adj.立体声的n.立体声','/ˈstɛɹi.əʊ/','/ˈstɛɹi.əʊ/','noun',["He liked to listen to classical music on his stereo."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('doctrine','n.教条，教义；学说','/ˈdɒktɹɪn/','/ˈdɑktɹɪn/','noun',["The four noble truths summarise the main doctrines of Buddhism.","What is the understanding of marriage and family in orthodox Marxist doctrine?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('template','n.模板，样板','/ˈtɛm.pleɪt/','/ˈtɛm.plət/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prophet','n.先知；预言者；拥护者，鼓吹者','/ˈpɹɒf.ɪt/','/ˈpɹɑf.ɪt/','noun',["Muslims believe that Muhammad was the final prophet sent to mankind."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pursuit','n.追求；','/pəˈsjuːt/','/pɝˈsuːt/','noun',["Unremitting pursuit of wealth doesn''t bring happiness, particularly if successful."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cowhand','n.牛仔，牧牛工','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tournament','n.比赛；锦标赛','/ˈtɔːnəmənt/','/ˈtɔːnəmənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ruthless','adj.无情的，残酷的，冷酷的；坚决的，彻底的','/ˈɹuːθləs/','/ˈɹuːθləs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lure','vt.吸引，诱惑n.诱惑力；诱饵','/l(j)ʊə/','/lɔɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('simile','n.明喻','/ˈsɪməli/','/ˈsɪməli/','noun',["A simile is a bit like a metaphor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inflammation','n.炎症，发炎','/ɪnfləˈmeɪʃən/','/ɪnfləˈmeɪʃən/','noun',["an inflammation of the mind, of the body politic, or of parties"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prejudice','n.偏见，成见vt.使产生偏见；使…受到损害，有损于','/ˈpɹɛd͡ʒədɪs/','/ˈpɹɛd͡ʒədɪs/','noun',["I am free of all prejudices. I hate everyone equally."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('urgent','adj.急迫的，紧迫的','/ˈɜːdʒənt/','/ˈɚdʒənt/','adjective',["An urgent appeal was sent out for assistance."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('optic','adj.眼的；视觉的；光学上的n.光学仪器','/ˈɒptɪk/','/ˈɒptɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bundle','n.捆，束；包袱vt.收集，归拢；把…塞入','/ˈbʌnd(ə)l/','/ˈbʌnd(ə)l/','noun',["a bundle of straw or of paper; a bundle of old clothes","This software bundle includes a wordprocessor, a spreadsheet, and two games.","The inventor of that gizmo must have made a bundle."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soybean','n.大豆','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('counseling','n.咨询；辅导','','','verb',["Psychiatrists, psychologists, social workers and other mental health professionals counsel clients.","I would counsel prudence in this matter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thorn','n.刺，荆棘；带刺小灌木','/θɔːn/','/θɔɹn/','noun',["the cockspur thorn"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('predominate','vi.统治，支配，占优势','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vogue','adj.流行的，时髦的n.时尚，风气，流行','/vəʊɡ/','/vəʊɡ/','noun',["Miniskirts were the vogue in the ''60s.","Hula hoops are no longer in vogue.","Vogue me up."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('combustible','adj.可燃的，易燃的','/kəmˈbʌstɪbəl/','/kəmˈbʌstɪbəl/','noun',["Dumping fertilizer on top of whatever mysterious goop was in the storage tank created a combustible mix which caught fire."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reapply','v.再申请；再利用','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('likewise','adv.同样；也','/ˈlaɪkˌwaɪz/','/ˈlaɪkˌwaɪz/','adverb',["Public transportation is virtually inaccessible in this country; likewise, its hospitals are also not very user-friendly.","Margaret enjoys playing tennis on Saturdays, Jeremy likewise.","It was very nice meeting you, Samantha. ― Likewise, Mr Thompson."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bacon','n.咸肉，熏肉','/ˈbeɪ.kən/','/ˈbeɪ.kən/','noun',["Run! It''s the bacon!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corporate','adj.法人的，公司的；共同的，全体的','/ˈkɔːp(ə)ɹət/','/ˈkɔːp(ə)ɹət/','noun',["McDonald''s corporate issued a new policy today.","The one on Seventh Street is a corporate franchise."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shuffle','v&n.拖着脚走；洗；蒙混；搅乱','/ˈʃʌfəl/','/ˈʃʌfəl/','noun',["He made a real mess of the last shuffle.","The sad young girl left with a tired shuffle.","Don''t forget to shuffle the cards."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('infatuate','vt.使迷恋；使糊涂','/ɪnˈfætju(w)ət/','/ɪnˈfætju(w)ət/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('debatable','adj.有争议的','[dɪˈbeɪtəbəɫ]','[dɪˈbeɪtəbəɫ]','noun',["It''s debatable whether he is the best candidate for the position.","The lack of bonuses this year is not debatable."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lament','n.挽歌，悼词vt.抱怨；痛惜','/ləˈmɛnt/','/ləˈmɛnt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outrage','n.暴行；','/ˈæot.ɹæed͡ʒ/','/ˈaʊt.ɹeɪd͡ʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diffuse','v.散播，传播；漫射，扩散adj.扩散的，漫射的；冗长的','/dɪˈfjuːz/','/dɪˈfjuz/','verb',["Food coloring diffuses in water."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('communal','adj.公共的，共享的；社区的','/kəˈmjuː.nəl/','/kəˈmju.nəl/','adjective',["communal politics"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contagious','adj.传染性的；有感染力的','/kənˈteɪdʒəs/','/kənˈteɪdʒəs/','adjective',["The flu was so contagious that everybody in town got sick!","Wearing jeans was a contagious fad at that time.","They were highly contagious, spreading bacteria to other people."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immerse','vt.使浸没于；使沉浸于，使陷入','/ɪˈmɜː(ɹ)s/','/ɪˈmɜː(ɹ)s/','verb',["Archimedes determined the volume of objects by immersing them in water.","The sculptor immersed himself in anatomic studies."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('publication','n.出版，发行；出版物；公布，发表','/ˌpʌblɪˈkeɪʃən/','/ˌpʌblɪˈkeɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lust','v.对…有强烈的欲望n.性欲；强烈的欲望','/lʌst/','/lʌst/','noun',["Seeing Kim fills me with a passionate lust.","The boarders hide their lust to go home.","An ideal son is his father''s lasting lust."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sardonic','adj.嘲笑的，讥讽的','/saːˈdɔnɪk/','/sɑɹˈdɑːnɪk/','adjective',["He distances himself from people with his nasty, sardonic laughter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('squirt','v.喷射，喷；向…喷射n.喷射；〈口，贬〉无名小辈','/skwɜː(ɹ)t/','/skwɜː(ɹ)t/','noun',["Hey squirt! Where you been?","The toothpaste squirted from the tube."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sow','v.播种，种；灌输；煽动','/saʊ/','/saʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('novice','n.生手，新手；新信徒','/ˈnɒvɪs/','/ˈnɒvɪs/','noun',["I''m only a novice at coding, and my programs frequently have bugs that more experienced programmers would avoid."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('portraiture','n.画像技法；肖像，画像','/ˈpɔː(ɹ)tɹɪtjʊə(ɹ)/','/ˈpɔː(ɹ)tɹɪtjʊə(ɹ)/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incoming','adj.引入的；新任的；正来临的，刚收到的n.进来，到来；','','','noun',["Incoming tides cause a tidal bore in many rivers.","The incoming prime minister gave a press conference."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inanimate','adj.无生命的；无生气的','/ɪnˈænɪmət/','/ɪnˈænɪmət/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('level','adj.平坦的；等高的n.水平；高度；级别vt.夷平，使平坦','/ˈlɛv.əl/','/ˈlɛv.əl/','noun',["Hand me the level so I can tell if this is correctly installed.","By the end of the day, we''d dug down to the level of the old basement floor.","The sound level is much too high; this hurts my ears.   We''ve reached a new level of success."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lush','adj.茂盛的','/lʌʃ/','/lʌʃ/','adjective',["That meal was lush! We have to go that restaurant again sometime!","Boys with long hair are lush!","Your voice is lush, Lucy! I could listen to it all day!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deter','v.威慑，阻止','/dɪˈtɜː(ɹ)/','/dɪˈtɜː(ɹ)/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proclaim','v.宣布，声明；显示','/pɹoʊˈkleɪm/','/pɹoʊˈkleɪm/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bunch','v.捆成一束；聚集n.簇，束，捆；帮，伙','/ˈbʌntʃ/','/ˈbʌntʃ/','noun',["a bunch of grapes;  a bunch of bananas;  a bunch of keys;  a bunch of yobs on a street corner","He still hangs out with the same bunch.","a bunch of trouble"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jolt','v.震动，颠簸；震惊n.震动，颠簸；震惊；一阵强烈的感情等','/dʒɒlt/','/dʒoʊlt/','noun',["The bus jolted its passengers at every turn.","I jolted her out of complacency.","Her untimely death jolted us all."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jeopardize','vt.破坏，危及','','','verb',["After having an affair with a junior, her chances of promotion were seriously jeopardized."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('provincialism','n.地方主义，乡土性','','','noun',["The blacksmith''s provincialism showed in his speech and manner"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('predominant','adj.占优势的，主导的，支配的；显著的，盛行的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('domesticate','vt.驯养，驯化；使精于家务，使喜爱家居','','','noun',["The Russian claims to have successfully domesticated foxes.","Dogs have clearly domesticated more than cats."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recipe','n.食谱；方法，秘诀，诀窍','/ˈɹɛs.ə.pi/','/ˈɹɛs.ə.pi/','noun',["His new approach is definitely a recipe for success.","Stepper recipes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apportion','vt.分配；分派','/əˈpɔːʃən/','/əˈpɔːʃən/','verb',["The controlling party had apportioned the voting districts such that their party would be favored in the next election.","The children were required to dump all of their Halloween candy on the table so that their parents could apportion it among them."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mental','adj.精神的；智力的；精神健康的','/ˈmɛntəl/','/ˈmɛntəl/','adjective',["He is the most mental freshman I''ve seen yet.","That was a mental party last night."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decent','adj.体面的；适当的，得体的；令人满意的；正派的','/ˈdiːsənt/','','adjective',["Are you decent? May I come in?","He''s a decent saxophonist, but probably not good enough to make a career of it.","There are a decent number of references out there, if you can find them."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('afloat','adv.漂浮地adj.漂浮的；有偿债能力的，能维持下去的','/əˈfloʊt/','/əˈfloʊt/','adverb',["A rubber duck and other toys were afloat in the bath.","The decks are afloat.","The donation will keep our business afloat for quite a while."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('auxiliary','adj.辅助的，补助的，补充的；备用的，后备的','/ɔːkˈsɪli.əɹi/','/ɔːkˈsɪli.əɹi/','noun',["auxiliary troops"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('savage','adj.凶残的；野蛮的，未开化的n.野蛮人，未开化的人vt.残害；激烈抨击','/ˈsævɪdʒ/','/ˈsævɪdʒ/','noun',["No matter how anyone might savage me, I should stay strong.","His latest film was savaged by most reviewers.","a savage wilderness"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('viable','adj.可行的，可实施的；可生长发育的','/ˈvaɪəbəl/','/ˈvaɪəbəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('by-product','n.副产品；副作用，意外结果','','','noun',["The many Indian restaurants all over Britain are a by-product of the large waves of immigration from the subcontinent."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('console','vt.安慰，抚慰','/ˈkɒn.səʊl/','/ˈkɑːn.soʊl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('auspicious','adj.吉兆的，吉利的；幸运的','/ɔːˈspɪʃəs/','/ɔːˈspɪʃəs/','adjective',["This is an auspicious day."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('medication','n.药物治疗；药物','/mɛdɪˈkeɪʃən/','/mɛdɪˈkeɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('demanding','adj.苛求的，难满足的；需要高的，费力的','/dɪˈmɑːndɪŋ/','/dɪˈmɑːndɪŋ/','verb',["I demand to see the manager.","The bank is demanding the mortgage payment.","I demand an immediate explanation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corollary','n.必然的结果；推断','/kɔˈɹoʊˌlɛɹi/','/kɔˈɹoʊˌlɛɹi/','noun',["Finally getting that cracked window fixed was a nice corollary of redoing the whole storefront.","We have proven that this set is finite and well ordered; as a corollary, we now know that there is an order-preserving map from it to the natural numbers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conjure','v.变魔术，变戏法；召唤','/kənˈd͡ʒʊə(ɹ)/','/kənˈd͡ʒʊə(ɹ)/','noun',["He started conjuring at the age of 15, and is now a famous stage magician."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acknowledge','v.承认，确认；对…表示感谢','/əkˈnɒ.lɪdʒ/','/ækˈnɑː.lɪdʒ/','verb',["to acknowledge the being of a god","to acknowledge a favor","This is to acknowledge your kind invitation to participate in the upcoming debate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('receptor','n.感受器；受体','/ɹɪˈsɛp.tə/','/ɹɪˈsɛp.tə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dormant','adj.静止的；休眠的；隐匿的','/ˈdɔːmənt/','/ˈdɔːmənt/','noun',["Grass goes dormant during the winter, waiting for spring before it grows again.","a lion dormant"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lobby','v.游说n.休息室，大厅；游说团','/lɒbi/','/lɒbi/','noun',["I had to wait in the lobby for hours before seeing the doctor.","The influence of the tobacco lobby has decreased considerably in the US.","For years, pro-life groups have continued to lobby hard for restrictions on abortion."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pulse','n.脉搏，脉率；脉冲','/pʊls/','/pʌls/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reconstruction','n.复兴；改造，再建','','','noun',["The reconstruction of the medieval bridge began last year.","The detective''s reconstruction of what happened that night is dubious."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hereditary','adj.遗传的；可继承的，世袭的','/həˈɹɛdɪt(ə)ɹi/','/həˈɹɛdɪˌtɛɹi/','noun',["Duke is a hereditary title which was created in Norman times.","hereditary rulers","Haemophilia is hereditary in his family."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stumble','vi.绊脚；蹒跚而行；结巴','/ˈstʌmbəl/','/ˈstʌmbəl/','noun',["He stumbled over a rock.","I always stumble over verbs in Spanish."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lineage','n.宗系，世系，血统','/ˈlɪ.ni.ɪdʒ/','/ˈlɪ.ni.ɪdʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lighthearted','adj.无忧无虑的；愉快的','','','adjective',["The lighthearted young lovers ran over the hills.","His lighthearted banjo performance was appreciated because it relieved the tension in tight situations."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hoard','v.贮藏，囤积n.储藏，贮存','/hɔːd/','/hɔɹd/','noun',["a hoard of provisions; a hoard of money"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coherent','adj.条理清楚的，连贯的；有表达能力的','/kəʊˈhɪəɹənt/','/koʊˈhiɹənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ledge','n.突出部分；暗礁','/lɛdʒ/','/lɛdʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('infrared','adj.红外线的；产生红外线的n.红外线','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('respondent','adj.回答的n.回答者，响应者；调查对象；被告','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ponder','v.思索，沉思','/ˈpɒn.də(ɹ)/','/ˈpɑn.dɚ/','noun',["I lit my pipe and had a ponder about it, but reached no definite conclusion.","I have spent days pondering the meaning of life."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('animate','adj.活的，有生命的vt.赋予生命，使有活力','/ˈæ.nə.meɪt/','/ˈæ.nə.meɪt/','verb',["If we animate the model, we can see the complexity of the action.","She is an engaging and animate speaker.","Nouns can be singular or plural, and one of two genders, animate or inanimate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scene','n.地点，现场；景色；一场，一个镜头；场面；活动领域，圈子','/siːn/','/siːn/','noun',["the scene of the crime","They stood in the centre of the scene.","behind the scenes"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exert','vt.运用，行使；施加；努力，竭力','/ɪɡˈzɜːt/','/ɪɡˈzɝt/','verb',["I exerted myself in today''s training.","He considered exerting his influence on John to gain an advantage for himself."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scandal','n.丑事，丑闻；恶意诽谤，流言蜚语；可耻的行为','/ˈskændəl/','/ˈskændəl/','noun',["Their affair was reported as a scandal by most tabloids.","The incident brought considerable scandal to his family.","When their behaviour was made public it caused a great scandal."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dormancy','n.休眠；催眠状态；隐匿','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hinder','vt.阻碍，妨碍','/ˈhɪndə/','/ˈhɪndɚ/','verb',["A drought hinders the growth of plants.","She hindered a man from committing suicide."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scent','n.香味，香气；气味；踪迹，线索；香水vt.闻出；察觉','/sɛnt/','/sɛnt/','noun',["the scent of a skunk","The dogs lost the scent.","I believe the bloodhound has the best scent of all dogs."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adjunct','n.附加物，附件；附加语，修饰语','/ˈædʒ.ʌŋkt/','/ˈædʒ.ʌŋkt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mushroom','vi.迅速成长n.蘑菇','/ˈmʌʃˌɹuːm/','/ˈmʌʃˌɹuːm/','noun',["Some mushrooms are edible and taste good, while others are poisonous and taste foul.","The town’s population mushroomed from 10,000 to 110,000 in five years.","We used to go mushrooming in the forest every weekend."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pinpoint','adj.准确的，精确的vt.精准定位；准确解释n.极小的范围；光点','','','noun',["The investigators tried to pinpoint the source of the flames.","The machine assembles parts at high speed and with pinpoint accuracy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('altruistic','adj.利他的，无私心的，为他人着想的','/ˌɑl.tɹuˈɪs.tɪk/','/ˌɑl.tɹuˈɪs.tɪk/','adjective',["His helping the old woman with her shopping was deemed highly altruistic by everyone, especially since her home was a mile away."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extremity','n.末端；极端，极度','/ɛk-/','/ɛk-/','noun',["Guillain–Barré syndrome causes one to not be able to move one’s extremities."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deny','v.否认；拒绝承认；拒绝给予','/dɪˈnaɪ/','/dɪˈnaɪ/','verb',["I wanted to go to the party, but I was denied.","Everyone knows he committed the crime, but he still denies it.","My father denied me a good education."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alchemist','n.炼金术士','/ˈæl.kə.mɪst/','/ˈæl.kə.mɪst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trench','v.挖沟n.沟渠，壕沟；战壕','/tɹɛntʃ/','/tɹɛntʃ/','noun',["to trench land for the purpose of draining it","to trench a garden for certain crops"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miserable','adj.痛苦的；可怜的；令人不快的','/ˈmɪz(ə)ɹəbəl/','/ˈmɪz(ə)ɹəbəl/','noun',["He''s good at some sports, like tennis, but he''s just miserable at football.","a miserable sinner"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subtract','vt.减去','/səbˈtɹækt/','/səbˈtɹækt/','verb',["If you subtract the $100 for gas from the total cost, it was a fairly inexpensive trip."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dent','vt.使凹下；挫伤，损害n.缺口，凹痕','/dɛnt/','/dɛnt/','noun',["The crash produced a dent in the left side of the car.","That purchase put a bit of a dent in my wallet.","Copper is soft and dents easily."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurricane','n.飓风，暴风','/ˈhʌɹɪkən/','/ˈhɝɪˌkeɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('asthma','n.哮喘','/ˈasmə/','/ˈasmə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hike','v&n.徒步旅行，远足','/haɪk/','/haɪk/','noun',["The tenants were not happy with the rent hike.","Don''t forget to bring the map when we go hiking tomorrow.","She hiked her skirt up."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generalization','n.概括，归纳','','','noun',["A hypersphere is a generalization of a sphere across more than three dimensions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rancher','n.牧场主；大农场工人','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hustle','v.推搡，硬挤n.忙碌；喧闹','/ˈhʌsəl/','/ˈhʌsəl/','noun',["I''ll have to hustle to get there on time.","The guy tried to hustle me into buying into a bogus real estate deal."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dosage','n.剂量','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advisable','adj.可取的，适当的；明智的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dormitory','n.宿舍','/ˈdɔɹmɪˌtɔɹi/','/ˈdɔɹmɪˌtɔɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stratigraphy','n.地层学；地层中的岩石组成','/stɹəˈtɪɡɹəfi/','/stɹəˈtɪɡɹəfi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obliterate','vt.覆盖；消灭；忘却','/əbˈlɪtəɹeɪt/','/əbˈlɪtəɹeɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bookstore','n.书店','/ˈbʊkstɔː/','/ˈbʊkstɔː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obligate','vt.使负义务，强迫','','','verb',["an obligate anaerobe"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('audit','vt.旁听；审计','/ɔː.dɪt/','/ɔː.dɪt/','noun',["National Assembly audit","to audit the accounts of a treasure, or of parties who have a suit depending in court"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cactus','n.仙人掌','/ˈkæktəs/','/ˈkæktəs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('audio','adj.音频的；声音的','/ˈɔː.di.əʊ/','/ˈɔ.di.oʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patriarchy','n.父权制，父系社会，家长统治','/ˈpeɪt(ʃ)ɹiɑɹki/','/ˈpeɪt(ʃ)ɹiɑɹki/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incense','n.〔燃烧时发出怡人香味的〕香v.使〔某人〕十分愤怒','/ɪnˈsɛns/','/ɪnˈsɛns/','noun',["I think it would incense him to learn the truth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('offensive','adj.攻击性的；冒犯的，使人不快的；攻方的n.进攻，攻击；攻势','/əˈfɛnsɪv/','/əˈfɛnsɪv/','noun',["The Marines today launched a major offensive.","He took the offensive in the press, accusing his opponent of corruption.","An offensive smell."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amid','prep.在…中，被…围绕','/əˈmɪd/','/əˈmɪd/','preposition',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('launch','vt.发动，发起；推出；使下水；','/lɔːnt͡ʃ/','/lɔnt͡ʃ/','noun',["book launch","The navy launched another ship.","NASA launched several unmanned rockets before launching any of the Mercury astronauts."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quell','vt.制止，镇压；缓解，减轻','/kwɛl/','/kwɛl/','noun',["to quell grief"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('understate','vt.轻描淡写，避重就轻地说','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('detectable','adj.可发觉的，可察觉的','/dɪˈtɛktəbəɫ/','/dɪˈtɛktəbəɫ/','adjective',["There was a detectable pause before he continued. We all noticed it but no one commented."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uppermost','adv.在最上面，在最重要的位置adj.最高的，最上面的；最重要的','/ˈʌpəməʊst/','/ˈʌpəməʊst/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expeditious','adj.迅速而有效的，迅速完成的','/ɛkspɪˈdɪʃəs/','/ɛkspɪˈdɪʃəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gallop','v.飞奔，疾驰','/ˈɡæləp/','/ˈɡæləp/','noun',["The horse galloped past the finishing line.","to gallop a horse"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neoclassical','adj.新古典主义的','','','noun',["The English word \"psychopathy\" is a neoclassical compound from Ancient Greek roots."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mortality','n.死亡率','/mɔɹˈtælɪti/','/mɔɹˈtælɪti/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dissent','vi.不同意，持异议n.不同意见，异议','/dɪˈsɛnt/','/dɪˈsɛnt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ignite','v.点燃，着火','/ɪɡˈnaɪt/','/ɪɡˈnaɪt/','verb',["to ignite iron or platinum"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('declare','v.表明；断言，声称；申报','/dɪˈkleə/','/dəˈklɛɚ/','verb',["He declared him innocent.","declare bankruptcy","Houghton and Sunderland South was the first constituency to declare in the 2015 general election."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('calamitous','adj.灾难性的','/kəˈlæmɪtəs/','/kəˈlæmɪtəs/','adjective',["The city was struck by a calamitous cyclone."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unequal','adj.不同的，不相等的；不平等的，不相称的；不胜任的','/ʌnˈiːkwəl/','/ʌnˈiːkwəl/','noun',["unequal to the task"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('posthumous','adj.死后的，身后的','/ˈpɒs.tʃə.məs/','/ˈpɒs.tʃə.məs/','adjective',["Posthumous orphans never even knew their fathers.","Usage note: Posthumous awards are made when the intended recipient dies as a result of the action which merits the award. Even a short time lag between the action and the decision may cause the award to be conferred after death or there may be a longer delay such as when a review board decides to confer an award decades after a war has ended but such awards while they may be post mortem (literally, \"after death\") are not posthumous awards.","Artists obscure during their life often receive posthumous recognition, too late for them to enjoy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consort','vi.结交；鬼混n.配偶；团伙','/ˈkɒnsɔːt/','/ˈkɒnsɔːt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drawback','n.缺点，障碍，不利条件；退款，退税','/ˈdɹɔːˌbæk/','/ˈdɹɔːˌbæk/','noun',["Poor fuel economy is a common drawback among larger vehicles."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('missile','n.发射物；导弹，飞弹','/ˈmɪsaɪl/','/ˈmɪsaɪl/','noun',["The Rhodians, who used leaden bullets, were able to project their missiles twice as far as the Persian slingers, who used large stones.","That missile is explosive enough to kill hundreds."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('variant','adj.不同的，变异的n.变体，变形','/ˈvɛəɹi.ənt/','/ˈvɛəɹi.ənt/','noun',["All breeds of dog are variants of the species “Canis lupus familiaris”."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passion','n.激情，热情','[ˈpʰæʃən]','[ˈpʰæʃən]','noun',["We share a passion for books.","It started as a hobby, but now my motorbike collection has become my passion.","We shared a night of passion."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anecdotal','adj.轶话的，逸闻趣事的','/ˌænɪkˈdoʊtl̩/','/ˌænɪkˈdoʊtl̩/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('athlete','n.运动员，体育家','/ˈæθ.lit/','/ˈæθ.lit/','noun',["She''s the first athlete in her sport to obtain a corporate sponsor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('despoil','vt.夺取，掠夺；蹂躏','/dɪˈspɔɪl/','/dɪˈspɔɪl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('query','v.向…提问；对…表示怀疑n.疑问，问题','/ˈkwɪə.ɹi/','/ˈkwɪə.ɹi/','noun',["The teacher answered the student’s query concerning biosynthesis.","The database admin switched on query logging for debugging purposes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dismal','adj.阴沉的，阴郁的；忧郁的，沮丧的；差劲的','[ˈdɪzməɫ]','[ˈdɪzməɫ]','adjective',["He received a dismal compensation.","The storm made for a dismal weekend","She was lost in dismal thoughts of despair"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vocalize','v.用言语表达；说，唱，发声','/ˈvoʊ.kə.laɪz/','/ˈvoʊ.kə.laɪz/','verb',["We could hear the monkeys vocalizing, though we could not see them.","In Hong Kong English, /l/ may be vocalized at the end of a syllable."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astronomy','n.天文学','/æˈstɹɑnəˌmi/','/æˈstɹɑnəˌmi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ranch','n.大牧场，饲养场','/ɹɑːntʃ/','/ɹæntʃ/','noun',["Formally the widow still ranches, but in fact she leaves all ranching to the foreman."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discord','n.不一致；不和，纷争；不和谐','/ˈdɪskɔːd/','/ˈdɪskɔɹd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ripple','v.起涟漪；扩散n.细浪，涟漪','/ˈɹɪp(ə)l/','/ˈɹɪp(ə)l/','noun',["I dropped a small stone into the pond and watched the ripples spread.","I enjoy fudge ripple ice cream, but I especially like to dig through the carton to get at the ripple part and eat only that."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dismay','vt.使气馁，使沮丧；使诧异n.灰心，气馁；诧异','/dɪsˈmeɪ/','/dɪsˈmeɪ/','noun',["He looked in dismay at the destruction of the town caused by the hurricane."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('naval','adj.海军的','/ˈneɪvəl/','/ˈneɪvəl/','adjective',["naval architect"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hint','v.暗示，示意n.暗示，提示；','/hɪnt/','/hɪnt/','noun',["I needed a hint to complete the crossword.","He gave me a hint that my breath smelt.","I could taste a hint of lemon in the wine."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('myopic','adj.近视的；缺乏远见的','/maɪˈɒpɪk/','/maɪˈɒpɪk/','noun',["A stronger prescription for myopic night drivers is often needed.","So it is no wonder that some of the remarkable discoveries of the scientific method (...) can draw most of us well outside our myopic comfort zone."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('illegible','adj.难以辨认的，模糊的','/ɪˈlɛd͡ʒəbəl/','/ɪˈlɛd͡ʒəbəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decompose','v.分解；腐烂','/ˌdiːkəmˈpəʊz/','/ˌdiːkəmˈpəʊz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('throng','v.群集，拥向n.一大群人','/θɹɒŋ/','/θɹɑŋ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monument','n.纪念碑；历史遗迹','/ˈmɒnjʊmənt/','/ˈmɑnjəmənt/','noun',["There is a monument on the town green to the soldiers who died in World War I."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inventory','n.目录，清单；库存','/ɪnˈvɛn.tə.ɹi/','/ɪnˈvɛn.tə.ɹi/','noun',["Due to an undersized inventory at the Boston outlet, customers had to travel to Providence to find the item.","The inventory included several items that one wouldn''t normally think to find at a cheese shop.","This month''s inventory took nearly three days."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('saunter','vi&n.闲逛，漫步','/ˈsɑntɚ/','/ˈsɑntɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vivid','adj.清晰的；鲜明的；生动的；活泼的','/ˈvɪvɪd/','/ˈvɪvɪd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blues','n.布鲁斯音乐，蓝调','/bluːz/','/bluːz/','noun',["The boys in blue marched to the pipers.","His request for leave came out of the blue."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defecate','vi.排便；澄清','/ˈdɛfɪkeɪt/','/ˈdɛfɪkeɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assent','n&vi.同意，赞成','/əˈsɛnt/','/əˈsɛnt/','noun',["I will give this act my assent."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coverage','n.新闻报道；覆盖范围','/ˈkʌv.əɹ.ɪdʒ/','','noun',["Before laying sod on that clay, the ground needs two inches of coverage with topsoil.","Mobile phone coverage is poor in some areas."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perishable','adj.易腐的，易变质的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corrupt','adj.堕落的，腐化的；腐败的，','/kəˈɹʌpt/','/kəˈɹʌpt/','verb',["to corrupt a book","The government here is corrupt, so we''ll emigrate to escape them.","It turned out that the program was corrupt - that''s why it wouldn''t open."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commemorate','vt.庆祝，纪念','/kəˈmɛməˌɹeɪt/','/kəˈmɛməˌɹeɪt/','verb',["On November 11th we commemorate the fallen with a march.","The cenotaph commemorates the fallen."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transmit','v.传送，传递，输送；传播，传染','/tɹænsˈmɪt/','/tɹænsˈmɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repertory','n.保留剧目；保留剧目轮演；库存，储备；仓库','/ˈɹɛpətɹi/','/ˈɹɛpətɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hazel','n.榛树adj.〔眼睛〕绿褐色的','/ˈheɪzəl/','/ˈheɪzəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('voltage','n.电压，伏特数','/voʊltɪdʒ/','/voʊltɪdʒ/','noun',["Be careful when opening high-voltage equipment."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vaccine','n.疫苗','/vækˈsaɪn/','/vækˈsaɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zest','n.趣味；热情，狂热','/zɛst/','/zɛst/','noun',["The orange zest gives the strong flavor in this dish.","I add zest to the meat by rubbing it with a spice mixture before grilling."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bluff','v.虚张声势，吓唬adj.直率的，坦率的n.悬崖，峭壁；虚张声势，唬人','/blʌf/','/blʌf/','noun',["That is only bluff, or a bluff.","John''s bet was a bluff: he bet without even so much as a pair.","John bluffed by betting without even a pair."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punctual','adj.守时的','/ˈpʌŋktjʊəl/','/ˈpʌŋktʃuəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compromise','n&v.妥协，折中','/ˈkɒmpɹəˌmaɪz/','/ˈkɑmpɹəˌmaɪz/','noun',["a compromise of character or right","He tried to compromise the security in the computer by guessing the password."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yogurt','n.酸奶','/ˈjəʉɡət/','/ˈjoʊɡɚt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hesitant','adj.犹豫的，吞吞吐吐的，犹豫不定的','/ˈhɛzɪtənt/','/ˈhɛzɪtənt/','adjective',["I am hesitant to recommend him as a manager because he has a short temper."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feedback','n.反馈；反馈信息','/ˈfiːdˌbæk/','/ˈfiːdˌbæk/','noun',["After you hand in your essays, I will give both grades and feedback.","The show ended with a riot of feedbacking guitars.","His employees feedbacked him a lot more than he wanted."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('folklore','n.民间传说；民俗学','/ˈfəʊk.lɔː/','/ˈfəʊk.lɔː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('credential','n.证书；文凭；资格','/kɹɪˈdɛnʃəl/','/kɹɪˈdɛnʃəl/','noun',["May I see your credentials, please?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entrench','vt.使根深蒂固，牢固确立','/ɛnˈtɹɛntʃ/','/ɛnˈtɹɛntʃ/','verb',["The army entrenched its camp, or entrenched itself.","Senator Cornpone was able to entrench by spending millions on each campaign."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('roam','vi.漫游，漫步，闲逛n.漫步，漫游','/ɹəʊm/','/ɹoʊm/','verb',["Gangs of thugs roamed the streets."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('simulate','vt.模仿，模拟；假装，伪装','/-jə-/','/-jə-/','verb',["We will use a smoke machine to simulate the fog you will actually encounter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tenet','n.原则；信条；教义','/ˈtɛnət/','/ˈtɛnət/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spectacle','n.精彩的表演；壮观的场面；奇观；壮丽的景象；','/ˈspɛktəkl̩/','/ˈspɛktəkl̩/','noun',["The horse race was a thrilling spectacle.","He made a spectacle out of himself."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('efficiency','n.效率，功效','/ɪˈfɪʃn̩si/','/ɪˈfɪʃn̩si/','noun',["The efficiency of the planning department is deplorable.","The efficiency of this loudspeaker is 40%.","I have an efficiency available June through July."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ethnic','adj.种族的；民族的','/ˈɛθ.nɪk/','/ˈɛθ.nɪk/','noun',["There are many ethnic Indonesians in the Netherlands","I like to eat ethnic food"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lettuce','n.生菜；莴苣','/ˈlɛtəs/','/ˈlɛtəs/','noun',["I’ll have a ham sandwich with lettuce and tomato.","Twelve dollars an hour? That''s a lot of lettuce!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intact','adj.无损伤的，完整的','/ɪnˈtækt/','/ɪnˈtækt/','adjective',["I packed my belongings carefully so that they would survive the move intact.","The opposite of a circumcised penis is an intact penis."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('motto','n.座右铭；箴言，格言','/ˈmɒtəʊ/','/ˈmɒtəʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('juvenile','adj.幼稚的，不成熟的；少年的，未成年的n.幼体；未成年人，少年','/ˈdʒuːvənaɪl/','/ˈdʒuːvənaɪl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pervasive','adj.普遍深入的；遍及的，弥漫的','/pəˈveɪ.sɪv/','/pɚˈveɪ.sɪv/','adjective',["The medication had a pervasive effect on the patient''s health."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tableland','n.高原，台地','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hive','v.入蜂箱；群居n.蜂箱，蜂房；闹市，忙碌之地','/haɪv/','/haɪv/','noun',["to hive a swarm of bees"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laborious','adj.艰苦的，费力的，艰难的；勤劳的','/ləˈbɔːɹiəs/','/ləˈbɔːɹiəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flag','v.标记n.旗帜；标记','/flæɡ/','/flæɡ/','noun',["Please flag down a taxi for me.","to flag an order to troops or vessels at a distance","I''ve flagged up the need for further investigation into this."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('racing','adj.比赛的n.比赛，竞赛','/ˈɹeɪsɪŋ/','/ˈɹeɪsɪŋ/','verb',["The drivers were racing around the track.","I raced him to the car, but he was there first, so he got to ride shotgun.","As soon as it was time to go home, he raced for the door."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sympathetic','adj.感应的，交感的；有同情心的；体谅的','/ˌsɪmpəˈθɛtɪk/','/ˌsɪmpəˈθɛtɪk/','adjective',["John looked very upset. I gave him a sympathetic look.","Sympathetic magic is based on imitation or correspondence.","Sympathetic innervation involves epinephrine."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('botany','n.植物学；植物','/-ɪ/','/-ɪ/','noun',["the botany of Greenland"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('topsoil','n.表层土','','','noun',["Little grew on the farm, after the floods from the hurricane washed away the topsoil."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glamorous','adj.富有魅力的，迷人的','/ˈɡlaməɹəs/','/ˈɡlaməɹəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disprove','vt.证明…不成立，证明…是错误的','/dɪsˈpɹuːv/','/dɪsˈpɹuːv/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overseas','adv.在海外，在国外adj.海外的，国外的','/ˌəʊvəˈsiːz/','/ˌəʊvəˈsiːz/','adjective',["Overseas branches of the company are doing well.","Overseas Chinese communities exist in North and South America.","Her overseas trip went well."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leak','v.漏，渗出，泄漏n.漏洞，裂缝；泄露；走漏','/liːk/','/liːk/','noun',["a leak in a boat","The babies'' diapers had big leaks.","The leaks by Chelsea Manning showed the secrets of the US military."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complacence','n.自满，满足','/kəmˈpleɪsəns/','/kəmˈpleɪsəns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assert','v.断言，声称','/əˈsɜːt/','/əˈsɝt/','noun',["He would often assert that there was life on other planets.","Salman Rushdie has asserted his right to be identified as the author of this work.","to assert our rights and liberties"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flap','n.拍打；振翅；封盖，','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leap','vi.跳跃；急速行动；骤变；激增n.跳跃；骤变；激增','/liːp/','/liːp/','noun',["It''s quite a leap to claim that those cloud formations are evidence of UFOs.","to leap a wall or a ditch","to leap a horse across a ditch"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('picturesque','adj.如画的；别致的；生动的','/pɪktʃəˈɹɛsk/','/pɪktʃəˈɹɛsk/','adjective',["picturesque language"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('informed','adj.有学识的；见多识广的，有见识的','/ɪnˈfɔːmd/','/ɪnˈfɔɹmd/','verb',["His sense of religion informs everything he writes.","An informed young man delivered a lecture on the history of modern art."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dispute','v.争论；对…表示异议n.争论；纠纷','/ˈdɪs.pjuːt/','/dɪsˈpjuːt/','noun',["Some residents disputed the proposal, saying it was based more on emotion than fact.","to dispute assertions or arguments"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refurbish','vt.再装修，重新装饰','/ɹiːˈfɜːbɪʃ/','/ɹiˈfɝbɪʃ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rugged','adj.崎岖的，凹凸不平的；艰难的；粗犷的；结实的，耐用的；粗野的，不文雅的','/ˈɹʌɡɪd/','/ˈɹʌɡɪd/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lead','v.领导，引导；领先，占首位；通向，导致，','/lɛd/','/lɛd/','noun',["This copy has too much lead; I prefer less space between the lines.","They pumped him full of lead.","continuous firing leads the grooves of a rifle."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fraction','n.小部分，一点儿，少许','/ˈfɹæk.ʃən/','/ˈfɹæk.ʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('token','adj.象征性的n.表示，标志，象征；记号；信物；代币；礼券，代价券','/ˈtəʊkən/','/ˈtoʊkən/','noun',["According to the Bible, the rainbow is a token of God''s covenant with Noah.","Please accept this bustier as a token of our time together.","A book token is the easiest option for a Christmas gift."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('filter','v.过滤；筛选；走漏；渗入，透过n.过滤器；筛选','/ˈfɪltə/','/ˈfɪltɚ/','noun',["He runs an email filter to catch the junk mail.","He''s got no filter, and he''s always offending people as a result.","If (1) the universal set (here, the set of natural numbers) were called a \"large\" set, (2) the superset of any \"large\" set were also a \"large\" set, and (3) the intersection of a pair of \"large\" sets were also a \"large\" set, then the set of all \"large\" sets would form a filter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emotion','n.感情，激情，情绪','/iˈmoʊʃən/','/iˈmoʊʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soothe','vt.缓和，减轻；抚慰，安慰','/suːð/','/suːð/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assess','vt.估价；评定','/əˈsɛs/','/əˈsɛs/','verb',["He assessed the situation.","A $10.00 late fee will be assessed on all overdue accounts.","Once you''ve submitted a tax return, the Tax Department will assess the amount of tax you still owe."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('etiquette','n.礼节，礼仪','/ˈɛtɪkɪt/','/ˈɛtɪkɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prescription','n.处方，药方；开处方，开药方','/pɝˈskɹɪpʃən/','/pɝˈskɹɪpʃən/','noun',["\"Jurisdiction to prescribe\" is a state''s authority to make its laws applicable to certain persons or activities. -- Richard G. Alexander, Iran and Libya Sanctions Act of 1996: Congress exceeds its jurisdiction to prescribe law. Washington and Lee Law Review, 1997.","The surgeon wrote a prescription for a pain killer and physical therapy.","The pharmacist gave her a bottle containing her prescription."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('submission','n.屈服，服从；提交，呈递；提交物；看法，意见','/səbˈmɪʃən/','/səbˈmɪʃən/','noun',["Any submissions received after Friday will have marks deducted for lateness."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obsess','v.迷住；牵挂','/əbˈsɛs/','/əbˈsɛs/','verb',["Some people are obsessed with sports.","Thoughts of her obsess my every waking moment.","Stop obsessing over it, will you!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('utter','adj.完全的vt.出声；说','/ˈʌtə/','/ˈʌtɚ/','adjective',["utter ruin; utter darkness"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uniformity','n.同样，一致；一致性','','','noun',["the uniformity of the decor"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bustle','vi.奔忙，匆匆忙忙n.忙乱嘈杂，喧嚣','/ˈbʌsəl/','/ˈbʌsəl/','noun',["The commuters bustled about inside the train station.","The train station was bustling with commuters."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('substantiate','vt.证实，证明','/səbˈstanʃɪeɪt/','/səbˈstanʃɪeɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('divert','vt.转移…的注意力，使分心；使娱乐；使转向，使改道','/daɪˈvɜːt/','/daɪˈvɝt/','verb',["The workers diverted the stream away from the road.","Don''t let him divert your attention; keep your eye on the ball."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hygiene','n.卫生；卫生学','/ˈhaɪˌdʒiːn/','/ˈhaɪˌdʒiːn/','noun',["Hygiene is an important consideration in places where food is prepared.","They have poor personal hygiene."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sage','adj.贤明的；审慎的n.智者，圣人','/seɪdʒ/','/seɪdʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tycoon','n.巨头，大亨','/taɪˈkuːn/','/taɪˈkuːn/','noun',["Chairman Yu is a tycoon who owns multiple hotel chains."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conspicuous','adj.显眼的，明显的','/kənˈspɪk.ju.əs/','/kənˈspɪk.ju.əs/','adjective',["He was conspicuous by his absence.","He had a conspicuous lump on his forehead."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('justice','n.法官；司法；正义，公正','/ˈdʒʌs.tɪs/','/ˈdʒʌs.tɪs/','noun',["the justice of a description","Justice was served.","to demand justice"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('verse','n.诗歌；韵文；诗节','/ˈvɜːs/','/ˈvɝs/','noun',["Restoration literature is well known for its carefully constructed verse.","The restrictions of verse have been steadily relaxed over time.","Note the shift in tone between the first verse and the second."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('furious','adj.狂怒的，狂暴的；强烈的，猛烈的','/ˈfjʊə.ɹɪəs/','/ˈfjɝ.i.əs/','adjective',["a furious animal; parent furious at their child''s behaviour","a furious stream; a furious wind or storm"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('individual','adj.单独的；独特的n.个人，个体','/ˌɘndɘˈvɘd͡ʒɘl/','/ˌɪndəˈ-/','noun',["He is an unusual individual.","As we can''t print them all together, the individual pages will have to be printed one by one.","individual personal pension; individual cream cakes"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salmon','n.鲑鱼，大马哈鱼','/ˈsɑmən/','/ˈsælmən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bouquet','n.花束；香味，芬芳','/boʊˈkeɪ/','/boʊˈkeɪ/','noun',["For my birthday I received two bouquets.","This Bordeaux has an interesting bouquet.","The remarkable flower bouquet lasts for hours until it dissolves into a sweet vanilla smell."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instinctual','adj.本能的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('constrain','vt.束缚，限制','/kənˈstɹeɪn/','/kənˈstɹeɪn/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('empress','n.女皇，皇后','/ˈɛmpɹəs/','/ˈɛmpɹəs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('informant','n.提供消息或情报的人，线人；提供资料的人；合作者','/ɪnˈfɔːmənt/','/ɪnˈfɔːmənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tendon','n.腱','/ˈtɛndən/','/ˈtɛndən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interim','adj.暂时的，过渡的n.间歇，过渡期间','/ˈɪntəɹɪm/','/ˈɪntəɹɪm/','noun',["His car is in the shop, but they gave him a rental to drive in the interim.","Iraq''s government is interim.","You are interim manager until he returns from hospital."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('testimony','n.证词；证据，证明','/ˈtɛstɪməni/','/ˈtɛstɪmoʊni/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enforce','vt.实施，生效，执行；强迫，迫使','/ɪnˈfɔːs/','/ɪnˈfɔːs/','verb',["The police are there to enforce the law.","The victim was able to enforce his evidence against the alleged perpetrator.","to enforce a passage"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glitter','vi.闪烁，闪耀n.灿烂的光辉；诱惑力，魅力','/ˈɡlɪtə(ɹ)/','/ˈɡlɪtɚ/','noun',["a glittering sword","the glittering scenes of a court"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('destined','adj.注定的；以…为目的地的','/ˈdɛstɪnd/','','verb',["He is sure he is destined for fame."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('painstaking','adj.煞费苦心的，勤勉的','/ˈpeɪnzˌteɪkɪŋ/','/ˈpeɪnzˌteɪkɪŋ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sociology','n.社会学','/ˌsəʊsiːˈɒlədʒiː/','/ˌsəʊsiːˈɒlədʒiː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stout','adj.结实的，强壮的；肥胖的；顽强的','/stʌʊt/','/staʊt/','noun',["Stout is darker, stronger and sweeter than porter beer.","Campers prefer stout vessels, sticks and cloth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gigantic','adj.巨大的，庞大的','/dʒaɪˈɡæntɪk/','/dʒaɪˈɡæntɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nomadic','adj.游牧的；流浪的','/nəʊˈmæd.ɪk/','/nəʊˈmæd.ɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hedge','v.用篱笆围；避免直接回答n.树篱；防止损失的措施；防备','/hɛdʒ/','/hɛdʒ/','noun',["He trims the hedge once a week.","A hedge is an investment position intended to offset potential losses/gains that may be incurred by a companion investment. In simple language, a hedge is used to reduce any substantial losses/gains suffered by an individual or an organization."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dragonfly','n.蜻蜓','/ˈdɹæɡənˌflaɪ/','/ˈdɹæɡənˌflaɪ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eligible','adj.符合条件的，合格的；适合的','/ˈɛlɪdʒəb(ə)l/','/ˈɛlɪdʒəb(ə)l/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weed','n.杂草；水草','/wiːd/','/wiːd/','noun',["If it isn''t in a straight line or marked with a label, it''s a weed."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Babylonian','adj.巴比伦的；奢华的n.巴比伦人','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glacier','n.冰川，冰河','/ˈɡleɪ.ʃɚ/','/ˈɡleɪ.ʃɚ/','noun',["They warned that the effects of glacier melting on water resources are becoming “increasingly serious” for China."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ultimatum','n.最后通牒','/ˌʌl.tɪˈmeɪ.təm/','/ˌʌl.tɪˈmeɪ.təm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horde','n.一大群人；游牧部落','/hɔːd/','/hɔɹd/','noun',["We were beset by a horde of street vendors who thought we were tourists and would buy their cheap souvenirs."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('racism','n.种族主义，种族歧视','/ˈɹeɪsɪzm̩/','/ˈɹeɪsɪzm̩/','noun',["Martin Luther King spoke out against racism."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('luxurious','adj.奢侈的，奢华的','/lʌkˈsjʊɹ.i.əs/','/lʌkˈsjʊɹ.i.əs/','adjective',["a luxurious hotel suite"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('idle','adj.懒散的；没有工作的，闲散的；空闲的；漫无目的的；无用的，无效的v.无所事事，虚度','/ˈaɪd(ə)l/','/ˈaɪd(ə)l/','noun',["My computer hibernates after it has been idle for 30 minutes.","idle workmen","an idle fellow"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plight','n.困境，苦境','/plaɪt/','/plaɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hail','v.招呼；高呼；赞扬，称颂；下冰雹n.冰雹；一阵','/heɪl/','/heɪl/','noun',["They say it''s going to hail tomorrow.","The cloud would hail down furiously within a few minutes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accent','n.重音；口音；重音符号vt.重读','/ˈak.sənt/','/ˈak.sənt/','noun',["In the word \"careful\", the accent is placed on the first syllable.","At this hotel, the accent is on luxury.","The name Cézanne is written with an acute accent."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passive','adj.被动的，消极的；被动语态的','/ˈpæs.ɪv/','/ˈpæs.ɪv/','noun',["He remained passive during the protest.","a passive balloon; a passive aeroplane; passive flight, such as gliding and soaring"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nauseous','adj.恶心的；令人作呕的，令人厌恶的','/ˈnɔːsɪəs/','/ˈnɔːsɪəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('granite','n.花岗岩，花岗石','/ˈɡɹæ.nɪt/','/ˈɡɹæ.nɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refreshing','adj.使人耳目一新的；提神的，使人精神振作的','/ɹəˈfɹɛʃɪŋ/','/ɹəˈfɹɛʃɪŋ/','verb',["Sleep refreshes the body and the mind."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oblivious','adj.遗忘的；未注意的，不知不觉的','/əˈblɪ.vi.əs/','/əˈblɪ.vi.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rival','adj.竞争的，对抗的vt.与…相匹敌，比得上n.竞争对手','/ˈɹaɪvəl/','/ˈɹaɪvəl/','noun',["Chris is my biggest rival in the 400-metre race.","As a social historian, he has no rival.","to rival somebody in love"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('latitude','n.纬度；','/ˈlæt.ɪ.tjuːd/','/ˈlæt.ə.tjud/','noun',["His parents gave him a great deal of latitude."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vigor','n.活力，精力','/ˈvɪɡɚ/','/ˈvɪɡɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scan','vt.细察，审视；扫描；粗略地看，浏览n.扫描检查；浏览','/skæn/','/skæn/','noun',["The operators vacated the room during the scan.","The doctors looked at the scans and made a diagnosis.","She scanned the passage carefully but could not find what she was looking for."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('industry','n.勤劳，勤奋；工业，行业','/ˈɪndəstɹi/','/ˈɪndəstɹi/','noun',["Over the years, their industry and business sense made them wealthy.","The software and tourism industries continue to grow, while the steel industry remains troubled.","There used to be a lot of industry around here, but now the economy depends on tourism."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eliminate','vt.消除；淘汰','/ɪˈlɪməneɪt/','/ɪˈlɪməneɪt/','verb',["a ruthless mobster who eliminated his enemies","Bill was eliminated as a suspect when the police interviewed witnesses."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('augment','vt.增加，提高','/ɔːɡˈmɛnt/','/ɑɡˈmɛnt/','noun',["The money from renting out a spare room can augment a salary."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tangent','adj.切线的，相切的n.切线；正切','/ˈtæn.dʒənt/','/ˈtæn.dʒənt/','noun',["I believe we went off onto a tangent when we started talking about monkeys on unicycles at his retirement party."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('benign','adj.良性的；有利的；善良的，和蔼的','/bɪˈnaɪn/','/bɪˈnaɪn/','adjective',["an ozone-benign refrigerant"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('destruction','n.毁坏，毁灭','/ˌdɪsˈtɹʌkʃən/','/ˌdɪsˈtɹʌkʃən/','noun',["The destruction of the condemned building will take place at noon.","Amid the seemingly endless destruction, a single flower bloomed."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquit','vt.宣告无罪；表现','/əˈkwɪt/','/əˈkwɪt/','verb',["The jury acquitted the prisoner of the charge.","The orator acquitted himself very poorly."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stiff','adv.极其，非常；僵硬地adj.硬的，僵直的；呆板的；拘谨的；艰难的，费劲的；强烈的','/stɪf/','/stɪf/','noun',["A Working Stiff''s Manifesto: A Memoir of Thirty Jobs I Quit, Nine That Fired Me, and Three I Can''t Remember was published in 2003.","She convinced the stiff to go to her hotel room, where her henchman was waiting to rob him.","Realizing he had forgotten his wallet, he stiffed the taxi driver when the cab stopped for a red light."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prosper','vi.繁荣，兴旺；成功','/ˈpɹɒspə(ɹ)/','/ˈpɹɒspə(ɹ)/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blizzard','n.暴风雪，大风雪','/ˈblɪ.zəd/','/ˈblɪ.zɚd/','noun',["a blizzard of political ads"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appeal','vi.上诉，起诉；呼吁，恳求；吸引n.上诉，申诉；呼吁，恳求；感染力，吸引力','/əˈpiːl/','/əˈpiːl/','noun',["He made an appeal for volunteers to help at the festival.","I appeal to all of you to help the orphans.","That idea appeals to me."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swamp','n.沼泽地，湿地vt.使陷入，淹没；使应接不暇，使疲于应对','/swɒmp/','/swɑmp/','noun',["The boat was swamped in the storm.","I have been swamped with paperwork ever since they started using the new system."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entrepreneur','n.企业家；承包人','/ˌɒn.tɹə.pɹəˈnɜː/','/ˌɑn.trə.prəˈnɝ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transportation','n.运输；运输系统，运输工具','/tɹænspɔːˈteɪʃən/','/tɹænspɔːˈteɪʃən/','noun',["We have to get people out of their cars and encourage them to use alternative forms of transportation.","Mulligan''s sentence was commuted from death to transportation.","Nice transportation, dude, but your brake lights are busted."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dedicate','vt.致力于，奉献给；题献词于上','/ˈdɛdɪkeɪt/','/ˈdɛdɪkeɪt/','verb',["dedicated their money to scientific research.","dedicated ourselves to starting our own business.","dedicate a monument."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dye','v.染色n.颜料，染料','/daɪ/','/daɪ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extensive','adj.广大的，广阔的；广泛的，大量的','/ɛksˈtɛn.sɪv/','/ɛksˈtɛn.sɪv/','adjective',["I have done extensive research on the subject."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monotonous','adj.单调的，无聊的','/məˈnɒtənəs/','/məˈnɒtənəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negate','vt.取消；否定','/nɪˈɡeɪt/','/nɪˈɡeɪt/','verb',["The investigation tending to negate any supernatural influences.","Persecution can be negated through exposure.","a pessimism that always negates"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impart','vt.传授；传达；给予','/ɪmˈpɑːt/','/ɪmˈpɑːɹt/','verb',["The sun imparts warmth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inspire','vt.鼓舞，激励；给…以灵感','/ɪn.ˈspaɪə(ɹ)/','/ɪn.ˈspaɪə(ɹ)/','verb',["Elders should inspire children with sentiments of virtue."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bureaucracy','n.官僚主义，官僚作风；政府机构，官僚机构','/bjʊəˈɹɒkɹəsi/','/bjʊəˈɹɒkɹəsi/','noun',["At that time the administration replaced the system of patronage in the civil service with a bureaucracy.","The bureaucracy is expanding to meet the needs of the expanding bureaucracy. (apocryphal quip)","The head of the civil service promised to clamp down on bureaucracy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('geometry','n.几何，几何学','/dʒiːˈɒmɪtɹi/','/dʒiˈɑmətɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devote','vt.为…付出；献身于','/dɪˈvəʊt/','/dɪˈvoʊt/','verb',["I devoted this afternoon to repainting my study, and nothing will get in my way.","The city was devoted to the flames."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delectable','adj.美味可口的；有吸引力的；令人喜爱的，赏心悦目的','/dɪˈlɛktəbəl/','/dɪˈlɛktəbəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barb','n.鱼钩，倒钩；挖苦的话','/bɑː(ɹ)b/','/bɑː(ɹ)b/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alumnus','n.校友，毕业生','/əˈlʌmnəs/','/əˈlʌmnəs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('far-fetched','adj.牵强的','','','adjective',["He is full of far-fetched ideas to make money."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('approximate','adj.大约的，近似的vt.接近，近似','','','verb',["NASA''s Genesis spacecraft has on board an ion monitor to record the speed, density, temperature and approximate composition of the solar wind ions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('craftsman','n.能工巧匠，手艺人，工艺师','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('project','v.放映；规划；预测，推想n.方案；课题，项目；工程','','','noun',["Projects like Pruitt-Igoe were considered irreparably dangerous and demolished.","a man given to projects","The CEO is projecting the completion of the acquisition by April 2007."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aberrant','adj.越轨的；异常的','/əˈbɛɹ.n̩t/','/əˈbɛɹ.n̩t/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lope','vi.轻松地大步跑n.轻快的步伐','/ləʊp/','/loʊp/','noun',["He loped along, hour after hour, not fast but steady and covering much ground."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lateral','adj.侧面的，旁边的；横向的','/ˈlæt.ɹəl/','/ˈlæt.ɹəl/','noun',["Instead of a promotion, I opted for a lateral move to a similar position in the marketing department.","A fish senses changes in hydrodynamic pressure with its lateral line."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hinterland','n.内地，腹地；内地贸易区','/ˈhɪntə(ɹ)ˌlænd/','/ˈhɪntə(ɹ)ˌlænd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nominate','vt.任命，指定；提名，推荐','/ˈnɒm.ə.neɪt/','/ˈnɒm.ə.neɪt/','verb',["1658: the City of Norwich [...] was enlarged, builded and nominated by the Saxons. — Sir Thomas Browne, Urne-Burial (Penguin 2005, p. 12)","the nominate subspecies"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tread','v.踏，践踏；行走n.轮胎面；脚步声；步法','/tɹɛd/','/tɹɛd/','verb',["Don''t tread on the lawn.","Actors tread the boards.","to tread a path; to tread land when too light; a well-trodden path"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diameter','n.直径','/daɪˈæmɪtə(ɹ)/','/daɪˈæmɪtɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stationary','adj.静止的；固定的，稳定的，不变的','/ˈsteɪʃ(ə)n(ə)ɹi/','/ˈsteɪʃ(ə)n(ə)ɹi/','noun',["The train remained stationary for a few moments, before lurching forward along the track."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barn','n.谷仓；牲口棚','[bɑːn]','[baːn]','noun',["Maple Leaf Gardens was a grand old barn."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bark','v.吠叫；厉声质问n.树皮；犬吠声','/bɑːk/','/bɑɹk/','noun',["The neighbour''s dog is always barking.","The sergeant barked an order."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kennel','n.狗窝；养狗场','/ˈkɛnəl/','/ˈkɛnəl/','noun',["She raises registered Dalmatians at her kennel.","While we''re away our friends will kennel our pet poodle."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ellipse','n.椭圆，椭圆形','/iˈlɪps/','/iˈlɪps/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bare','adj.赤裸的；光秃的，无遮盖的；最基本的vt.脱掉；显露','/bɛə(ɹ)/','/bɛəɹ/','noun',["a bare majority","I do wonder why keeping my little breasts bare can be lewd even as none tells my brother anything for being bare-chested.","The cupboard was bare."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sidewalk','n.人行道','/ˈsaɪdwɔːk/','/ˈsaɪdwɔːk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('formidable','adj.难对付的；强大的；令人敬畏的','/fɔːˈmɪdəbəl/','/fɔːɹˈmɪdəbəl/','adjective',["a formidable opponent"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abound','vi.富于；大量存在；充满','/əˈbaʊnd/','/əˈbaʊnd/','verb',["Wild animals abound wherever man does not stake his claim.","The wilderness abounds in traps."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suitcase','n.手提箱，衣箱','/ˈsutkeɪs/','/ˈsutkeɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invert','vt.使倒转，使倒置，使颠倒','','','noun',["to invert a cup, the order of words, rules of justice, etc.","invert sugar"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discrete','adj.分离的，个别的；离散的','/dɪsˈkɹiːt/','/dɪsˈkɹiːt/','adjective',["a government with three discrete divisions","\"I resign my life, but not my honour\" is a discrete proposition."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('temperate','adj.气候温和的，温带的；温和的，自我克制的','/ˈtɛmpəɹət/','/ˈtɛmpəɹət/','verb',["a temperate climate.","temperate in eating and drinking.","temperate fishes"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immutable','adj.不可改变的，永恒不变的','','','noun',["The government has enacted an immutable law.","Constants are immutable."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disrupt','vt.使中断；扰乱；使分裂，使瓦解','/dɪsˈɹʌpt/','','verb',["Hecklers disrupted the man''s speech.","Work on the tunnel was disrupted by a strike.","The internet makes it easier for leaner businesses to disrupt the larger and more unwieldy ones."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scar','vt.给…留下疤痕；给…留下精神创伤；损害…的外观n.疤痕；创伤','/skɑː(ɹ)/','/skɑː(ɹ)/','noun',["Seeing his parents die in a car crash scarred him for life."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abort','v.夭折，中止；使流产','/əˈbɔːt/','/əˈbɔɹt/','noun',["We''ve had aborts on three of our last seven launches.","We''ve had three aborts over the last two days."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hypothetical','adj.假设的','/ˌhaɪpəˈθɛtɪkl/','/ˌhaɪpəˈθɛtɪkl/','noun',["These hypotheticals serve no purpose until we have more information."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coefficient','n.系数','/ˌkəʊ.iˈfɪʃn̩t/','/ˌkəʊ.iˈfɪʃn̩t/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('converse','vi.交谈，会话adj.逆向的，相反的n.相反的事物；反面','/kənˈvɜːs/','/kənˈvɜːs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gospel','n.准则，信条；绝对真理；[G-]福音；福音音乐；训示','/ˈɡɒspəl/','/ˈɡɒspəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eccentric','adj.古怪的，反常的n.古怪的人','/ɪkˈsɛntɹɪk/','/ɛkˈsɛntɹɪk/','noun',["As of 2008, Margaret had the most eccentric orbit of any moon in the solar system, though Nereid''s mean eccentricity is greater."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appliance','n.用具，器具；装置','/əˈplaɪəns/','/əˈplaɪəns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alloy','n.合金vt.使成合金','','','noun',["gold without alloy"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defer','v.推迟，延期','/dɪˈfɜː(ɹ)/','/dɪˈfɜː(ɹ)/','verb',["We''re going to defer the decision until we have all the facts."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drowsy','adj.昏昏欲睡的；催眠的','/ˈdɹaʊzi/','/ˈdɹaʊzi/','adjective',["I was feeling drowsy and so decided to make a cup of coffee to try to wake myself up.","It was a warm, drowsy summer afternoon."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lore','n.学问，学识；传说，传统','/lɔː/','/lɔɹ/','noun',["the lore of the Ancient Egyptians"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mast','n.船桅；旗杆；天线塔','/mæst/','/mæst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mass','adj.大量的n.质量；块，团；众多；群众，平民百姓','/mæs/','/mæs/','noun',["I mass 70 kilograms.","There is evidence of mass extinctions in the distant past.","Mass unemployment resulted from the financial collapse."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('muggy','adj.闷热的','/ˈmʌɡi/','/ˈmʌɡi/','adjective',["muggy straw"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revoke','vt.撤销，撤回；取消，废除','','','noun',["I hereby revoke all former wills."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proper','adj.正确的；合乎体统的，适当的；固有的，特有的','/ˈpɹɔp.ə/','/ˈpɹɑ.pɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('renaissance','n.[theR-]文艺复兴，文艺复兴时期；复兴，再生','/ˈɹɛnəˌsɑns/','/ˈɹɛnəˌsɑns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poisonous','adj.有毒的，有害的；恶毒的','/ˈpɔɪznəs/','/ˈpɔɪznəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('auction','n&v.拍卖','/ˈɒkʃən/','/ˈɔːkʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allot','vt.分配，配给，拨给','/əˈlɒt/','/əˈlɒt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('propel','vt.推进，驱使；激励','/pɹəˈpɛl/','/pɹəˈpɛl/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admit','v.承认；准许…进入，接纳','/ədˈmɪt/','/ədˈmɪt/','verb',["A ticket admits one into a playhouse.","the prisoner was admitted to bail","he admitted his guilt"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rampant','adj.猖獗的，肆虐的；蔓生的','/ˈɹæm.pənt/','/ˈɹæm.pənt/','adjective',["The Vienna riding school displays splendid rampant movement.","Weeds are rampant in any neglected garden.","There was rampant corruption in the city."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interest','n.兴趣，关注；业余爱好；利息；利害关系vt.使感兴趣，引起…关注','/ˈɪntəɹɪst/','/ˈɪntəɹst/','noun',["Our bank offers borrowers an annual interest of 5%.","He has a lot of interest in vintage cars.","I have business interests in South Africa."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uneven','adj.不平均的；不平坦的；不规则的；不势均力敌的；不公平的','/ʌnˈivən/','/ʌnˈivən/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('twig','n.嫩枝，小枝','/twɪɡ/','/twɪɡ/','noun',["They used twigs and leaves as a base to start the fire."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immature','adj.未成熟的，未充分发展的','/ɪməˈtjʊə(ɹ)/','/ɪməˈtjʊə(ɹ)/','noun',["The man was immature for throwing a tantrum."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('organic','adj.有机的；器官的；有机体的','/ɔːˈɡænɪk/','/ɔɹˈɡænɪk/','noun',["The writing of the script was an organic process.","The production came together in an organic whole."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chaste','adj.贞洁的；简朴的，朴实的','/tʃeɪst/','/tʃeɪst/','adjective',["a chaste style in composition or art","a chaste mind;  chaste eyes"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mask','n.面具；面罩；假面具，','/mæsk/','/mæsk/','noun',["a dancer''s mask; a fencer''s mask; a ball player''s mask","to mask a body of troops or a fortess by a superior force, while some hostile evolution is being carried out"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evacuation','n.撤离','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patron','n.资助人，赞助人；老主顾，顾客','/ˈpeɪ.tɹən/','/ˈpeɪ.tɹən/','noun',["This car park is for patrons only."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apply','v.申请，请求；适用；应用，运用；涂，敷，施','/əˈplaɪ/','/əˈplaɪ/','verb',["to apply cream to a rash","to apply funds to the repayment of a debt","We need to apply the skills we''ve learned to solve this problem"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stew','v.炖，煨；思考；不安，担忧n.炖菜；不安，担忧','/stʃʉː/','/stʃʉː/','noun',["to be in a stew","I''m going to stew some meat for the casserole."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overlook','vt.俯瞰，眺望；忽略；对…不予考虑','/əʊvəˈlʊk/','/oʊvəɹˈlʊk/','noun',["Our hotel room overlooks the lake.","These errors were overlooked by the proofreaders.","I’m not willing to overlook such bad behaviour."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incredible','adj.惊人的，难以置信的','/ɪŋˈkɹɛdɪbəl/','/ɪŋˈkɹɛdɪbəl/','adjective',["He was so wrapped up in watching the incredible special effects that he couldn''t keep track of the story.","I had such an incredible slice of pizza last night that I simply can''t think about anything else."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('layout','n.编排，版面设计；规划，布局','/ˈleɪ.aʊt/','/ˈleɪ.aʊt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('landing','n.登陆；着陆，降落','/ˈlændɪŋ/','/ˈlændɪŋ/','verb',["The plane is about to land.","It can be tricky to land a helicopter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('formula','n.公式，方程式；分子式；配方','/ˈfɔː.mjʊ.lə/','/ˈfɔː.mjʊ.lə/','noun',["H2O is the formula for water.","The company''s winning formula includes excellent service and quality products.","The formula of the rocket fuel has not been revealed."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('avalanche','n&v.雪崩；山崩','/ˈævəlɑːnʃ/','/ˈævəlæntʃ/','noun',["The shelf broke and the boxes avalanched the workers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revolt','v.反叛，反抗；违抗；厌恶，反感n.起义，叛乱，反抗','/ɹɪˈvɒlt/','/ɹɪˈvoʊlt/','noun',["The farmers had to revolt against the government to get what they deserved.","Your brother revolts me!","The stomach revolts at such food; his nature revolts at cruelty."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disgust','vt.厌恶，嫌恶','/dɪsˈɡʌst/','/dɪsˈɡʌst/','noun',["With an air of disgust, she stormed out of the room.","It disgusts me to see her chew with her mouth open."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tribute','n.贡品；颂词，称赞；悼念，致哀；礼物','/ˈtɹɪbjuːt/','/ˈtɹɪbjuːt/','noun',["Please accept this as a tribute of our thanks.","The Ancient Romans made their conquered countries pay tribute."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('endanger','vt.危及，危害','/ənˈdeɪndʒə/','/ənˈdeɪndʒə/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('base','adj.卑鄙的，不道德的vt.把设在；','/beɪs/','/beɪs/','noun',["The logarithm to base 2 of 8 is 3.","Peter adjusted the equalizer on his audio equipment to emphasize the bass.","The conductor preferred to situate the bass in the middle rear, rather than to one side of the orchestra."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stem','vt.阻止，遏制；起源n.茎，干','/stɛm/','/stɛm/','noun',["the stem of an apple or a cherry","to stem cherries; to stem tobacco leaves","The current crisis stems from the short-sighted politics of the previous government."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subordinate','adj.次要的；下级的vt.使处于次要地位，使从属于n.部属，下属','','','noun',["In the sentence “The barbecue finished before John arrived”, the subordinate clause “before John arrived” specifies the time of the main clause, “The barbecue finished”."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trend','n.趋势，倾向','/tɹɛnd/','/tɹɛnd/','noun',["the trend of a coastline","There is a trend, these days, for people in films not to smoke.","Miniskirts were one of the biggest trends of the 1960s."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mechanic','n.技工，机修工','/məˈkænɪk/','/məˈkænɪk/','noun',["This game has a mechanic where if you run toward a ledge you automatically jump off rather than just falling."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revolution','n.革命；巨变；旋转','/ˌɹɛvəˈl(j)uːʃən/','/ˌɹɛvəˈl(j)uːʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reliable','adj.可靠的，可信赖的','/ɹɪˈlaɪəbəl/','/ɹɪˈlaɪəbəl/','noun',["the old reliables"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incentive','n.刺激；动机','/ɪnˈsɛntɪv/','/ɪnˈsɛntɪv/','noun',["I have no incentive to do housework right now.","Management offered the sales team a $500 incentive for each car sold."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relate','v.叙述，讲述；有关联','/ɹiˈleɪt/','/ɹiˈleɪt/','verb',["Please relate the circumstances of your journey here today.","The patterns on the screen relate to the pitch and volume of the music being played.","I find it difficult to relate to others because I''m extremely introverted."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preliminary','adj.预备的，初步的n.初步做法，起始行为','/pɹɪˈlɪmɪnəɹi/','/pɹɪˈlɪmɪnəɹi/','noun',["These are just the preliminary results."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obstacle','n.障碍，妨害物','/ˈɒbstəkl̩/','/ˈɑbstəkl̩/','noun',["A big obstacle to understanding the manual was that it had been poorly translated from the Japanese."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leftover','adj.剩余的','','','noun',["It''s a leftover from yesterday, but it''s still perfectly good.","Not leftovers again!","Do you want some of the leftover supplies from the event?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collaborative','adj.合作的，协作的','','','noun',["No need to thank me - it was a collaborative effort."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('constitute','v.组成；设立；制定','/ˈkɒnstɪtjuːt/','/ˈkɒnstɪtjuːt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indict','vt.控诉，起诉，控告','/ˌɪnˈdaɪt/','/ˌɪnˈdaɪt/','verb',["a book that indicts modern values","his former manager was indicted for fraud"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('courier','n.送急件的人，信使；旅游服务员','/ˈkʊɹ.ɪə/','/ˈkʊɹ.ɪə/','noun',["We''ll have the contract couriered to you."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convince','vt.使确信，说服','/kənˈvɪns/','/kənˈvɪns/','verb',["I wouldn''t have or do something, unless I''m convinced that it''s good."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mate','v.交配n.配偶；朋友，伙伴；同事；大副','/meɪt/','/meɪt/','noun',["He''s my best mate.","Excuse me, mate, have you got the time?","I found one of the socks I wanted to wear, but I couldn''t find its mate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stampede','v.狂奔，涌向；使仓促行事n.逃窜，狂奔；热潮，风尚','/stæmˈpiːd/','/stæmˈpiːd/','noun',["The annual Muslim Hajj in Mecca, Saudi Arabia, which is attended by millions of pilgrims, has increasingly suffered from stampedes.","a stampede toward US bonds in the credit markets"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gorge','v.狼吞虎咽n.山峡，峡谷','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terminate','v.停止，结束','/ˈtɜːmɪneɪt/','/ˈtɜːmɪneɪt/','verb',["to terminate a surface by a line","Mountains on the Moon cast shadows that are very dark, terminate and more distinct than those cast by mountains on the Earth.","One third is a recurring decimal, but one half is a terminate decimal."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mannerism','n.怪癖，癖性；过分的独特风格','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theory','n.理论，原理；学说；见解，看法','/ˈθiːəɹi/','/ˈθiːəɹi/','noun',["Knot theory classifies the mappings of a circle into 3-space.","A theory is consistent if it has a model."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confederacy','n.联盟，同盟，联邦；私党','/kənˈfɛdəɹəsi/','/kənˈfɛdəɹəsi/','noun',["The Blackfoot, Iroquois, and Sioux peoples all were governed as confederacies.  There were also multi-ethnic confederacies, such as the Iron Confederacy made up of the Plains Cree, Assiniboine, Stoney, and Saulteaux."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flock','vi.聚结，成群n.群；一群；大量','/flɒk/','/flɑk/','noun',["People flocked to the cinema to see the new film."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extension','n.延长；延伸；电话分机，分机号码','/ɪkˈstɛnʃən/','/ɪkˈstɛnʃən/','noun',["Files with the .txt extension usually contain text.","a browser extension"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('internal','adj.内在的，内部的；国内的，内政的；内心的','/ɪnˈtɝnəl/','/ɪnˈtɝnəl/','adjective',["We saw the internal compartments.","Her bleeding was internal.","The nation suffered from internal conflicts."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gender','n.性别；性','/ˈdʒɛndə/','/ˈdʒɛndə/','noun',["The effect of the medication is dependent upon age, gender, and other factors.","His low voice allowed him to become a bass in the choir.","to cultivate the voice"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('literary','adj.文学的；文人的，书卷气的','/ˈlɪt(ə)ɹi/','/ˈlɪtəɹɛ(ə)ɹi/','adjective',["a literary history","a literary man"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('architect','n.建筑师；设计师，缔造者','/ˈɑːkɪtɛkt/','/ˈɑɹkɪtɛkt/','noun',["Plato made the causes of things to be matter, ideas, and an efficient architect.","Peisistratus was the first architect of the Iliad and the Odyssey.","He architected the military coup against the government."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excise','vt.切除；删去','/ˈɛkˌsaɪz/','/ˈɛkˌsaɪz/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punch','vt.拳打；打孔；按，压n.重拳击打；冲床，打孔机','/pʌntʃ/','/pʌntʃ/','noun',["If she punches me, I''m gonna break her nose.","He punched a hit into shallow left field.","to punch one with the end of a stick or the elbow"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('across','adv.横过；到对面，向对面prep.穿过，越过；在对面','/əˈkɹɑs/','/əˈkɹɔs/','noun',["I solved all of the acrosses, but then got stuck on 3 down.","she helped the blind man across;  the river is half a mile across","If we sail off at noon, when will we be across?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flexibility','n.灵活性；弹性，韧性；适应性','','','noun',["I had some flexibility in terms of whether to stay in a hotel or in a bed-and-breakfast."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mortgage','n.抵押贷款，按揭；抵押证书vt.用…作抵押','/ˈmɔː.ɡɪdʒ/','/ˈmɔɹ.ɡɪdʒ/','noun',["We''re renting a property in the city centre because we can''t afford to get a mortgage yet.","lands given in mortgage","We mortgaged our house in order to start a company."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('identity','n.身份；特征，特性；同一性','/aɪˈdɛntəti/','/aɪˈdɛntəti/','noun',["I''ve been through so many changes, I have no sense of identity.","This criminal has taken on several identities.","2013 April 4, \"Cricket identities consult lawyers\", New Zealand Herald"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('federal','adj.联邦的；联邦制的；联邦政府的','/ˈfɛdəɹəl/','/ˈfɛdəɹəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('verify','v.检验，核实','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excursion','n.远足，短途旅游','/ɛks.kɜː(ɹ).ʃən/','/ɛks.kɜː(ɹ).ʃən/','noun',["While driving home I took an excursion and saw some deer."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inaugurate','vt.为…举行就职典礼；为…举行开幕式；开始，开创','/ɪˈnɔːɡjʊɹət/','/ɪˈnɔːɡjʊɹət/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cramp','n.痉挛，抽筋；vt.阻碍，阻止','/kɹæmp/','/kɹæmp/','noun',["You''re cramping my style.","You''re going to need to cramp the wheels on this hill.","to cramp boot legs"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('academy','n.学会，研究院；专科院校','/əˈkæd.ə.mi/','/əˈkæd.ə.mi/','noun',["the military academy at West Point; a riding academy; the Academy of Music.; a music academy; a language academy"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solitude','n.孤独，单独；独处，独居；隐居处','/ˈsɒlɪˌtjuːd/','/ˈsɑlɪˌtud/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reward','n.报答，奖赏，报酬vt.奖赏，奖励，给以报酬','/ɹəˈwɔːd/','/ɹiˈwɔɹd/','noun',["For catching the thief, you''ll get a nice reward.","The rewards for bringing in badly wanted criminals are printed on ''dead or alive'' posters","Is this the reward I get for telling the truth: to be put in jail?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hockey','n.曲棍球','/ˈhɒki/','/ˈhɒki/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('graze','v.吃草；放牧；擦伤n.擦伤','/ɡɹeɪz/','/ɡɹeɪz/','noun',["1999: Although it is perfectly good meadowland, none of the villagers has ever grazed animals on the meadow on the other side of the wall. — Stardust, Neil Gaiman, page 4 (2001 Perennial Edition).","Cattle graze in the meadows.","the bullet grazed the wall"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swallow','v.吞，咽；吞没，侵吞；轻信，轻易接受；默默忍受；使不流露，抑制n.燕子；吞，咽','/ˈswɒləʊ/','/ˈswɑloʊ/','noun',["He took the aspirin with a single swallow of water.","My throat was so sore that I was unable to swallow.","to swallow one''s opinions"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perquisite','n.津贴，利益；特权','/ˈpɜːkwɪzɪt/','/ˈpɜːkwɪzɪt/','noun',["The perquisites of this job include health insurance and a performance bonus.","After the wonderful service that evening he didn’t hesitate in laying a substantial perquisite on the table.","Private jets and motor yachts are a perquisite of the rich."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hominid','adj.灵长目的n.原始人类；人科动物','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nucleus','n.(原子)核','/ˈnjuː.kli.əs/','/ˈnuːkli.əs/','noun',["This collection will form the nucleus of a new library."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sting','v.刺，蜇；感觉刺痛n.尾刺；刺痛','/stɪŋ/','/stɪŋ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('juice','vt.榨出汁液n.汁，液','/d͡ʒuːs/','/d͡ʒus/','noun',["Squeeze the orange and some juice will come out.","I’d like two orange juices please."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('haste','v.赶快，匆忙n.急忙，急速，匆忙','/heɪst/','/heɪst/','noun',["We were running late so we finished our meal in haste."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nurture','vt.养育，养护，培养；扶植，支持；滋长，助长n.养育，培养','/ˈnɜːɹ.tʃəɹ/','/ˈnɜːɹ.tʃəɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('buckle','v.扣紧；变形，弯曲n.皮带扣环','/ˈbʌk(ə)l/','/ˈbʌk(ə)l/','verb',["It is amazing that he has never buckled after so many years of doing such urgent work."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('degenerate','vi.退化，衰退adj.堕落的；退化的','','','noun',["In the cult of degenerates, acts of decency, kindness and modesty could be seen as acts of apostasy.","His condition continued to degenerate even after admission to hospital."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('destructive','adj.破坏性的，毁灭性的','/dɪˈstɹʊktɪv/','/dɪˈstɹʊktɪv/','adjective',["Catabolism is a destructive metabolism that involves the breakdown of molecules and release of energy.","Blurring an image is a destructive operation, but rotating an image is not."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monastery','n.男修道院，寺院','/ˈmɒnəstɹi/','/ˈmɑnəstəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devout','adj.虔敬的；诚恳的','/dɪˈvaʊt/','/dəˈvʌʊt/','noun',["devout sighs; devout eyes; a devout posture","devout wishes for one''s welfare"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('censor','n.审查员vt.审查，检查','/ˈsɛnsə/','/ˈsɛnsɚ/','noun',["The Ancient Roman censors were part of the cursus honorum, a series of public offices held during a political career, like consuls and praetors.","The headmaster was an even stricter censor of his boarding pupils’ correspondence than the enemy censors had been of his own when the country was occupied.","Occupying powers typically censor anything reeking of resistance"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devour','vt.狼吞虎咽地吃，吞食；吞没，吞噬；如饥似渴地读','/dɪˈvaʊ(w)ə(ɹ)/','','verb',["The fire was devouring the building.","She intended to devour the book.","After the death of his wife, he was devoured by grief."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stir','v.搅拌；煽动；激发，打动；行动，活动n.搅拌，搅动；激动，震动','/stɜː/','/stɝ/','noun',["Can you give the soup a little stir?","She stirred the pudding with a spoon.","Would you please stand here and stir this pot so that the chocolate doesn''t burn?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insult','vt.侮辱，凌辱n.侮辱，凌辱','/ɪnˈsʌlt/','/ɪnˈsʌlt/','noun',["The way the orchestra performed tonight was an insult to my ears."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('existence','n.存在，实在；生存，生活','/ɛɡ.ˈzɪs.təns/','/ɛɡ.ˈzɪs.təns/','noun',["In order to destroy evil, we must first acknowledge its existence."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('craft','v.手工制作n.手艺，工艺','/kɹɑːft/','/kɹæft/','noun',["The craft of writing plays.","He learned his craft as an apprentice.","She represented the craft of brewers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('axis','n.轴；轴线，中心线','/ˈæksəs/','/ˈæksɪs/','noun',["The Earth rotates once a day on its axis"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maze','n.迷宫；复杂难懂的细节；困惑，迷惘vt.使混乱；使困惑，迷惑','/ˈmeɪz/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('float','v.漂浮，浮动；飘动','/fləʊt/','/floʊt/','noun',["Attach the float and the weight to the fishing line, above the hook.","When pouring a new driveway, you can use a two-by-four as a float.","That float covered in roses is very pretty."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gaseous','adj.气体的，气态的','/ˈɡæʃəs/','/ˈɡæʃəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negligent','adj.忽略的；疏忽的；粗心大意的','/ˈnɛɡ.lɪ.dʒənt/','/ˈnɛɡ.lɪ.dʒənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expressive','adj.有表现力的，富有表情的；表示…的，表现…的','/ɪkˈspɹɛsɪv/','/ɪkˈspɹɛsɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conductivity','n.传导性；传导率','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('desolate','adj.荒凉的，无人烟的；不幸的，忧伤的vt.使感到悲惨，使感到凄凉；使荒芜','','','verb',["a desolate isle; a desolate wilderness; a desolate house","desolate altars","He was left desolate by the early death of his wife."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coarse','adj.粗糙的；粗俗的','/kɔːs/','/kɔːɹs/','adjective',["coarse language"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evade','v.逃避，回避；躲开，避开','/ɪˈveɪd/','/ɪˈveɪd/','verb',["He evaded his opponent''s blows."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('associative','adj.联想的；结合的；关联的','/əˈsoʊ.si.ə.tɪv/','/əˈsoʊ.si.ə.tɪv/','adjective',["AWK''s associative arrays may be indexed by strings."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exaggerate','v.夸张，夸大','/ɛɡˈzæ.dʒə.ɹeɪt/','/ɛɡˈzæ.dʒə.ɹeɪt/','verb',["He said he''d slept with hundreds of girls, but I know he''s exaggerating. The real number is about ten."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cortex','n.皮层，皮质','/ˈkɔːtɛks/','/ˈkɔːtɛks/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imply','vt.意味着，暗示；说明，表明；使有必要','/ɪmˈplaɪ/','/ɪmˈplaɪ/','verb',["The proposition that \"all dogs are mammals\" implies that my dog is a mammal","When I state that your dog is brown, I am not implying that all dogs are brown"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('offset','n.分支；补偿；抵消vt.补偿；抵消','/ɒfˈsɛt/','/ɒfˈsɛt/','noun',["Today''s victory was an offset to yesterday''s defeat.","offset lithographs","An array of bytes uses its index as the offset, of words a multiple thereof."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('backhand','n.反手击球','/ˈbækhænd/','/ˈbækhænd/','noun',["He scored on a backhand shot."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cascade','vi.倾泻，流注n.小瀑布；倾泻','/kæsˈkeɪd/','/kæsˈkeɪd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cavity','n.腔；洞，穴，窟窿；龋洞','[ˈkʰævɪɾi]','[ˈkʰævɪɾi]','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sequence','n.一系列，一连串；顺序，次序，序列vt.按顺序排列','/ˈsiːkwəns/','/ˈsiːkwəns/','noun',["Complete the listed tasks in sequence."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('provision','n.供应，供应品；条款；准备，预备','/pɹəˈvɪʒ.ən/','/pɹəˈvɪʒ.ən/','noun',["We increased our provision for bad debts on credit sales going into the recession.","An arrest shall be made in accordance with the provisions of this Act.","to provision an army"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recruit','v.招募，征募n.新兵；新成员','/ɹɪˈkɹuːt/','/ɹɪˈkɹuːt/','noun',["These new recruits were hired after passing the interviews","We need to recruit more admin staff to deal with the massive surge in popularity of our products","the army was recruited for a campaign"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thrust','v.挤；插；戳，刺n.戳，刺；要旨；驱动力','/θɹʌst/','/θɹʌst/','noun',["Pierre was a master swordsman, and could parry the thrusts of lesser men with barely a thought.","The cutpurse tried to knock her satchel from her hands, but she avoided his thrust and yelled, \"Thief!\"","Spacecraft are engineering marvels, designed to resist the thrust of liftoff, as well as the reverse pressure of the void."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abolition','n.废除，废止；废奴运动','/ˌæb.əˈlɪʃ.n̩/','/ˌæb.əˈlɪʃ.n̩/','noun',["the abolition of debts;   the abolition of laws;   the abolition of slavery;   the abolition of police;;   the abolition of taxes"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sporadic','adj.偶发的，间或出现的，零星的','/spɒˈɹædɪk/','/spɔˈɹæɾɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turnout','n.出席人数；产量，产额','','','noun',["When towing a trailer, use the turnouts to let faster traffic pass.","A man with a showy carriage and horses is said to have a fine turnout."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('configuration','n.布局，格局；结构，构造，形状；配置','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scientific','adj.科学的；细致严谨的','/ˌsaɪənˈtɪfɪk/','/ˌsaɪənˈtɪfɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spherical','adj.球形的，球状的','/sfiːɹɪkəl/','/sfiːɹɪkəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chunk','n.厚片，大块；相当大的部分；矮胖的人','/t͡ʃʌŋk/','/t͡ʃʌŋk/','noun',["The statue broke into chunks.","a chunk of granite","examples of chunks would include \"in accordance with\", \"the results of\", and \"so far\""]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('asteroid','n.小行星','/ˈæstəɹoɪd/','/ˈæstəɹoɪd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commonplace','adj.普通的，平凡的n.平凡的事；老生常谈','/ˈkɒmənˌpleɪs/','/ˈkɑmənˌpleɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('libel','vt.诽谤n.诽谤；诽谤性文字','/ˈlaɪbəl/','/ˈlaɪbəl/','noun',["He libelled her when he published that."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parameter','n.参量，参数；界限，范围','/pəˈɹæm.ɪ.tə/','','noun',["Roughly, a tuple of arguments could be thought of as a vector, whereas a tuple of parameters could be thought of as a covector (i.e., linear functional). When a function is called, a parameter tuple becomes \"bound\" to an argument tuple, allowing the function instance itself to be computed to yield a return value. This would be roughly analogous to applying a covector to a vector (by taking their dot product (or, rather, matrix-product of row vector and column vector)) to obtain a scalar.","The parameter of the principal axis of a conic section is called the latus rectum."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extinct','adj.灭绝的，不存在的；不再活跃的','/ɛkˈstɪŋkt/','/ɛkˈstɪŋkt/','verb',["Poor Edward''s cigarillo was already extinct.","Luckily, such ideas about race are extinct in current sociological theory.","The dinosaurs have been extinct for millions of years."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forerunner','n.先驱者，开路人；先兆，预兆','','','noun',["Bakelite is a forerunner of today''s plastics."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cubism','n.立体派；立体主义','/ˈkjuː.bɪz.əm/','/ˈkjuː.bɪz.əm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agonize','vi.苦苦思索；焦虑不已','/ˈæ.ɡən.aɪz/','/ˈæ.ɡən.aɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('percolate','v.过滤；渗入，渗透；逐渐流传，传开n.滤液','/ˈpɜːkəleɪt/','/ˈpəɹkəleɪt/','noun',["Water percolates through sand.","I''ll percolate some coffee.","Reports on the pitiful state of many prisons have finally percolated through to the Home Office, which has promised to look into the situation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opaque','adj.不透明的，不透光的；难懂的，晦涩的','/əʊˈpeɪk/','/əʊˈpeɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advantage','n.优点；优势，有利条件vt.有益于','/ədˈvɑːn.tɪdʒ/','/ədˈvæn.tɪdʒ/','noun',["The enemy had the advantage of a more elevated position.","Having the faster car is of little advantage."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assistant','adj.辅助的，助理的；副的n.助手，助教','/əˈsɪstənt/','/əˈsɪstənt/','noun',["an assistant surgeon"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humid','adj.湿的，潮湿的；湿润的','/ˈhjuːmɪd/','/ˈhjuːmɪd/','adjective',["humid earth"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instead','adv.代替，顶替；反而，却','/ɪnˈstɛd/','/ɪnˈstɛd/','adverb',["I was going to go shopping, but I went dancing instead."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('controversy','n.争论，辩论','/kənˈtɹɒvəsi/','/ˈkɑntɹəˌvɝsi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('command','n&v.命令；指挥，统率','/kəˈmɑːnd/','/kəˈmænd/','noun',["I was given a command to cease shooting.","to have command of an army","England has long held command of the sea"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compulsory','adj.必须做的，义务的；强制性的；必修的','/kəmˈpʌlsəri/','/kəmˈpʌlsəri/','noun',["The ten-dollar fee was compulsory.","Such compulsory measures are limited."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abortive','adj.落空的，失败的','/əˈbɔː.tɪv/','/əˈbɔː.tɪv/','noun',["an abortive child","an abortive attempt","an abortive organ"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swarm','vi.云集v.密集，云集；成群地飞行n.群，一大群','/swɔːm/','/swɔɹm/','noun',["a swarm of meteorites"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anticipate','v.预见，预期；先于…行动','/ænˈtɪs.ɪ.peɪt/','/ænˈtɪs.ə.peɪt/','verb',["The advocate plans to anticipate a part of her argument.","Please anticipate a journey of an hour from your house to the airport","Little Johnny started to anticipate the arrival of Santa Claus a week before Christmas."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('variable','adj.易变的；','/ˈvɛəɹ.i.ə.bl̩/','/ˈvæɹ.i.ə.bl̩/','noun',["There are several variables to consider here.","variable winds or seasons; a variable quantity; a variable resistor"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('temple','n.寺庙，教堂；太阳穴','/ˈtɛmp(ə)l/','/ˈtɛmp(ə)l/','noun',["a temple of commerce, a temple of drinking and dining","My body is my temple."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slash','v.砍；大幅削减n.砍痕，伤痕；斜线号','/slaʃ/','/slaʃ/','noun',["Slash generated during logging may constitute a fire hazard.","The province''s traditional slash-and-burn agriculture was only sustainable with a much smaller population."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fabricate','vt.编造；制造','/ˈfæb.ɹɪ.keɪt/','/ˈfæb.ɹɪ.keɪt/','verb',["to fabricate a bridge or ship","to fabricate computer chips","to fabricate a lie or story"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uproot','v.根除；离开家园','/ʌpˈɹuːt/','/ʌpˈɹuːt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tally','v.吻合n.记录；账','/ˈtæli/','/ˈtæli/','interjection',["(Air Traffic Control): Speedbird 123, New York, traffic at two o’clock, seven miles, a Boeing 737, west-bound, at 4000 feet.”"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('landscape','n.风景，景色；地貌，地形；风景画vt.美化…的环境','/ˈlandskeɪp/','/ˈlandskeɪp/','noun',["The software patent landscape has changed considerably in the last years"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exception','n.除外，例外','/əkˈsɛpʃən/','/əkˈsɛpʃən/','noun',["That rule is usually true, but there are a few exceptions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prevailing','adj.普遍的；流行的；一地常刮的，盛行的','/pɹɪˈveɪ.lɪŋ/','/pɹɪˈveɪ.lɪŋ/','verb',["Red colour prevails in the Canadian flag.","In his day and age, such practices prevailed all over Europe.","I prevailed on him to wait."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('temporary','adj.暂时的，临时的','/ˈtɛmpəɹi/','/ˈtɛmpəˌɹɛɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('habitat','n.自然环境，栖息地','/ˈhæbɪtæt/','/ˈhæbɪtæt/','noun',["This park offers important amphibian habitat and breeding area."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('optimal','adj.最佳的，最理想的','/ˈɒptɪməl/','/ˈɑptɪməl/','noun',["Finding the optimal balance between features and price is a common problem."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('desperate','adj.绝望的；不顾死活的，拼命的；极度渴望的','/ˈdɛsp(ə)ɹət/','','noun',["I hadn''t eaten in two days and was desperate for food.","I was so desperate at one point, I even went to see a loan shark.","a desperate effort"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awful','adj.不舒服的；糟糕的；可怕的；非常的','/ˈɔːfəl/','/ˈɔfəl/','adjective',["My socks smell awful.","I have learnt an awful amount today.","He was blubbering away something awful."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('urge','v.促进，力劝；驱赶，驱策n.强烈的欲望，冲动','/ɜːd͡ʒ/','/ɝd͡ʒ/','noun',["to urge an argument; to urge the necessity of a case","to urge an ore with intense heat"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handy','adj.可用的；易使用的，便利的；手巧的','/ˈhæn.di/','/ˈhæn.di/','adjective',["Some people regard duct tape as a handy fix-all.","I keep a first-aid kit handy in case of emergency.","She''s very handy: she made all her own kitchen cupboards."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anguish','v.极度痛苦n.极度痛苦','/ˈæŋ.ɡwɪʃ/','/ˈæŋ.ɡwɪʃ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refraction','n.折射','/ɹəˈfɹækʃən/','/ɹəˈfɹækʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('visual','adj.视觉的','/ˈvɪʒuəl/','/ˈvɪʒuəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sanctuary','n.禁猎区，动物保护区；庇护所，避难所；圣所，圣殿','/ˈsæŋktjʊəɹi/','/ˈsæŋktjʊəɹi/','noun',["My car is a sanctuary, where none can disturb me except for people who cut me off.","The bird sanctuary has strict restrictions on visitors so the birds aren''t disturbed.","The government granted sanctuary to the defector, protecting him from his former government."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aerobics','n.有氧运动','/əˈɹoʊbɪks/','/əˈɹoʊbɪks/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inviting','adj.动人的，诱人的；引人注目的','/ɪnˈvaɪtɪŋ/','/ɪnˈvaɪtɪŋ/','verb',["We invited our friends round for dinner.","I invite you all to be seated.","I always invite criticism of my definitions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instruct','vt.指示；教授','/ˌɪnˈstɹʌkt/','/ˌɪnˈstɹʌkt/','noun',["Listen carefully when someone instructs you how to assemble the furniture.","The doctor instructed me to keep my arm immobilised and begin physiotherapy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agreeable','adj.使人愉快的；欣然同意的','/əˈɡɹiːəbl/','/əˈɡɹiːəbl/','noun',["agreeable manners","Agreeable to the order of the day, the House took up the report."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('merchant','n.商人','/ˈmɜːtʃənt/','/ˈmɝtʃənt/','noun',["a merchanting service"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('community','n.社会；社团；群落；共同体','/k(ə)ˈmjunəti/','/k(ə)ˈmjunəti/','noun',["a community of goods"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ailment','n.小病','/ˈeɪlmənt/','/ˈeɪlmənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('version','n.译文，译本；版本','/ˈvɜːʃən/','/ˈvɝʒən/','noun',["It''s only in the King James Version of the Bible.","He gave another version of the affair.","Upgrade to the latest version for new features and bug fixes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('charismatic','adj.蒙受神恩的；有超凡魅力的','/ˌkæɹɪzˈmætɪk/','/ˌkæɹɪzˈmætɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overload','vt.使超载，使过载；使超负荷；给…增加负担n.超载；超负荷','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bronze','adj.青铜色的n.青铜；青铜色；青铜制品；铜牌','/bɹɒnz/','/bɹɑnz/','noun',["She wanted to win the tournament, but had to settle for the bronze after being beaten in the semi-finals.","My mother bronzed my first pair of baby shoes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('staunch','adj.坚定的，忠诚的','/stɑːntʃ/','/stɑːntʃ/','verb',["Somebody''s got to staunch those press leaks!","He''s been a staunch supporter of mine through every election.","Without our staunch front line the enemy would have split the regiment."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('selection','n.选择，挑选；精选；被挑选出来的人，精选品；可供选择的事物','/səˈlɛkʃən/','/səˈlɛkʃən/','noun',["The large number of good candidates made selection difficult.","My final selection was a 1934 Chateau Lafitte.","I''ve brought a selection of fine cheeses to go with your wine."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adolescence','n.青春','/ˌædəˈlɛsəns/','/ˌædəˈlɛsəns/','noun',["During adolescence, the body and mind go through many complex changes, some of which are difficult to deal with."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notch','n.等级，档次；','/nɒtʃ/','/nɒtʃ/','noun',["Can you speak a notch louder, please?","The tribe''s hunters notch their kills by notches on each''s axe''s handle.","The team notched a pair of shutout wins on Sunday."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subculture','n.亚文化行为观念，次文化','','','noun',["The goth subculture has its own mode of dress, and it has a characteristic musical style."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exhale','v.呼出；散发','/ɛksˈheɪl/','/ɛksˈheɪl/','noun',["The earth exhales vapor; marshes exhale noxious effluvia.","The sun exhales the moisture of the earth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appropriate','adj.适当的vt.拨款；占用，挪用','','','verb',["Let no man appropriate the use of a common benefit.","A spot of ground is appropriated for a garden.","The headmaster wondered what an appropriate measure would be to make the pupil behave better."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('least','adv.最小；最少；微不足道adj.最小的；最少的；最不重要的','/list/','/list/','noun',["It was the least surprising thing.","They travel the least of all."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('utility','n.功用，效用；公用事业','/juːˈtɪl.ɪ.ti/','/juːˈtɪl.ɪ.ti/','noun',["I''ve bought a new disk utility that can recover deleted files.","utility line; utility bill","utility room"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abrasion','n.表面磨损','/əˈbɹeɪ.ʒn̩/','/əˈbɹeɪ.ʒn̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symphony','n.交响乐，交响曲；和谐，协调','/ˈsɪm.fə.ni/','/ˈsɪm.fə.ni/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eloquent','adj.雄辩的；动人的','/ˈɛl.əˌkwənt/','/ˈɛl.əˌkwənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('observatory','n.天文台，天文观测站','/əbˈzəːvət(ə)ɹi/','/əbˈzəɹvətɔɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('optimistic','adj.乐观的','/ˌɒptɪˈmɪstɪk/','/ˌɒptɪˈmɪstɪk/','adjective',["in an optimistic mood","optimistic concurrency"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proponent','n.支持者；倡导者','/pɹəˈpəʊnənt/','/pɹəˈpoʊnənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insolvent','adj.财力不足的，破产的','','','noun',["an insolvent debtor","an insolvent estate"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('submarine','adj.水下的，海底的n.潜水艇','/sʌb.məˈɹiːn/','/sʌb.məˈɹiːn/','noun',["a submarine patent"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('empiricism','n.经验论，经验主义','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sleek','adj.光滑而有光泽的；线条流畅的；时髦的vt.使平整光亮','/sliːk/','/sliːk/','noun',["sleek hair"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('particle','n.微粒，颗粒；【语】小品词','/ˈpɑːtɪk(ə)l/','/ˈpɑɹtɪkəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('musician','n.音乐家，乐师','/mjuˈzɪʃən/','/mjuˈzɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('typify','vt.是…的典范；成为…的特征','/ˈtɪpɪfaɪ/','/ˈtɪpɪfaɪ/','verb',["His attitude typifies the attitude of young people today.","The angry captain typified all new sailors as incompetent.","The chosen specimen typifies plants belonging to that species."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stagnant','adj.不景气的；停滞的；迟钝的；因不流动而污浊的','/ˈstæɡnənt/','/ˈstæɡnənt/','adjective',["a stagnant pool","a stagnant economy"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perceptive','adj.感知的，知觉的；有洞察力的，理解力强的','/pəˈsɛptɪv/','/pəˈsɛptɪv/','adjective',["He is so perceptive when it comes to other people''s feelings."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('annotation','n.注释，注解','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minimize','vt.将…减到最少，使最小化；降低，贬低','/ˈmɪn.ə.maɪz/','/ˈmɪn.ə.maɪz/','verb',["I didn''t close anything, but I minimized all the windows so I could see the desktop."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sweep','v.打扫；席卷，横扫；挥动，舞动；迅速传播；','/swiːp/','/swiːp/','noun',["Give the front steps a quick sweep to get rid of those fallen leaves.","Bradman attempted a sweep, but in fact top edged the ball to the wicket keeper","Jim will win fifty dollars in the office sweep if Japan wins the World Cup."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('descend','v.遗传；下降；起源；降临，来临','/dɪˈsɛnd/','/dɪˈsɛnd/','verb',["The rain descended, and the floods came.","And on the suitors let thy wrath descend.","he descended from his high estate"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mechanics','n.机械学，力学；技巧，方法','','','noun',["the mechanics of a board game"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toed','adj.有趾的','/toʊd/','/toʊd/','adjective',["He become more pigeon-toed with age."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maglev','n.磁力悬浮火车','/ˈmæɡ.lɛv/','/ˈmæɡ.lɛv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('logical','adj.逻辑的；符合逻辑的，合理的；有逻辑头脑的','/ˈlɒdʒɪkəɫ/','/ˈlɑdʒɪkəɫ/','adjective',["Logical memory appears contiguous to an application program, but may well be stored on several physical devices, including in RAM and on hard-disks, as determined by the operating system."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('characterize','vt.以…为特征；刻画；描述','/ˈkæɹəktəɹaɪz/','/ˈkæɹəktəɹaɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('descent','n.血统，世系；下降','/dɪˈsɛnt/','','noun',["We climbed the mountain with difficulty, but the descent was easier.","We had difficulty in finding the correct descent.","The descent into the cavern was wet and slippery."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stunt','vt.阻碍生长；遏制n.特技表演；噱头；愚蠢行为','/stʌnt/','/stʌnt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weird','adj.怪异的，神秘的','/ˈwiːəd/','/ˈwiɚd/','noun',["There are lots of weird people in this place.","It was quite weird to bump into all my ex-girlfriends on the same day.","There was a weird light shining above the hill."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('farce','n.笑剧，滑稽剧；闹剧','/fɑːs/','/fɑɹs/','noun',["The farce that we saw last night had us laughing and shaking our heads at the same time.","The first month of labor negotiations was a farce.","The political arena is a mere farce, with all sorts of fools trying to grab power."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ridiculous','adj.荒唐的，可笑的','/ɹiːˈdɪkjʊləs/','/ɹiːˈdɪkjʊləs/','adjective',["It''s ridiculous to charge so much for a little souvenir.","Gaines is a classic motor player with a low center of gravity and ridiculous strength."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intrusion','n.侵扰，干扰；侵犯；侵入，闯入','/ɪnˈtɹuːʒən/','/ɪnˈtɹuːʒən/','noun',["He viewed sales calls as an unwelcome intrusion."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refute','vt.反驳，驳斥','/ɹəˈfjut/','/ɹəˈfjut/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('severe','adj.严重的；严厉的；剧烈的；严峻的，艰巨的；朴素的，不加装饰的','/sɪˈvɪə/','','adjective',["a severe taskmaster","a severe old maiden aunt"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exemplify','vt.是…的典型；例示，举例证明','/ɛɡˈzɛmplɪfaɪ/','/ɛɡˈzɛmplɪfaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emerge','vi.显露，暴露；出来，现出','/iˈmɜːd͡ʒ/','/iˈmɜːd͡ʒ/','verb',["He emerged unscathed from the accident.","Gradually the truth emerged."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lease','n.租约；租期vt.出租','/liːs/','/liːs/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exploit','vt.开发；利用；剥削n.英勇行为，业绩，功绩','','','noun',["The first trek to the summit of Mount Everest was a stunning exploit.","Materialistic monsters who exploit \"kind\" folks will not have good outcomes, no matter how much comforts were ill-gained."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eager','adj.渴望的，热切的','/ˈiːɡə/','/ˈiɡɚ/','adjective',["I was eager to show my teacher how much I''d learned over the holidays.","an eager algorithm"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evidence','vt.证明n.证据；迹象；根据','[ˈɛvəɾəns]','[ˈɛvəɾəns]','noun',["There is no evidence that anyone was here earlier.","She was furious, as evidenced by her slamming the door."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('republic','n.共和国；共和政体','[ɹɪˈpʌblɪk]','[ɹɪˈpʌblɪk]','noun',["The United States is a republic; the United Kingdom of Great Britain and Northern Ireland is a constitutional monarchy.","The Republic of Udmurtia is west of the Permian Oblast."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('errand','n.差事，差使','/ˈɛɹənd/','/ˈɛɹənd/','noun',["All the servants were on holiday or erranded out of the house.","She spent an enjoyable afternoon erranding in the city."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flamboyant','adj.艳丽的，绚丽夺目的；炫耀的','/flamˈbɔɪənt/','/flæmˈbɔɪ(j)ənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lethal','adj.致命的；破坏性极大的，极其有害的','/ˈliː.θəl/','/ˈliː.θəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stun','vt.使昏迷；使震惊；使…目瞪口呆，给以深刻印象','/stʌn/','/stʌn/','noun',["Williams will need a lot of stun to avoid going in the middle pocket","Bill tried to stun the snake by striking it on the head.","He stood there stunned, looking at the beautiful, breath-taking sunrise."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repetition','n.重复，反复；重复的事','/ɹɛpəˈtɪʃən/','/ɹɛpəˈtɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sled','v.乘雪橇，用雪橇运n.雪橇；摘棉机','/slɛd/','/slɛd/','noun',["The child zoomed down the hill on his sled.","\"Mush!\" he yelled at the dogs pulling the sled."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('polygamous','adj.一夫多妻的，一妻多夫的','/pəˈlɪɡəməs/','/pəˈlɪɡəməs/','adjective',["That Mormon community no longer practises polygamous relationships."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suspense','n.担心，焦虑；悬念，不确定','/səˈspɛns/','/səˈspɛns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gemstone','n.经雕琢的宝石','/ˈdʒɛmˌstoʊn/','/ˈdʒɛmˌstoʊn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('narrate','v.讲述，叙述','/nəˈɹeɪt/','/nəˈɹeɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spring','v.跳跃；涌现，突然出现；突然提出n.泉；弹簧，发条；春天；跳，跃','/spɹɪŋ/','/spɹɪŋ/','verb',["to sprain one''s ankle","Spring is the time of the year most species reproduce.","The documentary made tears spring to their eyes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('autonomy','n.自治，自治权；自主，自主权','/ɑˈtɑnəmi/','/ɔˈtɑnəmi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gibe','n&v.嘲弄，讥笑','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fitness','n.健康，健壮；适合','/ˈfɪtnəs/','/ˈfɪtnəs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shred','n.碎片，细条；些许，少量vt.切碎，撕碎','/ʃɹɛd/','/ʃɹɛd/','noun',["There isn''t a shred of evidence to support his claims."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kindle','v.点燃，开始燃烧；激起','/ˈkɪndl/','/ˈkɪndl/','verb',["He kindled an enthusiasm for the project in his fellow workers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surrender','v.投降；放弃，交出n.投降；屈服，屈从；放弃','/səˈɹɛndəɹ/','/səˈɹɛndəɹ/','noun',["I surrender!","to surrender a right, privilege, or advantage","to surrender oneself to grief, to despair, to indolence, or to sleep"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('faint','vi.昏厥，晕倒adj.模糊的，不清楚的；无力的，虚弱的；眩晕的n.昏厥','/feɪnt/','/feɪnt/','noun',["She suffered another faint.","I felt faint after my fifth gin and tonic.","There was a faint red light in the distance."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elm','n.榆树','/ɛlm/','/ɛlm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shade','n.阴凉处，遮光物；阴暗；色度；差别vt.遮蔽，遮光','/ʃeɪd/','/ʃeɪd/','noun',["The old oak tree gave shade in the heat of the day.","Close the shade, please: it''s too bright in here.","I''ve painted my room in five lovely shades of pink and chartreuse."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collide','vi.碰撞，互撞；冲突，抵触','/kəˈlɑɪd/','','verb',["When a body collides with another, then momentum is conserved.","China collided with the modern world."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cardinal','adj.主要的，最重要的n.红衣凤头鸟','/ˈkɑː.dɪ.nəl/','/ˈkɑɹdnəl/','noun',["a cardinal rule","a cardinal mark"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insist','v.坚持要求；坚决主张','/ɪnˈsɪst/','/ɪnˈsɪst/','verb',["I insist that my secretary dresses nicely.","I insist that my secretary dress nicely."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evergreen','adj.常绿的n.常绿树，常青树','/ˈɛvəɡɹiːn/','/ˈɛvəɡɹiːn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('staggered','adj.交错的，错开的；震惊的','','','verb',["The U.S. Senate holds staggered elections, with only one third of the seats being filled every two years."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('volume','n.体积，容积，容量；音量；卷，册；书','/ˈvɒl.juːm/','/ˈvɑl.jum/','noun',["The room is 9x12x8, so its volume is 864 cubic feet.","Please turn down the volume on the stereo.","I looked at this week''s copy of the magazine. It was volume 23, issue 45."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transact','v.交易；执行，处理','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('catalyst','n.催化剂，触媒；促使变化的人','/ˈkæt.əl.ɪst/','/ˈkæt.əl.ɪst/','noun',["Economic development and integration are working as a catalyst for peace."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guideline','n.指导方针，指导原则','','','noun',["He considered the Ten Commandments more a guideline than a requirement."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loose','adj.松散的，宽松的；不精确的，不严密的；不牢固的；自由的，散漫的','/luːs/','/luːs/','noun',["This wheelbarrow has a loose wheel.","''You can buy apples in a pack, but they are cheaper loose.","The dog is loose again."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loathsome','adj.令人厌恶的，讨厌的','/ˈləʊð.səm/','/ˈləʊð.səm/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flint','n.燧石，打火石','/flɪnt/','/flɪnt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preeminent','adj.卓越的，杰出的','/pɹiːˈɛmɪnənt/','/pɹiːˈɛmɪnənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indignant','adj.愤慨的，恼怒的','/ɪnˈdɪɡ.nənt/','/ɪnˈdɪɡ.nənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decimal','adj.十进位的，小数的n.小数','[ˈdɛsɪməɫ]','/ˈdɛsɪməl/','noun',["Pi has a value of 3.142, to three decimals."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hardly','adv.几乎不，简直不；刚刚，仅仅','/ˈhɑːdli/','/ˈhɑɹdli/','adverb',["I can''t really deal hardly with people.","they hardly ever watch television;  I hardly think they''ll come in this bad weather;  it''s hardly possible he could lose the election.","I think the Beatles are a really overrated band. ― Hardly!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lasting','adj.持久的，永久的','/ˈlastɪŋ/','/ˈlastɪŋ/','verb',["Summer seems to last longer each year.","I don''t know how much longer we can last without reinforcements.","to last a boot"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cynical','adj.愤世嫉俗的，冷嘲热讽的','/ˈsɪnɪkəl/','/ˈsɪnɪkəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('technical','adj.技术的，工艺的；专业的','/ˈtɛk.nɪk.əl/','/ˈtɛk.nɪk.əl/','noun',["The performance showed technical virtuosity, but lacked inspiration.","The market had a technical rally, due to an oversold condition.","Crossing the front lawn of that house to get to the mailbox was a technical trespass."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outermost','adj.最外面的，离中心最远的','/ˈaʊtɚmoʊst/','/ˈaʊtɚmoʊst/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('companion','n.同伴，共事者','/kəmˈpænjən/','/kəmˈpænjən/','noun',["His dog has been his trusted companion for the last five years.","The companion guide gives an in-depth analysis of this particular translation.","a companion of the Bath"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('culminate','vi.达到顶点；告终；【天】到中天','/ˈkʌlmɪneɪt/','/ˈkʌlmɪneɪt/','verb',["The class will culminate with a rigorous examination."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tortuous','adj.折磨人的，令人痛苦的；曲折的，蜿蜒的；含混不清的，拐弯抹角的','/ˈtɔːt͡ʃuːəs/','/ˈtɔːt͡ʃuːəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paucity','n.极小量，少量','/ˈpɑsɪti/','/ˈpɑsɪti/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stretch','v.延伸，拉长n.一段路程；延伸','/stɹɛtʃ/','/stɹɛtʃ/','noun',["I was right in the middle of a stretch when the phone rang.","That rubber band has quite a bit of stretch.","It''s a bit of a stretch to call Boris Karloff a comedian."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strand','n.股，缕；部分，方面vt.使滞留；使搁浅','/stɹænd/','/stɹænd/','noun',["Grand Strand","Jones pops up; that''s going to strand a pair."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accomplish','vt.达到；完成；实现','/əˈkɐm.plɪʃ/','/əˈkɑm.plɪʃ/','verb',["to accomplish a design, an object, a promise"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('constituent','adj.有宪法制定或修改权的；组成的，构成的n.选民；要素，成分','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intentionally','adv.有意地，故意地','','','adverb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('irritate','vt.激怒，使烦躁；刺激','/ˈɪɹɪteɪt/','/ˈɪɹɪteɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('havoc','n.混乱，大破坏','/ˈhæv.ək/','/ˈhæv.ək/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('responsible','adj.有责任感的，负责的；需负责任的；责任重大的，重要的','/ɹɪˈspɒnsəbl̩/','/ɹɪˈspɑnsəbl̩/','noun',["Parents are responsible for their child''s behaviour.","Who is responsible for this mess?","She has a responsible position in the firm."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vagrant','adj.漂泊的n.无业游民，流浪者','/ˈveɪɡɹənt/','/ˈveɪɡɹənt/','noun',["Every morning before work, I see that poor vagrant around the neighbourhood begging for food."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('medal','n.奖牌，奖章','[ˈmɛd.ɫ̩]','[ˈmeɾ.ɫ̩]','noun',["He medalled twice at the Olympics."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('linen','n.亚麻织品；亚麻布','/ˈlɪnɪn/','/ˈlɪnɪn/','noun',["She put the freshly cleaned linens into the linen closet."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('satellite','n.卫星；人造卫星','/ˈsætəlaɪt/','/ˈsætəlaɪt/','noun',["A spent upper stage is a derelict satellite.","Many telecommunication satellites orbit at 36000km above the equator.","Do you have satellite at your house?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('packed','adj.拥挤的；压紧的','/pækt/','/pækt/','verb',["to pack a horse","packed lunch","packed with goodness"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('illuminate','vt.照亮；启发，启迪；阐明，说明','/ɪlˈl(j)uməneɪt/','/ɪlˈl(j)uməneɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lizard','n.蜥蜴','/ˈlɪz.əd/','/ˈlɪz.ɚd/','noun',["lounge lizard; lot lizard; beach lizard; truck stop lizard"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delirium','n.精神错乱，神志失常','/dɪˈlɪɹɪəm/','/dɪˈlɪɹɪəm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preoccupation','n.主要考虑因素；全神贯注','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vow','v.发誓n.誓约','/vaʊ/','/vaʊ/','noun',["The old hermit, up in the mountains, took a vow of silence.","The wronged woman vowed revenge.","The rebels vowed to continue their fight."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cipher','n.密码，暗号','/ˈsaɪfə/','/ˈsaɪfɚ/','noun',["a painter''s cipher, an engraver''s cipher, etc.","The message was written in a simple cipher. Anyone could figure it out.","The message is clearly a cipher, but I can''t figure it out."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('protrude','v.突出，伸出','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('residue','n.剩余物，残余物','/ˈɹɛzɪdjuː/','/ˈɹɛzɪdjuː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noted','adj.著名的','/ˈnəʊtɪd/','/ˈnoʊtɪd/','verb',["If you look to the left, you can note the old cathedral.","We noted his speech.","The modular multiplicative inverse of x may be noted x-1."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frenzy','n.狂暴，狂热，疯狂','/ˈfɹɛnzi/','/ˈfɹɛnzi/','noun',["She went into a cleaning frenzy to prepare for the unexpected guests."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forum','n.论坛；讨论会','/ˈfɔːɹəm/','/ˈfɔːɹəm/','noun',["Trish was an admin on three forums, and had no trouble at all when it came to moderating them."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contempt','n.轻视，鄙视，轻蔑','/kənˈtɛmpt/','/kənˈtɛmpt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horizon','n.地平线；','/həˈɹaɪzən/','/həˈɹaɪzən/','noun',["A tall building was visible on the horizon.","Some students take a gap year after finishing high school to broaden their horizons."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('undertaking','n.任务，项目；事业，企业；承诺，保证','/ˈʌndə(ɹ)ˌteɪkɪŋ/','/ˈʌndə(ɹ)ˌteɪkɪŋ/','verb',["He undertook to exercise more in future.","I hate people who try and undertake on the motorway."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('figurative','adj.比喻的，借喻的，象征的；形象的','/ˈfɪɡəɹətɪv/','/ˈfɪɡəɹətɪv/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sweat','v.出汗n.汗；一身汗','/swɛt/','/swɛt/','noun',["Just thinking about the interview tomorrow puts me into a nervous sweat.","the sweat of hay or grain in a mow or stack"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('progressive','adj.进步的；逐步的，渐进的；【语】进行时的','/pɹəˈɡɹɛsɪv/','/pɹəˈɡɹɛsɪv/','noun',["a progressive politician","a progressive school","progressive paralysis"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('betray','vt.出卖，泄露；辜负，对…不忠；流露情感','/bəˈtɹeɪ/','/bəˈtɹeɪ/','verb',["an officer betrayed the city","My eyes have been betraying me since I turned sixty.","Though he had lived in England for many years, a faint accent betrayed his Swedish origin."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aloft','adv.在高处；在空中','/əˈlɑft/','/əˈlɔft/','adverb',["high winds aloft"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contributory','adj.贡献的；捐助的；促进的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deliberate','adj.故意的，蓄意的；审慎的，深思熟虑的v.深思熟虑','','','verb',["It is now time for the jury to deliberate the guilt of the defendant.","Tripping me was deliberate action.","The jury took eight hours to come to its deliberate verdict."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swear','v.诅咒；宣誓，发誓','/swɛə/','/swɛɚ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('atmosphere','n.大气，大气层；空气；气氛，氛围','/ˈæt.məsˌfɪə(ɹ)/','/ˈætməsˌfɪɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decorate','v.装饰，布置','/ˈdɛkəɹeɪt/','/ˈdɛkəɹeɪt/','verb',["We decorated the Christmas tree with tinsel and baubles.","There''s some paint left over from when we decorated the guest bedroom.","People tend to decorate for the holidays or special events."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('career','n.生涯，经历；职业','/kəˈɹɪə/','/kəˈɹɪɹ/','noun',["Washington''s career as a soldier","The car careered down the road, missed the curve, and went through a hedge."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slacken','v.松弛，放松；减缓，放慢','/ˈslæ.kən/','/ˈslæ.kən/','verb',["The pace slackened.","to slacken lime"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('release','n&vt.释放；发布，公开；发泄','/ɹɪˈliːs/','/ɹɪˈliːs/','noun',["The video store advertised that it had all the latest releases.","They marked the occasion with a release of butterflies.","He released his grasp on the lever."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('charter','vt.特许设立，给予特权；包租n.纲领，宣言；宪章；特许状','/ˈt͡ʃɑːtə/','/ˈt͡ʃɑːtə/','noun',["2005 November 30, Stephen Foley \"The market where ''caveat emptor'' has become a charter for fraud\" The Independent, London"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abiding','adj.持久的，永久的','/əˈbaɪ.dɪŋ/','/əˈbaɪ.dɪŋ/','verb',["The old oak tree abides the wind endlessly.","a deep and abiding hatred of wealth"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liberate','vt.解放；释放','/ˈlɪbəɹeɪt/','/ˈlɪbəɹeɪt/','verb',["We didn''t need IDs. We just liberated these beers from the back of the shop."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moral','adj.道德的，道义上的；有道德的，品行端正的；精神的','/ˈmɒɹəl/','/ˈmɑɹəl/','noun',["a candidate with strong morals","moral judgments;  a moral poem","a moral obligation"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diminution','n.减少，缩减','/dɪmɪˈnjuːʃ(ə)n/','/dɪmɪˈnjuːʃ(ə)n/','noun',["The new emission standards have produced a measurable diminution in air pollution."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aspire','v.有志于；热望，向往','/əˈspaɪə(ɹ)/','/əˈspaɪɚ/','verb',["He aspires to become a successful doctor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explode','v.爆炸；激增；冲动，发怒','/ɪkˈspləʊd/','/ɪkˈsploʊd/','verb',["The assassin exploded the car by means of a car bomb.","They sought to explode the myth.","Explode the assembly drawing so that all the fasteners are visible."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outbreak','n.发作；爆发','/ˈaʊtbɹeɪk/','/ˈaʊtbɹeɪk/','noun',["Any epidemic outbreak causes understandable panic.","There has been an outbreak of broken windows in the street.","There has been an outbreak of vandalism at the school."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nap','n.小睡，打盹','/nap/','/nap/','noun',["The regulators were caught napping by the financial collapse."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('manipulate','vt.操作，处理；利用，操纵','/məˈnɪpjʊleɪt/','/məˈnɪpjʊleɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('similar','adj.相似的，类似的','/ˈsɪmələ/','/ˈsɪməlɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ecological','adj.生态的','/ˌiːkəˈlɒd͡ʒɪkl̩/','/ˌiːkəˈlɒd͡ʒɪkl̩/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contradict','v.反驳；同…矛盾，相抵触','/kɒntɹəˈdɪkt/','/kɒntɹəˈdɪkt/','verb',["His testimony contradicts hers.","Everything he says contradicts me."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('digitize','vt.数字化','/ˈdɪdʒɪtaɪz/','/ˈdɪdʒɪtaɪz/','verb',["to digitize a pen"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('partnership','n.合伙；伙伴关系；合伙人身份','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shape','n.形状，外形，样子；体形，身材；形式；幻象；情况，状况vt.使成为…形状，塑造；决定…的形成','/ʃeɪp/','/ʃeɪp/','noun',["The used bookshop wouldn''t offer much due to the poor shape of the book.","The vet checked to see what kind of shape the animal was in.","He cut a square shape out of the cake."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('verbalize','v.用言语表达','','','verb',["Bill became tongue-tied and could not verbalize his thoughts in the presence of the girl he had a crush on."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('momentous','adj.重大的，重要的','/məʊˈmɛn.təs/','/moʊˈmɛn.təs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('specify','vt.使具体化；明确规定，详细说明','/ˈspɛsɪfaɪ/','/ˈspɛsɪfaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allegiance','n.忠诚，效忠，拥戴','/əˈliː.dʒəns/','/əˈliː.dʒəns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wanna','v.想要','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crossing','n.十字路口，人行横道；过境处；交叉点；穿越，横渡','/ˈkɹɑsɪŋ/','/ˈkɹɔsɪŋ/','verb',["They managed to cross a sheep with a goat."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relevance','n.有关，相关；中肯，适当；重大关系，意义；实用性','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quarry','v.采石；采集n.采石场，石矿；猎物，追捕的对象','/ˈkwɒɹi/','/ˈkwɔɹi/','noun',["Michelangelo personally quarried marble from the world-famous quarry at Carrara.","They quarried out new, interesting facts about ancient Egypt from old papyri."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gravel','n.沙砾，砾石','/ˈɡɹævəl/','/ˈɡɹævəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('malnutrition','n.营养不良','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('submerge','v.浸没，淹没','/sʌbˈmɜːdʒ/','/sʌbˈmɜːdʒ/','verb',["The submarine submerged in the water.","In films many people are murdered by being submerged in swimming pools.","Because of the death of his father, he is submerged in sorrow."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('converge','vi.汇聚，聚集，聚合；相交，会合；趋于一致','/kən.ˈvɜːdʒ/','/kən.ˈvɜːdʒ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pertinent','adj.相关的；恰当的，贴切的','/ˈpəːtɪnənt/','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compose','v.创作；组成；使安定','/kəmˈpəʊz/','/kəmˈpoʊz/','verb',["The editor composed a historical journal from many individual letters.","A church is composed of its members.","It''s difficult to compose without absolute silence."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('giraffe','n.长颈鹿','/dʒɪˈɹɑːf/','/d͡ʒəˈɹæf/','noun',["Are you having a giraffe?!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supersonic','adj.超音速的，超声波的n.超音速，超声波','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cell','n.细胞；基层组织；单人房间；电池','/sɛl/','/sɛl/','noun',["Gregor Mendel must have spent a good amount of time outside of his cell.","The combatants spent the night in separate cells.","This MP3 player runs on 2 AAA cells."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swell','v.增加，扩大；膨胀，肿胀n.波浪的涌动；隆起；增强，增加','/swɛl/','/swɛl/','verb',["Rains and dissolving snow swell the rivers in spring.","The organ music swelled.","to be swelled with pride or haughtiness"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remind','vt.提醒；使想起；使发生联想','/ɹəˈmaɪnd/','/ɹəˈmaɪnd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crude','adj.天然的，未提炼的；粗糙的；粗俗的','/kɹʉd/','/kɹuːd/','noun',["crude oil","a crude shelter","a crude truth"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('valid','adj.有根据的，合理的；有效的','/ˈvælɪd/','/ˈvælɪd/','adjective',["I will believe him as soon as he offers a valid answer.","A valid format for the date is MM/DD/YY.","An argument is valid if and only if the set consisting of both (1) all of its premises and (2) the contradictory of its conclusion is inconsistent."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('withstand','vt.经受住，耐；抵挡','/wɪðˈstænd/','/wɪðˈstænd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inertia','n.惯性；惰性','','/ɪnˈɝ.ʃə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('epitomize','vt.成为…的缩影；摘要，概括，缩写','/əˈpɪt.əˌmaɪz/','/əˈpɪt.əˌmaɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wintry','adj.冬天的；寒冷的；冷淡的','/ˈwɪnt(ə)ɹɪ/','/ˈwɪnt(ə)ɹɪ/','adjective',["wintry weather","It will be cloudy overnight, with outbreaks of heavy rain at times. The rain may turn wintry over higher ground.","a wintry remark"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('encourage','v.鼓励，激励；促进，激发','/ɪnˈkʌɹɪdʒ/','/ɪnˈkɝɹɪdʒ/','verb',["I encouraged him during his race.","We encourage the use of bicycles in the town centre.","The royal family has always encouraged the arts in word and deed"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vacuum','n.真空；真空状态，空白，','/ˈvæ.kjuː.əm/','/ˈvæ.kjuː.əm/','noun',["a vacuum of 26 inches of mercury, or 13 pounds per square inch"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('era','n.纪元，年代，时代；代','/ˈɪə̯ɹ.ə/','/ˈɛɹ.ə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('administer','vt.管理；执行；给予，提供','/ədˈmɪnɪstɚ/','/ədˈmɪnɪstɚ/','verb',["We administered the medicine to our dog by mixing it in his food.","administering to the sick"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transplant','vt.移植；使迁移，使移居；移栽，移种n.移植','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deficit','n.不足额；赤字，逆差','/ˈdɛfɪsɪt/','/ˈdɛfɪsɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elegant','adj.优美的，高雅的；雅致的，精美的；简练的，简洁的','/ˈɛl.ə.ɡənt/','/ˈɛl.ə.ɡənt/','adjective',["an elegant solution"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cohere','vi.连贯，一致；黏合；齐心协力，团结一致','/koʊˈhɪɹ/','/koʊˈhɪɹ/','verb',["Separate molecules will cohere because of electromagnetic force.","Members of the party would cohere in the message they were sending."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snowflake','n.雪花，雪片','/ˈsnəʊ.fleɪk/','/ˈsnoʊ.fleɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('linger','vi.徘徊，流连；继续存留；缓慢消失','/ˈlɪŋɡə/','/ˈlɪŋɡə/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grasshopper','n.蚂蚱，蝗虫','/ɡɹæsˌhɒpə(ɹ)/','/ˈɡɹæsˌhɑpəɹ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dispel','vt.驱散，驱逐；消除','[dɪˈspɛɫ]','[dɪˈspɛɫ]','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cascara','n.缓泻剂','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slip','v.滑倒，失足；滑落；悄悄疾行，溜；摆脱；下降，跌落；陷入n.差错，纰漏；滑倒；纸片','/slɪp/','/slɪp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('species','n.种类，类群','/ˈspiːsiːz/','/ˈspiːsiːz/','noun',["the male species"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anchor','v.抛锚；使固定；扎根，基于；主持n.锚；给人安全感的物，精神支柱','/ˈæŋ.kə/','/ˈæŋ.kɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('manifesto','n.宣言，声明','/ˌmæn.əˈfɛs.təʊ/','/ˌmæn.əˈfɛs.təʊ/','noun',["A creed is a manifesto of religious or spiritual beliefs."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quench','vt.扑灭，熄灭；解','/kwɛnt͡ʃ/','/kwɛnt͡ʃ/','noun',["The library quenched her thirst for knowledge.","The swordsmith quenched the sword in an oil bath so that it wouldn''t shatter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spice','n.香料，调味品；趣味，情趣vt.加香料于；给…增添趣味','/spaɪs/','/spaɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pedagogy','n.教育学，教学法','/ˈpɛdəˌɡoʊdʒi/','/ˈpɛdəˌɡoʊdʒi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('screen','vt.掩蔽；审查；筛选n.屏幕','/skɹiːn/','/skɹiːn/','noun',["a fire screen","a drug screen, a genetic screen","Mary screened the beans to remove the clumps of gravel."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('autonomous','adj.自治的；独立自主的','/ɔːˈtɒnəməs/','/ɔˈtɑnəməs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('naked','adj.裸露的，无遮盖的；直白的，露骨的，不加掩饰的','/ˈnɛkɪd/','/ˈnɛkɪd/','adjective',["She was as naked as the day she was born.","The naked facts lay there on the table, enclosed within the files.","I entered her naked and came in her too."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vibration','n.振动，颤动','/vaɪˈbɹeɪʃən/','/vaɪˈbɹeɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aerial','adj.空中的，地表以上的；从飞行器上的n.天线','/ˈɛː.ɹi.əl/','/ˈɛː.ɹi.əl/','noun',["The seabirds put on an astonishing aerial display.","The aerial photographs clearly showed the damage caused by the storm."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trial','n.审讯；试验，试用；令人伤脑筋的人','/ˈtɹaɪəl/','/ˈtɹaɪəl/','noun',["They will perform the trials for the new equipment next week.","That boy was a trial to his parents.","soccer trials"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perception','n.感知，感觉；认识，观念；洞察力','/pəˈsɛpʃ(ə)n/','/pɚˈsɛpʃ(ə)n/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('saturation','n.饱和；饱和度','','','noun',["Modulation often requires that amplifiers operate below saturation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stylistic','adj.风格上的，文体上的','/staɪˈlɪstɪk/','/staɪˈlɪstɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('undertake','v.承担；进行，从事','/ʌndəˈteɪk/','','verb',["He undertook to exercise more in future.","I hate people who try and undertake on the motorway."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('optimize','vt.使最优化；充分利用','/ˈɒptɪmaɪz/','/ˈɑptɪmaɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indigenous','adj.本地的，本土的；土产的；土著的','/ɪnˈdɪdʒɪnəs/','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('visualize','v.想象，使形象化；构思','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rejuvenate','vt.使年轻；使恢复活力','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obituary','n.讣闻，讣告','/əʊ̯ˈbɪtjʊəɹiː/','/əʊ̯ˈbɪtjʊəɹiː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bureau','n.局，署；办公室；机构','/ˈbjʊɹ.oʊ/','/ˈbjʊɹ.oʊ/','noun',["a news bureau; a travel bureau; a service bureau; an employment bureau; the Citizens Advice Bureau"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moist','adj.潮湿的；多雨的','/mɔɪst/','/mɔɪst/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cable','v.给…发电报，用电报传送n.缆绳，钢索；电缆；电报','/keɪ.bl/','/keɪ.bl/','noun',["I tried to watch the movie last night but my cable was out."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intense','adj.强烈的；热切的；激烈的','/ɪnˈtɛns/','/ɪnˈtɛns/','adjective',["intense study;  intense thought","The artist was a small, intense man with piercing blue eyes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thrifty','adj.节省的，节俭的','/ˈθɹɪfti/','/ˈθɹɪfti/','adjective',["a thrifty person","a thrifty plant"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yelp','v.尖叫n.短而尖的叫声','/jɛlp/','/jɛlp/','noun',["The puppy let out a yelp when I stepped on her tail."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('estate','n.地产；庄园；个人财产，遗产','/ɪsˈteɪt/','/ɪsˈteɪt/','noun',["an estate diamond; estate jewelry"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acoustic','adj.非电声乐器的，原声的；听觉的，声音的','/əˈkuːstɪk/','/əˈkuːstɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('articulate','adj.善于表达的；发音清晰的，口齿清楚的v.明确表达，清楚说明；清晰地吐，清晰地发；用关节连接','/ɑː(ɹ)ˈtɪk.jʊ.lət/','/ɑːɹˈtɪk.jə.lət/','noun',["She’s a bright, articulate young woman.","The robot arm was articulate in two directions.","an articulate period in history"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brass','n.铜管乐器；黄铜','/bɹɑːs/','/bɹæs/','noun',["The brass are not going to like this.","You''ve got a lot of brass telling me to do that!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dignify','vt.使有尊严，使高贵；美化','/ˈdɪɡnɪfaɪ/','','verb',["I will not dignify that comment with a response."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bluster','v.虚张声势地恫吓；猛刮','/ˈblʌs.tə/','/ˈblʌs.tɚ/','noun',["When confronted by opposition his reaction was to bluster, which often cowed the meek."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('traverse','v.横穿，横渡','/tɹəˈvɜːs/','/tɹəˈvɜːs/','noun',["He will succeed, as long as there are no unlucky traverses not under his control.","He will have to traverse the mountain to get to the other side.","to traverse all nodes in a network"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impending','adj.即将发生的，迫近的','/ɪmˈpɛndɪŋ/','/ɪmˈpɛndɪŋ/','verb',["I have no time right now because of an impending paper submission deadline."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rigorous','adj.缜密的，谨慎的；严格的，严厉的','/ˈɹɪɡəɹəs/','/ˈɹɪɡəɹəs/','adjective',["a rigorous execution of law","a rigorous winter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amino','adj.氨基的','/əˈmiːnəʊ/','/əˈmiːnəʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('secular','adj.现世的；世俗的；非宗教的','/ˈsɛkjʊlə/','/ˈsɛkjələɹ/','noun',["secular clergy in Catholicism","The secular games of ancient Rome were held to mark the end of a saeculum and the beginning of the next.","The long-term growth in population and income accounts for most secular trends in economic phenomena."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('activate','vt.刺激，使活动','/ˈæktɪˌveɪt/','/ˈæktɪˌveɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strenuous','adj.费劲的，费力的，艰苦的；精力充沛的；奋力的','/ˈstɹɛnjuəs/','/ˈstɹɛnjuəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lethargy','n.死气沉沉；无精打采，倦怠','/ˈlɛθədʒi/','/ˈlɛθədʒi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amusement','n.可笑；娱乐，消遣','/əˈmjuzmənt/','/əˈmjuzmənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boundary','n.分界线；边界','/ˈbaʊndɹi/','/ˈbaʊndəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shame','n.羞耻，羞愧，耻辱；可耻的人vt.使羞愧；玷辱','/ʃeɪm/','/ʃeɪm/','noun',["The teenager couldn’t bear the shame of introducing his parents.","It was a shame not to see the show after driving all that way.","Shame, you poor thing, you must be cold!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('endow','vt.使天生具有，赋予；资助，捐赠','/ɛn-/','/ɛn-/','verb',["She was endowed with a beautiful voice."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precipitate','v.使…突然降临；加速；降水；使突然陷入；adj.仓促的，鲁莽的','/pɹəˈsɪpɪteɪt/','/pɹəˈsɪpɪteɪt/','verb',["it precipitated their success","we were precipitated into a conflict","Adding the acid will cause the salt to precipitate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('centric','adj.以…为中心的','/ˈsɛntɹɪk/','/ˈsɛntɹɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mandate','v.强制执行；授权n.授权；委托书，授权令；任期','/ˈmæn.deɪt/','/ˈmæn.deɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slog','v.艰难行进；埋头苦干；猛击','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('financial','adj.财政的，财务的，金融的','/faɪˈnænʃəl/','/faɪˈnænʃəl/','adjective',["For financial reasons, we''re not going to be able to continue to fund this program.","Jerry is a financial member of the club."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('respective','adj.分别的，各自的','/ɹɪˈspɛktɪv/','/ɹɪˈspɛktɪv/','adjective',["They returned to their respective places of abode.","the respective connections of society"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inactivate','vt.使不活动，使不活跃','/ɪˈnæktɪveɪt/','/ɪˈnæktɪveɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('media','n.媒介，媒体','/ˈmiːdɪə/','/ˈmiːdɪə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plaudit','n.喝彩；赞美','/ˈplɔːdɪt/','/ˈplɔːdɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exalt','vt.高度赞扬，褒扬；提升，提拔','/ɪɡˈzɔːlt/','/ɪɡˈzɔːlt/','verb',["They exalted their queen.","The man was exalted from a humble carpenter to a minister."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reversible','adj.可逆的，可翻转的；正反两用的；可恢复原状的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('define','vt.定义，解释；限定','/dɪˈfaɪn/','/dɪˈfaɪn/','noun',["the defining power of an optical instrument","I define myself as a techno-anarchist.","The textbook defined speed as velocity divided by time."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dictate','v.规定；决定；口述；支配n.命令，规定','/ˈdɪkˌteɪt/','/ˈdɪkˌteɪt/','noun',["I must obey the dictates of my conscience.","She is dictating a letter to a stenographer."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flick','v.轻拍；移动n.轻拍；浏览','/flɪk/','/flɪk/','noun',["He removed the speck of dust with a flick of his finger.","My all-time favorite flick is \"Gone with the Wind.\"","a flick of bacon"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('memorize','vt.记住，记忆，熟记','/ˈmɛm.əɹˌaɪ̯z/','/ˈmɛm.əɹˌaɪ̯z/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('render','vt.给予，提供；致使；递交，呈献；表达；翻译','/ˈɹɛn.də/','/ˈɹɛn.dɚ/','noun',["A low-resolution render might look blocky.","The shot rendered her immobile.","The pianist rendered the Beethoven sonata beautifully."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('haven','n.港口；庇护所，避难所；栖息处','/ˈheɪvən/','/ˈheɪvən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neon','n.氖；霓虹灯','/ˈni.ɒn/','/ˈni.ɒn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('manifest','adj.明显的vt.表明，显示n.货物清单','/ˈmæn.ə.fɛst/','/ˈmæn.ə.fɛst/','noun',["His courage manifested itself through the look on his face."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relieve','vt.缓解，减轻；使轻松，使宽慰；调剂；接替，换班','/ɹɪˈliːv/','/ɹɪˈliːv/','verb',["I was greatly relieved by the jury''s verdict.","This shall not relieve either Party of any obligations."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('buffalo','n.水牛；野牛','/ˈbʌf.əl.əʊ/','/ˈbʌf.ə.loʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('endeavor','vi&n.努力，尽力','/ɪnˈdɛv.ə/','/ɛnˈdɛv.ɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quartz','n.石英','/kwɔːts/','/kwɔɹts/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prelude','n.前奏曲，序幕','/ˈpɹeɪl(j)uːd/','/ˈpɹeɪl(j)uːd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adjacent','adj.邻近的，毗连的','/əˈdʒeɪ.sənt/','/əˈdʒeɪ.sənt/','noun',["Because the conference room is filled, we will have our meeting in the adjacent room.","The picture is on the adjacent page.","A notice was sent to the house adjacent the school."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transport','n.运输；运输系统，运载工具vt.运输；传播','','','noun',["The transport of goods is not included in the price given on the website.","The local transport received a big boost as part of the mayor''s infrastructural plans.","to transport goods; to transport troops"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grump','vi.发脾气，发牢骚n.脾气不好的人','/ɡɹʌmp/','/ɡɹʌmp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('specific','adj.明确的，具体的；特定的，特有的','/spəˈsɪf.ɪk/','/spəˈsɪf.ɪk/','noun',["a highly specific test, specific and nonspecific symptoms","Quinine is a specific medicine in cases of malaria."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sprain','n&vt.扭伤','/spɹeɪn/','/spɹeɪn/','noun',["a bad sprain of the wrist","to sprain one''s ankle"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prioritize','v.划分优先顺序；优先处理','/pɹaɪˈɒɹətaɪz/','/pɹaɪˈɒɹətaɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engage','v.从事于，忙于；吸引；订婚；聘用','/ɛnˈɡeɪdʒ/','/ɛnˈɡeɪdʒ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adroit','adj.精明的，干练的；熟练的，灵巧的','/əˈdɹɔɪt/','/əˈdɹɔɪt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appetite','n.胃口，食欲；欲望','/ˈæp.ə.taɪt/','/ˈæp.ə.taɪt/','noun',["appetite for reading"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frivolity','n.轻浮；愚蠢的行为','','','noun',[]);
