INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deprive','vt.使失去，剥夺','/dɪˈpɹaɪv/','/dɪˈpɹaɪv/','verb',[]);
