INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sanitation','n.卫生；卫生设施，卫生设备','/ˌsænɪˈteɪʃən/','/ˌsænɪˈteɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elite','adj.卓越的，精锐的n.精英','/eɪˈliːt/','/eɪˈliːt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ornament','n.装饰vt.装饰，点缀','/ˈɔː(ɹ)nəmənt/','/ˈɔɹnəmənt/','noun',["We will ornament the windows with trim to make the room seem brighter.","The editor ornamented his plain writing, making it fancier but less clear."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chubby','adj.丰满的，圆胖的','/ˈtʃʌbi/','/ˈtʃʌbi/','noun',["Obviously the chubby child was eating too much.","It’s quite normal for babies to have chubby cheeks."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ivory','n.象牙；象牙制品；象牙色，乳白色','/ˈaɪvəɹi/','/ˈaɪvəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anomalous','adj.异常的；不规则的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deficient','adj.不足的，缺乏的；有缺陷的，不完善的','/dɪˈfɪʃənt/','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('henceforth','adv.从此以后','/hɛnsˈfɔɹθ/','/hɛnsˈfɔɹθ/','adverb',["I will try to do a better job, henceforth, now that I know the proper technique!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preponderance','n.优势','/pɹɪˈpɒnd(ə)ɹəns/','/pɹɪˈpɒnd(ə)ɹəns/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barrel','n.桶','/ˈbæɹəl/','/ˈbæɹəl/','noun',["a cracker barrel","the barrel of a windlass;  the barrel of a watch, within which the spring is coiled.","Throw it into the trash barrel."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chain','n.链；vt.用链条拴住；联号，连锁店','/ˈt͡ʃeɪn/','/ˈt͡ʃeɪn/','noun',["He wore a gold chain around the neck.","This led to an unfortunate chain of events.","That chain of restaurants is expanding into our town."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('efficient','adj.有效的，有效率的；有能力的，能胜任的','/əˈfɪʃənt/','/əˈfɪʃənt/','noun',["An efficient process would automate all the routine work.","The motor is only 20% efficient at that temperature.","Ownership, maintenance, or use of the automobile need not be the direct and efficient cause of the injury sustained"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unify','vt.统一，联合','/ˈjuːnɪfaɪ/','/ˈjuːnɪfaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consistent','adj.一致的；稳定的；调和的；始终如一的','/kənˈsɪstənt/','/kənˈsɪstənt/','noun',["He is very consistent in his political choices: economy good or bad, he always votes Labour!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reverse','v.反转；彻底转变，颠倒；撤销，废除；交换；adj.相反的','/ɹɪˈvɜːs/','','noun',["We believed the Chinese weren''t ready for us. In fact, the reverse was true.","to reverse a portion of video footage","to reverse a judgment, sentence, or decree"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ravage','vt.毁坏；抢劫，掠夺','/ˈɹævɪdʒ/','/ˈɹævɪdʒ/','noun',["the ravage of a lion; the ravages of fire or tempest; the ravages of an army, or of time"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barren','adj.贫瘠的，荒芜的；不结果实的，不育的','/ˈbæɹən/','','noun',["The pine barrens are a site lonely enough to suit any hermit.","I silently wept as my daughter''s husband rejected her. What would she do now that she was no longer a maiden but also barren?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fungi','n.[fungus的复数]真菌','/ˈfʌn.dʒaɪ/','/ˈfʌn.dʒaɪ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('permanent','adj.持久的，永久的；固定不变的','/ˈpɜːmənənt/','/ˈpɝmənənt/','noun',["Nothing in this world is truly permanent.","The countries are now locked in a permanent state of conflict."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foster','v.鼓励，促进，助长；培养，抚育；领养adj.代养的','/ˈfɒstə/','/ˈfɑstɚ/','noun',["Some fosters end up adopting.","Our company fosters an appreciation for the arts.","foster parents"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('receptacle','n.容器；插座','/ɹɪˈsɛp.tə.kl̩/','/ɹɪˈsɛp.tə.kl̩/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('summarize','v.概括，总结','/ˈsʌməˌɹaɪz/','/ˈsʌməˌɹaɪz/','verb',["Jim was asked to summarize the document by Wednesday.","After the meeting, Jim summarized the major decisions made."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('facility','n.设施；设备；容易；灵巧','/fəˈsɪlɪti/','/fəˈsɪlɪti/','noun',["The facility she shows in playing the violin is unrivalled.","Transport facilities in Bangkok are not sufficient to prevent frequent traffic collapses during rush hour."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gregarious','adj.群居的；合群的，爱社交的','/ɡɹɪˈɡɛə.ɹɪ.əs/','/ɡɹɨˈɡɛɹ.i.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beam','v.面露喜色；发射，播送；照射n.束，波束，光线；梁；笑容，喜色','/biːm/','/biːm/','noun',["This ship has more beam than that one.","a beam of energy","a beam of hope, or of comfort"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beak','n.鸟嘴，喙','/biːk/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fiction','n.小说；虚构，编造','/ˈfɪk.ʃən/','/ˈfɪk.ʃən/','noun',["I am a great reader of fiction.","The butler’s account of the crime was pure fiction."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bead','n.珠子；小滴','/biːd/','/biːd/','noun',["We now have a bead on the main technical issues for the project","the borax bead;  the iron bead, etc.","The raindrops beaded on the car''s waxed finish."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('replace','vt.替换，取代；归还，把…放回原处','/ɹɪˈpleɪs/','/ɹɪˈpleɪs/','verb',["When you''ve finished using the telephone, please replace the handset.","You can take what you need from the petty cash, but you must replace it tomorrow morning.","I replaced my car with a newer model."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aviation','n.航空，航空学；飞行','/eɪviˈeɪʃən/','/eɪviˈeɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appointment','n.约会，约定；任命，委派；职位','/əˈpɔɪnt.mɛnt/','/əˈpɔɪnt.mɛnt/','noun',["His appointment was deemed suitable","the appointment of treasurer","I''m leaving work early because I have a doctor''s appointment."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('synthesize','vt.合成；综合','/ˈsɪnθəsaɪz/','/ˈsɪnθəsaɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trek','n&v.艰苦跋涉','/tɹɛk/','/tɹɛk/','noun',["We''re planning a trek up Kilimanjaro.","I would drive to the shops from here; you can walk, but it''s quite a trek."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('squash','v.压碎，挤压；挤进，塞入；制止n.软式墙网球，壁球；果汁汽水','/skwɒʃ/','/skwɔʃ/','noun',["When I''m thirsty I drink squash; it tastes much nicer than plain water.","It''s a bit of a squash in this small room.","Somehow, she squashed all her books into her backpack, which was now too heavy to carry."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('major','vi.主修，专攻adj.较大的；主要的；主修的n.专业','/ˈmeɪ.dʒə(ɹ)/','/ˈmeɪ.dʒɚ/','noun',["He used to be a major in the army."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('playwright','n.剧作家','/ˈpleɪˌɹaɪt/','/ˈpleɪˌɹaɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interrupt','v.打扰；中断；阻碍','/ˌɪntəˈɹʌpt/','/ˌɪntəˈɹʌpt/','noun',["The interrupt caused the packet handler routine to run.","A maverick politician repeatedly interrupted the debate by shouting.","The evenness of the road was not interrupted by a single hill."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beat','v.打拍子，指挥；敲打；打败，胜过；跳动adj.疲惫的n.跳动；节拍，节奏；有规律的敲击','/biːt/','/biːt/','noun',["a beat of the heart; the beat of the pulse","the beat of him","a dead beat"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feasible','adj.可行的，行得通的','/ˈfiːzəbəl/','/ˈfiːzəbəl/','adjective',["His plan to rid Trafalgar Square of pigeons by bringing in peregrine falcons to eat them was dismissed as not feasible."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prescribe','v.开处方；规定；指示','/pɹɪˈskɹaɪb/','/pɹɪˈskɹaɪb/','verb',["The doctor prescribed aspirin.","The property meets the criteria prescribed by the regulations."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proofread','v.校对，校正','/ˈpɹuːfɹiːd/','/ˈpɹuːfɹiːd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('potential','adj.潜在的；可能的n.潜能，潜力','/pəˈtɛnʃəl/','/po(ʊ)ˈtɛnʃəl/','noun',["Even from a young age it was clear that she had the potential to become a great musician."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lounge','vi.懒洋洋地站n.等候室，休息室','/laʊndʒ/','/laʊndʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gross','adj.总的，毛的；粗俗的，粗野的；令人不快的vt.总收入为n.一罗；','/ɡɹəʊs/','/ɡɹoʊs/','noun',["The movie grossed three million on the first weekend.","a gross mistake;  gross injustice;  gross negligence; a gross insult","gross domestic product; gross income; gross weight"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resist','v.抵抗；耐，抗','/ɹəˈzɪst/','/ɹəˈzɪst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('archive','n.档案室vt.存档','/ˈɑɹkaɪv/','/ˈɑɹkaɪv/','noun',["His archive of Old High German texts is the most extensive in Britain.","soil archive; peat archive","I was planning on archiving the documents from 2001."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disarm','v.解除武装；裁军；消除，消解','/dɪsˈɑː(ɹ)m/','/dɪsˈɑː(ɹ)m/','noun',["to disarm a man''s wrath"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extrapolate','v.外推；推断，推知','/ɛkˈstɹæp.əˌleɪt/','/ɛkˈstɹæp.əˌleɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stimulate','vt.刺激；激励，激发','/ˈstɪmjʊleɪt/','/ˈstɪmjʊleɪt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reciprocity','n.互惠，互助；互惠主义','','','noun',["In a friendship, reciprocity occurs where the contribution of each party meets the expectations of the other party."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eclipse','vt.遮住光；使相形见绌n.日食，月食','/iˈklɪps/','/iˈklɪps/','noun',["The Moon eclipsed the Sun."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('square','adj.正方形的；成直角的，方的；平方的n.正方形；广场；平方vt.使成正方形；求平方；使打成平局','/skwɛə(ɹ)/','/skwɛɚ/','noun',["64 is the square of 8.","Why do you always wear a tie? Don''t be such a square!","Enter your account number followed by a square."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('careless','adj.粗心的，疏忽的；无忧无虑的；不关心的，冷漠的','/ˈkɛələs/','/ˈkɛɹləs/','adjective',["Jessica was so careless that she put her shorts on backwards."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soak','v.浸泡，浸湿，浸透','/səʊk/','/səʊk/','noun',["After the strenuous climb, I had a nice long soak in a bath.","I''m going to soak in the bath for a couple of hours.","Soak the beans overnight before cooking."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('counteract','vt.消除；抵消','/ˈkaʊntəɹˌækt/','/ˈkaʊntəɹˌækt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deserted','adj.荒废的，空无一人的；被离弃的，被遗弃的','/dɪˈzɜːtəd/','','verb',["You can''t just drive off and desert me here, in the middle of nowhere.","Anyone found deserting will be punished."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commute','v.上下班往返，经常往返；代偿；减刑','/kəˈmjuːt/','/kəˈmjuːt/','verb',["to commute tithes into rentcharges for a sum; to commute market rents for a premium, to commute daily fares for a season ticket","A pair of matrices share the same set of eigenvectors if and only if they commute."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sustain','vt.保持，维持；支持，支撑；经受，承受','/səˈsteɪn/','/səˈsteɪn/','noun',["The city came under sustained attack by enemy forces.","provisions to sustain an army","The building sustained major damage in the earthquake."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anarchist','n.无政府主义者','/ˈæn.ə.kɪst/','/ˈæn.ə.kɪst/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('classify','vt.分类；分等','/ˈklæsɪfaɪ/','/ˈklæsɪfaɪ/','verb',["Should we classify \"make up\" as an idiom or as a phrasal verb?","They decided to classify that information."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('altitude','n.海拔，高度；','/ˈælt.ɪˌtjuːd/','/ˈælt.ɪˌtjuːd/','noun',["As the altitude increases, the temperature gets lower, so remember to bring warm clothes to the mountains.","The perpendicular height of a triangle is known as its altitude."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('request','n&vt.要求，请求','/ɹɪˈkwɛst/','/ɹɪˈkwɛst/','noun',["The server returned a 404 error to the HTTP request.","I have requested that the furniture be moved back to its original position.","She called me into her office and requested me to sit down."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('colony','n.群，群体；殖民地；聚居地','/ˈkɒl.əni/','/ˈkɑləniː/','noun',["Bermuda is a crown colony of Great Britain.","Our colony is quite small, but each apartment is large.","The Amana Colonies in Iowa were settled by people from Germany."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wagon','n.四轮马车；货车','/ˈwæɡ(ə)n/','/ˈwæɡən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('numeric','adj.数字的','/n(j)uːˈmɛɹɪk/','/n(j)uːˈmɛɹɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('debut','n.首次演出；初次亮相','/dəˈbʉː/','/deɪˈbjuː/','noun',["Since making its debut two years ago, the program has gained cult status.","Amalgamated Software Systems debuted release 3.2 in Spring of 2004.","Release 3.2 debuted to mixed reviews in Spring of 2004."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uphold','vt.支持，维护；维持','/ˌʌpˈhold/','/ˌʌpˈhold/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dimension','n.维，元；尺寸；方面；特点；','/daɪˈmɛnʃən/','/daɪˈmɛnʃən/','noun',["The dimension of velocity is length divided by time."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nostalgia','n.思乡病，乡愁；怀旧之情，恋旧','/nɒˈstaldʒə/','/nɒˈstaldʒə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deserve','v.应得，值得','/dɪˈzɜːv/','/dɪˈzɝv/','verb',["After playing so well, the team really deserved their win."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('process','vt.加工，处理n.过程；程序，手续；工序，制作法','/ˈpɹəʊsɛs/','/ˈpɹɑsɛs/','noun',["This product of last month''s quality standards committee is quite good, even though the process was flawed.","1960, Mack Tyner, Process Engineering Calculations: Material and Energy Balances – Ordinarily a process plant will use a steam boiler to supply its process heat requirements and to drive a steam-turbine generator.","We have processed the data using our proven techniques, and have come to the following conclusions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('artisan','n.工匠，手艺人','/ˈɑː(ɹ)tɪzæn/','/ˈɑː(ɹ)tɪzæn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sprout','v.发芽，抽条，生长；迅速出现，涌现出n.新芽，嫩枝，苗','/spɹʌʊt/','/spɹaʊt/','noun',["I sprouted beans and radishes and put them in my salad.","to sprout potatoes","Whiskers sprouted from the old man''s chin."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('restore','vt.恢复；修复；归还，交还','/ɹɪˈstɔː/','/ɹɪˈstɔɹ/','noun',["We backed up the data successfully, but the restore failed.","He restored my lost faith in him by doing a good deed.","There was a crash last night, and we''re still restoring the file system."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('viscous','adj.黏滞的，黏性的','/ˈvɪs.kəs/','/ˈvɪs.kəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nostalgic','adj.思乡的；怀旧的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alternative','adj.可供替代的；非传统的n.可供选择的事物；选择的自由，选择的余地','/ɒl.ˈtɜː(ɹ).nə.tɪv/','/ɔl.ˈtɝ.nə.tɪv/','noun',["an alternative proposition"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('banner','n.横幅','/ˈbænə/','/ˈbænɚ/','noun',["The mayor hung a banner across Main Street to commemorate the town''s 100th anniversary.","They usually make their case under the banner of environmentalism."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('encounter','vt&v.偶然碰到；遭遇','/ɪnˈkaʊntə/','/ɪnˈkaʊntɚ/','noun',["Their encounter was a matter of chance.","Three armies encountered at Waterloo."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soda','n.苏打，纯碱','/ˈsəʊdə/','/ˈsəʊdə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('landslide','n.山崩，塌方；压倒性胜利','/ˈlænd.slaɪd/','/ˈlænd.slaɪd/','noun',["The candidate won by a landslide."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prairie','n.大草原','/ˈpɹɛəɹi/','/ˈpɹɛəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('approve','v.批准；赞成','/əˈpɹuːv/','/əˈpɹuːv/','verb',["Although we may disagree with it, we must nevertheless approve the sentence handed down by the court-martial.","We approve the measure of the administration, for it is an excellent decision.","Her mother never approves of any of her boyfriends. She thinks nobody is good enough for her little girl."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chafe','v.擦破，擦痛；恼怒，焦躁','/tʃeɪf/','/tʃeɪf/','noun',["to chafe a cable","A cable chafes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chew','v.咀嚼；思量，熟思','/tʃuː/','/tʃu/','noun',["I popped the gum into my mouth and gave it a chew.","Phillip purchased a bag of licorice chews at the drugstore.","The school had banned chew and smokes from the school grounds, even for adults."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('domicile','n.住处，住所','/ˈdɑmɪsaɪl/','/ˈdɑmɪsaɪl/','noun',["The call to jury duty was sent to my legal domicile; too bad I was on vacation at the time.","The answer depends on which state he was domiciled in at his death."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pedestrian','adj.徒步的；缺乏想象力的n.步行者，行人','/pəˈdɛst.ɹi.ən/','/pəˈdɛst.ɹi.ən/','noun',["pedestrian crossing","His manner of dress was pedestrian but tidy.","The choreographer prefers pedestrian movements."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurry','v.使加快，催促；赶快，匆忙n.急忙，匆忙，仓促','/ˈhʌ.ɹi/','/ˈhʌ.ɹi/','noun',["Why are you in such a big hurry?","There is no hurry on that paperwork.","He''s hurrying because he''s late."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('account','v.说明，解释；占n.解释，描述，叙述；账目；账户','/ə.ˈkaʊnt/','/ə.ˈkaʊnt/','noun',["to keep one''s account at the bank.","No satisfactory account has been given of these phenomena.","Don''t trouble yourself on my account."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radioactive','adj.放射性的，有辐射的','/ˌɹeɪdioʊˈaktɪv/','/ˌɹeɪdioʊˈaktɪv/','noun',["Even sleazy tactics and his radioactive mouth may not be able to contain this debacle."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('innocent','adj.天真的；清白的；无恶意的','/ˈɪnəsn̩t/','/ˈɪnəsn̩t/','noun',["The slaughter of the innocents was a significant event in the New Testament.","an innocent trade","innocent goods carried to a belligerent nation"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alphabet','n.字母表','/ˈæl.fə.bɛt/','/ˈæl.fə.bɛt/','noun',["In the first year of school, pupils are taught to recite the alphabet.","Let L be a regular language over the alphabet \\Sigma."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stride','n.大步；步法；','/stɹaɪd/','/stɹaɪd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advance','v.前进，向前移动；发展，进步；促进；预付adj.预先的；先头的n.前进；进展；预付','/ədˈvaːns/','/ədˈvæns/','noun',["an advance in health or knowledge","an advance on the prime cost of goods","He made an advance payment on the prior shipment to show good faith."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appreciate','vt.赏识；鉴赏，欣赏；感激','/əˈpɹiː.si.eɪt/','/əˈpɹiː.si.eɪt/','verb',["I appreciate your efforts","You must learn to appreciate time","I appreciate that what I''m asking you to do is very difficult."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bleach','v.变白，漂白n.漂白剂','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diverse','adj.不同的；多样的','/daɪˈvɜːs/','/daɪ.ˈvɝs/','adjective',["Idris Elba was a diverse hire for the franchise"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rally','v.集合，召集；恢复，重新振作n.集会，大会','/ˈɹæ.li/','/ˈɹæ.li/','noun',["a campaign rally","a political rally"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soft','adj.柔软的；柔和的；不强烈的；心肠软的；软性的','/sɑft/','/sɔft/','noun',["My head sank easily into the soft pillow.","Polish the silver with a soft cloth to avoid scratching.","I could hear the soft rustle of the leaves in the trees."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fictitious','adj.虚构的；假的；假装的，虚伪的','/fɪkˈtɪʃəs/','/fɪkˈtɪʃəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prime','adj.主要的；最初的；最好的；首先的n.全盛时期，盛年vt.使准备好；事先指点','/pɹaɪ̯m/','/pɹaɪ̯m/','noun',["3 is a prime.","I''m threatening to build a prime here.","Our prime concern here is to keep the community safe."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intellect','n.智力，理解力；知识分子','/ˈɪntəlɛkt/','/ˈɪntəlɛkt/','noun',["Intellect is one of man''s greatest powers.","They were chosen because of their outstanding intellect.","Some of the world''s leading intellects were meeting there."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amble','vi.缓行，漫步','/ˈæm.bəl/','/ˈæm.bəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loyal','adj.忠诚的，忠贞的','/ˈlɔɪəl/','/ˈlɔɪəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preference','n.偏爱；优先','/ˈpɹɛf(ə)ɹ(ə)ns/','/ˈpɹɛf(ə)ɹ(ə)ns/','noun',["He has a preference for crisp wines.","Can I keep my preferences when I upgrade to the new version of this application?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mainstream','n.主流，主要倾向；主流思想','','','noun',["His ideas were well outside the mainstream, but he presented them intelligently, and we were impressed if not convinced.","Mainstreaming has become more common in recent years, as studies have shown that many mainstreamed students with mild learning disabilities learn better than their non-mainstreamed counterparts.","They often carry stories you won''t find in the mainstream media."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opportunity','n.机会，时机','/ˌɒp.əˈtjuː.nɪ.tɪ/','/ˌɑpɚˈtunəti/','noun',["The world is full of opportunities and it''s up to me to see them and pursue them.","Having a holiday is a great opportunity to relax.","The Court questioned the opportunity of introducing these measures in such an uncertain economic climate."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dissolute','adj.放荡的，放纵的，道德沦丧的','/ˈdɪsəljuːt/','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('court','n.法院，法庭；宫廷，朝廷；球场vt.献殷勤，讨好；招致；求爱','/kɔːt/','/kɔɹt/','noun',["The girls were playing in the court.","The local sports club has six tennis courts and two squash courts.","He was courting big new accounts that previous salesman had not attempted."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chapel','n.教堂；祈祷室','/ˈtʃæ.pəl/','/ˈtʃæ.pəl/','noun',["The village butcher is chapel."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distort','vt.弄歪；扭曲，歪曲','/dɪsˈtɔːt/','/dɪsˈtɔːt/','verb',["In their articles, journalists sometimes distort the truth."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subsidiary','adj.次要的；辅助的，附设的；附属的n.子公司；附属机构；支流','/sʌbˈsɪ.di.əɹ.i/','/sʌbˈsɪ.di.əɹ.i/','noun',["a subsidiary stream","subsidiary payments to an ally"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('venture','v.敢于去；冒险n.冒险，投机；投机活动，风险项目','/ˈvɛn.t͡ʃə/','/ˈvɛn.t͡ʃɚ/','noun',["Nothing ventured, nothing gained.","to venture a horse to the West Indies"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interrelate','v.相互关联，紧密联系','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corrosive','adj.腐蚀的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enthusiasm','n.热情；积极性；热衷的事物','/-θuː-/','/-θuː-/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discern','vt.洞悉；识别','','','verb',["He was too young to discern right from wrong."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('propensity','n.倾向，癖好','/pɹəˈpɛnsɪti/','/pɹəˈpɛnsɪti/','noun',["He has a propensity for lengthy discussions of certain favorite topics."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entreat','v.乞求，恳求，请求','/ənˈtɹiːt/','/ənˈtɹiːt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flexible','adj.易弯曲的；柔韧的；灵活的，可变通的','/ˈflɛk.sə.bəl/','/ˈflɛk.sə.bəl/','noun',["This was a principle more flexible to their purpose. -Rogers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agile','adj.敏捷的，灵活的','/ˈæd͡ʒ.aɪl/','/ˈæd͡ʒ.aɪl/','adjective',["an agile creature","agile movements","agile methods"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('replenish','vt.添加，补充','/ɹɪˈplɛn.ɪʃ/','/ɹɪˈplɛn.ɪʃ/','verb',["It''s a popular product, and they have to replenish their stock of it frequently."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hoe','vt.用锄头锄n.锄头','/həʊ/','/həʊ/','noun',["Every year, I hoe my garden for aeration.","to hoe corn"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amenable','adj.顺从的，服从劝导的；有服从义务的','/əˈmɛn.ə.bəl/','/əˈmɛn.ə.bəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depict','vt.描写，描述，描绘','/dɪˈpɪkt/','/dɪˈpɪkt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sustainable','adj.不破坏生态平衡的，可持续的；足可支撑的；可忍受的','/səˈsteɪnəbəl/','/səˈsteɪnəbəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hop','v.单足跳行；齐足跳行；跳上n.蹦跳；短程旅行','/hɒp/','/hɑp/','noun',["The frog crossed the brook in three or four hops.","Sorry, can''t chat. Got to hop.","He hopped a train to California."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('secede','vi.正式脱离，退出','/sɪˈsiːd/','/sɪˈsiːd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('characteristic','adj.特有的；典型的n.特性，特征','/ˌkæɹəktəˈɹɪstɪk/','/ˌkæɹəktəˈɹɪstɪk/','noun',["The characteristic of a field, if non-zero, must be a prime number."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interior','adj.内部的；内地的n.内部；[the～]内陆','/ɪnˈtɪəɹɪə/','/ɪnˈtɪɹiɚ/','noun',["Sir Richard Burton explored far into the African interior.","the interior apartments of a house; the interior surface of a hollow ball","the interior parts of a region or country"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interweave','v.交织，编结','/ɪntəɹˈwiːv/','/ɪntəɹˈwiːv/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rouse','vt.唤起，唤醒；激起，鼓舞；激怒','/ˈɹaʊz/','/ˈɹaʊz/','noun',["to rouse the faculties, passions, or emotions","to rouse a deer or other animal of the chase","He roused on her for being late yet again."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('capability','n.能力；性能；容量；潜质','/keɪpəˈbɪləti/','/keɪpəˈbɪləti/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spark','v.激发，引发，触发；','/spɑːk/','/spɑɹk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('integral','adj.构成整体所必需的，不可或缺的；完整的','/ˈɪntɪɡɹəl/','/ˈɪntɪɡɹəl/','noun',["The integral of x\\mapsto x^2 on [0,1] is \\frac{1}{3}.","The integral of x^2 is \\frac{x^3}{3} plus a constant."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comet','n.彗星','/ˈkɒmət/','/ˈkɒmət/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assembly','n.集会；集会者；装配，安装；立法机构，议会','/əˈsɛmb.lɪ/','/əˈsɛmb.li/','noun',["In order to change the bearing, you must first remove the gearbox assembly.","assembly line","freedom of assembly"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smelting','n.冶炼，熔炼','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spare','adj.备用的；空闲的vt.抽出；免除n.备用品','/ˈspɛə(ɹ)/','/ˈspɛəɹ/','noun',["a spare diet","I have no spare time.","a spare anchor; a spare bed or room"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chip','v.削下n.碎片；芯片','/tʃɪp/','/tʃɪp/','noun',["This cup has a chip in it.","Do you want sauce or mayonnaise on your chips?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('replicate','v.复制；再制，再生','/ˈɹɛpləˌkeɪt/','/ˈɹɛpləˌkeɪt/','noun',["On entering a host cell, a virus will start to replicate.","a replicate leaf or petal"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emotional','adj.感情的，情绪的；引起情感的；易动感情的','/ɪˈməʊʃnəl/','/ɪˈməʊʃnəl/','adjective',["emotional crisis","emotional decision","emotional speech"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noticeable','adj.明显的，值得注意的','/ˈnəʊtɪsəbl̩/','/ˈnəʊtɪsəbl̩/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assemble','v.集合；装配','/əˈsɛmbl̩/','/əˈsɛmbl̩/','verb',["He assembled the model ship.","The parents assembled in the school hall."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hibernation','n.冬眠；休眠，蛰伏','/ˌhaɪ.bəːˈneɪ.ʃən/','/ˌhaɪ.bəːˈneɪ.ʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transition','n.过渡，过渡时期；转变','/tɹænˈzɪʃən/','/tɹænˈzɪʃən/','noun',["The soldier was transitioned from a combat role to a strategic role."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('march','v.前进，进发；行进，齐步走；游行示威n.行进，行军；示威游行；进行曲；进行，进展','/mɑːtʃ/','/mɑɹtʃ/','noun',["the march of time"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blast','v.爆炸；发出尖响；猛烈抨击n.一阵；爆炸；冲击波；响声','/blɑːst/','/blɑːst/','noun',["many tons of iron were melted at a blast","We had a blast at the party last night.","an e-mail blast; a fax blast"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repel','v.击退，驱逐；排斥；抵制，拒绝；使反感，使厌恶','/ɹɪˈpɛl/','/ɹɪˈpɛl/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('publicize','vt.宣传，推广，宣扬','/ˈpʌblɪˌsaɪz/','/ˈpʌblɪˌsaɪz/','verb',["The scandal was so publicised that he lost the next election.","They''re already publicising next month''s concert."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('underscore','vt.强调；在…之下画线n.底线','/ˈʌn.də(ɹ)ˌskɔː(ɹ)/','','noun',["I wish to underscore the importance of proper formatting."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seashore','n.海岸，海滨','/ˈsiːʃɔː/','/ˈsiːʃɔː/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('series','n.系列，连续；连续剧','/ˈsɪə.ɹiːz/','/ˈsiɹiz/','noun',["A series of seemingly inconsequential events led cumulatively to the fall of the company.","“Friends” was one of the most successful television series in recent years.","The harmonic series has been much studied."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cultivate','vt.耕种；培养','/ˈkʌltɪveɪt/','/ˈkʌltɪveɪt/','verb',["Most farmers in this region cultivate maize.","They tried to cultivate an interest in learning among their students."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thrive','vi.茂盛；茁壮成长；兴旺，繁荣','/θɹaɪv/','/θɹaɪv/','verb',["Not all animals thrive well in captivity.","Since expanding in June, the business has really thrived."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imaginative','adj.富有想象力的；创新的','/-ənətɪv/','/-ənətɪv/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('treadmill','n.踏车；枯燥乏味的工作','/ˈtɹɛd.mɪl/','/ˈtɹɛd.mɪl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('represent','vt.代表；表现；描绘；象征','/ɹɛp.ɹɪ.ˈzɛnt/','/ɹɛp.ɹɪ.ˈzɛnt/','verb',["The sculptor represented a horse in bronze.","It has always been his dream to represent Hamlet on Broadway.","An attorney''s job is to represent his client in court"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dispatch','vt&n.分派，派遣；发送','/dəˈspætʃ/','/dɪˈspætʃ/','noun',["We must act with dispatch in this matter."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corpus','n.文集，文献，汇编；语料库','/ˈkɔːpəs/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inconvenient','adj.不便的；让人不舒服的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dramatize','v.改编成戏剧；戏剧化，戏剧性地表现','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absurd','adj.可笑的，荒唐的','/æbˈzɝd/','/æbˈsɝd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prior','adj.在…前的；优先的','/ˈpɹaɪɚ/','/ˈpɹaɪɚ/','noun',["I had no prior knowledge you were coming.","His prior residence was smaller than his current one.","The doctor had known three months prior."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trait','n.特性，特点','/tɹeɪ/','/tɹeɪ/','noun',["The number one personality trait I hate is hypocrisy. Why can''t you be consistent!?","Traits are somewhat between an interface and a mixin."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('landmark','n.路标，地标；〈喻〉里程碑','','/ˈlændmɑɹk/','noun',["a landmark paper in neurosurgery"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vanish','vi.消失；灭绝','/ˈvænɪʃ/','/ˈvænɪʃ/','noun',["a as in ale ordinarily ends with a vanish of i as in ill.","The French drop is a well-known vanish involving sleight of hand.","The function f(x)=x^2 vanishes at x=0."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vault','v.跳过n.拱顶；金库，保险库；撑杆跳','/vɒlt/','/vɑlt/','noun',["Family members had been buried in the vault for centuries.","The bank kept their money safe in a large vault."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concave','adj.凹的','/ˈkɒŋkeɪv/','/ˈkɒŋkeɪv/','noun',["Aristotle makes [Fire] to move to the concave of the Moon. - Thomas Salusbury (1661)."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dolphin','n.海豚','/ˈdɒlfɪn/','/ˈdɑlfɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enactment','n.制订，颁布；法律，法规','','','noun',["The actors'' powerful enactment of the play was breathtaking.","The enactments passed by the council that year included sweeping reforms."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('planet','n.行星','/ˈplænət/','/ˈplænɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ornithology','n.鸟类学','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prerequisite','adj.必备的，作为先决条件的n.先决条件，前提','/pɹiːˈɹɛkwɪzɪt/','/pɹiːˈɹɛkwɪzɪt/','noun',["A degree is a prerequisite for entry into this profession.","Algebra is typically a prerequisite for physics.","The prerequisite warm-up to the match was ignored."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('count','v.数，计算；算入；看做，认为；值得考虑，有重要意义n.计数，计算；总数；罪状','/kaʊnt/','/kaʊnt/','noun',["Give the chairs a quick count to check if we have enough.","He has a 3–2 count with the bases loaded.","Can you count to a hundred?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('creep','vi.缓慢行进；爬行；悄悄地移动','/kɹiːp/','/kɹiːp/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deciduous','adj.落叶的；非永久的，短暂的','/dɪˈsɪdʒʊəs/','/dəˈsɪd.ju.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scholar','n.学者；奖学金获得者','/ˈskɒlə/','/ˈskɒlə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contradictory','adj.对立的，矛盾的；反驳的n.对立物；矛盾因素','/ˌkɑntɹəˈdɪktəɹi/','/ˌkɑntɹəˈdɪktəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accompany','vt.为…伴奏；陪伴，陪同；伴随，和…一起发生','/ə.ˈkʌm.pə.ni/','/ə.ˈkʌm.pə.ni/','verb',["Geoffrey accompanied the group on their pilgrimage.","I will accompany her on the oboe.","Thunder almost always accompanies lightning during a rain storm."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immediate','adj.即刻的；当前的；最接近的；紧接的，紧靠的','/ɪˈmiːdɪət/','/ɪˈmi.di.ət/','adjective',["Computer users these days expect immediate results when they click on a link.","immediate family;  immediate vicinity","Bravo Three, this Bravo Six. Immediate! We are coming under fire from the north from an unknown enemy, over!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perspicuous','adj.明白易懂的；明了的','/pəˈspɪkjuːəs/','/pəˈspɪkjuːəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beneficial','adj.有益的，有利的','/ˌbɛnəˈfɪʃəl/','/ˌbɛnəˈfɪʃəl/','noun',["Recycling and reusing garbage can be beneficial to the environment."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blame','vt.谴责，责备n.过失，责备；责任','/bleɪm/','/bleɪm/','noun',["Blame came from all directions.","The blame for starting the fire lies with the arsonist.","They accepted the blame, but it was an accident."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confusion','n.困惑；混乱，混淆','/kənˈfjuːʒən/','/kənˈfjuːʒən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('platitude','n.陈词滥调，老生常谈','/ˈplatɪtjuːd/','/ˈplætɪt(j)ud/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('auditorium','n.礼堂；观众席','/ɔː.dɪˈtɔː.ɹɪ.əm/','/ɔː.dɪˈtɔː.ɹɪ.əm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('session','n.会议；开庭；开庭期；一节','/ˈsɛʃən/','/ˈsɛʃən/','noun',["\"Are we having a recording session?\" / \"Yes. We''ve even got some session musicians to provide some brass.\"","This court is now in session.","Logging out or shutting down the computer will end your session."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tactile','adj.触觉的；有触觉的；可感触的','/ˈtæktaɪl/','/ˈtæktaɪl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extrinsic','adj.外来的，外在的，非本质的','/ɛks.ˈtɹɪn.zɪk/','/ɛks.ˈtɹɪn.zɪk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bland','adj.平淡的，乏味的；清淡的；沉稳的','/blænd/','/blænd/','adjective',["a bland diet","The coffee was bland."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('microbe','n.微生物，细菌','/ˈmaɪkɹoʊb/','/ˈmaɪkɹoʊb/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reception','n.招待会；反响；接纳，接待；接收','/ɹɪˈsɛp.ʃn̩/','/ɹɪˈsɛp.ʃn̩/','noun',["The new system provides exceptional quality of the reception signal.","After the wedding we proceeded to the reception.","The ambassador''s jokes met a cold reception."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sole','adj.单独的；唯一的n.鞋底，脚底','/səʊl/','/soʊl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lumber','v.笨拙地移动；迫使担负n.木材，木料；杂物','/ˈlʌm.bə/','/ˈlʌm.bɚ/','noun',["I got lumbered with that boring woman all afternoon.","to lumber up a room"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sledding','n.进展','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solo','adv.独自，单独地adj.单独的；独唱的，独奏的n.独唱，独奏，独舞','/ˈsoʊ.loʊ/','/ˈsoʊ.loʊ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monitor','vt.监控；调节n.显示器；监视器；班长','/ˈmɒnɨtə/','/ˈmɒnɨtə/','noun',["The camp monitors look after the children during the night, when the teachers are asleep.","The information flashed up on the monitor.","a machine code monitor"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tuition','n.学费；教学，讲授','/ˈtjuːʃən/','/ˈtjuːʃən/','noun',["These rosemaling workshops are no place for anyone who wants to pester me or the students with the \"white privilege\" card, inter alia. Therefore, I reserve the right to refund the tuition of such men and women, kick them out the door, and bar them from at least two of my future events."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Fahrenheit','adj.华氏温度的n.华氏温度计','','','',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tangible','adj.可触摸的，可感知的；明确的，确凿的；有形的，实际的','/ˈtæn(d)ʒɪb(ə)l/','/ˈtændʒəbəl/','noun',["Yes, but what are the tangibles?"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('congest','v.充满，拥塞；充血','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('postage','n.邮资，邮费','/ˈpəʊstɪdʒ/','/ˈpəʊstɪdʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tame','adj.驯服的；沉闷的，乏味的vt.驯化；控制并利用','/teɪm/','/teɪm/','verb',["He tamed the wild horse.","to tame a rebellion","They have a tame wildcat."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cavern','n.大洞穴，大山洞','/ˈkæv.ən/','/ˈkæv.ən/','noun',["catacombs caverning the hillsides"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('material','adj.物质的，身体上的；重要的；实质性的，客观存在的n.材料，原料；素材，资料','/məˈtɪəɹɪəl/','/məˈtɪəɹɪəl/','noun',["Asphalt, composed of oil and sand, is a widely used material for roads.","We were a warm-up act at the time; we didn''t have enough original material to headline.","You''ll need about a yard of material to make this."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adjoin','v.贴近，紧挨，毗连','/əˈdʒɔɪn/','/əˈdʒɔɪn/','verb',["The living room and dining room adjoin each other."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spectacular','adj.壮观的，引人注目的n.壮观的场面；壮观的演出','/spɛkˈtæk.jʊ.lə/','/spɛkˈtæk.jʊ.lə/','noun',["The parachutists were spectacular.","the merely spectacular"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('peculiar','adj.独特的；罕见的；奇怪的，古怪的','[pʰə̥ˈkʰj̊uːljʊə]','[pʰə̥ˈkʰj̊uljɚ]','noun',["It would be rather peculiar to see a kangaroo hopping down a city street.","Kangaroos are peculiar to Australia."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hue','n.颜色；色度，色调；信仰，观点；形式，样子','/hjʉː/','/hju/','noun',["In digital arts, HSV color uses hue together with saturation and value."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('idiom','n.习惯用语；术语；风格，特色','/ˈɪdɪəm/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diplomat','n.外交官；有手腕的人','/ˈdɪ.plə.mæt/','/ˈdɪ.plə.mæt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('landmass','n.大片陆地','/ˈlænd.mæs/','/ˈlænd.mæs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('president','n.总统，校长，主席','/ˈpɹɛzɨdənt/','/ˈpɹɛzɨdənt/','noun',["The vast majority of presidents have been male."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('muscular','adj.肌肉的；肌肉发达的；强健的，强壮的','/ˈmʌs.kjə.lə/','/ˈmʌs.kjə.lə/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('staple','n.主要产品；原材料；主食；订书钉','/ˈsteɪ.pəl/','/ˈsteɪ.pəl/','noun',["Rice is a staple in the diet of many cultures.","to staple cotton","a staple town"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('memo','n.备忘录','/ˈmɛməʊ̯/','/ˈmɛməʊ̯/','noun',["I made sure to memo him about the client''s complaints."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('artifice','n.诡计，奸计；策略','/ˈɑː(ɹ)tɪfɪs/','/ˈɑː(ɹ)tɪfɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collaborate','v.协作，合作；勾结，通敌','/kəˈlabəɹeɪt/','/kəˈlabəɹeɪt/','verb',["Let''s collaborate on this project, and get it finished faster.","If you collaborate with the occupying forces, you will be shot."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collaborator','n.合作者，协作者；通敌者','/kəˈlæbəɹeɪtə/','/kəˈlæbəɹeɪtə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superficial','adj.肤浅的，浅薄的；表面的，外表的，外层的','/ˌs(j)uːpəˈfɪʃəl/','/ˌsupɚˈfɪʃəl/','noun',["He always concentrates on the superficials and fails to see the real issue."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('executive','adj.执行的，实施的；行政的n.执行者；管理人员；行政负责人','/ɛɡˈzɛkjʊtɪv/','','noun',["an executive officer","an executive bathroom"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('melt','v.融化，熔化；溶化；消散','/mɛlt/','/mɛlt/','noun',["I melted butter to make a cake.","His troubles melted away.","She melted when she saw the romantic message in the Valentine''s Day card."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hook','v.连接到无线电设备；勾住n.钩，吊钩；钩状物','/huːk/','/huːk/','noun',["He is not handling this job, so we''re giving him the hook.","The song''s hook snared me.","We''ve added hooks to allow undefined message types to be handled with custom code."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stadium','n.竞走场；运动场','/ˈsteɪ.di.əm/','/ˈsteɪ.di.əm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refrigerate','vt.冷冻，冷藏；使冷却，使变冷','/ɹɪˈfɹɪdʒəɹeɪt/','/ɹɪˈfɹɪdʒəɹeɪt/','verb',["Please refrigerate your uncooked meats at or below 40° Fahrenheit."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('casualty','n.伤亡事故；伤亡','/ˈkaʒ(ʊ)əlti/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spatial','adj.空间的','/ˈspeɪʃəl/','/ˈspeɪʃəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gauge','n.标准，规格；测量仪表，计量器vt.测量，度量','/ˈɡeɪdʒ/','/ˈɡeɪdʒ/','noun',["A vessel has the weather gauge of another when on the windward side of it, and the lee gauge when on the lee side of it."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('belt','n.地带，地区；腰带，皮带；带状物','/bɛlt/','/bɛlt/','noun',["As part of the act, the fat clown''s belt broke, causing his pants to fall down.","Keep your belt fastened; this is going to be quite a bumpy ride.","The motor had a single belt that snaked its way back and forth around a variety of wheels."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ridicule','vt.嘲笑，奚落n.嘲笑，奚落','/ˈɹɪdɪkjuːl/','/ˈɹɪdɪkjuːl/','noun',["His older sibling constantly ridiculed him with sarcastic remarks."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('protest','v.抗议，反对n.抗议，反对','/ˈpɹəʊ.tɛst/','/ˈpɹoʊ.tɛst/','noun',["They lodged a protest with the authorities.","We held a protest in front of City Hall.","How dare you, I protest!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sensitive','adj.敏感的；灵敏的','/ˈsɛnsɪtɪv/','/ˈsɛnsɪtɪv/','noun',["Max is very sensitive; he cried today because of the bad news.","Religion is often a sensitive topic of discussion and should be avoided when dealing with foreign business associates.","These are highly sensitive documents."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vacant','adj.空的；闲置的；茫然的，空虚的','/ˈveɪkənt/','/ˈveɪkənt/','adjective',["a vacant stare"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hoof','n.蹄','/huːf/','/huːf/','noun',["Get your hooves off me!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('afford','v.买得起，担负得起；冒险做；提供，给予','/əˈfɔːd/','/əˈfoɹd/','verb',["I think we can afford the extra hour it will take.  We can only afford to buy a small car at the moment.","A affords his goods cheaper than B.","Grapes afford wine.  Olives afford oil.  The earth affords fruit.  The sea affords an abundant supply of fish."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('underground','adv.在地下，往地下；秘密地，不公开地adj.地下的；秘密的，不公开的记组合词：under+ground→地下的','/ˈʌndəɡɹaʊnd/','/ˈʌndəɡɹaʊnd/','noun',["the French underground during World War II","There is an underground tunnel that takes you across the river.","These criminals operate through an underground network."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sieve','n.筛子；漏勺vt.筛，滤','/sɪv/','/sɪv/','noun',["Use the sieve to get the pasta from the water.","Given a list of consecutive numbers starting at 1, the Sieve of Eratosthenes algorithm will find all of the prime numbers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appease','vt.平息；安抚，抚慰；绥靖','/əˈpiːz/','/əˈpiːz/','verb',["to appease the tumult of the ocean","They appeased the angry gods with burnt offerings."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reddish','adj.微红的','/ˈɹɛdɪʃ/','/ˈɹɛdɪʃ/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impede','vt.妨碍，阻碍，阻止','/ɪmˈpiːd/','/ɪmˈpiːd/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acting','adj.代理的n.演戏，表演','/ˈæk.tɪŋ/','/ˈæk.tɪŋ/','verb',["If you don''t act soon, you will be in trouble.","I started acting at the age of eleven in my local theatre.","A dog which acts aggressively is likely to bite."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('machinery','n.〈总称〉机器，机械；机构','/məˈʃiːnəɹi/','/məˈʃiːnəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shield','n.防护物；盾vt.保护','/ʃiːld/','/ʃiːld/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anatomy','n.解剖；解剖构造；剖析','/əˈnætəmi/','/əˈnætəmi/','noun',["Animal anatomy is also called zootomy; vegetable anatomy, phytotomy; and human anatomy, anthropotomy.","Burton''s famous treatise, \"The Anatomy of Melancholy\"","I went to the Venice beach body-building competition and noticed the competitor from Athens, and let me tell you, that''s what I call classic Greek anatomy."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deliver','v.传送，传递；发表，宣布；履行诺言；移交，交出；接生','/dɪˈlɪvə(ɹ)/','/dɪˈlɪvɚ/','verb',["deliver a captive from the prison","deliver a package;  deliver the mail","deliver the thief to the police"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instantaneous','adj.瞬间的，即刻的，立即的','/ɪnstənˈteɪni.əs/','/ɪnstənˈteɪni.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('phenomenon','n.现象，迹象；非凡的人','/fɪˈnɒmənɒn/','/fɪˈnɒmənɒn/','noun',["An electromagnetic phenomenon.","A volcanic eruption is an impressive phenomenon."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quarterly','adv.按季度，一季一次adj.季度的，每季一次的n.季刊','','','noun',["quarterly rent payments","The arms of Hohenzollern is quarterly argent and sable."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notify','vt.通报','/ˈnoʊtɪfaɪ/','/ˈnoʊtɪfaɪ/','verb',["Once a decision has been reached and notified to the parties it becomes binding."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smirk','vi.假笑，得意地笑','/smɜːk/','/smɜːk/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barbecue','v.在烤架上烧烤n.烧烤野餐；金属烤架','/ˈbɑːbɪˌkjuː/','/ˈbɑɹbɪˌkju/','noun',["We cooked our food on the barbecue.","We''re having a barbecue on Saturday, and you''re invited.","She ordered a plate of barbecue with a side of slaw."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abbey','n.修道院；大教堂','/ˈæb.i/','/ˈæb.i/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alienable','adj.可转让的','','','adjective',["Land is alienable according to the laws of the state."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('buoyant','adj.有浮力的，漂浮的；轻快的，快乐的；繁荣的；看涨的','/ˈbɔɪ.ənt/','/ˈbɔɪ.ənt/','adjective',["I’m in a buoyant mood."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intrepid','adj.勇敢的，无畏的','/ɪnˈtɹɛpɪd/','/ɪnˈtɹɛpɪd/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generalize','v.概括，归纳；推广','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accredit','vt.委任，授权；把…归于；正式认可','/ə.ˈkɹɛd.ɪt/','/ə.ˈkɹɛd.ɪt/','verb',["The school was an accredited college."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nourish','vt.滋养；养育','/ˈnʌɹ.ɪʃ/','/ˈnɝ.ɪʃ/','noun',["to nourish rebellion"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('faucet','n.龙头，旋塞','/ˈfɔːsɪt/','/ˈfɔsɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lengthen','v.延长，变长','/ˈlɛŋ(k)θən/','/ˈlɛŋ(k)θən/','verb',["The shadows on the lawn lengthened as the sun began to set."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unconsolidated','adj.松散的，疏松的','','','adjective',["unconsolidated backfill"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strike','v.碰，撞，撞击；侵袭；突然想到；给…以深刻印象；罢工；敲响n.罢工；袭击','/stɹaɪk/','/stɹaɪk/','noun',["Thus hand strikes now include single knuckle strikes, knife hand strikes, finger strikes, ridge hand strikes etc., and leg strikes include front kicks, knee strikes, axe kicks, ...","The batsmen have crossed, and Dhoni now has the strike.","Please strike the last sentence."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subdue','vt.制服，征服；抑制，克制','/səbˈdjuː/','/səbˈdjuː/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allege','vt.断言，宣称','/əˈlɛdʒ/','/əˈlɛdʒ/','verb',["The agency alleged my credit history had problems."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('positive','adj.肯定的；积极的；确凿的；自信的，乐观的；正电的','/ˈpɒzɪ̈tɪv/','/ˈpɑzɪ̈tɪv/','noun',["I’m absolutely positive you''ve spelt that wrong.","‘Better’ is an irregular comparative of the positive form ‘good’.","The idea of beauty is not positive, but depends on the different tastes of individuals."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trigger','vt.引发，导致n.扳机','/ˈtɹɪɡə/','/ˈtɹɪɡə/','noun',["Just pull the trigger.","Sleeping in an unfamiliar room can be a trigger for sleepwalking.","I can''t watch that violent film. Blood is one of my triggers."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('segregate','vt.隔离，使分开','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maize','n.玉米','/meɪz/','/meɪz/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meticulous','adj.细心的，小心翼翼的','','','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rental','adj.租用的；出租的n.租金额；租赁，出租','/ˈɹɛntəl/','/ˈɹɛntəl/','noun',["It''s just a rental, so I don''t need to take very good care of it."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prospect','v.勘探，勘察n.前景，前途；可能性；景象；期望','/ˈpɹɒspɛkt/','/ˈpɹɑspɛkt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radar','n.雷达','/ˈɹeɪdɑː(ɹ)/','/ˈɹeɪdɚ/','noun',["His sensitive radar for hidden alliances keeps him out of trouble."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('withhold','vt.拒绝给，不给；抑制；忍住','/wɪðˈhəʊld/','/wɪðˈhoʊld/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kinetic','adj.运动的，运动引起的；动力学的','/kɪˈnɛtɪk/','/kɪˈnɛtɪk/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('specialize','v.专攻；专用于','/ˈspɛʃəˌlaɪz/','/ˈspɛʃəˌlaɪz/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rotate','v.转动，旋转；轮流','/ɹəʊˈteɪt/','/ˈɹoʊteɪt/','verb',["He rotated in his chair to face me.","The nurses'' shifts rotate each week.","The aircraft rotates at sixty knots."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instance','n.例子，事例','/ˈɪnstəns/','/ˈɪnstəns/','noun',["It sends some precious instance of itself/ After the thing it loves. Hamlet IV. v. ca. 1602"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consonant','adj.和谐的，协调的，符合的n.辅音','/ˈkɒn.sə.nənt/','/ˈkɑn.sə.nənt/','noun',["The 19 unquestionable consonants in the English alphabet are B, C, D, F, G, H, J, K, L, M, N, P, Q, R, S, T, V, X, Z.","consonant tones; consonant chords"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engulf','vt.吞没','','','verb',["Desperation engulfed her after her daughter''s death.","Only Noah and his family survived when the Flood engulfed the world."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inheritance','n.遗产，继承物；继承；遗传','/ɪnˈhɛɹətəns/','/ɪnˈhɛɹətəns/','noun',["The Indo-European languages share various similarities as a result of their inheritance from a common ancestor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reptile','n.爬行动物，爬虫类；卑鄙的人','/ɹɪpˈtaɪl/','/ɹɪpˈtaɪl/','noun',["a reptile race or crew; reptile vices"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cassette','n.盒式录音带','/kæˈsɛt/','/kæˈsɛt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('receptive','adj.接受得快的；善于接受的，能接纳的','/ɹɪˈsɛptɪv/','/ɹɪˈsɛptɪv/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blade','n.刀刃，刀片；叶片；草叶；桨叶','/bleɪd/','/bleɪd/','noun',["Want to go blading with me later in the park?","The gang member got bladed in a fight."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solution','n.溶液；解答，解决','/səˈl(j)uːʃən/','/səˈl(j)uːʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foreshorten','vt.用透视法缩小；缩短，节略','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diverge','vi.分开，叉开；分歧；偏离','/daɪˈvɜːdʒ/','/daɪˈvɜːdʒ/','verb',["Both stories start out the same way, but they diverge halfway through.","The sidewalk runs next to the street for a few miles, then diverges from it and turns north.","The software is pretty good, except for a few cases where its behavior diverges from user expectations."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opponent','adj.对立的，反对的，对抗的n.敌手，对手，反对者','/ɒpəʊnənt/','/ɒpəʊnənt/','noun',["During the crackdown, many opponents of the regime were arrested."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accelerate','v.加快，加速','/æk.ˈsɛl.ə.ˌɹeɪt/','','verb',["to accelerate the growth of a plant, the increase of wealth, etc.","to accelerate our departure"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emblem','n.徽章；标记，象征','/ˈɛmbləm/','/ˈɛmbləm/','noun',["The rampant poverty in the ethnic slums was just an emblem of the group''s disenfranchisement by the society as a whole."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regardless','adv.不顾，不管','/ɹɪˈɡɑːd.lɪs/','/ɹɪˈɡɑːd.lɪs/','adjective',["Tatiana knew the meat had passed its expiry date, but she ate it regardless."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confiscate','vt.没收，充公，征用','','','verb',["In schools it is common for teachers to confiscate electronic games and other distractions."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('filial','adj.子女的；子孙后代的','/ˈfɪl.i.əl/','/ˈfi.li.əl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barge','v.冲撞，乱闯n.驳船','/bɑːdʒ/','/bɑːdʒ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turtle','n.龟，海龟','/ˈtɜːtəl/','/ˈtɝtəl/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meteorology','n.气象学','/ˌmiːtɪəˈɹɒlədʒi/','/ˌmiːtɪəˈɹɒlədʒi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('occur','vi.发生，出现；存在于','/əˈkɜː/','/əˈkɝ/','verb',["The liftoff will occur in exactly twelve seconds.","I will write if the opportunity occurs.","The chemical monofluoroacetate occurs in all parts of Dichapetalum cymosum, and is responsible for its toxic effects."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('illustrate','vt.说明，解释；加插图于；显示…存在','/ɪ.ˈlʌs.tɹeɪt/','/ɪ.ˈlʌs.tɹeɪt/','verb',["We illustrate our definitions by including quotations or simple examples.","The economics textbook was illustrated with many graphs."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scuba','n.水中呼吸器，水肺','/ˈskuːbə/','/ˈskuːbə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('definitive','adj.确定的，最后的，决定性的；','/dɪˈfɪn.ɪt.ɪv/','/dɪˈfɪn.ɪt.ɪv/','noun',["a definitive word"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breeze','vi.飘然移动n.微风，和风','/bɹiːz/','/bɹiːz/','noun',["The breeze rustled the papers on her desk.","After studying Latin, Spanish was a breeze.","The discovery produced a breeze."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trash','n.无价值之物，废物；拙劣的文学作品；没用的人vt.捣毁，破坏','/tɹæʃ/','/tɹæʃ/','noun',["I am Harry Potter trash.","The burglars trashed the house.","to trash the rattoons of sugar cane"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horn','n.角；号角，喇叭','/hɔːn/','/hɔɹn/','noun',["an umbrella with a handle made of horn","hunting horn","The shot was after the horn and therefore did not count."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('troupe','n.剧团；马戏团；芭蕾舞团','/tɹuːp/','/tɹuːp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transit','n.运输，运送；中转；转变；交通运输系统','/ˈtɹæn.sɪt/','/ˈtɹæn.sɪt/','noun',["the transit of goods through a country","Beufort road, Birkenhead, about 17.15 June 19 2013, white transit overtakes and swerves left into junction almost taking my front wheel.","I always take the transit to work."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sore','adj.疼痛的；恼火的n.疮口，痛处','/sɔː/','/sɔɹ/','noun',["They put ointment and a bandage on the sore.","Her feet were sore from walking so far.","The school was in sore need of textbooks, theirs having been ruined in the flood."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('position','vt.安置n.位置；职位；立场；姿势，姿态；见解','/pəˈzɪʃ(ə)n/','/pəˈzɪʃ(ə)n/','noun',["Chief of Staff is the second-highest position in the army.","My position on this issue is unchanged.","Stand in this position, with your arms at your side."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curtail','vt.缩短，缩减，削减','/kɜːˈteɪl/','/kɚˈteɪl/','noun',["Curtailing horses procured long horse-hair.","When the audience grew restless, the speaker curtailed her speech."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glow','vi.发光；发红，发热；洋溢n.暗淡的光；容光焕发；喜悦','/ɡləʊ/','/ɡloʊ/','noun',["He had a bright red glow on his face.","The fire was still glowing after ten hours.","The zealots glowed with religious fervor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patent','adj.有专利的；显而易见的vt.取得专利权n.专利权','/ˈpeɪtənt/','/ˈpeɪtənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sheath','n.鞘，外壳；套；护皮；紧身连衣裙','/ʃiːθ/','/ʃiθ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pollen','n.花粉','/ˈpɒlən/','/ˈpɑlən/','noun',["\"...and ther was good wyne of Gascoyne,... as well of pollen, as of other vitailes...\" Froissart, Jean, 1338?-1410?; Berners, John Bourchier, Lord https//archive.org/details/chroniclefroiss00froigoog"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remodel','vt.重新塑造，改造；改编；改变','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('groove','n.沟；槽；唱片上的纹路','/ɡɹuːv/','/ɡɹuːv/','noun',["I was just starting to groove to the band when we had to leave."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('certificate','n.证书，证明书；文凭，结业证书','','','noun',["The film is certificate 15."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dispersal','n.疏散；散布，散开','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quantum','n.量子','[ˈkwɑɾ̃əm]','/ˈkwɑntəm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('racket','n.球拍；喧嚷，吵闹；勒索，诈骗','/ˈɹækɪt/','/ˈɹækɪt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mess','n.肮脏，杂乱；混乱，困境vt.弄脏，弄乱；搞糟','/mɛs/','/mɛs/','noun',["He made a mess of it.","My boss dumped a whole mess of projects on my desk today.","Parked under a tree, my car was soon covered in birds'' mess."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sour','v.变酸；变馊；变坏，恶化adj.酸的；馊的；乖戾的，尖酸刻薄的；酸痛的','/ˈsaʊə/','/ˈsaʊ(ə)ɹ/','noun',["Too much lemon juice will sour the recipe.","We broke up after our relationship soured.","Lemons have a sour taste."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transform','vt.使变形；改造，改革；转换','/tɹænzˈfɔːm/','/tɹænzˈfɔɹm/','noun',["The alchemists sought to transform lead into gold."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('magnitude','n.巨大；重要性；星等，星球的亮度','/ˈmæɡnɪtjuːd/','/ˈmæɡnɪtjuːd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('genuine','adj.真的，非人造的；真诚的，诚实的','/ˈdʒɛnjuːˌaɪn/','/ˈdʒɛnjuːˌaɪn/','adjective',["a genuine text;  a genuine production;  genuine materials; genuine friendship"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agitate','v.鼓动，煽动；激怒，使激动，使不安；搅动','/ˈæ.dʒɪ.teɪt/','/ˈæ.dʒɪ.teɪt/','verb',["He was greatly agitated by the news.","the wind agitates the sea","politicians agitate desperate designs"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('microwave','n.微波；微波炉','/ˈmaɪkɹəʊˌweɪv/','/ˈmaɪkɹəʊˌweɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gorilla','n.大猩猩','/ɡəˈɹɪl.ə/','/ɡəˈɹɪl.ə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immune','adj.免疫的，有免疫力的；不受影响的；免除的，豁免的','','/ɪˈmjuːn/','noun',["As a diplomat, you are immune from prosecution.","I am immune to chicken pox.","Alas, he was immune to my charms."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brochure','n.小册子，说明书','/ˈbɹəʊ.ʃə(ɹ)/','/bɹoʊˈʃɝ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('downside','n.缺点，负面；底侧；下降趋势','/ˈdaʊnˌsaɪd/','/ˈdaʊnˌsaɪd/','noun',["The downside of obtaining a higher rank is that far more work is expected."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equation','n.等式，方程式；等同，相等；均衡','/ɪˈkweɪʃən/','/ɪˈkweɪʃən/','noun',["We need to bring the balance of power into equation"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impressive','adj.给人深刻印象的；感人的','/ɪmˈpɹɛsɪv/','/ɪmˈpɹɛsɪv/','adjective',["an impressive movie"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prospector','n.勘探者，采矿者','/pɹəˈspɛktə/','/pɹəˈspɛktə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compound','n.化合物，vt.使恶化，使加重；混合','/ˈkɒmpaʊnd/','/ˈkɒmpaʊnd/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discredit','vt.使丧失声誉；使怀疑n.名誉丧失','','','noun',["Later accounts have brought the story into discredit.","The candidate tried to discredit his opponent."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extraordinary','adj.特别的；非凡的','/ɪksˈtɹɔː(ɹ)dɪnəɹi/','','noun',["an extraordinary poet","an extraordinary professor in a German university"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spawn','v.产卵；产生，促成n.卵','/ˈspɔːn/','/ˈspɔːn/','verb',["The Web server spawns a new process to handle each client''s request."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sensory','adj.感觉的，感官的','/ˈsɛnsəɹi/','/ˈsɛnsəɹi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('puzzle','n.难题，谜vt.迷惑，使困惑','/ˈpʌzəl/','/ˈpʌzəl/','noun',["Where he went after he left the house is a puzzle.","to be in a puzzle","We puzzled over the curious-shaped lock, but were unable to discover how the key should be inserted."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mere','adj.仅仅的，纯粹的','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suburb','n.市郊，郊区','/ˈsʌbɜːb/','/ˈsʌbɜːb/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('taut','adj.绷紧的；肌肉结实的；结构严谨的，紧凑的','/tɔːt/','/tɔt/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('simplify','vt.简化，使简单，使单纯','/ˈsɪmpləfaɪ/','/ˈsɪmpləfaɪ/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lubricant','n.润滑剂','/ˈljuːbɹɪkənt/','/ˈlubɹəkənt/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glue','vt.胶合，黏合；紧附于n.胶，胶水','/ɡluː/','/ɡluː/','noun',["I need to glue the chair-leg back into place.","His eyes were glued to the screen."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('orbital','adj.轨道的','','','noun',["The M25 is an orbital motorway around London."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solder','vt.焊接n.焊料，焊锡','/ˈsɒldə(ɹ)/','/ˈsɑdɚ/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('envelop','vt.包围','/ɛnˈvɛləp/','/ɛnˈvɛləp/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('firm','adj.结实的；坚定的，坚决的n.公司','/fɜːm/','/fɜɹm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reflect','v.反射，映现；显示，表明；仔细考虑，深思','/ɹɪˈflɛkt/','/ɹɪˈflɛkt/','verb',["A mirror reflects the light that shines on it.","The moonlight reflected from the surface of water.","The shop window reflected his image as he walked past."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adventitious','adj.偶然的，偶发的','/ˌæd.vənˈtɪʃ.əs/','/ˌæd.vənˈtɪʃ.əs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ongoing','adj.正在进行的；不间断的；继续存在的n.前进，发展','','','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outfit','n.全套装备；全套服装','/ˈaʊtfɪt/','/ˈaʊtfɪt/','noun',["She wore a fashionable outfit with matching purse and shoes.","Should we buy it here, or do you think the outfit across town will have a better deal?","The expedition was outfitted with proper clothing, food, and other necessities."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ignorant','adj.无知的，愚昧的；无知觉的','/ˈɪɡnəɹənt/','/ˈɪɡnəɹənt/','noun',["His manner was at best off-hand, at worst totally ignorant."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extort','vt.勒索，敲诈，强夺','/ɪkˈstɔː(ɹ)t/','/ɪkˈstɔː(ɹ)t/','verb',["to extort a promise"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trample','v.踩碎；践踏，摧残','/ˈtɹæmpəl/','/ˈtɹæmpəl/','noun',["to trample grass or flowers"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negligible','adj.可以忽略的，微不足道的；无关紧要的','/ˈnɛɡlɪdʒɪbəl/','/ˈnɛɡlɪdʒɪbəl/','adjective',["We found errors, but their effects were negligible."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('setback','n.挫折，阻碍；倒退','/ˈsɛtbæk/','/ˈsɛtbæk/','noun',["After some initial setbacks, the expedition went safely on its way.","Setbacks were initially used for structural reasons, but now are often mandated by land use codes."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spray','n.浪花；飞沫；','/spɹeɪ/','/spɹeɪ/','noun',["The sailor could feel the spray from the waves.","The firemen sprayed the house.","Spray some ointment on that scratch."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distinguish','v.区别，辨别；使有别于，成为…的特征；看清，听出；使杰出，使著名','/dɪsˈtɪŋɡwɪʃ/','/dɪsˈtɪŋɡwɪʃ/','verb',["The soldier distinguished himself in combat and received a medal."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('primordial','adj.原始的，最初的；基本的','/pɹaɪˈmɔː.di.əl/','/pɹaɪˈmɔɹ.di.əl/','noun',["a primordial leaf; a primordial cell"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('husbandry','n.耕种，务农，农牧业','/ˈhʌzb(ə)ndɹi/','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('haircut','n.理发','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decorative','adj.装饰性的，做装饰用的','/ˈdɛkɹətɪv/','/ˈdɛkɹətɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pointed','adj.尖的，尖角的；尖锐的，尖刻的','/ˈpɔɪntɪd/','/ˈpɔɪntɪd/','verb',["It''s rude to point at other people.","The arrow of a compass points north","to point a gun at a wolf, or a cannon at a fort"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enthusiastic','adj.热情的，热心的','/ɪnˌθjuːzɪˈæstɪk/','/ɪnˌθjuːzɪˈæstɪk/','adjective',["an enthusiastic lover of art"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elongate','v.延长，伸长','/ɪ.ˈlɔŋ.ˌɡeɪt/','/ɪ.ˈlɔŋ.ˌɡeɪt/','verb',["Painted turtles lay oval, elongate eggs."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symptom','n.症状；征兆','/ˈsɪm(p)təm/','/ˈsɪm(p)təm/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fray','vi.磨损，磨破；烦躁，恼火n.争斗','/fɹeɪ/','/fɹeɪ/','verb',["The ribbon frayed at the cut end.","The hectic day ended in frayed nerves. (Metaphorical use; nerves are visualised as strings)"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thereby','adv.因此，从而','/ðɛəˈbaɪ/','/ðɛɹˈbaɪ/','adverb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wield','vt.支配，掌权，行使','/wiːld/','/wiːld/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disastrous','adj.灾难性的','/dɪˈzɑːstɹəs/','/dɪˈzɑːstɹəs/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impulse','n.冲动，一时的念头；刺激，推动力；脉冲','/ˈɪmpʌls/','/ˈɪmpʌls/','noun',["The impulse to learn drove me to study night and day.","The total impulse from the impact will depend on the kinetic energy of the bullet."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crystallize','v.结晶；明确','/ˈkɹɪstəlaɪz/','/ˈkɹɪstəlaɪz/','verb',["I crystallized the copper sulphate by slowly cooling a saturated solution.","The copper sulphate crystallized from solution.","After some thought, I crystallized my ideas for the paper."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subspecies','n.亚种','/-siːz/','/-siːz/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shower','v.淋浴；下阵雨；洒落，纷纷降落；抛撒n.阵雨，暴雨；淋浴；一阵，一大批','/ˈʃaʊ.ə(ɹ)/','/ˈʃaʊ.ə(ɹ)/','noun',["Today there will be frequent showers and some sunny spells.","I′m going to have a shower.","a shower of sparks;  a meteor shower;  a Gatorade shower"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('infectious','adj.传染性的，传染病的；有感染力的','','','adjective',["Cancer is not infectious.","Despite feeling better, the patient is still infectious.","Her enthusiasm for work can be really infectious."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concur','v.同时发生；意见一致','/kənˈkɜː/','/kənˈkɜː/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nevertheless','adv.然而，不过','/ˈnɛvəðəlɛs/','/ˈnɛvəðəlɛs/','adverb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prominent','adj.卓著的，杰出的；突起的，凸出的','/ˈpɹɒmɪnənt/','/ˈpɹɑmɪnənt/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insulin','n.胰岛素','/ˈɪnsjʊlin/','/ˈɪnsjʊlin/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ironic','adj.说反话的，讽刺的；出乎意料的','/aɪˈɹɒn.ɪk/','/aɪˈɹɒn.ɪk/','adjective',["It''s ironic to have a blizzard in the middle of the summer.","It''s ironic that we are eating a sandwich in Sandwich, Massachusetts."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fundamental','adj.基础的，基本的，根本的n.基本原则；基础','/ˌfʌndəˈmɛntəl/','/ˌfʌndəˈmɛntəl/','noun',["one of the fundamentals of linear algebra","A need for belonging seems fundamental to humans."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hieratic','adj.僧侣的；','/ˌhaɪ(ə)ˈɹætɪk/','/ˌhaɪ(ə)ˈɹætɪk/','noun',["Some of the more hieratic sculptures leave the viewer curiously unmoved."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entitle','vt.使…有权；给题名','/ənˈtaɪtəl/','/ənˈtaɪtəl/','verb',["A passport entitles the bearer to travel to other countries."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monotony','n.单调，千篇一律','/məˈnɒtəni/','/məˈnɑtəni/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outline','n.轮廓；概要，大纲vt.描绘；略述','/ˈaʊtlaɪn/','/ˈaʊtlaɪn/','noun',["the outline of a speech","Wikipedia items featuring books usually outline them after giving their background."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('counselor','n.顾问；律师','/ˈkaʊnsələ(ɹ)/','/ˈkaʊnsələ(ɹ)/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fade','v.褪色；凋谢；逐渐消失','/feɪd/','/feɪd/','noun',["The milkman''s whistling faded into the distance."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overdue','adj.过期未付的，逾期的；过度的，过火的；迟到的，延误的','/ˌəʊ.vəˈdju/','/ˌoʊ.vəɹˈdu/','adjective',["his library books were three days overdue;  my car is overdue for an oil change;  she finally left on a long overdue vacation"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nominal','adj.名义上的；微不足道的','/ˈnɑm.ɪnl̩/','/ˈnɑm.ɪnl̩/','noun',["This sentence contains two nominals.","Numeric codes of characters used in programming are nominals.","a nominal difference"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excess','adj.过量的；额外的n.过度，超过','/əkˈsɛs/','/əkˈsɛs/','noun',["The excess of heavy water was given away to the neighbouring country.","The difference between two numbers is the excess of one over the other."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perspective','n.展望；观点，看法；远景；透视图，透视法；前途','/pɚˈspɛktɪv/','/pɚˈspɛktɪv/','noun',["a perspective drawing"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('galaxy','n.星系；[G-]银河系，银河；群英','/ˈɡaləksi/','/ˈɡæləksi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invade','v.侵入，侵略；侵扰','/ɪnˈveɪd/','/ɪnˈveɪd/','verb',["Under some circumstances police are allowed to invade a person''s privacy.","Argentinian troops invaded the Falkland Islands in 1982.","The picnic was invaded by ants."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intervening','adj.介于中间的，发生于期间的','','','verb',["The police had to be called to intervene in the fight.","An instant intervened between the flash and the report.","Nothing intervened to prevent the undertaking."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clump','v.聚集，成群；以沉重的脚步行走n.丛，簇，束；块，团；群，组','/klʌmp/','/klʌmp/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thorough','adj.彻底的；详尽的；一丝不苟的','/ˈθʌɹə/','/ˈθɜɹoʊ/','noun',["He is the most thorough worker I have ever seen."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('democracy','n.民主政体，民主制度；民主国家；民主精神','/dɪˈmɒkɹəsi/','/dɪˈmɒkɹəsi/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('peninsula','n.半岛','/pəˈnɪn.ʃə.lə/','/pəˈnɪn.sə.lə/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evolve','v.发展；进化','/ɪˈvɒlv/','/ɪˈvɒlv/','verb',["to evolve odours"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('congratulation','n.祝贺，道喜','/kənˌɡɹætjʊˈleɪʃ(ə)n/','/kənˌɡɹætjʊˈleɪʃ(ə)n/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abandon','vt.离弃，放弃n.放纵，放任','/əˈbæn.dən/','/əˈbæn.dn̩/','verb',["Many baby girls have been abandoned on the streets of Beijing."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extol','vt.赞美，颂扬','/ɪkˈstəʊl/','/ɪkˈstəʊl/','verb',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('household','adj.家庭的，家用的；家喻户晓的n.家庭','/ˈhaʊshəʊld/','/ˈhaʊshoʊld/','noun',["a household word; a household name"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adverse','adj.负面的；不利的；逆的','/ədˈvɜ(ɹ)s/','/ədˈvɜ(ɹ)s/','adjective',["adverse criticism","adverse circumstances","the adverse page"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bulletin','n.新闻简报；公告，布告；简报','/ˈbʊlətɪn/','/ˈbʊlətɪn/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ratio','n.比，比率','/ˈɹeɪ.ʃi.əʊ/','/ˈɹeɪ.ʃiˌoʊ/','noun',["The schoolchildren ganged up to ratio the school catering over its shamefully undemocratic inclusion of vegetables in meals."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('junction','n.交叉点，汇合处；连接，接合','/ˈdʒʌŋkʃən/','/ˈdʒʌŋkʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electrolysis','n.电解作用；电解术','/ɪlɛkˈtɹɒləsɪs/','/ɪlɛkˈtɹɒləsɪs/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bandanna','n.色彩鲜艳的围巾','','','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instinct','n.本能，直觉；生性，天性','/ˈɪn.stɪŋkt/','/ˈɪn.stɪŋkt/','noun',["Many animals fear fire by instinct.","Debbie''s instinct was to distrust John."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gourmet','adj.美味的n.美食家','/ˈɡɔːmeɪ/','/ˈɡɔːmeɪ/','noun',["The restaurant offered gourmet coffee and cigars after the meal."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reputation','n.名声，声望，名誉','/ˌɹɛpjʊˈteɪʃən/','/ˌɹɛpjʊˈteɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spike','n.长钉，大钉；猛增，急升','/spaɪk/','/spaɪk/','noun',["The trap was lined with spikes.","oil of spike","to spike down planks"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shrub','n.灌木','/ʃɹʌb/','/ʃɹʌb/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('presentation','n.提供，显示；介绍，陈述；赠送；表演','/ˌpɹizənˈteɪʃən/','/ˌpɹizənˈteɪʃən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('genesis','n.起源，开端','/ˈd͡ʒɛn.ə.sɪs/','/ˈd͡ʒɛn.ə.sɪs/','noun',["Some point to the creation of Magna Carta as the genesis of English common law."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subliminal','adj.下意识的，潜意识的','/səˈblɪmɪnəl/','/səˈblɪmɪnəl/','adjective',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engrave','vt.雕刻；铭刻','/ɪnˈɡɹeɪv/','/ɪnˈɡɹeɪv/','verb',["He engraved the plaque with his name.","He engraved his name."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tavern','n.小旅馆，客栈；小酒店','/ˈtævən/','/ˈtævən/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glimmer','vi.发微光；隐约出现n.闪烁的微光；隐约的迹象；一丝，一线','/ˈɡlɪmə(ɹ)/','/ˈɡlɪmɚ/','noun',["The glimmer of the fireflies was pleasant to watch.","A glimmer of hope.","The fireflies glimmered in the dark."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('awkward','adj.别扭的；笨拙的；难处理的，棘手的；难操纵的','/ˈɑkwɚd/','/ˈɔkwɚd/','noun',["John was awkward at performing the trick. He''ll have to practice to improve.","An awkward silence had fallen.","I''m very awkward at parties."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adhesive','adj.带黏性的n.胶合剂','/ædˈhi.sɪv/','/ædˈhi.sɪv/','noun',[]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monumental','adj.纪念碑的；不朽的','/ˌmɒnjʊˈmɛntəl/','/ˌmɒnjʊˈmɛntəl/','adjective',["Monumental construction."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ruin','vt.破坏，毁灭；使破产n.毁灭，毁坏；','/ˈɹuː.ɪn/','/ˈɹuː.ɪn/','noun',["The monastery has fallen into ruin.","Gambling has been the ruin of many.","the ruin of a ship or an army;  the ruin of a constitution or a government;  the ruin of health or hopes"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spill','v.溢出，溅出；蜂拥而出n.溢出，泄漏','/spɪl/','/spɪl/','noun',["The bruise is from a bad spill he had last week.","I spilled some sticky juice on the kitchen floor.","Some sticky juice spilled onto the kitchen floor."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('celebrate','v.赞美；庆祝','/ˈsɛl.ə.bɹeɪt/','/ˈsɛl.ə.bɹeɪt/','verb',["to celebrate the name of the Most High","to celebrate a birthday","I was promoted today at work—let’s celebrate!"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cradle','n.摇篮；发源地','/ˈkɹeɪdəl/','/ˈkɹeɪdəl/','noun',["a cradle of crime","from the cradle to the grave","The cradle was ill-made. One victim fell into the sea and was lost and the ensuing delay cost three more lives."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abut','v.邻接，毗邻','/əˈbʌt/','/əˈbʌt/','verb',["His land abuts on the road."]);
