INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('geometric','adj.几何的，几何学的','/ˌdʒi.əˈmɛt.ɹɪk/','/ˌdʒi.əˈmɛt.ɹɪk/','adjective',["The architect used geometric techniques to design her home.","Bacteria exhibit geometric increase in numbers when the environment is not limiting.","The building''s profile was strikingly geometric."]);
