INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inspect','vt.检查，视察','/ɪnˈspɛkt/','/ɪnˈspɛkt/','verb',["Inspect the system for leaks.","The general inspected the troops and their barracks."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('campaign','vi.竞选；参加战斗n.竞选活动；活动；战役','/kæmˈpeɪn/','/kæmˈpeɪn/','noun',["The company is targeting children in their latest advertising campaign.","She campaigned for better social security."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vital','adj.生死攸关的；至关重要的；精力充沛的，有活力的','/ˈvaɪt̬əl/','/ˈvaɪt̬əl/','adjective',["vital energies; vital functions; vital actions","The brain is a vital organ.","The transition to farming was vital for the creation of civilisation."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conflict','vi.冲突；不一致；争论n.冲突；争论','/kənˈflɪkt/','/kənˈflɪkt/','noun',["The conflict between the government and the rebels began three years ago.","I wanted to attend the meeting but there''s a conflict in my schedule that day.","It appears that our schedules conflict."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engraving','n.雕刻术，刻版术；版画','','','verb',["He engraved the plaque with his name.","He engraved his name."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rough','adj.粗糙不平的；粗暴的；艰难的n.高低不平的地面','/ɹʌf/','/ɹʌf/','noun',["Rough in the shape first, then polish the details.","a rough estimate; a rough sketch of a building; a rough plan","rough sea"]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lawsuit','n.诉讼','/ˈlɔˌs(j)ut/','/ˈlɔˌs(j)ut/','noun',["The lawyer advised his client against filing a lawsuit as it would take a lot of time and money to resolve."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sequential','adj.序列的；连续的；随之而来的','','','adjective',[]);
