INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wonder','v.诧异；纳闷，想知道n.惊奇，惊异；奇迹，奇事','/ˈwʌndə/','/ˈwʌndɚ/','noun',["Wonders of the World seem to come in sevens.","The idea was so crazy that it is a wonder that anyone went along with it.","He''s a wonder at cooking."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mansion','n.公寓，府邸；大厦','/ˈmæn(t)ʃən/','/ˈmæn(t)ʃən/','noun',[]);
