INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('artificial','adj.人工的，人造的，假的；矫揉造作的，假装','/ɑː(ɹ)təˈfɪʃəl/','/ɑː(ɹ)təˈfɪʃəl/','adjective',["The flowers were artificial, and he thought them rather tacky.","Her manner was somewhat artificial."]);
