INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imaginary','adj.想象中的，虚构的，假想的','/ɪˈmædʒɪn(ə)ɹi/','/ɪˈmædʒɪˌnɛɹi/','noun',["Santa Claus is imaginary."]);
