INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sum','v.共计，合计，总计n.和，总数；金额，数额；算术','/sʌm/','/sʌm/','noun',["The sum of 3 and 4 is 7.","We''re learning about division, and the sums are tricky.","a tidy sum"]);
