INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bud','vi.发芽，萌芽n.芽；蓓蕾','/bʌd/','/bʌd/','noun',["After a long, cold winter, the trees finally began to produce buds.","breast buds","In this slide, you can see a yeast cell forming buds."]);
INSERT INTO TOEFL (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uppermost','adv.在最上面，在最重要的位置adj.最高的，最上面的；最重要的','/ˈʌpəməʊst/','/ˈʌpəməʊst/','adjective',[]);
